window.GRAM=[{"id":1,"name":"Masculino, femenino (1)","motto":"el hijo, la hija","theory":[{"k":"img","src":"img/gram/u01_teoria-hijo-hija.png","alt":"Un padre con su hijo y una madre con su hija delante de una casa."},{"k":"p","t":"<i>El hijo, el padre</i> son nombres masculinos. <i>La hija, la madre</i> son nombres femeninos."},{"k":"p","t":"En español, los <b>nombres</b> son masculinos o femeninos."},{"k":"table","head":["MASCULINOS (hombres)","FEMENINOS (mujeres)"],"rows":[["el hijo","la hija"],["el padre","la madre"],["el camarero","la camarera"],["el doctor","la doctora"],["el estudiante","la estudiante"],["el taxista","la taxista"]]},{"k":"h","t":"Formación del femenino"},{"k":"p","t":"Muchos nombres masculinos y femeninos se distinguen por la terminación."},{"k":"table","head":["MASCULINO","FEMENINO","PERO:"],"rows":[["-o, -e<br>el niño<br>el cocinero<br>el dependiente","-a<br>la niña<br>la cocinera<br>la dependienta","el piloto – la piloto<br>el paciente – la paciente<br>el modelo – la modelo"],["consonante<br>el profesor<br>el director<br>el marqués","+a<br>la profesora<br>la directora<br>la marquesa","el joven – la joven"]]},{"k":"p","t":"Los nombres acabados en <i>-ante, -ista</i> no cambian en masculino y femenino: <i>el estudiante – la estudiante; el pianista – la pianista</i>."},{"k":"p","t":"Algunos nombres forman el femenino con otras terminaciones: <i>el actor – la actriz; el rey – la reina; el alcalde – la alcaldesa</i>."},{"k":"p","t":"Algunos nombres tienen formas diferentes para el masculino y el femenino: <i>el marido – la mujer; el papá – la mamá; el hombre – la mujer; el padre – la madre</i>."},{"k":"p","t":"Algunos nombres tienen dos formas posibles de femenino: <i>el médico – la médica / la médico; el jefe – la jefa / la jefe</i>."},{"k":"note","h":"ATENCIÓN","rows":["Algunas palabras que acompañan al nombre son diferentes para masculino y femenino.","<i>aquel chico rubio – aquella chica rubia; un hombre alto – una mujer alta</i>"]}],"ex":[{"id":"gram:1.1","type":"cloze","lab":"1.1","title":"1.1","instr":"Escriba M (masculino) o F (femenino) en cada ilustración. Después, complete como en el ejemplo utilizando las palabras del recuadro con el o la.","bank":["cantante","cocinero","estudiante","modelo","paciente","~periodista","pianista","piloto","rey","taxista"],"items":[{"tpl":"___ ___","blanks":2,"ans":["F la periodista"],"img":"img/gram/u01_ej1-1_01.png","alt":"Ilustración 1","example":true},{"tpl":"___ ___","blanks":2,"ans":["M el cocinero"],"img":"img/gram/u01_ej1-1_02.png","alt":"Ilustración 2"},{"tpl":"___ ___","blanks":2,"ans":["M el rey"],"img":"img/gram/u01_ej1-1_03.png","alt":"Ilustración 3"},{"tpl":"___ ___","blanks":2,"ans":["F la estudiante"],"img":"img/gram/u01_ej1-1_04.png","alt":"Ilustración 4"},{"tpl":"___ ___","blanks":2,"ans":["F la modelo"],"img":"img/gram/u01_ej1-1_05.png","alt":"Ilustración 5"},{"tpl":"___ ___","blanks":2,"ans":["M el taxista"],"img":"img/gram/u01_ej1-1_06.png","alt":"Ilustración 6"},{"tpl":"___ ___","blanks":2,"ans":["F la piloto"],"img":"img/gram/u01_ej1-1_07.png","alt":"Ilustración 7"},{"tpl":"___ ___","blanks":2,"ans":["M el cantante"],"img":"img/gram/u01_ej1-1_08.png","alt":"Ilustración 8"},{"tpl":"___ ___","blanks":2,"ans":["F la pianista"],"img":"img/gram/u01_ej1-1_09.png","alt":"Ilustración 9"},{"tpl":"___ ___","blanks":2,"ans":["F la paciente"],"img":"img/gram/u01_ej1-1_10.png","alt":"Ilustración 10"}]},{"id":"gram:1.2","type":"type","lab":"1.2","title":"1.2","instr":"Escriba el femenino de los siguientes nombres.","items":[{"q":"señor","ans":["señora"],"example":true},{"q":"jefe","ans":["jefe","jefa"]},{"q":"marido","ans":["mujer"]},{"q":"pintor","ans":["pintora"]},{"q":"actor","ans":["actriz"]},{"q":"turista","ans":["turista"]},{"q":"escritor","ans":["escritora"]},{"q":"bailarín","ans":["bailarina"]},{"q":"rey","ans":["reina"]},{"q":"joven","ans":["joven"]},{"q":"hombre","ans":["mujer"]},{"q":"niño","ans":["niña"]},{"q":"dependiente","ans":["dependienta"]},{"q":"amigo","ans":["amiga"]},{"q":"médico","ans":["médico","médica"]}]},{"id":"gram:1.3","type":"type","lab":"1.3","title":"1.3","instr":"Observe el dibujo y complete las frases con las palabras del recuadro.","img":"img/gram/u01_ej1-3_arbol.png","alt":"Árbol familiar: Luis y Ana; sus hijos Julio y Gabriel con Lucía y Laura; sus nietos Blanca, Pedro, Raúl y Silvia.","bank":["abuela","abuelo","hermana","hermano","hija","hijo","madre","~padre","tía","tío"],"items":[{"q":"Luis es mi","ans":["padre"],"example":true},{"q":"Ana es mi","ans":["madre"]},{"q":"Laura es mi","ans":["hermana"]},{"q":"Blanca es mi","ans":["hija"]},{"q":"Pedro es mi","ans":["hijo"]},{"q":"Luis es mi","ans":["abuelo"]},{"q":"Ana es mi","ans":["abuela"]},{"q":"Lucía es mi","ans":["tía"]},{"q":"Julio es mi","ans":["tío"]},{"q":"Raúl es mi","ans":["hermano"]}]}]},{"id":2,"name":"Masculino, femenino (2)","motto":"el libro, la mesa","theory":[{"k":"img","src":"img/gram/u02_teoria-mesa.png","alt":"Una mesa con un teléfono y un libro, y una silla."},{"k":"p","t":"<i>El libro, el teléfono</i> son nombres masculinos. <i>La mesa, la silla</i> son nombres femeninos."},{"k":"p","t":"En español, los <b>nombres de cosas</b> pueden ser masculinos o femeninos."},{"k":"h","t":"Los nombres acabados en -o son masculinos"},{"k":"eg","t":"el libro, el carro, el teléfono, el vaso, el brazo, el museo"},{"k":"note","h":"PERO","rows":["la mano, la foto, la moto, la radio"]},{"k":"h","t":"Los nombres acabados en -a son femeninos"},{"k":"eg","t":"la casa, la silla, la mesa, la caja, la tortilla, la cara"},{"k":"note","h":"PERO","rows":["el día, el idioma, el mapa, el problema, el pijama, el planeta"]},{"k":"h","t":"Los nombres acabados en -e o en consonante pueden ser:"},{"k":"p","t":"<b>Masculinos:</b> los días de la semana (<i>el lunes, el miércoles...</i>); los nombres compuestos (<i>el paraguas, el cumpleaños...</i>); otros: <i>el restaurante, el coche, el cine, el hotel, el lápiz, el pan, el pulóver...</i>"},{"k":"p","t":"<b>Femeninos:</b> los acabados en <i>-ción, -sión</i> (<i>la canción, la habitación, la televisión...</i>); los acabados en <i>-dad, -tad</i> (<i>la ciudad, la universidad, la libertad...</i>); otros: <i>la clase, la noche, la leche, la sal, la flor, la luz...</i>"},{"k":"h","t":"Los nombres de animales"},{"k":"p","t":"La mayoría de los nombres de animales son masculinos o femeninos. Son solo masculinos: <i>el pez, el pájaro, el ratón, el conejo...</i> Son solo femeninos: <i>la jirafa, la serpiente, la rana, la sardina...</i>"},{"k":"p","t":"Algunos tienen una forma masculina y otra femenina:"},{"k":"table","rows":[["el gato – la gata","el caballo – la yegua"],["el perro – la perra","el toro – la vaca"],["el león – la leona","el gallo – la gallina"]]}],"ex":[{"id":"gram:2.1","type":"sort","lab":"2.1","title":"2.1","instr":"Clasifique los siguientes nombres: ¿el o la?","opts":["el","la"],"items":[{"w":"atención","ans":["la"],"example":true},{"w":"cama","ans":["la"]},{"w":"casa","ans":["la"]},{"w":"cine","ans":["el"],"example":true},{"w":"ciudad","ans":["la"]},{"w":"cuaderno","ans":["el"]},{"w":"cumpleaños","ans":["el"]},{"w":"día","ans":["el"]},{"w":"expresión","ans":["la"]},{"w":"foto","ans":["la"]},{"w":"habitación","ans":["la"]},{"w":"hotel","ans":["el"]},{"w":"idioma","ans":["el"]},{"w":"lámpara","ans":["la"]},{"w":"lápiz","ans":["el"]},{"w":"leche","ans":["la"]},{"w":"libro","ans":["el"]},{"w":"luz","ans":["la"]},{"w":"mano","ans":["la"]},{"w":"minuto","ans":["el"]},{"w":"museo","ans":["el"]},{"w":"noche","ans":["la"]},{"w":"página","ans":["la"]},{"w":"planeta","ans":["el"]},{"w":"problema","ans":["el"]},{"w":"radio","ans":["la"]},{"w":"teatro","ans":["el"]},{"w":"teléfono","ans":["el"]},{"w":"universidad","ans":["la"]},{"w":"vaso","ans":["el"]},{"w":"ventana","ans":["la"]},{"w":"viernes","ans":["el"]}]},{"id":"gram:2.2","type":"cloze","lab":"2.2","title":"2.2","instr":"Complete las siguientes tablas con los animales correspondientes.","items":[{"tpl":"el gato — ___","blanks":1,"ans":["la gata"],"example":true},{"tpl":"___ — la yegua","blanks":1,"ans":["el caballo"]},{"tpl":"el gallo — ___","blanks":1,"ans":["la gallina"]},{"tpl":"___ — la perra","blanks":1,"ans":["el perro"]},{"tpl":"el león — ___","blanks":1,"ans":["la leona"]},{"tpl":"___ — la vaca","blanks":1,"ans":["el toro"]}]},{"id":"gram:2.3","type":"type","lab":"2.3","title":"2.3","instr":"Escriba lo que hay en cada ilustración con el o la como en el ejemplo. Consulte el diccionario en caso de duda.","bank":["~árbol","diccionario","gorila","hospital","llave","mariposa","nariz","pez","tenedor","tren"],"items":[{"q":"","ans":["el árbol"],"img":"img/gram/u02_ej2-3_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["el tren"],"img":"img/gram/u02_ej2-3_02.png","alt":"Ilustración 2"},{"q":"","ans":["el diccionario"],"img":"img/gram/u02_ej2-3_03.png","alt":"Ilustración 3"},{"q":"","ans":["la mariposa"],"img":"img/gram/u02_ej2-3_04.png","alt":"Ilustración 4"},{"q":"","ans":["el gorila"],"img":"img/gram/u02_ej2-3_05.png","alt":"Ilustración 5"},{"q":"","ans":["la llave"],"img":"img/gram/u02_ej2-3_06.png","alt":"Ilustración 6"},{"q":"","ans":["el hospital"],"img":"img/gram/u02_ej2-3_07.png","alt":"Ilustración 7"},{"q":"","ans":["el tenedor"],"img":"img/gram/u02_ej2-3_08.png","alt":"Ilustración 8"},{"q":"","ans":["el pez"],"img":"img/gram/u02_ej2-3_09.png","alt":"Ilustración 9"},{"q":"","ans":["la nariz"],"img":"img/gram/u02_ej2-3_10.png","alt":"Ilustración 10"}]}]},{"id":3,"name":"Singular, plural","motto":"libro, libros","theory":[{"k":"img","src":"img/gram/u03_teoria-singular-plural.png","alt":"Un libro y un reloj (singular); varios libros y varios relojes (plural)."},{"k":"p","t":"Se usa el <b>singular</b> para hablar de una sola persona, animal o cosa: <i>niño, gato, mesa</i>. Se usa el <b>plural</b> para hablar de más de una: <i>niños, gatos, mesas</i>."},{"k":"h","t":"Formación del plural"},{"k":"table","head":["Terminación","Plural","Ejemplos"],"rows":[["-a, -e, -i, -o, -u","+ s","casa → casas; libro → libros"],["-á, -é, -ó, -ú","+ s","café → cafés; menú → menús"],["consonante","+ es","frijol → frijoles; reloj → relojes; mes → meses"],["-í, -y","+ es","rubí → rubíes; ley → leyes"],["-as, -es, -is, -os, -us (palabras de dos o más sílabas)","no cambian","(el) lunes → (los) lunes; (el) paraguas → (los) paraguas"],["-z","-ces","actriz → actrices; pez → peces"]]},{"k":"note","h":"ATENCIÓN","rows":["autobús → autobuses; televisión → televisiones"]},{"k":"p","t":"Algunos nombres utilizan la misma forma para el singular y el plural, o solo existen en plural: <i>unas tijeras, tres tijeras; gafas; pantalones; vaqueros</i>."},{"k":"h","t":"Masculino + femenino = plural masculino"},{"k":"eg","t":"padre + madre = <b>padres</b>: Los padres de Miguel se llaman Antonio y Pilar."},{"k":"eg","t":"hijo(s) + hija(s) = <b>hijos</b>: Julia tiene tres hijos."},{"k":"eg","t":"rey + reina = <b>reyes</b>: Los reyes de España son Juan Carlos y Sofía."}],"ex":[{"id":"gram:3.1","type":"type","lab":"3.1","title":"3.1","instr":"Escriba el plural de los siguientes nombres.","items":[{"q":"mujer","ans":["mujeres"],"example":true},{"q":"pez","ans":["peces"]},{"q":"autobús","ans":["autobuses"]},{"q":"actriz","ans":["actrices"]},{"q":"habitación","ans":["habitaciones"]},{"q":"mamá","ans":["mamás"]},{"q":"pantalones","ans":["pantalones"]},{"q":"hotel","ans":["hoteles"]},{"q":"universidad","ans":["universidades"]},{"q":"televisión","ans":["televisiones"]},{"q":"niño","ans":["niños"]},{"q":"hermana","ans":["hermanas"]},{"q":"león","ans":["leones"]},{"q":"día","ans":["días"]},{"q":"clase","ans":["clases"]},{"q":"foto","ans":["fotos"]},{"q":"banana","ans":["bananas"]},{"q":"jueves","ans":["jueves"]}]},{"id":"gram:3.2","type":"list","lab":"3.2","title":"3.2","instr":"Continúe la descripción indicando los objetos que aparecen en el dibujo. En el dibujo hay...","img":"img/gram/u03_ej3-2_dibujo.png","alt":"Una mesa con botellas, vasos, libros, lápices, tijeras, gafas, una lámpara, postales y sillas.","bank":["~botella","gafas","lámpara","lápiz","libro","~mesa","postal","silla","tijeras","vaso"],"items":[{"ans":["1 mesa"],"example":true},{"ans":["2 botellas"],"example":true},{"ans":["1 lámpara"]},{"ans":["3 tijeras"]},{"ans":["1 gafas"]},{"ans":["2 postales"]},{"ans":["4 libros"]},{"ans":["3 lápices"]},{"ans":["4 sillas"]},{"ans":["2 vasos"]}]},{"id":"gram:3.3","type":"cloze","lab":"3.3","title":"3.3","instr":"Sustituya las palabras subrayadas como en el ejemplo.","items":[{"tpl":"Amalia tiene tres ___.","blanks":1,"ans":["hijos"],"ctx":"Amalia tiene <u>un hijo y dos hijas</u>.","example":true},{"tpl":"Los ___ de Marta viven en Caracas.","blanks":1,"ans":["abuelos"],"ctx":"<u>El abuelo y la abuela</u> de Marta viven en Caracas."},{"tpl":"Dos ___ míos están en Chile.","blanks":1,"ans":["amigos"],"ctx":"<u>Un amigo y una amiga</u> míos están en Chile."},{"tpl":"Mis ___ son médicos.","blanks":1,"ans":["hermanos"],"ctx":"<u>Mi hermano y mi hermana</u> son médicos."},{"tpl":"Mis ___ son muy altos.","blanks":1,"ans":["padres"],"ctx":"<u>Mi padre y mi madre</u> son muy altos."},{"tpl":"Los ___ de España viven en Madrid.","blanks":1,"ans":["reyes"],"ctx":"<u>El rey y la reina</u> de España viven en Madrid."},{"tpl":"En mi clase hay ocho ___.","blanks":1,"ans":["alumnos"],"ctx":"En mi clase hay <u>tres alumnos y cinco alumnas</u>."},{"tpl":"En mi escuela hay tres ___.","blanks":1,"ans":["profesores"],"ctx":"En mi escuela hay <u>un profesor y dos profesoras</u>."},{"tpl":"He mandado un correo electrónico a mis ___.","blanks":1,"ans":["tíos"],"ctx":"He mandado un correo electrónico <u>a mi tío y a mi tía</u>."},{"tpl":"Es una compañía de ballet con tres ___.","blanks":1,"ans":["bailarines"],"ctx":"Es una compañía de ballet con <u>un bailarín y dos bailarinas</u>."}]}]},{"id":4,"name":"El artículo indeterminado","motto":"un, una, unos, unas","theory":[{"k":"img","src":"img/gram/u04_teoria-dialogos.png","alt":"Dos diálogos: «¿Qué es eso? – Es un reloj» y «Una entrada, por favor»."},{"k":"h","t":"Formas del artículo indeterminado"},{"k":"table","head":["","MASCULINO","FEMENINO"],"rows":[["SINGULAR","<b>un</b><br>un chico, un abrigo","<b>una</b><br>una chica, una casa"],["PLURAL","<b>unos</b><br>unos chicos, unos abrigos","<b>unas</b><br>unas chicas, unas casas"]]},{"k":"note","h":"ATENCIÓN","rows":["<b>un</b> (no <s>una</s>) + nombres femeninos en singular que empiezan por <i>a, ha</i>: <i>un águila, un aula, un hacha</i>","Pero: <i>unas águilas, una buena aula, una pequeña hacha</i>"]},{"k":"h","t":"Se usa un, una, unos, unas + nombre"},{"k":"p","t":"<b>Para identificar algo o a alguien como parte de una clase o grupo.</b>"},{"k":"eg","t":"–¿Qué es eso? –Es <b>un</b> reloj."},{"k":"eg","t":"–¿Quién es Chayanne? –Es <b>un</b> cantante."},{"k":"eg","t":"La papaya es <b>una</b> fruta."},{"k":"p","t":"<b>Para indicar cantidad.</b>"},{"k":"p","t":"<i>un, una</i> + nombres contables en singular = 1"},{"k":"eg","t":"Necesito <b>un</b> lápiz. <b>Una</b> entrada, por favor."},{"k":"p","t":"<i>unos, unas</i> + nombres con forma única de plural = 1"},{"k":"eg","t":"Necesito <b>unas</b> tijeras. Quiero <b>unos</b> vaqueros."},{"k":"p","t":"<i>unos, unas</i> + nombres contables en plural = algunos, algunas (3, 4, 5...)"},{"k":"eg","t":"Me han regalado <b>unas</b> flores. He comprado <b>unos</b> libros."}],"ex":[{"id":"gram:4.1","type":"cloze","lab":"4.1","title":"4.1","instr":"Complete con un, una, unos, unas.","items":[{"tpl":"___ flor","blanks":1,"ans":["una"],"example":true},{"tpl":"___ sillas","blanks":1,"ans":["unas"]},{"tpl":"___ relojes","blanks":1,"ans":["unos"]},{"tpl":"___ paraguas","blanks":1,"ans":["un","unos"]},{"tpl":"___ alumnos","blanks":1,"ans":["unos"]},{"tpl":"___ cine","blanks":1,"ans":["un"]},{"tpl":"___ habitación","blanks":1,"ans":["una"]},{"tpl":"___ lápices","blanks":1,"ans":["unos"]},{"tpl":"___ chica","blanks":1,"ans":["una"]},{"tpl":"___ aulas","blanks":1,"ans":["unas"]},{"tpl":"___ ciudad","blanks":1,"ans":["una"]},{"tpl":"___ aula","blanks":1,"ans":["un"]},{"tpl":"___ profesora","blanks":1,"ans":["una"]},{"tpl":"___ pantalones","blanks":1,"ans":["unos"]},{"tpl":"___ camarero","blanks":1,"ans":["un"]}]},{"id":"gram:4.2","type":"cloze","lab":"4.2","title":"4.2","instr":"Complete las respuestas utilizando un, una, unos, unas y las palabras de los recuadros.","bank":["ciudad","~deporte","flor","fruta","país","científico","escritora","director de cine","~futbolista","pintora"],"items":[{"tpl":"¿Qué es el balonmano? Es ___.","blanks":1,"ans":["un deporte"],"example":true},{"tpl":"¿Qué es Sevilla? Es ___.","blanks":1,"ans":["una ciudad"]},{"tpl":"¿Qué es Colombia? Es ___.","blanks":1,"ans":["un país"]},{"tpl":"¿Qué es una rosa? Es ___.","blanks":1,"ans":["una flor"]},{"tpl":"¿Qué es el mango? Es ___.","blanks":1,"ans":["una fruta"]},{"tpl":"¿Quién es Ronaldo? Es ___.","blanks":1,"ans":["un futbolista"],"example":true},{"tpl":"¿Quién es Isabel Allende? Es ___.","blanks":1,"ans":["una escritora"]},{"tpl":"¿Quién es Frida Kahlo? Es ___.","blanks":1,"ans":["una pintora"]},{"tpl":"¿Quién es Amenábar? Es ___.","blanks":1,"ans":["un director de cine"]},{"tpl":"¿Quién es Stephen Hawking? Es ___.","blanks":1,"ans":["un científico"]}]},{"id":"gram:4.3","type":"type","lab":"4.3","title":"4.3","instr":"Escriba lo que hay en cada ilustración utilizando un, una, unos, unas y las palabras del recuadro.","bank":["árboles","caballo","casa","chicas","~coche","gafas","gato","hacha","libros","niños","televisión","vacas"],"items":[{"q":"","ans":["un coche"],"img":"img/gram/u04_ej4-3_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["unos niños"],"img":"img/gram/u04_ej4-3_02.png","alt":"Ilustración 2"},{"q":"","ans":["un hacha"],"img":"img/gram/u04_ej4-3_03.png","alt":"Ilustración 3"},{"q":"","ans":["unos libros"],"img":"img/gram/u04_ej4-3_04.png","alt":"Ilustración 4"},{"q":"","ans":["una casa"],"img":"img/gram/u04_ej4-3_05.png","alt":"Ilustración 5"},{"q":"","ans":["un gato"],"img":"img/gram/u04_ej4-3_06.png","alt":"Ilustración 6"},{"q":"","ans":["unas vacas"],"img":"img/gram/u04_ej4-3_07.png","alt":"Ilustración 7"},{"q":"","ans":["unas chicas"],"img":"img/gram/u04_ej4-3_08.png","alt":"Ilustración 8"},{"q":"","ans":["una televisión"],"img":"img/gram/u04_ej4-3_09.png","alt":"Ilustración 9"},{"q":"","ans":["unos árboles"],"img":"img/gram/u04_ej4-3_10.png","alt":"Ilustración 10"},{"q":"","ans":["unas gafas"],"img":"img/gram/u04_ej4-3_11.png","alt":"Ilustración 11"},{"q":"","ans":["un caballo"],"img":"img/gram/u04_ej4-3_12.png","alt":"Ilustración 12"}]},{"id":"gram:4.4","type":"cloze","lab":"4.4","title":"4.4","instr":"Complete las frases con un, una, unos, unas.","items":[{"tpl":"—___ melón, por favor.","blanks":1,"ans":["Un"],"example":true},{"tpl":"El Orinoco es ___ río.","blanks":1,"ans":["un"]},{"tpl":"¡Cuidado, ___ serpiente!","blanks":1,"ans":["una"]},{"tpl":"¡Mira! ___ águila.","blanks":1,"ans":["Un"]},{"tpl":"Quiero ___ vaqueros, por favor.","blanks":1,"ans":["unos"]},{"tpl":"—¿Qué es eso? —Es ___ radio.","blanks":1,"ans":["una"]},{"tpl":"¿Tienes ___ mapa de Ecuador?","blanks":1,"ans":["un"]},{"tpl":"Rosa tiene ___ hija.","blanks":1,"ans":["una"]},{"tpl":"Necesitamos ___ tijeras.","blanks":1,"ans":["unas"]},{"tpl":"Tengo ___ zapatos muy cómodos.","blanks":1,"ans":["unos"]}]}]},{"id":5,"name":"Ausencia de artículo","motto":"un coche / coche","theory":[{"k":"h","t":"No se usa un, una, unos, unas"},{"k":"p","t":"Detrás de <i>ser</i> o <i>hacerse</i> con nombres de profesión, religión, nacionalidad o ideología política."},{"k":"eg","t":"Soy estudiante. Chantal es francesa. Es abogada. Lenin y Stalin eran comunistas."},{"k":"note","h":"PERO","rows":["Se usa <i>un, una, unos, unas</i> cuando el nombre va con un calificativo: <i>Chantal es una francesa muy simpática. Es un médico extraordinario.</i>","Se usa <i>un, una, unos, unas</i> cuando se identifica a alguien por su profesión: <i>–¿Quiénes son las Hijas del Sol? –Son unas cantantes. Es una actriz muy famosa.</i>"]},{"k":"p","t":"Compare: <i>La hermana de Rosa es profesora de español. Es una profesora muy seria. Almodóvar es director de cine. ¿Quién es Almodóvar? –Es un director de cine.</i>"},{"k":"p","t":"Ante el objeto directo de un verbo cuando nos referimos a la clase de objeto, no a un objeto concreto."},{"k":"eg","t":"Lola colecciona sellos. Están buscando piso. ¿Tienes teléfono? No tengo coche. Siempre bebemos agua en las comidas. Ernesto no come carne. ¿Hay pan? Luis siempre lleva corbata. Tomás canta flamenco."},{"k":"note","h":"PERO","rows":["Se usa <i>un, una, unos, unas</i> cuando se habla de cantidad: <i>La novia de José Alfonso ha publicado una novela. (= 1) Me han regalado unos sellos. (= algunos sellos)</i>","Se usa <i>un, una, unos, unas</i> cuando se añade un adjetivo al nombre: <i>Tengo unos sellos muy raros. Aquí hacen un pan buenísimo. Hoy lleva una corbata muy original.</i>"]},{"k":"p","t":"Compare: <i>Antonio vende coches. Hoy ha vendido un coche. Necesito gafas. Necesito unas gafas especiales. ¿Tienes hermanos? Tengo una hermana.</i>"}],"ex":[{"id":"gram:5.1","type":"cloze","lab":"5.1","title":"5.1","instr":"Observe las ilustraciones y complete las frases con las palabras del recuadro.","bank":["~abogada","actriz","camarera","cocinero","estudiante","fotógrafo","médico","profesora"],"items":[{"tpl":"Eva es ___.","blanks":1,"ans":["abogada"],"img":"img/gram/u05_ej5-1_01.png","alt":"Ilustración 1","example":true},{"tpl":"José Luis es ___.","blanks":1,"ans":["estudiante"],"img":"img/gram/u05_ej5-1_02.png","alt":"Ilustración 2"},{"tpl":"Mar es ___.","blanks":1,"ans":["actriz"],"img":"img/gram/u05_ej5-1_03.png","alt":"Ilustración 3"},{"tpl":"Félix es ___.","blanks":1,"ans":["fotógrafo"],"img":"img/gram/u05_ej5-1_04.png","alt":"Ilustración 4"},{"tpl":"Roberto es ___.","blanks":1,"ans":["médico"],"img":"img/gram/u05_ej5-1_05.png","alt":"Ilustración 5"},{"tpl":"Adrián es ___.","blanks":1,"ans":["cocinero"],"img":"img/gram/u05_ej5-1_06.png","alt":"Ilustración 6"},{"tpl":"Eloísa es ___.","blanks":1,"ans":["camarera"],"img":"img/gram/u05_ej5-1_07.png","alt":"Ilustración 7"},{"tpl":"Leonor es ___.","blanks":1,"ans":["profesora"],"img":"img/gram/u05_ej5-1_08.png","alt":"Ilustración 8"}]},{"id":"gram:5.2","type":"pick","lab":"5.2","title":"5.2","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"—¿Quién es Luis Miguel? —Es [cantante|un cantante]; es [mexicano|un mexicano].","ans":["un cantante","mexicano"],"example":true},{"tpl":"La doctora Ramírez es [médica|una médica] buenísima; es [argentina|una argentina].","ans":["una médica","argentina"]},{"tpl":"El marido de Luisa es [abogado|un abogado]. Es [abogado|un abogado] muy caro.","ans":["abogado","un abogado"]},{"tpl":"Tomás se ha hecho [musulmán|un musulmán].","ans":["musulmán"]},{"tpl":"Los tíos de Andrea son [protestantes|unos protestantes].","ans":["protestantes"]},{"tpl":"El hermano de Patricio es [actor|un actor] famoso.","ans":["un actor"]},{"tpl":"—¿Quién es Vargas Llosa? —Es [escritor|un escritor]; es [peruano|un peruano].","ans":["un escritor","peruano"]},{"tpl":"Alberto y Lola son [estudiantes|unos estudiantes]. Son [socialistas|unos socialistas].","ans":["estudiantes","socialistas"]},{"tpl":"Sarita quiere ser [bailarina|una bailarina].","ans":["bailarina"]},{"tpl":"García Márquez es [escritor|un escritor] de éxito.","ans":["un escritor"]}]},{"id":"gram:5.3","type":"cloze","lab":"5.3","title":"5.3","instr":"Complete con un, una, unos, unas cuando sea necesario. Escriba Ø cuando no haga falta ningún artículo.","items":[{"tpl":"—¿Comes ___ carne? —No, soy ___ vegetariano.","blanks":2,"ans":["Ø Ø"],"example":true},{"tpl":"Colecciono ___ monedas. Ayer me compré ___ monedas chinas.","blanks":2,"ans":["Ø unas"]},{"tpl":"Alberto tiene ___ apartamento en Benidorm.","blanks":1,"ans":["un"]},{"tpl":"—¿Tomas ___ café? —Solo ___ taza al día.","blanks":2,"ans":["Ø una"]},{"tpl":"—¿Azúcar? —Gracias, no tomo ___ azúcar.","blanks":1,"ans":["Ø"]},{"tpl":"¿Tenéis ___ hijos?","blanks":1,"ans":["Ø"]},{"tpl":"Chelo canta ___ ópera.","blanks":1,"ans":["Ø"]},{"tpl":"Ernesto es ___ músico. Escribe ___ canciones.","blanks":2,"ans":["Ø Ø"]},{"tpl":"¿Necesitas ___ dinero?","blanks":1,"ans":["Ø"]},{"tpl":"—¿Quieres ___ queso? —No, gracias; es ___ queso muy fuerte.","blanks":2,"ans":["Ø un"]},{"tpl":"Carolina es ___ vendedora. Vende ___ enciclopedias.","blanks":2,"ans":["Ø Ø"]},{"tpl":"¿Tienes ___ hermanos?","blanks":1,"ans":["Ø"]}]}]},{"id":6,"name":"El artículo determinado","motto":"el, la, los, las","theory":[{"k":"img","src":"img/gram/u06_teoria-dialogos.png","alt":"Tres escenas: «Mira, la madre de Antonio», «¿Puedo ver al director?» y «Las rosas son mis flores preferidas»."},{"k":"h","t":"Formas del artículo determinado"},{"k":"table","head":["","MASCULINO","FEMENINO"],"rows":[["SINGULAR","<b>el</b><br>el padre, el libro","<b>la</b><br>la madre, la hoja"],["PLURAL","<b>los</b><br>los padres, los libros","<b>las</b><br>las madres, las hojas"]]},{"k":"note","h":"ATENCIÓN","rows":["<b>el</b> (no <s>la</s>) + nombres femeninos en singular que empiezan por <i>a, ha</i>: <i>el aula, el agua, el hacha, el águila</i>","Pero: <i>la otra aula, las aulas, las hachas, las águilas</i>"]},{"k":"p","t":"<i>a + el = <b>al</b></i>: Juego <b>al</b> fútbol. &nbsp; <i>de + el = <b>del</b></i>: El hijo <b>del</b> profesor está en mi clase."},{"k":"h","t":"Se usa el, la, los, las + nombre"},{"k":"p","t":"<b>Para hablar de una persona o una cosa única.</b>"},{"k":"eg","t":"La madre de Antonio es policía. (Antonio solo tiene una madre.)"},{"k":"eg","t":"Buenos Aires es la capital de Argentina. (Argentina solo tiene una capital.)"},{"k":"eg","t":"¿Quién es el presidente de Brasil? (Brasil solo tiene un presidente.)"},{"k":"p","t":"<b>Para hablar de una persona o una cosa específica;</b> es decir, cuando está claro de qué persona o cosa estamos hablando."},{"k":"eg","t":"Quiero ver al director. (el director de este banco)"},{"k":"eg","t":"Enciende la luz, por favor. (la luz de la habitación)"},{"k":"eg","t":"Luis está en la cocina. (la cocina de esta casa)"},{"k":"p","t":"<b>Para hablar de algo o alguien en sentido general.</b>"},{"k":"eg","t":"El tabaco es malo para la salud. (todo el tabaco)"},{"k":"eg","t":"Los chilenos hablan español. (todos los chilenos)"}],"ex":[{"id":"gram:6.1","type":"cloze","lab":"6.1","title":"6.1","instr":"Complete con el, la, los, las.","items":[{"tpl":"___ casa","blanks":1,"ans":["la"],"example":true},{"tpl":"___ médico","blanks":1,"ans":["el"]},{"tpl":"___ naranjas","blanks":1,"ans":["las"]},{"tpl":"___ coche","blanks":1,"ans":["el"]},{"tpl":"___ habitación","blanks":1,"ans":["la"]},{"tpl":"___ águila","blanks":1,"ans":["el"]},{"tpl":"___ pantalones","blanks":1,"ans":["los"]},{"tpl":"___ aula","blanks":1,"ans":["el"]},{"tpl":"___ sillas","blanks":1,"ans":["las"]},{"tpl":"___ lápices","blanks":1,"ans":["los"]},{"tpl":"___ tijeras","blanks":1,"ans":["las"]},{"tpl":"___ profesor","blanks":1,"ans":["el"]},{"tpl":"___ perro","blanks":1,"ans":["el"]},{"tpl":"___ hermana","blanks":1,"ans":["la"]},{"tpl":"___ alumnos","blanks":1,"ans":["los"]}]},{"id":"gram:6.2","type":"cloze","lab":"6.2","title":"6.2","instr":"Observe la ilustración y complete las frases con el, la, los, las y las palabras del recuadro.","img":"img/gram/u06_ej6-2_familia.png","alt":"Árbol familiar: Felipe y Claudia; Javier y Lucía; Juan y Marta; Enrique, Fernando e Isabel; las hijas Irene y Juana.","bank":["hermana","hermanos","hijas","madre","marido","~padre","tía","tío"],"items":[{"tpl":"___ ___ de Marta se llama Felipe.","blanks":2,"ans":["El padre"],"example":true},{"tpl":"___ ___ de Marta se llama Claudia.","blanks":2,"ans":["La madre"]},{"tpl":"___ ___ de Marta se llama Javier.","blanks":2,"ans":["El tío"]},{"tpl":"___ ___ de Marta se llama Lucía.","blanks":2,"ans":["La tía"]},{"tpl":"___ ___ de Marta se llaman Enrique y Fernando.","blanks":2,"ans":["Los hermanos"]},{"tpl":"___ ___ de Marta se llama Isabel.","blanks":2,"ans":["La hermana"]},{"tpl":"___ ___ de Marta se llama Juan.","blanks":2,"ans":["El marido"]},{"tpl":"___ ___ de Marta se llaman Irene y Juana.","blanks":2,"ans":["Las hijas"]}]},{"id":"gram:6.3","type":"type","lab":"6.3","title":"6.3","instr":"Complete las frases con las palabras del recuadro y el, la, los, las.","bank":["agua","diccionario","~jardín","luz","tijeras","ventana"],"items":[{"q":"","ans":["el jardín"],"img":"img/gram/u06_ej6-3_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["la ventana"],"img":"img/gram/u06_ej6-3_02.png","alt":"Ilustración 2"},{"q":"","ans":["el agua"],"img":"img/gram/u06_ej6-3_03.png","alt":"Ilustración 3"},{"q":"","ans":["el diccionario"],"img":"img/gram/u06_ej6-3_04.png","alt":"Ilustración 4"},{"q":"","ans":["la luz"],"img":"img/gram/u06_ej6-3_05.png","alt":"Ilustración 5"},{"q":"","ans":["las tijeras"],"img":"img/gram/u06_ej6-3_06.png","alt":"Ilustración 6"}]},{"id":"gram:6.4","type":"cloze","lab":"6.4","title":"6.4","instr":"Complete las siguientes frases con el, la, los, las (utilice al y del cuando sea necesario).","items":[{"tpl":"___ águilas son aves.","blanks":1,"ans":["Las"],"example":true},{"tpl":"Montevideo es ___ capital de Uruguay.","blanks":1,"ans":["la"]},{"tpl":"Queremos ver a ___ jefe de estudios.","blanks":1,"ans":["al"]},{"tpl":"Cierra ___ puerta de ___ jardín, por favor.","blanks":2,"ans":["la del"]},{"tpl":"Tenéis que ir a ___ aula 15.","blanks":1,"ans":["al"]},{"tpl":"___ agua es mi bebida preferida.","blanks":1,"ans":["El"]},{"tpl":"___ padres de Sofía viven en Lima.","blanks":1,"ans":["Los"]},{"tpl":"Me gustan ___ naranjas.","blanks":1,"ans":["las"]},{"tpl":"Vivimos cerca de ___ centro.","blanks":1,"ans":["del"]},{"tpl":"Ese coche es de ___ padre de Mónica.","blanks":1,"ans":["del"]}]}]},{"id":7,"name":"Contraste entre el artículo determinado y el indeterminado","motto":"un perro / el perro","theory":[{"k":"h","t":"Compare"},{"k":"p","t":"<b>Artículo indeterminado</b>"},{"k":"img","src":"img/gram/u07_teoria-indet.png","alt":"«Tengo un loro y un perro». «Estoy leyendo un libro sobre una cantante»."},{"k":"p","t":"Se usa <i>un, una, unos, unas</i> cuando se habla por primera vez de algo nuevo para el oyente (información nueva)."},{"k":"p","t":"<b>Artículo determinado</b>"},{"k":"img","src":"img/gram/u07_teoria-det.png","alt":"«El loro se llama Ricky y el perro se llama Trotski». «El libro se titula Mi vida. La cantante tiene…»."},{"k":"p","t":"Se usa <i>el, la, los, las</i> cuando se habla de algo ya mencionado (información conocida)."},{"k":"h","t":"Parte de una clase o grupo / algo único o específico"},{"k":"p","t":"<b>Indeterminado:</b> se usa <i>un, una, unos, unas</i> cuando se habla de una persona, animal o cosa como parte de una clase o grupo."},{"k":"eg","t":"<b>Un</b> hijo de Andrés es médico. (Andrés tiene tres hijos.)"},{"k":"eg","t":"Tucumán es <b>una</b> ciudad de Argentina. (Hay muchas ciudades en Argentina.)"},{"k":"eg","t":"He visto <b>una</b> película de terror. (Hay muchas películas de esa clase.)"},{"k":"eg","t":"Necesito alquilar <b>un</b> coche. (un coche cualquiera)"},{"k":"p","t":"<b>Determinado:</b> se usa <i>el, la, los, las</i> cuando se habla de una persona, animal o cosa único o específico (único en la situación)."},{"k":"eg","t":"<b>La</b> hija de Rosa es escritora. (Rosa solo tiene una hija.)"},{"k":"eg","t":"Buenos Aires es <b>la</b> capital de Argentina. (Argentina tiene solo una capital.)"},{"k":"eg","t":"<b>Los</b> actores eran muy malos. (los actores de la película)"},{"k":"eg","t":"Necesito arreglar <b>el</b> coche. (Es mi coche.)"},{"k":"h","t":"Cantidad / sentido general"},{"k":"p","t":"<b>Indeterminado:</b> se usa <i>un, una, unos, unas</i> para indicar cantidad."},{"k":"eg","t":"—<b>Un</b> melón, por favor."},{"k":"p","t":"<b>Determinado:</b> se usa <i>el, la, los, las</i> para hablar de algo en sentido general."},{"k":"eg","t":"—Me encanta <b>el</b> melón."}],"ex":[{"id":"gram:7.1","type":"cloze","lab":"7.1","title":"7.1","instr":"Complete los textos con un, una, unos, unas o el, la, los, las (utilice al o del cuando sea necesario).","items":[{"tpl":"He visto ___ película preciosa. Es ___ comedia. ___ actores son fabulosos. ___ película es sobre ___ médico que se enamora de ___ paciente. ___ médico no sabe cómo decírselo a ___ paciente. Esta tiene ___ hijo y ___ médico tiene ___ hija. ___ hijo de ___ paciente y ___ hija de ___ médico se conocen y se hacen amigos. ___ día dan ___ fiesta e invitan a sus padres a ___ fiesta. ___ película acaba con ___ boda de ___ padres.","blanks":21,"ans":["una una Los La un una El la un el una El la la del Un una la La la los"],"perBlank":true,"ctx":"Texto 1","exN":1},{"tpl":"Es ___ cuadro precioso. Se ve a ___ hombre y ___ mujer en ___ jardín. ___ hombre está leyendo ___ libro y ___ mujer está tumbada debajo de ___ árbol. En ___ ramas de ___ árbol hay ___ pájaros de muchos colores. ___ pájaros tienen ___ alas extendidas; parece que van a echarse a volar.","blanks":13,"ans":["un un una un El un la un las del unos Los las"],"perBlank":true,"ctx":"Texto 2"},{"tpl":"Mis hijos tienen ___ perro y ___ gato. ___ perro duerme en ___ jardín y ___ gato dentro de casa.","blanks":5,"ans":["un un El el el"],"perBlank":true,"ctx":"Texto 3"}]},{"id":"gram:7.2","type":"pick","lab":"7.2","title":"7.2","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"Chihuahua es [la|una] ciudad de México.","ans":["una"],"example":true},{"tpl":"He visto [la|una] película de acción. [El|Un] personaje principal era [el|un] detective.","ans":["una","El","un"]},{"tpl":"[La|Una] nueva película de Fernando Trueba es muy buena.","ans":["La"]},{"tpl":"Soy enfermero y trabajo en [el|un] hospital.","ans":["un"]},{"tpl":"Estoy leyendo [el|un] libro sobre [el|un] rey Juan Carlos.","ans":["un","el"]},{"tpl":"¿Qué es eso? ¿Es [la|una] televisión portátil?","ans":["una"]},{"tpl":"¿Quién es [el|un] primer ministro?","ans":["el"]},{"tpl":"Carmen trabaja en [el|un] hotel. Es recepcionista.","ans":["un"]},{"tpl":"[La|Una] novia de Arturo es brasileña.","ans":["La"]},{"tpl":"[El|Un] Sol es [la|una] estrella.","ans":["El","una"]},{"tpl":"Paco es [el|un] nombre español.","ans":["un"]},{"tpl":"—¿Dónde está Carlos? —En [la|una] cocina.","ans":["la"]},{"tpl":"Vivo en [el|un] centro de Lima.","ans":["el"]},{"tpl":"[La|Una] moto de Pedro es italiana.","ans":["La"]},{"tpl":"[La|Una] Luna gira alrededor de [la|una] Tierra.","ans":["La","la"]}]},{"id":"gram:7.3","type":"cloze","lab":"7.3","title":"7.3","instr":"Complete con un, una, unos, unas o el, la, los, las.","items":[{"tpl":"Me han regalado ___ bombones.","blanks":1,"ans":["unos"],"example":true},{"tpl":"No me gusta ___ chocolate.","blanks":1,"ans":["el"]},{"tpl":"___ piña, por favor.","blanks":1,"ans":["Una"]},{"tpl":"___ piña es mi fruta preferida.","blanks":1,"ans":["La"]},{"tpl":"Me encantan ___ cuadros de Dalí.","blanks":1,"ans":["los"]},{"tpl":"¿Te gustan ___ peras?","blanks":1,"ans":["las"]},{"tpl":"Me he comprado ___ vaqueros.","blanks":1,"ans":["unos"]},{"tpl":"Te he comprado ___ margaritas.","blanks":1,"ans":["unas"]},{"tpl":"Quiero comprarme ___ pantalones cortos.","blanks":1,"ans":["unos"]},{"tpl":"Me encanta ___ agua.","blanks":1,"ans":["el"]}]}]},{"id":8,"name":"El artículo determinado con nombres propios","motto":"el señor Alonso, la calle Mayor","theory":[{"k":"img","src":"img/gram/u08_teoria-senor-alonso.png","alt":"Un hombre saluda: «Buenos días, señor Alonso»."},{"k":"h","t":"El, la, los, las con nombres de personas"},{"k":"p","t":"Se usa <i>el, la, los, las</i> + <i>señor, señora, señorita, doctor, doctora, presidente, presidenta…</i> + (nombre +) apellido."},{"k":"eg","t":"<b>El</b> señor Alonso es mi jefe. <b>La</b> señora Gómez es muy amable. <b>La</b> doctora Blanco trabaja en este hospital."},{"k":"p","t":"No se usa <i>el, la, los, las</i> cuando se habla directamente a una persona."},{"k":"eg","t":"Buenos días, señor Alonso. Una llamada para usted, doctora Blanco."},{"k":"p","t":"No se usa <i>el, la, los, las</i> con <i>don/doña</i> + nombre propio."},{"k":"eg","t":"Julián es mi primo. Doña Rosa es maestra."},{"k":"h","t":"El, la, los, las con nombres de lugares"},{"k":"img","src":"img/gram/u08_teoria-donde-estudias.png","alt":"«Y tú, ¿dónde estudias?»"},{"k":"p","t":"Se usa <i>el, la</i> + nombres de calles, plazas, avenidas…"},{"k":"eg","t":"Marga vive en <b>la</b> avenida de América. Hay un cine nuevo en <b>la</b> calle Bolívar."},{"k":"p","t":"Se usa <i>el, la, los, las</i> + nombres de cines, hoteles, museos…"},{"k":"eg","t":"<b>el</b> (hotel) Ritz · <b>el</b> (cine) Gran Vía · <b>el</b> (teatro) Buenos Aires · <b>el</b> (Museo del) Prado · <b>la</b> (Universidad) Autónoma · <b>el</b> (hospital) Sotomayor"},{"k":"p","t":"Se usa <i>el, la, los, las</i> + nombres de ríos, lagos, mares, océanos, grupos de islas, montañas, desiertos…"},{"k":"eg","t":"<b>el</b> (río) Tajo, <b>el</b> Amazonas · <b>el</b> (lago) Titicaca · <b>el</b> (mar) Mediterráneo, <b>el</b> Caribe · <b>el</b> (océano) Pacífico, <b>el</b> Atlántico"},{"k":"eg","t":"<b>las</b> (islas) Canarias, <b>las</b> Antillas · <b>los</b> (montes) Pirineos, <b>los</b> Andes · <b>el</b> (desierto del) Sahara"},{"k":"p","t":"No se usa <i>el, la, los, las</i> con nombres de islas solas."},{"k":"eg","t":"Mallorca, Sicilia, Santo Domingo"},{"k":"note","h":"ATENCIÓN","rows":["<b>No</b> se usa artículo con nombres de ciudades, comunidades autónomas, estados, países, continentes…","Ciudades: <i>Barcelona, París, Santiago de Chile, Buenos Aires.</i>","Países, regiones…: <i>España, Alemania, Bolivia, Francia; Galicia, Andalucía, California.</i>","Continentes: <i>África, América del Sur.</i>","<b>Pero</b> con artículo: ciudades: <i>La Habana, El Escorial, La Haya, La Paz, Las Palmas, Los Ángeles, El Cairo.</i>","Países y regiones: <i>El Salvador, (la) India, (los) Estados Unidos, La Mancha, La Rioja, La Pampa.</i>"]}],"ex":[{"id":"gram:8.1","type":"cloze","lab":"8.1","title":"8.1","instr":"Complete con el, la, los, las cuando sea necesario. Escriba Ø cuando no haga falta ningún artículo.","items":[{"tpl":"¿Dónde vive ___ don José?","blanks":1,"ans":["Ø"],"example":true},{"tpl":"—Buenas tardes, ___ señor Alfonsín. —Buenas tardes, ___ Elena.","blanks":2,"ans":["Ø Ø"]},{"tpl":"___ doctora Castro está en la sexta planta.","blanks":1,"ans":["La"]},{"tpl":"¿Quién es ___ señora Jiménez?","blanks":1,"ans":["la"]},{"tpl":"Aquí trabaja ___ Josefa.","blanks":1,"ans":["Ø"]},{"tpl":"—Buenos días, ___ doctor Rojo. —Buenos días, ___ María.","blanks":2,"ans":["Ø Ø"]}]},{"id":"gram:8.2","type":"cloze","lab":"8.2","title":"8.2","instr":"Observe el mapa y complete las frases.","img":"img/gram/u08_ej8-2_mapa.png","alt":"Mapa de una ciudad con calle Mayor, plaza de España, avenida de América, plaza Real y paseo del Parque.","items":[{"tpl":"(Hotel Central) ___ está en ___.","blanks":2,"ans":["El Hotel Central la plaza de España"],"wide":true,"example":true,"exv":["El Hotel Central","la plaza de España"]},{"tpl":"(Museo Botero) ___ está en ___.","blanks":2,"ans":["El Museo Botero la calle Mayor"],"wide":true},{"tpl":"(Banco Nacional) ___ está en ___.","blanks":2,"ans":["El Banco Nacional el paseo del Parque"],"wide":true},{"tpl":"(Teatro Lorca) ___ está en ___.","blanks":2,"ans":["El Teatro Lorca la avenida de América"],"wide":true},{"tpl":"(Cine América) ___ está en ___.","blanks":2,"ans":["El Cine América la plaza Real"],"wide":true},{"tpl":"(Hospital Universitario) ___ está en ___.","blanks":2,"ans":["El Hospital Universitario el paseo del Parque"],"wide":true}]},{"id":"gram:8.3","type":"cloze","lab":"8.3","title":"8.3","instr":"Complete las frases con los nombres y el, la, los, las cuando sea necesario.","items":[{"tpl":"(Habana, Cuba) ___ es la capital de ___.","blanks":2,"ans":["La Habana Cuba"],"wide":true,"example":true,"exv":["La Habana","Cuba"]},{"tpl":"(India, Asia) ___ está en ___.","blanks":2,"ans":["La India Asia","India Asia"],"wide":true},{"tpl":"(Islas Galápagos, Ecuador) ___ están en ___.","blanks":2,"ans":["Las islas Galápagos Ecuador"],"wide":true},{"tpl":"(Salvador, Guatemala, Honduras) ___ tiene frontera con ___ y ___.","blanks":3,"ans":["El Salvador Guatemala Honduras"],"wide":true},{"tpl":"(Ángeles, California) ___ está en ___.","blanks":2,"ans":["Los Ángeles California"],"wide":true},{"tpl":"(Lago Titicaca, Perú, Bolivia) ___ está entre ___ y ___.","blanks":3,"ans":["El lago Titicaca Perú Bolivia"],"wide":true},{"tpl":"(Amazonas, América del Sur) ___ es el río más largo de ___.","blanks":2,"ans":["El Amazonas América del Sur"],"wide":true},{"tpl":"(Jamaica, mar Caribe) ___ está en ___.","blanks":2,"ans":["Jamaica el mar Caribe"],"wide":true},{"tpl":"(Puerto Rico, islas Antillas) ___ es una de ___.","blanks":2,"ans":["Puerto Rico las islas Antillas"],"wide":true},{"tpl":"(Francia, Europa) ___ es un país de ___.","blanks":2,"ans":["Francia Europa"],"wide":true},{"tpl":"(Pampa, Argentina) ___ es una región de ___.","blanks":2,"ans":["La Pampa Argentina"],"wide":true},{"tpl":"(Pirineos, España, Francia) ___ separan ___ de ___.","blanks":3,"ans":["Los Pirineos España Francia"],"wide":true}]},{"id":"gram:8.4","type":"pick","lab":"8.4","title":"8.4","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"¿Has estado en [el|Ø] Museo del Prado?","ans":["el"],"example":true},{"tpl":"[El|Ø] Felipe estudia en [la|Ø] Universidad de Alcalá.","ans":["Ø","la"]},{"tpl":"[La|Ø] doctora Soria trabaja en [el|Ø] Hospital Doce de Octubre.","ans":["La","el"]},{"tpl":"El hermano de Ana vive en [La|Ø] Paz.","ans":["La"]},{"tpl":"[El|Ø] Cairo es la capital de [El|Ø] Egipto.","ans":["El","Ø"]},{"tpl":"[El|Ø] Pancho vive en [El|Ø] Monterrey.","ans":["Ø","Ø"]},{"tpl":"Este queso es de [La|Ø] Mancha.","ans":["La"]},{"tpl":"[El|Ø] cine Cartago está en [la|Ø] calle Buenos Aires.","ans":["El","la"]}]}]},{"id":9,"name":"El artículo determinado con expresiones de tiempo y de cantidad","motto":"el seis de enero","theory":[{"k":"h","t":"Horas"},{"k":"p","t":"Se usa <i>la, las</i> + horas."},{"k":"img","src":"img/gram/u09_teoria-relojes.png","alt":"Dos relojes: «la una y diez» y «las dos»; un diálogo: «¿Qué hora es? – Las tres y cinco»."},{"k":"eg","t":"El partido es a <b>las</b> nueve."},{"k":"h","t":"Días de la semana y fechas"},{"k":"p","t":"Se usa <i>el</i> + días de la semana cuando se habla de un día específico."},{"k":"eg","t":"<b>El domingo</b> voy a una fiesta. (el domingo próximo)"},{"k":"eg","t":"<b>El sábado</b> estuve con Luisa. (el sábado pasado)"},{"k":"note","h":"PERO","rows":["–¿Qué día es hoy? –<b>Lunes</b>. Ayer fue <b>domingo</b>."]},{"k":"p","t":"Se usa <i>los</i> + días de la semana cuando se habla de una acción habitual."},{"k":"eg","t":"<b>Los miércoles</b> tengo clases de español. (todos los miércoles)"},{"k":"eg","t":"Mariano trabaja <b>los domingos</b>. (todos los domingos)"},{"k":"p","t":"Se usa <i>el</i> + fechas."},{"k":"img","src":"img/gram/u09_teoria-fechas.png","alt":"Diálogo: «¿Cuándo es tu cumpleaños? – El seis de enero»."},{"k":"eg","t":"Me examino <b>el doce</b> de junio."},{"k":"note","h":"PERO","rows":["–¿Qué día es hoy? –<b>Cinco</b> de marzo. Ayer fue <b>cuatro</b> de marzo."]},{"k":"note","h":"ATENCIÓN","rows":["día de la semana + fecha → solo un artículo","<i>El examen es <b>el jueves</b>. + El examen es <b>el veinte de junio</b>. → El examen es <b>el jueves, veinte de junio</b>.</i>","No se usa artículo con los nombres de los meses: <i>Mi cumpleaños es en <b>octubre</b>.</i>"]},{"k":"h","t":"Partes del día"},{"k":"p","t":"Se usa <i>por la</i> + partes del día (<i>mañana, tarde, noche</i>)."},{"k":"eg","t":"Trabajo <b>por la mañana</b> y estudio <b>por la tarde</b>."},{"k":"note","h":"PERO","rows":["<i>a mediodía, de madrugada</i>: Voy a casa <b>a mediodía</b>. El camión de la basura pasa <b>de madrugada</b>."]},{"k":"h","t":"Cantidad o frecuencia"},{"k":"p","t":"Cantidad o frecuencia (<i>una vez, cuatro horas, cinco días…</i>) + <i>al/a la</i> + período de tiempo."},{"k":"eg","t":"Ando una hora <b>al</b> día. Vamos al cine dos veces <b>al</b> mes. Voy al gimnasio dos días <b>a la</b> semana."},{"k":"h","t":"Unidades de medida"},{"k":"p","t":"Se usa <i>el, la, los, las</i> + unidades de medidas (<i>kilo, litro, docena…</i>)."},{"k":"eg","t":"El aceite de oliva ha subido veinte céntimos <b>el</b> litro. Los plátanos cuestan dos euros <b>el</b> kilo."}],"ex":[{"id":"gram:9.1","type":"type","lab":"9.1","title":"9.1","instr":"Escriba las horas utilizando las palabras del recuadro y la o las.","long":true,"bank":["cuatro menos diez","doce y cinco","dos","ocho y media","once y cuarto","~tres y veinte","una menos cuarto","una y veinticinco"],"items":[{"q":"","ans":["las tres y veinte"],"img":"img/gram/u09_ej9-1_01.png","alt":"Reloj 1","example":true},{"q":"","ans":["la una y veinticinco"],"img":"img/gram/u09_ej9-1_02.png","alt":"Reloj 2"},{"q":"","ans":["las cuatro menos diez"],"img":"img/gram/u09_ej9-1_03.png","alt":"Reloj 3"},{"q":"","ans":["las dos"],"img":"img/gram/u09_ej9-1_04.png","alt":"Reloj 4"},{"q":"","ans":["las ocho y media"],"img":"img/gram/u09_ej9-1_05.png","alt":"Reloj 5"},{"q":"","ans":["las doce y cinco"],"img":"img/gram/u09_ej9-1_06.png","alt":"Reloj 6"},{"q":"","ans":["la una menos cuarto"],"img":"img/gram/u09_ej9-1_07.png","alt":"Reloj 7"},{"q":"","ans":["las once y cuarto"],"img":"img/gram/u09_ej9-1_08.png","alt":"Reloj 8"}]},{"id":"gram:9.2","type":"cloze","lab":"9.2","title":"9.2","instr":"Complete con el, la, los, las cuando sea necesario. Escriba Ø cuando no haga falta ningún artículo.","items":[{"tpl":"Mi cumpleaños es ___ doce de febrero.","blanks":1,"ans":["el"],"example":true},{"tpl":"___ martes tenemos clase de español.","blanks":1,"ans":["El","Los"]},{"tpl":"Normalmente estudiamos por ___ noche.","blanks":1,"ans":["la"]},{"tpl":"Felipe se casa ___ martes, ___ trece de julio.","blanks":2,"ans":["el Ø"]},{"tpl":"La fiesta es ___ domingo a ___ siete.","blanks":2,"ans":["el las"]},{"tpl":"Hoy es ___ jueves, ___ cuatro de ___ octubre.","blanks":3,"ans":["Ø Ø Ø"]},{"tpl":"El partido es a ___ diez.","blanks":1,"ans":["las"]},{"tpl":"Trabajo por ___ tarde y estudio por ___ mañana.","blanks":2,"ans":["la la"]},{"tpl":"Nací ___ dos de ___ diciembre.","blanks":2,"ans":["el Ø"]},{"tpl":"Diana sale siempre ___ sábados.","blanks":1,"ans":["los"]},{"tpl":"Tengo vacaciones en ___ agosto.","blanks":1,"ans":["Ø"]},{"tpl":"Tenemos un examen ___ lunes.","blanks":1,"ans":["el"]}]},{"id":"gram:9.3","type":"cloze","lab":"9.3","title":"9.3","instr":"Complete las frases.","items":[{"tpl":"(8 horas, día) Duermo ___.","blanks":1,"ans":["ocho horas al día"],"wide":true,"example":true},{"tpl":"(2 días, semana) Voy al gimnasio ___.","blanks":1,"ans":["dos días a la semana"],"wide":true},{"tpl":"(1 vez, año) Vamos de vacaciones ___.","blanks":1,"ans":["una vez al año"],"wide":true},{"tpl":"(2 veces, mes) Voy al cine ___.","blanks":1,"ans":["dos veces al mes"],"wide":true},{"tpl":"(1 noche, semana) Salimos ___.","blanks":1,"ans":["una noche a la semana"],"wide":true},{"tpl":"(1 hora, día) Corro ___.","blanks":1,"ans":["una hora al día"],"wide":true}]},{"id":"gram:9.4","type":"cloze","lab":"9.4","title":"9.4","instr":"Escriba los precios como en el ejemplo.","long":true,"items":[{"tpl":"___ de kiwis.","blanks":1,"ans":["Dos euros el kilo"],"img":"img/gram/u09_ej9-4_01.png","alt":"Precio 1","wide":true,"example":true},{"tpl":"___ de leche.","blanks":1,"ans":["Cuatro pesos el litro"],"img":"img/gram/u09_ej9-4_02.png","alt":"Precio 2","wide":true},{"tpl":"___ de huevos.","blanks":1,"ans":["Dos euros la docena"],"img":"img/gram/u09_ej9-4_03.png","alt":"Precio 3","wide":true},{"tpl":"___ de queso.","blanks":1,"ans":["Un peso los 100 gramos","Un peso los cien gramos"],"img":"img/gram/u09_ej9-4_04.png","alt":"Precio 4","wide":true}]}]},{"id":10,"name":"Otros usos del artículo determinado","motto":"tocar la guitarra","theory":[{"k":"img","src":"img/gram/u10_teoria-piano.png","alt":"«Juan toca el piano muy bien…, pero necesita un piano nuevo»."},{"k":"h","t":"Se usa el, la, los, las en los casos siguientes"},{"k":"p","t":"<b>tocar el piano, la guitarra…</b>"},{"k":"eg","t":"Ana está aprendiendo a tocar <b>el piano</b>."},{"k":"note","h":"PERO","rows":["tener, necesitar, comprar <i>una</i> guitarra, <i>un</i> piano…: Tengo <b>una</b> guitarra española."]},{"k":"p","t":"<b>jugar al fútbol, al tenis, al ajedrez, a las cartas…</b>"},{"k":"eg","t":"¿Sabes jugar <b>al</b> ajedrez? Jugamos <b>al</b> fútbol todos los domingos."},{"k":"note","h":"PERO","rows":["hacer gimnasia, natación, alpinismo: Hago <b>gimnasia</b> todas las mañanas."]},{"k":"p","t":"<b>las matemáticas, la lengua, el griego, el español…</b>"},{"k":"eg","t":"Mi asignatura preferida son <b>las</b> matemáticas. <b>El</b> griego es una lengua muy sonora."},{"k":"img","src":"img/gram/u10_teoria-chino.png","alt":"«El chino es muy difícil»."},{"k":"note","h":"PERO","rows":["No con <i>hablar, saber, enseñar, estudiar…</i>: Claudia estudia <b>Filosofía</b>. ¿Usted habla <b>chino</b>?"]},{"k":"p","t":"<b>la policía, el ejército, los bomberos.</b>"},{"k":"eg","t":"El tío de Andrés es capitán <b>del</b> ejército. Luis quiere ingresar en <b>la</b> policía."},{"k":"p","t":"<b>la radio, la televisión, el periódico, las noticias.</b>"},{"k":"eg","t":"Me gusta escuchar música en <b>la</b> radio. Siempre escuchamos <b>las</b> noticias de las nueve. ¿Has leído <b>el</b> periódico hoy?"},{"k":"note","h":"PERO","rows":["<i>una</i> radio, <i>una</i> televisión (aparatos), <i>una</i> noticia: Tengo <b>una</b> radio nueva. (un aparato) Me he comprado <b>una</b> televisión. (un aparato) Tengo <b>una</b> buena noticia."]},{"k":"img","src":"img/gram/u10_teoria-campo.png","alt":"«¿Prefieres vivir en una ciudad o en el campo?»"},{"k":"p","t":"<b>el mar, el campo, la playa, el cielo, la naturaleza.</b>"},{"k":"eg","t":"Es muy sano bañarse en <b>el</b> mar. Vamos <b>al</b> campo todos los fines de semana. Hay que proteger <b>la</b> naturaleza."},{"k":"p","t":"<b>ir al… / venir del… / estar en el…</b> hospital, cine, teatro, dentista, médico, banco, aeropuerto, lavabo, trabajo, colegio."},{"k":"eg","t":"¿Puedo ir <b>al</b> servicio, por favor? La madre de Rosa está en <b>el</b> hospital. Mis padres van hoy <b>al</b> teatro."},{"k":"p","t":"<b>ir a la… / venir de la… / estar en la…</b> iglesia, universidad, cárcel, oficina."},{"k":"eg","t":"Mi hermana está en <b>la</b> universidad. Los domingos voy a <b>la</b> iglesia."},{"k":"note","h":"PERO","rows":["<i>ir a… / venir de… / estar en…</i> casa, correos, clase: Voy a <b>correos</b> a enviar un paquete. Edgar está en <b>casa</b> desde las doce."]},{"k":"img","src":"img/gram/u10_teoria-dentista.png","alt":"«Vengo del dentista»."}],"ex":[{"id":"gram:10.1","type":"cloze","lab":"10.1","title":"10.1","instr":"Observe las ilustraciones y complete las frases utilizando las palabras del recuadro y el, la, los, las, al.","long":true,"bank":["ajedrez","cartas","fútbol","~guitarra","piano","tenis","trompeta","violín"],"items":[{"tpl":"Santi toca ___","blanks":1,"ans":["la guitarra"],"img":"img/gram/u10_ej10-1_01.png","alt":"Ilustración 1","wide":true,"example":true},{"tpl":"Elsa toca ___","blanks":1,"ans":["el violín"],"img":"img/gram/u10_ej10-1_02.png","alt":"Ilustración 2","wide":true},{"tpl":"Rosa juega a ___","blanks":1,"ans":["al ajedrez","el ajedrez"],"img":"img/gram/u10_ej10-1_03.png","alt":"Ilustración 3","wide":true},{"tpl":"Elena toca ___","blanks":1,"ans":["el piano"],"img":"img/gram/u10_ej10-1_04.png","alt":"Ilustración 4","wide":true},{"tpl":"Inés juega a ___","blanks":1,"ans":["al fútbol","el fútbol"],"img":"img/gram/u10_ej10-1_05.png","alt":"Ilustración 5","wide":true},{"tpl":"Pepe juega a ___","blanks":1,"ans":["al tenis","el tenis"],"img":"img/gram/u10_ej10-1_06.png","alt":"Ilustración 6","wide":true},{"tpl":"Juan toca ___","blanks":1,"ans":["la trompeta"],"img":"img/gram/u10_ej10-1_07.png","alt":"Ilustración 7","wide":true},{"tpl":"Miguel juega a ___","blanks":1,"ans":["las cartas","a las cartas"],"img":"img/gram/u10_ej10-1_08.png","alt":"Ilustración 8","wide":true}]},{"id":"gram:10.2","type":"cloze","lab":"10.2","title":"10.2","instr":"Complete con el, la, los, las, al, del o un, una, unos, unas cuando sea necesario. Escriba Ø cuando no haga falta ningún artículo.","items":[{"tpl":"¡Fuego! Llamad a ___ bomberos.","blanks":1,"ans":["los"],"example":true},{"tpl":"¿Hablas ___ español?","blanks":1,"ans":["Ø"]},{"tpl":"___ griego no es difícil.","blanks":1,"ans":["El"]},{"tpl":"Este fin de semana vamos a ___ playa.","blanks":1,"ans":["la"]},{"tpl":"¿Has escuchado ___ noticias?","blanks":1,"ans":["las"]},{"tpl":"Susana estudia ___ Arquitectura.","blanks":1,"ans":["Ø"]},{"tpl":"Merche hace ___ gimnasia en el colegio.","blanks":1,"ans":["Ø"]},{"tpl":"El padre de Pepe es general ___ ejército.","blanks":1,"ans":["del"]},{"tpl":"___ Historia es una asignatura apasionante.","blanks":1,"ans":["La"]},{"tpl":"Los Martín tienen una casa en ___ campo.","blanks":1,"ans":["el"]},{"tpl":"Antonio tiene ___ guitarra eléctrica.","blanks":1,"ans":["una"]},{"tpl":"He comprado ___ televisión.","blanks":1,"ans":["una"]},{"tpl":"Escucho ___ radio por las mañanas.","blanks":1,"ans":["la"]},{"tpl":"¡Un ladrón! Llama a ___ policía.","blanks":1,"ans":["la"]},{"tpl":"Siempre leo ___ periódico después de desayunar.","blanks":1,"ans":["el"]}]},{"id":"gram:10.3","type":"cloze","lab":"10.3","title":"10.3","instr":"Complete las frases con las palabras del recuadro y con el, la, al o del si es necesario.","long":true,"bank":["cárcel","casa","colegio","cine","correos","hospital","médico","~universidad"],"items":[{"tpl":"Va a ___","blanks":1,"ans":["la universidad"],"img":"img/gram/u10_ej10-3_01.png","alt":"Ilustración 1","wide":true,"example":true},{"tpl":"Va a ___","blanks":1,"ans":["la cárcel"],"img":"img/gram/u10_ej10-3_02.png","alt":"Ilustración 2","wide":true},{"tpl":"Lo llevan a ___","blanks":1,"ans":["al hospital"],"img":"img/gram/u10_ej10-3_03.png","alt":"Ilustración 3","wide":true},{"tpl":"Está en ___","blanks":1,"ans":["casa"],"img":"img/gram/u10_ej10-3_04.png","alt":"Ilustración 4","wide":true},{"tpl":"Va a ___","blanks":1,"ans":["Correos"],"img":"img/gram/u10_ej10-3_05.png","alt":"Ilustración 5","wide":true},{"tpl":"Viene de ___","blanks":1,"ans":["del colegio"],"img":"img/gram/u10_ej10-3_06.png","alt":"Ilustración 6","wide":true},{"tpl":"Van a ___","blanks":1,"ans":["al cine"],"img":"img/gram/u10_ej10-3_07.png","alt":"Ilustración 7","wide":true},{"tpl":"Están en ___","blanks":1,"ans":["el médico"],"img":"img/gram/u10_ej10-3_08.png","alt":"Ilustración 8","wide":true}]}]},{"id":11,"name":"Omisión del nombre","motto":"el rojo, uno rojo","theory":[{"k":"img","src":"img/gram/u11_teoria-cabecera.png","alt":"Tres escenas: «¿Qué sombrero prefieres? – El grande»; «¿Qué tipo de bolígrafo quiere? – Quiero uno barato»; «Me gusta más el de la izquierda»."},{"k":"p","t":"<i>El, la, los, las</i> o <i>uno, una, unos, unas</i> se pueden usar en lugar de un nombre mencionado anteriormente o cuando no es necesario mencionarlo porque se sabe de qué se está hablando."},{"k":"h","t":"el, la, los, las o uno, una, unos, unas + adjetivo"},{"k":"eg","t":"–¿Qué camisa te gusta más? –<b>La verde</b>. (la camisa verde)"},{"k":"eg","t":"–¿Qué tipo de zapatos quiere? –Quiero <b>unos cómodos</b>. (unos zapatos cómodos)"},{"k":"eg","t":"–¿Quién es don Tomás? –<b>El delgado</b>. (el señor delgado)"},{"k":"h","t":"Compare"},{"k":"p","t":"<b>el, la, los, las</b> — cuando se habla de alguien o algo específico:"},{"k":"eg","t":"–¿Quién es Susi? –<b>La alta</b>. (la chica alta)"},{"k":"p","t":"<b>uno, una, unos, unas</b> — cuando se habla de una clase de objetos:"},{"k":"eg","t":"–¿Qué tipo de coche busca? –<b>Uno pequeño</b>. (un coche pequeño)"},{"k":"note","h":"ATENCIÓN","rows":["La forma del adjetivo (masculino, femenino, singular o plural) es la misma que la del nombre al que se refiere.","–¿Qué <b>zapatillas</b> te gustan más? –<b>Las rojas</b>."]},{"k":"h","t":"el, la, los, las + de + nombre = posesión, situación, materia"},{"k":"img","src":"img/gram/u11_teoria-hermana.png","alt":"«¿Cuál es la hermana de Andrés? – La del pelo largo»."},{"k":"eg","t":"Mi coche es peor que <b>el de</b> mi hermano. (el coche de mi hermano)"},{"k":"eg","t":"–¿Quién es Alicia? –<b>La del</b> vestido blanco. (la chica que tiene el vestido blanco)"},{"k":"eg","t":"Esas gafas no me gustan. Prefiero <b>las de la</b> derecha. (las gafas que están a la derecha)"},{"k":"eg","t":"–¿Qué pendientes te vas a poner? –<b>Los de</b> oro. (los pendientes de oro)"},{"k":"h","t":"lo + adjetivo masculino singular = la cosa, las cosas"},{"k":"img","src":"img/gram/u11_teoria-lo-dificil.png","alt":"Un hombre pensando: «Fui, quise, vaya, ponga». Pie: Lo difícil del español son los verbos."},{"k":"eg","t":"<b>Lo bueno</b> del verano son las vacaciones. (la cosa buena del verano)"},{"k":"eg","t":"<b>Lo mejor</b> de Perú es la gente. (la mejor cosa de Perú)"},{"k":"eg","t":"Me gusta <b>lo salado</b>. (las cosas saladas)"},{"k":"eg","t":"<b>Lo más bonito</b> de la vida son los amigos. (la cosa más bonita)"},{"k":"eg","t":"<b>Lo difícil</b> del español son los verbos."}],"ex":[{"id":"gram:11.1","type":"cloze","lab":"11.1","title":"11.1","instr":"Complete las frases con el, la, los, las o uno, una, unos, unas y los adjetivos entre paréntesis.","items":[{"tpl":"¿Qué zapatos prefieres, (negro, blanco) ___ o ___?","blanks":2,"ans":["los negros los blancos"],"example":true,"exv":["los negros","los blancos"]},{"tpl":"—¿Qué tipo de cuaderno quiere? —(pequeño) ___.","blanks":1,"ans":["uno pequeño"]},{"tpl":"—¿Te gustan estos sombreros? —(negro, marrón) Me gusta ___, pero no ___.","blanks":2,"ans":["el negro el marrón"]},{"tpl":"—¿Qué pantalones prefieres? —(rojo) ___. (blanco) ___ son muy caros.","blanks":2,"ans":["los rojos los blancos"]},{"tpl":"¿Ves a esas dos chicas? (alto) ___ es Marta.","blanks":1,"ans":["la alta"]},{"tpl":"—¿Qué tipo de libro quieres leer? —(entretenido) ___.","blanks":1,"ans":["uno entretenido"]},{"tpl":"¿Qué manzanas prefiere, (verde) ___ o (rojo) ___?","blanks":2,"ans":["las verdes las rojas"]},{"tpl":"Esta taza está sucia. Dame (limpio) ___, por favor.","blanks":1,"ans":["una limpia"]},{"tpl":"—¿Qué clase de cámara quiere? —Quiero (bueno) ___, aunque sea cara.","blanks":1,"ans":["una buena"]},{"tpl":"—¿Tienes ordenador? —Sí, tengo (portátil) ___.","blanks":1,"ans":["uno portátil"]}]},{"id":"gram:11.2","type":"cloze","lab":"11.2","title":"11.2","instr":"Observe las ilustraciones y complete las frases con el, la, los o las, con de y con las palabras dadas.","long":true,"items":[{"tpl":"___","blanks":1,"ans":["Las de la derecha"],"ctx":"derecha / izquierda","img":"img/gram/u11_ej11-2_01.png","alt":"Escena 1","wide":true,"example":true},{"tpl":"___","blanks":1,"ans":["El del pelo corto"],"ctx":"pelo corto / pelo largo","img":"img/gram/u11_ej11-2_02.png","alt":"Escena 2","wide":true},{"tpl":"Me gusta más ___","blanks":1,"ans":["la de la izquierda"],"ctx":"derecha / izquierda","img":"img/gram/u11_ej11-2_03.png","alt":"Escena 3","wide":true},{"tpl":"___","blanks":1,"ans":["Las de chocolate"],"ctx":"chocolate / coco","img":"img/gram/u11_ej11-2_04.png","alt":"Escena 4","wide":true},{"tpl":"___","blanks":1,"ans":["La de la falda larga"],"ctx":"falda corta / falda larga","img":"img/gram/u11_ej11-2_05.png","alt":"Escena 5","wide":true},{"tpl":"___","blanks":1,"ans":["Los de arriba"],"ctx":"abajo / arriba","img":"img/gram/u11_ej11-2_06.png","alt":"Escena 6","wide":true},{"tpl":"Quiero ___","blanks":1,"ans":["el de Sandra Arenas"],"ctx":"José Crespo / Sandra Arenas","img":"img/gram/u11_ej11-2_07.png","alt":"Escena 7","wide":true},{"tpl":"___","blanks":1,"ans":["El del bigote"],"ctx":"barba / bigote","img":"img/gram/u11_ej11-2_08.png","alt":"Escena 8","wide":true}]},{"id":"gram:11.3","type":"cloze","lab":"11.3","title":"11.3","instr":"Complete las frases con el, la, los, las o lo y los adjetivos entre paréntesis.","items":[{"tpl":"¿Qué es (mejor) ___ de Cuba?","blanks":1,"ans":["lo mejor"],"example":true},{"tpl":"¿Qué naranjas prefiere, (caro, barato) ___ o ___?","blanks":2,"ans":["las caras las baratas"]},{"tpl":"No me gusta (amargo) ___.","blanks":1,"ans":["lo amargo"]},{"tpl":"(barato) ___ es siempre caro.","blanks":1,"ans":["lo barato"]},{"tpl":"¿Veis a aquel grupo de chicas? Mis hermanas son (moreno) ___.","blanks":1,"ans":["las morenas"]},{"tpl":"(importante) ___ es ser feliz.","blanks":1,"ans":["lo importante"]},{"tpl":"(malo) ___ del invierno es el frío.","blanks":1,"ans":["lo malo"]},{"tpl":"¿Qué pendientes te gustan más, (largo, corto) ___ o ___?","blanks":2,"ans":["los largos los cortos"]},{"tpl":"—¿Qué coche es el tuyo? —(pequeño) ___.","blanks":1,"ans":["el pequeño"]},{"tpl":"(pequeño) ___ es hermoso.","blanks":1,"ans":["lo pequeño"]}]}]},{"id":12,"name":"Demostrativos","motto":"este, ese, aquel…","theory":[{"k":"img","src":"img/gram/u12_teoria-libro-a.png","alt":"«Quiero este libro»."},{"k":"img","src":"img/gram/u12_teoria-libro-b.png","alt":"«Quiero ese libro»."},{"k":"img","src":"img/gram/u12_teoria-libro-c.png","alt":"«Quiero aquel libro»."},{"k":"p","t":"<i>Este, ese, aquel…</i> sirven para señalar algo o a alguien. Su forma (masculino, femenino, singular o plural) depende del nombre al que se refieren."},{"k":"p","t":"<b>cerca de mí:</b> <i>este, esta, estos, estas</i>"},{"k":"p","t":"<b>cerca de usted:</b> <i>ese, esa, esos, esas</i>"},{"k":"p","t":"<b>lejos de usted y de mí:</b> <i>aquel, aquella, aquellos, aquellas</i>"},{"k":"p","t":"masculino singular: <i>este / ese / aquel</i> · masculino plural: <i>estos / esos / aquellos</i> · femenino singular: <i>esta / esa / aquella</i> · femenino plural: <i>estas / esas / aquellas</i>"},{"k":"img","src":"img/gram/u12_teoria-escena-a.png","alt":"«¿Cuánto cuesta esta revista?»"},{"k":"img","src":"img/gram/u12_teoria-escena-b.png","alt":"«¿Cuánto cuesta esa revista?»"},{"k":"img","src":"img/gram/u12_teoria-escena-c.png","alt":"«¿Quiénes son aquellas chicas?»"},{"k":"note","h":"PERO","rows":["A veces se usa <i>ese, esa, esos, esas</i> para señalar algo que está lejos de usted y de mí."]},{"k":"img","src":"img/gram/u12_teoria-casa.png","alt":"«Me gusta esa casa»."},{"k":"p","t":"<i>Este, ese, aquel…</i> se usan con nombres. En estos casos, tienen la misma forma (masculino o femenino, singular o plural) que el nombre al que acompañan."},{"k":"eg","t":"<b>Esa</b> chica es amiga de Ana. <b>Estos</b> zapatos son muy caros."},{"k":"p","t":"<i>Este, ese, aquel…</i> se pueden usar también solos."},{"k":"eg","t":"¿Cuál es tu maleta, <b>esta</b>, <b>esa</b> o <b>aquella</b>? <b>Este</b> es Juan, mi novio."},{"k":"p","t":"<i>Este, ese, aquel…</i> sirven también para señalar en el tiempo."},{"k":"p","t":"<i>este</i> → presente o futuro próximo."},{"k":"eg","t":"<b>Este</b> año ha sido muy frío."},{"k":"p","t":"<i>ese</i> → pasado."},{"k":"eg","t":"Estuve en Perú en 1999. <b>Ese</b> año hubo elecciones."},{"k":"p","t":"<i>aquel</i> → pasado lejano."},{"k":"eg","t":"Los españoles llegaron a América en 1492. En <b>aquella</b> época, el imperio inca iba de Chile a Ecuador."},{"k":"p","t":"Se usa <i>esto, eso</i> y <i>aquello</i> para señalar algo sin decir el nombre: porque no se sabe qué es, o porque no es necesario decirlo."},{"k":"img","src":"img/gram/u12_teoria-esto.png","alt":"«¿Qué es esto? – No sé. Parece una lámpara.»"},{"k":"img","src":"img/gram/u12_teoria-eso.png","alt":"«¿De quién es eso?»"}],"ex":[{"id":"gram:12.1","type":"type","lab":"12.1","title":"12.1","instr":"Complete con este, ese, aquel… y las palabras del recuadro.","long":true,"bank":["árboles","bolso","gafas","~llaves","llaves","maleta","paraguas","revista"],"items":[{"q":"","ans":["Estas llaves"],"img":"img/gram/u12_ej12-1_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["Esa revista"],"img":"img/gram/u12_ej12-1_02.png","alt":"Ilustración 2"},{"q":"","ans":["Aquella maleta"],"img":"img/gram/u12_ej12-1_03.png","alt":"Ilustración 3"},{"q":"","ans":["Ese bolso"],"img":"img/gram/u12_ej12-1_04.png","alt":"Ilustración 4"},{"q":"","ans":["Estas gafas"],"img":"img/gram/u12_ej12-1_05.png","alt":"Ilustración 5"},{"q":"","ans":["Este paraguas"],"img":"img/gram/u12_ej12-1_06.png","alt":"Ilustración 6"},{"q":"","ans":["Aquellos árboles"],"img":"img/gram/u12_ej12-1_07.png","alt":"Ilustración 7"},{"q":"","ans":["Esas llaves"],"img":"img/gram/u12_ej12-1_08.png","alt":"Ilustración 8"}]},{"id":"gram:12.2","type":"type","lab":"12.2","title":"12.2","instr":"Complete con este, ese, aquel…","long":true,"items":[{"q":"","ans":["este"],"img":"img/gram/u12_ej12-2_01.png","alt":"Escena 1","example":true},{"q":"","ans":["ese","aquel","ese chico","aquel chico"],"img":"img/gram/u12_ej12-2_02.png","alt":"Escena 2"},{"q":"","ans":["Esta"],"img":"img/gram/u12_ej12-2_03.png","alt":"Escena 3"},{"q":"","ans":["Aquel","Ese"],"img":"img/gram/u12_ej12-2_04.png","alt":"Escena 4"},{"q":"","ans":["Este","Este vaso"],"img":"img/gram/u12_ej12-2_05.png","alt":"Escena 5"},{"q":"","ans":["estas","estas gafas"],"img":"img/gram/u12_ej12-2_06.png","alt":"Escena 6"},{"q":"","ans":["Aquella","Esa"],"img":"img/gram/u12_ej12-2_07.png","alt":"Escena 7"},{"q":"","ans":["este","este autobús"],"img":"img/gram/u12_ej12-2_08.png","alt":"Escena 8"}]},{"id":"gram:12.3","type":"cloze","lab":"12.3","title":"12.3","instr":"Complete las frases con este, ese, aquel…","items":[{"tpl":"___ verano vamos a ir a Ibiza.","blanks":1,"ans":["Este"],"example":true},{"tpl":"Nací en 1983. ___ mismo año nació mi prima.","blanks":1,"ans":["Ese"]},{"tpl":"—¿Qué haces ___ noche? —Nada. ___ semana tengo mucho trabajo.","blanks":2,"ans":["esta Esta"]},{"tpl":"2001 fue un año extraordinario. ___ verano conocí a Maite.","blanks":1,"ans":["Ese"]},{"tpl":"Mis padres vivieron en Perú entre 1950 y 1965. ___ fueron los mejores años de su vida.","blanks":1,"ans":["Aquellos"]},{"tpl":"___ mes ha sido fabuloso. He encontrado piso y trabajo.","blanks":1,"ans":["Este"]},{"tpl":"Luis se casó en 1970. En ___ época yo vivía en México.","blanks":1,"ans":["aquella"]},{"tpl":"___ tarde tengo un examen.","blanks":1,"ans":["Esta"]}]},{"id":"gram:12.4","type":"type","lab":"12.4","title":"12.4","instr":"Complete con esto, eso o aquello.","long":true,"items":[{"q":"","ans":["esto"],"img":"img/gram/u12_ej12-4_01.png","alt":"Escena 1","example":true},{"q":"","ans":["eso","aquello"],"img":"img/gram/u12_ej12-4_02.png","alt":"Escena 2"},{"q":"","ans":["eso"],"img":"img/gram/u12_ej12-4_03.png","alt":"Escena 3"},{"q":"","ans":["esto"],"img":"img/gram/u12_ej12-4_04.png","alt":"Escena 4"}]}]},{"id":13,"name":"Adjetivos calificativos","motto":"un coche pequeño","theory":[{"k":"img","src":"img/gram/u13_teoria-coche-casa.png","alt":"Un coche pequeño y una casa pequeña."},{"k":"img","src":"img/gram/u13_teoria-rosi.png","alt":"«Rosi es alta» (1,82 m). «Estamos cansados»."},{"k":"p","t":"<i>Pequeño, pequeña, alta</i> y <i>cansados</i> son adjetivos calificativos: añaden información sobre una persona, animal o cosa."},{"k":"h","t":"Formación del femenino y del plural"},{"k":"p","t":"<b>–o</b> → –a, –os, –as"},{"k":"eg","t":"un coche pequeño · una casa pequeña · unos chicos altos · unas chicas altas"},{"k":"p","t":"<b>–e</b> → –e, –es, –es"},{"k":"eg","t":"un chico inteligente · una chica inteligente · unos pantalones verdes · unas flores verdes"},{"k":"p","t":"<b>–consonante</b> → –consonante, +es, +es"},{"k":"eg","t":"un chico joven · una chica joven · unos calcetines azules · unas camisas azules"},{"k":"p","t":"<b>–or, –án, –ón, –ín</b> → +a, +es, +as"},{"k":"eg","t":"un chico encantador · una chica encantadora · unos hombres charlatanes · unas mujeres charlatanas"},{"k":"note","h":"PERO","rows":["un gorro <b>marrón</b> · una bufanda <b>marrón</b> · unos pantalones <b>marrones</b> · unas faldas <b>marrones</b>"]},{"k":"note","h":"ATENCIÓN","rows":["feliz – felices · joven – jóvenes · charlatán – charlatana · marrón – marrones"]},{"k":"p","t":"El adjetivo tiene la misma forma (masculino o femenino, singular o plural) que la persona, animal o cosa a la que se refiere."},{"k":"img","src":"img/gram/u13_teoria-moreno.png","alt":"«Yo soy moreno». «Yo soy morena»."},{"k":"eg","t":"Susana y Elena son muy <b>trabajadoras</b>. Me he comprado unos zapatos <b>negros</b>. En Guatemala hay ruinas muy <b>antiguas</b>."},{"k":"note","h":"ATENCIÓN","rows":["nombre masculino + nombre femenino = adjetivo plural masculino","Antonio y Marta son <b>altos</b> y <b>morenos</b>. Gabi lleva una camisa y un pantalón <b>negros</b>."]},{"k":"h","t":"Colocación del adjetivo"},{"k":"p","t":"<i>ser/estar</i> + adjetivo"},{"k":"eg","t":"Roberto <b>es simpático</b>. Juan <b>está muy delgado</b>."},{"k":"p","t":"nombre + adjetivo"},{"k":"eg","t":"María tiene los <b>ojos azules</b>."},{"k":"note","h":"PERO","rows":["<i>buen/buena</i> + nombre: Julio es un <b>buen</b> escritor. Luisa es una <b>buena</b> profesora.","<i>mal/mala</i> + nombre: Felipe es un <b>mal</b> ejemplo para sus hijos. Tengo una <b>mala</b> noticia."]}],"ex":[{"id":"gram:13.1","type":"cloze","lab":"13.1","title":"13.1","instr":"Complete las frases con la forma correcta de los adjetivos entre paréntesis.","items":[{"tpl":"Vivo en un piso (pequeño) ___.","blanks":1,"ans":["pequeño"],"mid":true,"example":true},{"tpl":"Rosa tiene los ojos (verde) ___. Es (rubio) ___ y tiene el pelo (corto) ___ y (rizado) ___. Es muy (simpático) ___ y (alegre) ___, y muy (charlatán) ___.","blanks":7,"ans":["verdes rubia corto rizado simpática alegre charlatana"],"mid":true},{"tpl":"Gerardo y Ana son muy (inteligente) ___.","blanks":1,"ans":["inteligentes"],"mid":true},{"tpl":"Me gustan las rosas (blanco) ___.","blanks":1,"ans":["blancas"],"mid":true},{"tpl":"Don Santiago es una persona (encantador) ___.","blanks":1,"ans":["encantadora"],"mid":true},{"tpl":"Chus y Lolo no son (feliz) ___. Están siempre (enfadado) ___.","blanks":2,"ans":["felices enfadados"],"mid":true},{"tpl":"Me he comprado una camisa (rojo) ___ y unos pantalones (gris) ___.","blanks":2,"ans":["roja grises"],"mid":true},{"tpl":"Eduardo es (alto) ___ y (fuerte) ___. Es (moreno) ___ y tiene los ojos (negro) ___. Es muy (guapo) ___, pero es un poco (antipático) ___.","blanks":6,"ans":["alto fuerte moreno negros guapo antipático"],"mid":true},{"tpl":"Begoña lleva una falda (marrón) ___ y una blusa (amarillo) ___.","blanks":2,"ans":["marrón amarilla"],"mid":true},{"tpl":"Concha y Rodrigo son muy (simpático) ___ y muy (trabajador) ___. Además son muy (amable) ___.","blanks":3,"ans":["simpáticos trabajadores amables"],"mid":true},{"tpl":"Las hijas de Andrés son muy (joven) ___.","blanks":1,"ans":["jóvenes"],"mid":true}]},{"id":"gram:13.2","type":"type","lab":"13.2","title":"13.2","instr":"Complete las frases con los adjetivos del recuadro.","long":true,"bank":["alegre","campeón","cansado","enfermo","fuerte","gordo","~rubio","triste"],"items":[{"q":"","ans":["rubias"],"img":"img/gram/u13_ej13-2_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["gordo"],"img":"img/gram/u13_ej13-2_02.png","alt":"Ilustración 2"},{"q":"","ans":["enferma"],"img":"img/gram/u13_ej13-2_03.png","alt":"Ilustración 3"},{"q":"","ans":["tristes"],"img":"img/gram/u13_ej13-2_04.png","alt":"Ilustración 4"},{"q":"","ans":["alegre"],"img":"img/gram/u13_ej13-2_05.png","alt":"Ilustración 5"},{"q":"","ans":["cansadas"],"img":"img/gram/u13_ej13-2_06.png","alt":"Ilustración 6"},{"q":"","ans":["fuerte"],"img":"img/gram/u13_ej13-2_07.png","alt":"Ilustración 7"},{"q":"","ans":["campeones"],"img":"img/gram/u13_ej13-2_08.png","alt":"Ilustración 8"}]},{"id":"gram:13.3","type":"cloze","lab":"13.3","title":"13.3","instr":"Complete las frases con un nombre y un adjetivo del recuadro.","bank":["color","comida","edificio","flor","~ojo","idioma","profesor","ropa","antiguo","~azul","bueno","fácil","nuevo","preferido","preferido","rojo"],"items":[{"tpl":"Susana tiene los ___.","blanks":1,"ans":["ojos azules"],"wide":true,"example":true},{"tpl":"La amapola es una ___.","blanks":1,"ans":["flor roja"],"wide":true},{"tpl":"El español es un ___.","blanks":1,"ans":["idioma fácil"],"wide":true},{"tpl":"Don Tomás es un ___.","blanks":1,"ans":["buen profesor"],"wide":true},{"tpl":"La ___ de Peter es la tortilla de patatas.","blanks":1,"ans":["comida preferida"],"wide":true},{"tpl":"En Toledo hay muchos ___.","blanks":1,"ans":["edificios antiguos"],"wide":true},{"tpl":"Esta camisa y estos pantalones están muy viejos. Necesito ___.","blanks":1,"ans":["ropa nueva"],"wide":true},{"tpl":"Mi ___ es el rojo.","blanks":1,"ans":["color preferido"],"wide":true}]}]},{"id":14,"name":"Adjetivos de nacionalidad","motto":"una amiga chilena","theory":[{"k":"img","src":"img/gram/u14_teoria-elsa.png","alt":"«Esta es Elsa, una amiga chilena»."},{"k":"img","src":"img/gram/u14_teoria-cubanos.png","alt":"«¿De dónde sois? – Somos cubanos. ¿Y tú? – Yo soy español»."},{"k":"h","t":"Formación del femenino y del plural"},{"k":"p","t":"<b>–o</b> → –a, –os, –as"},{"k":"eg","t":"chileno, cubano · chilena, cubana · chilenos, cubanos · chilenas, cubanas"},{"k":"eg","t":"Donoso es un escritor <b>chileno</b>. Isabel Allende es una escritora <b>chilena</b>. Los puros <b>cubanos</b> son de gran calidad."},{"k":"p","t":"<b>–a, –e, –í</b> → –a, –e, –í (masculino y femenino iguales); plural: –as, –es, –ís (o –íes)"},{"k":"eg","t":"belga · canadiense · marroquí · plural: belgas, canadienses, marroquís / marroquíes"},{"k":"eg","t":"La capital <b>belga</b> es Bruselas. La bandera <b>canadiense</b> es roja y blanca. La capital <b>marroquí</b> es Rabat. Me encantan los bombones <b>belgas</b>."},{"k":"p","t":"<b>–consonante</b> → +a, +es, +as"},{"k":"eg","t":"portugués, alemán, español · portuguesa, alemana, española · portugueses, alemanes, españoles · portuguesas, alemanas, españolas"},{"k":"eg","t":"Bild es una revista <b>alemana</b>. A Carla le gusta mucho la comida <b>española</b>. Faro y Oporto son ciudades <b>portuguesas</b>."},{"k":"note","h":"ATENCIÓN","rows":["portugués → portuguesa, portugueses, portuguesas","alemán → alemana, alemanes, alemanas"]},{"k":"h","t":"Masculino + femenino = plural masculino"},{"k":"eg","t":"Iván es cubano. Haydée es cubana. → Iván y Haydée son <b>cubanos</b>."},{"k":"eg","t":"Tengo unos sellos y unas monedas <b>rusos</b>."},{"k":"h","t":"Colocación del adjetivo"},{"k":"p","t":"<i>ser</i> + adjetivo"},{"k":"eg","t":"Gabriel García Márquez <b>es colombiano</b>."},{"k":"p","t":"nombre + adjetivo"},{"k":"eg","t":"La <b>bandera argentina</b> es azul y blanca."}],"ex":[{"id":"gram:14.1","type":"cloze","lab":"14.1","title":"14.1","instr":"Complete la lista.","items":[{"tpl":"brasileño → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["brasileña brasileños brasileñas"],"wide":true,"example":true},{"tpl":"costarricense → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["costarricense costarricenses costarricenses"],"wide":true},{"tpl":"escocés → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["escocesa escoceses escocesas"],"wide":true},{"tpl":"iraní → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["iraní iranís iranís","iraní iranís iraníes","iraní iraníes iranís","iraní iraníes iraníes"],"wide":true},{"tpl":"japonés → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["japonesa japoneses japonesas"],"wide":true},{"tpl":"nicaragüense → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["nicaragüense nicaragüenses nicaragüenses"],"wide":true},{"tpl":"venezolano → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["venezolana venezolanos venezolanas"],"wide":true},{"tpl":"vietnamita → femenino: ___ · plural masculino: ___ · plural femenino: ___","blanks":3,"ans":["vietnamita vietnamitas vietnamitas"],"wide":true}]},{"id":"gram:14.2","type":"type","lab":"14.2","title":"14.2","instr":"Complete las frases con los adjetivos del recuadro.","long":true,"bank":["chino","egipcio","francés","indio","italiano","mexicano","~peruano","ruso"],"items":[{"q":"","ans":["peruana"],"img":"img/gram/u14_ej14-2_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["chinas"],"img":"img/gram/u14_ej14-2_02.png","alt":"Ilustración 2"},{"q":"","ans":["egipcios"],"img":"img/gram/u14_ej14-2_03.png","alt":"Ilustración 3"},{"q":"","ans":["francesa"],"img":"img/gram/u14_ej14-2_04.png","alt":"Ilustración 4"},{"q":"","ans":["italianas"],"img":"img/gram/u14_ej14-2_05.png","alt":"Ilustración 5"},{"q":"","ans":["mexicanos"],"img":"img/gram/u14_ej14-2_06.png","alt":"Ilustración 6"},{"q":"","ans":["india"],"img":"img/gram/u14_ej14-2_07.png","alt":"Ilustración 7"},{"q":"","ans":["rusos"],"img":"img/gram/u14_ej14-2_08.png","alt":"Ilustración 8"}]},{"id":"gram:14.3","type":"cloze","lab":"14.3","title":"14.3","instr":"Complete las frases con un nombre y un adjetivo de cada recuadro.","bank":["actriz","capital","capital","ciudad","ciudad","escritor","moneda","~moneda","canadiense","colombiano","estadounidense","francés","~japonés","marroquí","portugués","vietnamita"],"items":[{"tpl":"El yen es la ___.","blanks":1,"ans":["moneda japonesa"],"wide":true,"example":true},{"tpl":"El dirham es la ___.","blanks":1,"ans":["moneda marroquí"],"wide":true},{"tpl":"Gabriel García Márquez es un ___.","blanks":1,"ans":["escritor colombiano"],"wide":true},{"tpl":"Burdeos es una ___.","blanks":1,"ans":["ciudad francesa"],"wide":true},{"tpl":"Julia Roberts es una ___.","blanks":1,"ans":["actriz estadounidense"],"wide":true},{"tpl":"Hanoi es la ___.","blanks":1,"ans":["capital vietnamita"],"wide":true},{"tpl":"Montreal y Edmonton son ___.","blanks":1,"ans":["ciudades canadienses"],"wide":true},{"tpl":"Lisboa es la ___.","blanks":1,"ans":["capital portuguesa"],"wide":true}]}]},{"id":15,"name":"Forma comparativa de los adjetivos (1)","motto":"más caro, menos trabajador","theory":[{"k":"img","src":"img/gram/u15_teoria-relojes.png","alt":"Dos relojes: el Regina (130 €) es más caro que el Relomátic (120 €)."},{"k":"img","src":"img/gram/u15_teoria-jirafa.png","alt":"Una jirafa es más alta que un oso."},{"k":"img","src":"img/gram/u15_teoria-marta.png","alt":"Marta es menos trabajadora que Laura."},{"k":"p","t":"<i>Más caro, más alta</i> y <i>menos trabajadora</i> son formas comparativas de los adjetivos. Se usan para comparar dos personas, animales o cosas."},{"k":"h","t":"Formación del comparativo"},{"k":"p","t":"<b>Superioridad (+)</b> → <i>más</i> + adjetivo (+ <i>que</i>)"},{"k":"eg","t":"Felipe es <b>más alto que</b> su hermana. Y <b>más fuerte</b>. Necesitamos un piso <b>más grande</b>."},{"k":"p","t":"<b>Inferioridad (–)</b> → <i>menos</i> + adjetivo (+ <i>que</i>)"},{"k":"eg","t":"Clara es <b>menos trabajadora que</b> Gilberto."},{"k":"p","t":"<b>Formas irregulares:</b> + viejo → <i>mayor</i> · – viejo → <i>menor</i> · + bueno → <i>mejor</i> · – bueno → <i>peor</i>"},{"k":"img","src":"img/gram/u15_teoria-eva-javi.png","alt":"Eva, 24 años. Javi, 20 años."},{"k":"eg","t":"Eva es <b>mayor</b> que Javi. Javi es <b>menor</b> que Eva."},{"k":"img","src":"img/gram/u15_teoria-coches.png","alt":"Dos coches: el de Ana y el de Álvaro."},{"k":"eg","t":"El coche de Ana es <b>mejor</b> que el de Álvaro. El coche de Álvaro es <b>peor</b> que el de Ana."},{"k":"p","t":"El adjetivo tiene la misma forma (masculino o femenino, singular o plural) que la persona, animal o cosa a la que se refiere."},{"k":"eg","t":"Mis hermanos son más <b>altos</b> que yo. Marta es menos <b>trabajadora</b> que Raúl. Estas camisas son más <b>caras</b>."},{"k":"note","h":"PERO","rows":["<i>mayor/menor/mejor/peor</i> → singular (masculino y femenino); <i>mayores/menores/mejores/peores</i> → plural (masculino y femenino).","Eva es <b>mayor</b> que Javi, pero Javi es <b>mayor</b> que su hermano. Estas camisas son más baratas, pero son <b>peores</b>."]},{"k":"h","t":"Más/menos… que + pronombre personal sujeto"},{"k":"eg","t":"Eres más fuerte <s>que mí</s> → Eres más fuerte <b>que yo</b>. Somos menos altos <b>que vosotros</b>."},{"k":"p","t":"A veces no es necesario mencionar la persona o cosa con la que se compara algo."},{"k":"eg","t":"Este piso es pequeño. Yo quiero uno <b>más grande</b>."}],"ex":[{"id":"gram:15.1","type":"cloze","lab":"15.1","title":"15.1","instr":"Complete las frases con la forma comparativa adecuada.","items":[{"tpl":"¿Quién es (+ guapo) ___, Juan o su hermano?","blanks":1,"ans":["más guapo"],"example":true},{"tpl":"¿Quién es (– caprichoso) ___, Alberto o Luisa?","blanks":1,"ans":["menos caprichoso"],"example":true},{"tpl":"¿Qué ciudad es (+ antiguo) ___, Lima o Santiago?","blanks":1,"ans":["más antigua"]},{"tpl":"¿Quién es (+ bueno) ___, Ronaldo o Rivaldo?","blanks":1,"ans":["mejor"]},{"tpl":"¿Qué país está (– poblado) ___, Venezuela o Colombia?","blanks":1,"ans":["menos poblado"]},{"tpl":"¿Qué deporte es (– peligroso) ___, el esquí o el alpinismo?","blanks":1,"ans":["menos peligroso"]},{"tpl":"¿Qué es (+ malo) ___, estar enfermo o no tener dinero?","blanks":1,"ans":["peor"]},{"tpl":"¿Quién es (+ viejo) ___, Sofía o su esposo?","blanks":1,"ans":["mayor"]}]},{"id":"gram:15.2","type":"cloze","lab":"15.2","title":"15.2","instr":"Escriba comparaciones como en el ejemplo utilizando las palabras del recuadro.","bank":["~alto","caro","caro","largo","potente","pequeño","poblado","rápido","viejo"],"items":[{"tpl":"(Luis 1,90 cm; su hermano 1,82 cm) Luis es ___.","blanks":1,"ans":["más alto que su hermano"],"wide":true,"example":true},{"tpl":"(Uruguay 176 220 km²; Argentina, 2 766 890 km²) Uruguay es ___.","blanks":1,"ans":["más pequeño que Argentina"],"wide":true},{"tpl":"(Paraguay, 5,5 millones de habitantes; Ecuador, 13 millones) Paraguay está ___.","blanks":1,"ans":["menos poblado que Ecuador"],"wide":true},{"tpl":"(Luisa 19 años; Clara, 25 años) Luisa es ___.","blanks":1,"ans":["menor que Clara"],"wide":true},{"tpl":"(fresas 3,50 euros/kilo; plátanos, 1,75 euros/kilo) Las fresas son ___.","blanks":1,"ans":["más caras que los plátanos"],"wide":true},{"tpl":"(Amazonas 6 788 km; Paraná, 3 780 km) El Amazonas es ___.","blanks":1,"ans":["más largo que el Paraná"],"wide":true},{"tpl":"(televisión 345 euros; radio, 60 euros) Esta televisión es ___.","blanks":1,"ans":["más cara que esta radio"],"wide":true},{"tpl":"(Suiko, disco duro 20 GB; Misima, disco duro 80 GB) Los ordenadores Suiko son ___.","blanks":1,"ans":["menos potentes que los Misima"],"wide":true},{"tpl":"(león 80 km/h; canguro, 50 km/h) El canguro es ___.","blanks":1,"ans":["menos rápido que el león"],"wide":true}]},{"id":"gram:15.3","type":"type","lab":"15.3","title":"15.3","instr":"Complete las frases con la forma comparativa de los adjetivos del recuadro.","long":true,"bank":["alto","~fuerte","rápido","viejo"],"items":[{"q":"","ans":["más fuerte que tú"],"img":"img/gram/u15_ej15-3_01.png","alt":"Ilustración 1","example":true},{"q":"","ans":["más alto que vosotras"],"img":"img/gram/u15_ej15-3_02.png","alt":"Ilustración 2"},{"q":"","ans":["mayores que nosotros"],"img":"img/gram/u15_ej15-3_03.png","alt":"Ilustración 3"},{"q":"","ans":["menos rápido que yo"],"img":"img/gram/u15_ej15-3_04.png","alt":"Ilustración 4"}]},{"id":"gram:15.4","type":"cloze","lab":"15.4","title":"15.4","instr":"Complete las frases con la forma comparativa adecuada.","items":[{"tpl":"Este piso es muy antiguo. Prefiero uno (antiguo) ___.","blanks":1,"ans":["menos antiguo"],"example":true},{"tpl":"Esta casa es muy cara. Prefiero una (barato) ___.","blanks":1,"ans":["más barata"],"example":true},{"tpl":"Estos pantalones son muy grandes. Necesito unos (pequeño) ___.","blanks":1,"ans":["más pequeños"]},{"tpl":"Esta cama es incómoda. Prefiero una (cómodo) ___.","blanks":1,"ans":["más cómoda"]},{"tpl":"Mi trabajo es muy malo. Quiero uno (bueno) ___.","blanks":1,"ans":["mejor"]},{"tpl":"Este postre está muy dulce. Prefiero los postres (dulce) ___.","blanks":1,"ans":["menos dulces"]},{"tpl":"Este libro es un poco aburrido. Prefiero uno (entretenido) ___.","blanks":1,"ans":["más entretenido"]},{"tpl":"Esta falda es muy corta. Quiero una (largo) ___.","blanks":1,"ans":["más larga"]}]}]},{"id":16,"name":"Forma comparativa de los adjetivos (2)","motto":"tan alto, igual de alto","theory":[{"k":"img","src":"img/gram/u16_teoria-martin-carlos.png","alt":"Martín y Carlos."},{"k":"eg","t":"Martín es <b>tan alto como</b> Carlos. Martín es <b>igual de alto que</b> Carlos. Martín y Carlos son <b>igual de altos</b>."},{"k":"img","src":"img/gram/u16_teoria-elefante.png","alt":"Un elefante y un caballo."},{"k":"eg","t":"Un caballo no es <b>tan grande como</b> un elefante. Un caballo no es <b>igual de grande que</b> un elefante. Un elefante y un caballo no son <b>igual de grandes</b>."},{"k":"p","t":"<i>Tan alto, tan grande, igual de alto, igual de grande</i> son expresiones comparativas. Se usan para indicar si cierta cualidad –alto, grande– es igual o no en dos personas, animales o cosas."},{"k":"eg","t":"Sonia es <b>igual de guapa que</b> su madre. El tren no es <b>tan rápido como</b> el avión."},{"k":"h","t":"Formación del comparativo de igualdad"},{"k":"p","t":"<b>Igualdad (=)</b> → <i>tan</i> + adjetivo + <i>como</i>"},{"k":"eg","t":"Soy <b>tan alto como</b> tú, pero no soy <b>tan fuerte</b>. Un toro no es <b>tan rápido como</b> un caballo."},{"k":"p","t":"<b>Igualdad (=)</b> → <i>igual de</i> + adjetivo (+ <i>que</i>)"},{"k":"eg","t":"Soy <b>igual de alto que</b> mi hermano. Mi hermano y yo somos <b>igual de altos</b>."},{"k":"p","t":"El adjetivo tiene la misma forma (masculino o femenino, singular o plural) que la persona, animal o cosa a la que se refiere."},{"k":"eg","t":"Mi piso es igual de <b>pequeño</b> que el tuyo. Mi hermana es tan <b>alta</b> como yo. Sonia y su madre son igual de <b>guapas</b>. Estos dos televisores son igual de <b>caros</b>."},{"k":"p","t":"<i>que/como</i> + pronombre personal sujeto"},{"k":"eg","t":"Los hijos de Andrés no son tan guapos como <b>él</b>. Yo soy igual de trabajadora que <b>vosotros</b>."},{"k":"h","t":"Compare"},{"k":"eg","t":"—Juani es simpática. —Pues Loli es <b>tan simpática como ella</b>. / Pues Loli es <b>igual de simpática</b>."},{"k":"eg","t":"—Felipe es muy trabajador. —Pues sus hermanos no son <b>tan trabajadores</b>. / Pues sus hermanos no son <b>tan trabajadores como él</b>. / Pues sus hermanos no son <b>igual de trabajadores</b>."},{"k":"note","h":"ATENCIÓN","rows":["A veces se prefiere <i>no tan</i> + adjetivo positivo, en lugar de <i>más</i> + adjetivo negativo o <i>menos</i> + adjetivo positivo.","Adolfo es más feo que Jorge. → Adolfo <b>no es tan guapo como</b> Jorge.","Luisa es menos fuerte que Ana. → Luisa <b>no es tan fuerte como</b> Ana."]}],"ex":[{"id":"gram:16.1","type":"cloze","lab":"16.1","title":"16.1","instr":"Complete las frases con el comparativo de igualdad y las palabras del recuadro.","bank":["alegre","~alto","alto","caro","inteligente","~joven","rápido"],"items":[{"tpl":"(David, 52 años; Alonso, 40 años) David ___.","blanks":1,"ans":["no es tan joven como Alonso"],"wide":true,"full":true,"example":true},{"tpl":"(Ana, 1,72 m; María, 1,72 m) Ana y María ___.","blanks":1,"ans":["son igual de altas"],"wide":true,"full":true,"example":true},{"tpl":"(Darío, 90/100; Margarita, 90/100) Darío y Margarita ___.","blanks":1,"ans":["son igual de inteligentes"],"wide":true,"full":true},{"tpl":"(naranjas, 2,20 euros el kilo; manzanas, 1,90 euros el kilo) Las manzanas ___.","blanks":1,"ans":["no son tan caras como las naranjas","no están tan caras como las naranjas"],"wide":true,"full":true},{"tpl":"(Antonio, 100 m/9,5 s; Paco, 100 m/9,5 s) Antonio y Paco ___.","blanks":1,"ans":["son igual de rápidos"],"wide":true,"full":true},{"tpl":"(Esther, alegre ++; Pilar, alegre +) Pilar ___.","blanks":1,"ans":["no es tan alegre como Esther"],"wide":true,"full":true},{"tpl":"(Fermín, 1,75 m; Álvaro, 1,78 m) Fermín ___.","blanks":1,"ans":["no es tan alto como Álvaro"],"wide":true,"full":true}]},{"id":"gram:16.2","type":"cloze","lab":"16.2","title":"16.2","instr":"Complete las comparaciones de igualdad con los adjetivos del recuadro.","bank":["alto","bueno","entretenido","~fácil","fuerte","malo","peligroso","~rápido"],"items":[{"tpl":"El italiano es ___ el español.","blanks":1,"ans":["tan fácil como","igual de fácil que"],"wide":true,"full":true,"example":true},{"tpl":"Un coche no es ___ un avión.","blanks":1,"ans":["tan rápido como"],"wide":true,"full":true,"example":true},{"tpl":"Un gorila no es ___ una jirafa.","blanks":1,"ans":["tan alto como"],"wide":true,"full":true},{"tpl":"Un oso y un gorila son ___.","blanks":1,"ans":["igual de fuertes"],"wide":true,"full":true},{"tpl":"El café de Brasil es ___ el de México.","blanks":1,"ans":["tan bueno como","igual de bueno que"],"wide":true,"full":true},{"tpl":"El teatro es ___ el cine.","blanks":1,"ans":["tan entretenido como","igual de entretenido que"],"wide":true,"full":true},{"tpl":"El esquí no es ___ el alpinismo.","blanks":1,"ans":["tan peligroso como"],"wide":true,"full":true},{"tpl":"El tabaco y el alcohol son ___.","blanks":1,"ans":["igual de malos"],"wide":true,"full":true}]},{"id":"gram:16.3","type":"cloze","lab":"16.3","title":"16.3","instr":"Vuelva a escribir las frases con el comparativo de igualdad. Cambie el adjetivo si es necesario.","items":[{"tpl":"Jorge es más feo que yo. Jorge ___.","blanks":1,"ans":["no es tan guapo como yo"],"wide":true,"full":true,"example":true},{"tpl":"Elio es más bajo que su padre. Elio ___.","blanks":1,"ans":["no es tan alto como su padre"],"wide":true,"full":true},{"tpl":"La silla es más incómoda que el sillón. La silla ___.","blanks":1,"ans":["no es tan cómoda como el sillón"],"wide":true,"full":true},{"tpl":"Vosotras sois más simpáticas que Hugo. Hugo ___.","blanks":1,"ans":["no es tan simpático como vosotras"],"wide":true,"full":true},{"tpl":"Eres más fuerte que yo. (Yo) ___.","blanks":1,"ans":["no soy tan fuerte como tú"],"wide":true,"full":true},{"tpl":"Él es peor que Rinaldo. Él ___.","blanks":1,"ans":["no es tan bueno como Rinaldo"],"wide":true,"full":true}]},{"id":"gram:16.4","type":"cloze","lab":"16.4","title":"16.4","instr":"Complete los diálogos con el comparativo de igualdad.","items":[{"tpl":"—Luis es muy listo. —Pues su hermano es ___.","blanks":1,"ans":["igual de listo","tan listo como él"],"wide":true,"full":true,"example":true},{"tpl":"—Rosario es muy elegante. —Pues sus hijas no son ___.","blanks":1,"ans":["tan elegantes"],"wide":true,"full":true,"example":true},{"tpl":"—Jesús es muy simpático. —Pues su hermana no es ___.","blanks":1,"ans":["tan simpática","tan simpática como él"],"wide":true,"full":true},{"tpl":"—Los peruanos son muy amables. —Pues los colombianos son ___.","blanks":1,"ans":["igual de amables","tan amables","tan amables como los peruanos","igual de amables que los peruanos"],"wide":true,"full":true},{"tpl":"—Esta cama es muy cómoda. —Pues la mía no es ___.","blanks":1,"ans":["tan cómoda","tan cómoda como esa"],"wide":true,"full":true},{"tpl":"—Juan es muy amable. —Pues sus hijos no son ___.","blanks":1,"ans":["tan amables","tan amables como él"],"wide":true,"full":true},{"tpl":"—Este piso es viejo. —Pues el mío es ___.","blanks":1,"ans":["igual de viejo","tan viejo","tan viejo como el tuyo","igual de viejo que el tuyo"],"wide":true,"full":true},{"tpl":"—Elvira es muy guapa. —Pues sus hermanas son ___.","blanks":1,"ans":["igual de guapas","tan guapas","tan guapas como ella","igual de guapas que ella"],"wide":true,"full":true}]}]},{"id":17,"name":"Superlativo","motto":"la más alta, el menos trabajador","theory":[{"k":"img","src":"img/gram/u17_teoria-carla.png","alt":"Cuatro hermanos; Carla es la más alta."},{"k":"eg","t":"Carla es <b>la más alta</b> de sus hermanos."},{"k":"img","src":"img/gram/u17_teoria-zapatos.png","alt":"Anuncio: Zapatos Loto, los más cómodos."},{"k":"eg","t":"Zapatos Loto, <b>los más cómodos</b>."},{"k":"img","src":"img/gram/u17_teoria-david.png","alt":"David trabaja menos que sus amigos."},{"k":"eg","t":"David es <b>el menos trabajador</b> de sus amigos."},{"k":"p","t":"<i>La más alta, los más cómodos, el menos trabajador</i> son formas de superlativo. Se usan para comparar a alguien o algo con un grupo."},{"k":"eg","t":"El Teide es la montaña <b>más alta de</b> España. Soraya es <b>la más cariñosa de</b> su familia."},{"k":"h","t":"Formación del superlativo"},{"k":"p","t":"<b>Superioridad (+)</b> → <i>el/la/los/las</i> (+ nombre) + <i>más</i> + adjetivo (+ <i>de</i>)"},{"k":"eg","t":"Alberto es <b>el más trabajador</b> de su familia. El Everest es <b>la montaña más alta</b> del mundo."},{"k":"p","t":"<b>Inferioridad (–)</b> → <i>el/la/los/las</i> (+ nombre) + <i>menos</i> + adjetivo (+ <i>de</i>)"},{"k":"eg","t":"Hugo es <b>el menos hablador</b> de mis amigos. Paraguay es <b>el país menos poblado</b> de América del Sur."},{"k":"p","t":"<b>Formas irregulares:</b> + viejo → <i>el/la mayor, los/las mayores</i> · – viejo → <i>el/la menor, los/las menores</i> · + bueno → <i>el/la mejor, los/las mejores</i> · + malo → <i>el/la peor, los/las peores</i>"},{"k":"eg","t":"Eva es <b>la mayor</b> de sus hermanos. Estas naranjas son <b>las mejores</b> de España."},{"k":"note","h":"ATENCIÓN","rows":["<i>mejor / peor</i> (+ nombre) + <i>de</i> + nombre: Julián es <b>el mejor alumno de</b> la clase.","superlativo + <i>de</i> + nombre: Hoy es el día <b>más feliz de</b> mi vida.","superlativo + <i>que</i> + verbo: Elena es la chica <b>más alegre que</b> he conocido."]},{"k":"p","t":"El adjetivo tiene la misma forma (masculino o femenino, singular o plural) que la persona, animal o cosa a la que se refiere."},{"k":"eg","t":"Raúl es el más <b>cariñoso</b> de sus hermanos. Carola y Elena son las más <b>simpáticas</b> del grupo."},{"k":"p","t":"A veces no es necesario mencionar el grupo con el que se compara algo."},{"k":"img","src":"img/gram/u17_teoria-televisor.png","alt":"«Este televisor es el más caro.»"},{"k":"eg","t":"Este televisor es <b>el más caro</b>. (de todos los televisores de esta tienda)"},{"k":"img","src":"img/gram/u17_teoria-laura.png","alt":"«Laura es la más alta.»"},{"k":"eg","t":"Laura es <b>la más alta</b>. (de la clase)"}],"ex":[{"id":"gram:17.1","type":"cloze","lab":"17.1","title":"17.1","instr":"Complete las frases con un superlativo.","items":[{"tpl":"¿Cuál es (ciudad, + bonito) ___ de Cuba?","blanks":1,"ans":["la ciudad más bonita"],"wide":true,"full":true,"example":true},{"tpl":"¿Cuál es (país, – poblado) ___ de América Latina?","blanks":1,"ans":["el país menos poblado"],"wide":true,"full":true,"example":true},{"tpl":"¿Cuál es (ciudad, – contaminado) ___ de España?","blanks":1,"ans":["la ciudad menos contaminada"],"wide":true,"full":true},{"tpl":"¿Cuál es (río, + largo) ___ de México?","blanks":1,"ans":["el río más largo"],"wide":true,"full":true},{"tpl":"¿Cuál es (capital, + alto) ___ de América del Sur?","blanks":1,"ans":["la capital más alta"],"wide":true,"full":true},{"tpl":"¿Cuál es (país, + grande) ___ de América Latina?","blanks":1,"ans":["el país más grande"],"wide":true,"full":true},{"tpl":"¿Cuál es (isla, + pequeño) ___ del Caribe?","blanks":1,"ans":["la isla más pequeña"],"wide":true,"full":true},{"tpl":"¿Cuál es (catedral, + antiguo) ___ de México?","blanks":1,"ans":["la catedral más antigua"],"wide":true,"full":true}]},{"id":"gram:17.2","type":"cloze","lab":"17.2","title":"17.2","instr":"Escriba frases sobre un grupo de amigos.","items":[{"tpl":"(simpático: Lucas ++, Marina –, Leo +) Lucas es ___ de sus amigos.","blanks":1,"ans":["el más simpático"],"wide":true,"full":true,"example":true},{"tpl":"(simpático: Lucas ++, Marina –, Leo +) Marina es ___.","blanks":1,"ans":["la menos simpática"],"wide":true,"full":true,"example":true},{"tpl":"(trabajador: Lucas +, Marina ++, Leo ++) Marina y Leo son ___.","blanks":1,"ans":["los más trabajadores"],"wide":true,"full":true},{"tpl":"(trabajador: Lucas +, Marina ++, Leo ++) Lucas es ___.","blanks":1,"ans":["el menos trabajador"],"wide":true,"full":true},{"tpl":"(elegante: Lucas –, Marina ++, Leo +) Marina es ___.","blanks":1,"ans":["la más elegante"],"wide":true,"full":true},{"tpl":"(elegante: Lucas –, Marina ++, Leo +) Lucas es ___.","blanks":1,"ans":["el menos elegante"],"wide":true,"full":true},{"tpl":"(atractivo: Lucas +, Marina +, Leo –) Lucas y Marina son ___.","blanks":1,"ans":["los más atractivos"],"wide":true,"full":true},{"tpl":"(atractivo: Lucas +, Marina +, Leo –) Leo es ___.","blanks":1,"ans":["el menos atractivo"],"wide":true,"full":true}]},{"id":"gram:17.3","type":"cloze","lab":"17.3","title":"17.3","instr":"Complete estos eslóganes publicitarios.","items":[{"tpl":"Agua de Monteviejo, (bebida, + sano) ___ y (+ refrescante) ___.","blanks":2,"ans":["la bebida más sana la más refrescante"],"wide":true,"full":true,"example":true,"exv":["la bebida más sana","la más refrescante"]},{"tpl":"Regina, (reloj, + caro) ___ del mundo.","blanks":1,"ans":["el reloj más caro"],"wide":true,"full":true},{"tpl":"Ordenadores portátiles Misima, (+ pequeño) ___ y (+ potente) ___.","blanks":2,"ans":["los más pequeños los más potentes"],"wide":true,"full":true},{"tpl":"Ropa deportiva Libre, (+ cómodo) ___ y (+ elegante) ___.","blanks":2,"ans":["la más cómoda la más elegante"],"wide":true,"full":true},{"tpl":"Galletas Artaneda, (+ bueno) ___ para el desayuno.","blanks":1,"ans":["las mejores"],"wide":true,"full":true},{"tpl":"Supermercados García, (+ económico) ___.","blanks":1,"ans":["los más económicos"],"wide":true,"full":true},{"tpl":"Zumos Frutasol, (+ sano) ___.","blanks":1,"ans":["los más sanos"],"wide":true,"full":true},{"tpl":"Leche fresca Norte, (+ bueno) ___ para su familia.","blanks":1,"ans":["la mejor"],"wide":true,"full":true}]},{"id":"gram:17.4","type":"cloze","lab":"17.4","title":"17.4","instr":"Complete las frases con un superlativo y de o que.","items":[{"tpl":"Julia es (chica, + alegre) ___ conozco.","blanks":1,"ans":["la chica más alegre que"],"wide":true,"full":true,"example":true},{"tpl":"Para mí, el café de Colombia es (+ bueno) ___ el mundo.","blanks":1,"ans":["el mejor de","el mejor del"],"wide":true,"full":true},{"tpl":"Las ruinas de Machu Picchu son (+ impresionante) ___ he visto.","blanks":1,"ans":["las más impresionantes que"],"wide":true,"full":true},{"tpl":"El día de mi boda fue (+ feliz) ___ mi vida.","blanks":1,"ans":["el más feliz de"],"wide":true,"full":true},{"tpl":"¿Cuál es (país, + interesante) ___ has visitado?","blanks":1,"ans":["el país más interesante que"],"wide":true,"full":true},{"tpl":"Esther es (+ viejo) ___ mis hermanas.","blanks":1,"ans":["la mayor de"],"wide":true,"full":true}]}]},{"id":18,"name":"Posesivos (1)","motto":"mi, tu, su…","theory":[{"k":"img","src":"img/gram/u18_teoria-coche.png","alt":"«¿Cuál es tu coche? – Ese pequeño.»"},{"k":"img","src":"img/gram/u18_teoria-hermana.png","alt":"«Te presento a mi hermana.»"},{"k":"img","src":"img/gram/u18_teoria-profesor.png","alt":"«Mira, ese es nuestro profesor.»"},{"k":"p","t":"<i>Mi, tu, nuestro</i> son posesivos. Se usan para indicar posesión y otro tipo de relaciones con personas, animales o cosas: familia, origen, etc."},{"k":"eg","t":"<b>Mi</b> madre trabaja en un laboratorio. Jimena tiene un pequeño chalé en <b>su</b> pueblo. —¿Dónde es la fiesta? —En <b>mi</b> casa. —¿Cuál es <b>tu</b> color preferido? —El blanco."},{"k":"h","t":"Formas de los posesivos"},{"k":"p","t":"<b>yo:</b> mi, mi, mis, mis · <b>tú:</b> tu, tu, tus, tus · <b>usted:</b> su, su, sus, sus · <b>él, ella:</b> su, su, sus, sus"},{"k":"p","t":"<b>nosotros, -as:</b> nuestro, nuestra, nuestros, nuestras · <b>vosotros, -as:</b> vuestro, vuestra, vuestros, vuestras"},{"k":"p","t":"<b>ustedes:</b> su, su, sus, sus · <b>ellos, ellas:</b> su, su, sus, sus"},{"k":"p","t":"(orden: singular masculino, singular femenino, plural masculino, plural femenino)"},{"k":"p","t":"Se usa <i>mi, tu, su…</i> + nombres."},{"k":"eg","t":"¿Quién es <b>tu</b> profesor? Ayer vi a Ignacio con <b>sus</b> primas. ¿Dónde están <b>vuestras</b> cosas?"},{"k":"note","h":"ATENCIÓN","rows":["<i>su, sus</i> = de él; de ella; de usted; de ellos; de ellas; de ustedes"]},{"k":"img","src":"img/gram/u18_teoria-jorge.png","alt":"Jorge y sus hijas."},{"k":"img","src":"img/gram/u18_teoria-alicia.png","alt":"Alicia en su coche."},{"k":"img","src":"img/gram/u18_teoria-puebla.png","alt":"Los señores Puebla en su casa."},{"k":"img","src":"img/gram/u18_teoria-abel.png","alt":"«Abel, es su mujer.»"},{"k":"p","t":"Generalmente, la situación indica a quién se refiere <i>su, sus</i>."},{"k":"eg","t":"Mire, don Raúl. Ahí va Jorge con <b>sus</b> hijas. (Raúl sabe de quién son las hijas, de él o de Jorge.)"},{"k":"p","t":"Se usa <i>el, la, los, las</i> no <i>mi, tu, su…</i> con partes del cuerpo, prendas de vestir y otros objetos personales."},{"k":"eg","t":"Me duele <s>mi</s> cabeza. → Me duele <b>la</b> cabeza."},{"k":"eg","t":"Quítate <s>tu</s> abrigo. → Quítate <b>el</b> abrigo."},{"k":"eg","t":"Tengo que lavar <s>mi</s> coche. → Tengo que lavar <b>el</b> coche."}],"ex":[{"id":"gram:18.1","type":"cloze","lab":"18.1","title":"18.1","instr":"Observe los árboles genealógicos y complete las frases con mi, tu, su…","img":"img/gram/u18_ej18-1_arbol.png","alt":"Familia Suárez: Lucas–María; hijos Rosa y Begoña–Alfonso; nietos Arturo y Carlota. Familia Salina: Julio–Rosario; hijos Carmelo–Justa y Lupe; nietos Blanca, Lucía y Emilio.","items":[{"tpl":"ARTURO: ¿Cómo se llaman ___ padres, Blanca?","blanks":1,"ans":["tus"],"mid":true,"example":true},{"tpl":"EMILIO: ___ hermanas se llaman Blanca y Lucía.","blanks":1,"ans":["Mis"],"mid":true},{"tpl":"CARLOTA: ¿Cómo se llama ___ mujer, don Carmelo?","blanks":1,"ans":["su"],"mid":true},{"tpl":"BLANCA y LUCÍA: ___ abuela se llama Rosario.","blanks":1,"ans":["Nuestra"],"mid":true},{"tpl":"EMILIO: Arturo, Carlota, ¿cómo se llaman ___ abuelos?","blanks":1,"ans":["vuestros"],"mid":true},{"tpl":"ALFONSO: ___ madre se llama María.","blanks":1,"ans":["Mi"],"mid":true},{"tpl":"BLANCA: ¿Cómo se llama ___ tía, Arturo?","blanks":1,"ans":["tu"],"mid":true},{"tpl":"CARLOTA: ¿Cómo se llaman ___ hijos, don Julio?","blanks":1,"ans":["sus"],"mid":true},{"tpl":"CARMELO y LUPE: ___ padres se llaman Julio y Rosario.","blanks":1,"ans":["Nuestros"],"mid":true},{"tpl":"ARTURO: Blanca, Lucía, ¿cómo se llama ___ madre?","blanks":1,"ans":["vuestra"],"mid":true}]},{"id":"gram:18.2","type":"cloze","lab":"18.2","title":"18.2","instr":"Complete las frases con mi, tu, su…","items":[{"tpl":"—¿Cuál es ___ color preferido, Berta? —El azul.","blanks":1,"ans":["tu"],"mid":true,"example":true},{"tpl":"Mi hermano y yo jugamos mucho al tenis. Es ___ deporte preferido.","blanks":1,"ans":["nuestro"],"mid":true},{"tpl":"La señora Valverde y ___ hijas son muy agradables.","blanks":1,"ans":["Sus"],"mid":true},{"tpl":"—¿Dónde están Sol y Rocío? —En ___ casa.","blanks":1,"ans":["Su"],"mid":true},{"tpl":"Anoche fui al cine con ___ padre y ___ hermanos.","blanks":2,"ans":["mi mis"],"mid":true},{"tpl":"Jorge, Juan, ¿dónde están ___ libros?","blanks":1,"ans":["vuestros"],"mid":true},{"tpl":"—¿Cuál es ___ comida preferida, Enrique? —La paella.","blanks":1,"ans":["tu"],"mid":true},{"tpl":"Ayer conocí a ___ padres, Verónica. Son muy simpáticos.","blanks":1,"ans":["tus"],"mid":true}]},{"id":"gram:18.3","type":"pick","lab":"18.3","title":"18.3","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"Me estoy lavando [mi|el] pelo.","ans":["el"],"example":true},{"tpl":"Átate [tus|los] zapatos.","ans":["los"]},{"tpl":"Rodrigo trabaja con [su|el] padre.","ans":["su"]},{"tpl":"Tenéis [vuestros|los] ojos rojos.","ans":["los"]},{"tpl":"[Mis|Los] tíos viven en Puerto Rico.","ans":["Mis"]},{"tpl":"Le di [mi|la] mano.","ans":["la"]},{"tpl":"[Su|La] abuela tiene 85 años.","ans":["Su"]},{"tpl":"Tienes una mancha en [tu|la] nariz.","ans":["la"]},{"tpl":"Quitaos [vuestras|las] chaquetas.","ans":["las"]},{"tpl":"Al señor Alfonsín se le ha estropeado [su|el] coche.","ans":["el"]}]}]},{"id":19,"name":"Posesivos (2)","motto":"mío, tuyo, suyo…","theory":[{"k":"img","src":"img/gram/u19_teoria-comics.png","alt":"«¿De quién es esta maleta? – Es mía». «¿De quién es esto? – Es nuestro». «¿Es tuyo este diccionario? – No, el mío es más pequeño»."},{"k":"p","t":"<i>Mía, mío, tuyo, nuestro</i> son posesivos. Se usan para indicar posesión y otro tipo de relaciones con personas, animales o cosas: familia, origen, etc."},{"k":"eg","t":"—Mi madre trabaja en un banco. ¿Y <b>la tuya</b>? —<b>La mía</b> trabaja en una agencia de viajes."},{"k":"eg","t":"—Mi pueblo es muy bonito y moderno. —<b>El nuestro</b> es muy antiguo."},{"k":"h","t":"Formas de los posesivos"},{"k":"p","t":"<b>yo:</b> mío, mía, míos, mías · <b>tú:</b> tuyo, tuya, tuyos, tuyas"},{"k":"p","t":"<b>usted, él, ella:</b> suyo, suya, suyos, suyas"},{"k":"p","t":"<b>nosotros, -as:</b> nuestro, nuestra, nuestros, nuestras · <b>vosotros, -as:</b> vuestro, vuestra, vuestros, vuestras"},{"k":"p","t":"<b>ustedes, ellos, ellas:</b> suyo, suya, suyos, suyas"},{"k":"p","t":"(orden: singular masculino, singular femenino, plural masculino, plural femenino)"},{"k":"p","t":"Se usa <i>ser</i> + <i>mío, tuyo…</i> para expresar posesión."},{"k":"eg","t":"Esta bolsa no es <b>mía</b>. ¿Es <b>tuya</b>, Amparo? —¿Es esto <b>nuestro</b>? —No, es <b>suyo</b>."},{"k":"p","t":"Se usa <i>el, la, los, las</i> + <i>mío, tuyo…</i> cuando se habla de algo o alguien mencionado anteriormente."},{"k":"eg","t":"—¿Es tuya esa bolsa? —No, <b>la mía</b> es más pequeña. Como se estropeó el coche de Jaime, fuimos en <b>el nuestro</b>."},{"k":"p","t":"Se usa (<i>un, una, unos, unas</i> +) nombre + <i>mío, tuyo…</i> cuando hablamos de algo o alguien como parte de un grupo."},{"k":"eg","t":"—¿Conoces a Julián? —Sí, hombre. Es <b>amigo mío</b>. (Es uno de mis amigos.) <b>Una tía nuestra</b> vive en Panamá. (una de nuestras tías)"},{"k":"note","h":"ATENCIÓN","rows":["<i>suyo, suya, suyos, suyas</i> = de él; de ella; de usted; de ellos; de ellas; de ustedes","Generalmente, la situación indica a quién se refiere <i>suyo/suya/suyos/suyas</i>.","—¿Son estas las maletas de Felisa? —No, <b>las suyas</b> son azules. (las de Felisa)","—¿Son estas mis maletas? —No, <b>las suyas</b> son más pequeñas. (las de usted)"]}],"ex":[{"id":"gram:19.1","type":"cloze","lab":"19.1","title":"19.1","instr":"Complete las frases como en el ejemplo.","items":[{"tpl":"Son ___.","blanks":1,"ans":["mías"],"img":"img/gram/u19_ej19-1_01.png","alt":"«¿De quién son estas llaves?»","wide":true,"example":true},{"tpl":"Es ___.","blanks":1,"ans":["mío"],"img":"img/gram/u19_ej19-1_02.png","alt":"«¿De quién es este libro?»","wide":true},{"tpl":"Es ___.","blanks":1,"ans":["suyo"],"img":"img/gram/u19_ej19-1_03.png","alt":"«¿De quién es este paraguas?»","wide":true},{"tpl":"Son ___.","blanks":1,"ans":["nuestros"],"img":"img/gram/u19_ej19-1_04.png","alt":"«¿De quién son estos CD?»","wide":true},{"tpl":"¿Son ___ estos libros?","blanks":1,"ans":["vuestros"],"img":"img/gram/u19_ej19-1_05.png","alt":"Dos chicos con un libro.","wide":true},{"tpl":"¿Son ___ estas maletas?","blanks":1,"ans":["suyas"],"img":"img/gram/u19_ej19-1_06.png","alt":"Un hombre con una maleta ante dos personas.","wide":true},{"tpl":"¿Es ___ este reloj?","blanks":1,"ans":["tuyo","suyo"],"img":"img/gram/u19_ej19-1_07.png","alt":"Una chica enseña un reloj a un hombre.","wide":true},{"tpl":"¿Es ___ esta bufanda?","blanks":1,"ans":["suya"],"img":"img/gram/u19_ej19-1_08.png","alt":"Un chico enseña una bufanda a un hombre.","wide":true}]},{"id":"gram:19.2","type":"cloze","lab":"19.2","title":"19.2","instr":"Escriba el mío, la tuya, los suyos… según corresponda en las siguientes frases.","items":[{"tpl":"Estas llaves no son mías. ___ son más pequeñas.","blanks":1,"ans":["las mías"],"mid":true,"example":true},{"tpl":"—¿Es ese vuestro coche? —No, ___ es más grande.","blanks":1,"ans":["el nuestro"],"mid":true},{"tpl":"Este abrigo no es de Pedro. ___ es azul.","blanks":1,"ans":["el suyo"],"mid":true},{"tpl":"—Perdona, ¿es este mi asiento? —No, ___ está más atrás.","blanks":1,"ans":["el tuyo"],"mid":true},{"tpl":"—¿Es ese nuestro profesor? —No, ___ es mayor.","blanks":1,"ans":["el nuestro","el vuestro"],"mid":true},{"tpl":"—Mi deporte preferido es el fútbol. ¿Y ___? —___ es el esquí.","blanks":2,"ans":["el tuyo el mío"],"mid":true},{"tpl":"—Mis hijos practican muchos deportes. ¿Y ___, Manuel? —___ juegan al tenis.","blanks":2,"ans":["los tuyos los míos"],"mid":true},{"tpl":"—¿Son esos los padres de Arturo? —No, ___ son más jóvenes.","blanks":1,"ans":["los suyos"],"mid":true},{"tpl":"—Mi profesora es peruana. —___ es argentina.","blanks":1,"ans":["la mía"],"mid":true},{"tpl":"—Nuestros hijos son muy trabajadores. —___ son un poco vagos.","blanks":1,"ans":["los nuestros","los míos"],"mid":true}]},{"id":"gram:19.3","type":"cloze","lab":"19.3","title":"19.3","instr":"Complete con mío, tuyo, suyo… y un, una, unos o unas si es necesario.","items":[{"tpl":"(amigo, yo) ___ es pintor.","blanks":1,"ans":["un amigo mío"],"wide":true,"full":true,"example":true},{"tpl":"(amiga, yo) ___ ha ganado un premio.","blanks":1,"ans":["una amiga mía"],"wide":true,"full":true},{"tpl":"Ayer estuve con (primo, vosotros) ___.","blanks":1,"ans":["un primo vuestro"],"wide":true,"full":true},{"tpl":"El director del banco es (amigo, ellos) ___.","blanks":1,"ans":["amigo suyo"],"wide":true,"full":true},{"tpl":"Raquel es (prima, nosotros) ___.","blanks":1,"ans":["prima nuestra"],"wide":true,"full":true},{"tpl":"¿Es Alicia (tía, tú) ___?","blanks":1,"ans":["tía tuya"],"wide":true,"full":true},{"tpl":"—¿Conocéis a Mariano? —Sí, es (amigo, nosotros) ___.","blanks":1,"ans":["amigo nuestro"],"wide":true,"full":true},{"tpl":"El domingo conocimos a (familiares, ustedes) ___.","blanks":1,"ans":["unos familiares suyos"],"wide":true,"full":true}]}]},{"id":20,"name":"Indefinidos (1)","motto":"todos, algunos, unos, ninguno…","theory":[{"k":"img","src":"img/gram/u20_teoria-ninos.png","alt":"Todos los niños, algunos niños, un niño, ningún niño están llorando."},{"k":"p","t":"Se usa <i>todos, algunos, un, ningún</i> para referirse a los componentes de un grupo. <i>todos</i> = la totalidad del grupo · <i>algunos</i> = una parte del grupo · <i>un</i> = un elemento no determinado del grupo, no se dice cuál · <i>ningún</i> = nadie o nada del grupo."},{"k":"h","t":"todo, toda, todos, todas"},{"k":"p","t":"<i>todo, toda</i> + el, la / mi, tu… / este, ese, aquel… + nombre singular"},{"k":"eg","t":"Dame <b>todo el pan</b>. <b>Toda tu familia</b> es muy alegre. Tira <b>toda esa basura</b> al contenedor."},{"k":"p","t":"<i>todos, todas</i> + nosotros, vosotros… / los, las / mis, tus… / estos, esos, aquellos… + nombre plural"},{"k":"eg","t":"Sois muy amables <b>todos vosotros</b>. Voy a México <b>todos los veranos</b>. <b>Todos mis hermanos</b> hablan francés. Deme <b>todas esas manzanas</b>, por favor."},{"k":"h","t":"un, unos…; algún, algunos…; ningún, ninguna"},{"k":"p","t":"<i>un, una; algún, alguna; ningún, ninguna</i> + nombre singular"},{"k":"eg","t":"He conocido a <b>un compañero</b> tuyo. ¿Ha venido <b>algún alumno</b>? Alicia no sale <b>ningún domingo</b>."},{"k":"p","t":"<i>unos, unas; algunos, algunas</i> + nombre plural"},{"k":"eg","t":"Conozco a <b>unos chicos</b> que estudian quechua. He recorrido <b>algunas zonas</b> de Perú."},{"k":"p","t":"<i>uno, una; alguno, -a, algunos, -as; ninguno, ninguna</i> + <i>de</i> + nosotros, vosotros… / los, las… + nombre plural / mis, tus… + nombre plural / estos, esos… + (nombre plural)"},{"k":"eg","t":"¿<b>Alguno de vosotros</b> conduce? No veo a <b>ninguno de los niños</b>. <b>Uno de mis tíos</b> vive en Caracas. <b>Alguno de estos</b> es mío, seguro."},{"k":"p","t":"<i>algún, alguno, alguna</i> expresan cantidad e identidad indeterminadas (no se dice ni cuántos ni cuáles); por eso es muy común en preguntas."},{"k":"eg","t":"¿Alguno de vosotros habla árabe? —No, ninguno."},{"k":"p","t":"<i>Uno, ninguno, alguno</i> y <i>todo</i> se pueden usar solos cuando está claro de quién o de qué se habla."},{"k":"eg","t":"<b>Todos</b> quieren venir a la fiesta. (todos nuestros amigos) —¿Has visto a <b>alguno</b> de mis compañeros? —No, no he visto a <b>ninguno</b>."},{"k":"note","h":"ATENCIÓN","rows":["<i>ninguno</i> + verbo afirmativo → <b>Ninguno</b> de mis amigos ha salido.","verbo negativo + <i>ninguno</i> → No ha salido <b>ninguno</b> de mis amigos."]}],"ex":[{"id":"gram:20.1","type":"cloze","lab":"20.1","title":"20.1","instr":"Observe las ilustraciones y complete las frases con todo, algún, un, ningún… y las palabras del recuadro.","bank":["~caja","caja","coche","manzana","pera","plato","vaso","vaso"],"items":[{"tpl":"___ están vacías.","blanks":1,"ans":["Todas las cajas"],"img":"img/gram/u20_ej20-1_01.png","alt":"Cinco cajas abiertas y vacías.","wide":true,"example":true,"exv":["Todas las cajas"]},{"tpl":"___ están cerradas.","blanks":1,"ans":["Algunas cajas"],"img":"img/gram/u20_ej20-1_02.png","alt":"Cajas cerradas y otras abiertas.","wide":true},{"tpl":"___ están rotos.","blanks":1,"ans":["Algunos platos"],"img":"img/gram/u20_ej20-1_03.png","alt":"Platos apilados; algunos rotos.","wide":true},{"tpl":"___ está roto.","blanks":1,"ans":["Un vaso"],"img":"img/gram/u20_ej20-1_04.png","alt":"Cuatro vasos y uno roto.","wide":true},{"tpl":"___ están parados.","blanks":1,"ans":["Todos los coches"],"img":"img/gram/u20_ej20-1_05.png","alt":"Coches en un atasco.","wide":true},{"tpl":"___ está podrida.","blanks":1,"ans":["Una manzana"],"img":"img/gram/u20_ej20-1_06.png","alt":"Manzanas; una podrida.","wide":true},{"tpl":"___ está podrida.","blanks":1,"ans":["Ninguna pera"],"img":"img/gram/u20_ej20-1_07.png","alt":"Peras sanas.","wide":true},{"tpl":"___ están relucientes.","blanks":1,"ans":["Algunos vasos"],"img":"img/gram/u20_ej20-1_08.png","alt":"Vasos relucientes.","wide":true}]},{"id":"gram:20.2","type":"cloze","lab":"20.2","title":"20.2","instr":"Escriba todo, algún, un, ningún… según corresponda.","items":[{"tpl":"Alicia está estudiando con ___ compañeros.","blanks":1,"ans":["unos"],"example":true},{"tpl":"En ___ países de África se habla español.","blanks":1,"ans":["algunos"]},{"tpl":"¿Has estado en ___ país de América?","blanks":1,"ans":["algún"]},{"tpl":"___ mi familia habla español.","blanks":1,"ans":["Toda"]},{"tpl":"___ mis amigas son simpáticas.","blanks":1,"ans":["Todas"]},{"tpl":"___ aves no pueden volar.","blanks":1,"ans":["Algunas"]},{"tpl":"___ elefante come carne.","blanks":1,"ans":["Ningún"]}]},{"id":"gram:20.3","type":"cloze","lab":"20.3","title":"20.3","instr":"Complete las frases con uno, alguno, ninguno… + de cuando sea necesario.","items":[{"tpl":"Ayer conocí a ___ tus hermanos.","blanks":1,"ans":["uno de"],"mid":true,"example":true},{"tpl":"¿___ ustedes habla quechua?","blanks":1,"ans":["Alguno de"],"mid":true},{"tpl":"No he conocido a ___ mis abuelas.","blanks":1,"ans":["ninguna de"],"mid":true},{"tpl":"¿Trabaja ___ tus hermanos?","blanks":1,"ans":["alguno de"],"mid":true},{"tpl":"Felipe sale con ___ mis amigas.","blanks":1,"ans":["una de"],"mid":true},{"tpl":"___ nosotros ha estado en la Isla de Pascua, pero nos gustaría ir.","blanks":1,"ans":["Ninguno de"],"mid":true}]},{"id":"gram:20.4","type":"cloze","lab":"20.4","title":"20.4","instr":"Complete los diálogos con todo, algún, ningún…","items":[{"tpl":"—¿Conoces a los amigos de Pedro? —Conozco a ___, pero no a ___.","blanks":2,"ans":["algunos todos"],"example":true},{"tpl":"—¿Has comprado ya los libros? —Sí, los he comprado ___.","blanks":1,"ans":["todos"]},{"tpl":"—¿Conoces algún país de Asia? —No, no conozco ___.","blanks":1,"ans":["ninguno"]},{"tpl":"—¿Has visto a alguna de mis hermanas? —No, no he visto a ___.","blanks":1,"ans":["ninguna"]},{"tpl":"Me encantan las mariposas. ___ tienen las alas muy bonitas.","blanks":1,"ans":["Algunas"]}]}]},{"id":21,"name":"Indefinidos (2)","motto":"uno, otro, cualquiera","theory":[{"k":"h","t":"un, una, unos, unas"},{"k":"p","t":"<i>un, una</i> = un elemento indeterminado, no se dice cuál. <i>unos, unas</i> = identidad y cantidad indeterminadas, no se dice cuáles ni cuántos."},{"k":"eg","t":"Necesito <b>un móvil</b> nuevo. Ana está con <b>unas compañeras</b>."},{"k":"h","t":"otro, otra, otros, otras"},{"k":"img","src":"img/gram/u21_teoria-zumo.png","alt":"«Otro zumo, por favor»."},{"k":"p","t":"Uno o más elementos del mismo tipo:"},{"k":"eg","t":"Toma <b>otra galleta</b>. (una galleta más) <b>Otros dos bocadillos</b>, por favor. (dos bocadillos más)"},{"k":"p","t":"Uno o unos elementos de tipo distinto:"},{"k":"eg","t":"Déjame <b>otro libro</b>. Este no me gusta. (un libro diferente)"},{"k":"p","t":"<i>otro, otra</i> + nombre singular"},{"k":"eg","t":"Tráiganos <b>otra cuchara</b>, por favor."},{"k":"p","t":"<i>otros, otras</i> + nombre plural / + dos, tres… + nombre plural"},{"k":"eg","t":"Enséñeme <b>otros zapatos</b>. Estos no me gustan. Necesitamos <b>otras dos jugadoras</b>."},{"k":"p","t":"<i>otro, otra</i> + <i>de</i> + nosotros, vosotros… / los, las / mis, tus… / estos, esos… + nombre plural"},{"k":"eg","t":"Quiere que vayamos <b>otro de nosotros</b>. Pásame <b>otro de los pasteles</b> de chocolate. He perdido <b>otra de mis plumas</b>. Dame <b>otra de esas ciruelas</b>."},{"k":"h","t":"cualquier, cualquiera"},{"k":"img","src":"img/gram/u21_teoria-cualquiera.png","alt":"«¿Cuál le gusta? – Deme una cualquiera»."},{"k":"p","t":"Indica uno, no importa cuál, no conocido ni identificado."},{"k":"eg","t":"Dame <b>cualquier libro</b>. (Uno, pero no importa cuál.) Puedes llamarme a <b>cualquier hora</b>."},{"k":"p","t":"<i>cualquier</i> + nombre singular · nombre singular + <i>cualquiera</i>"},{"k":"eg","t":"<b>Cualquier día</b> voy a verte. Dame <b>un libro cualquiera</b>."},{"k":"p","t":"<i>cualquiera</i> + <i>de</i> + nosotros, ustedes… / los, las / mis, tus… / estos, esos… + nombre plural"},{"k":"eg","t":"<b>Cualquiera de ustedes</b> puede hacerlo. Pásame <b>cualquiera de los bolígrafos</b>. Ponte <b>cualquiera de mis trajes</b>. <b>Cualquiera de esos chicos</b> es más amable que tú."},{"k":"p","t":"<i>uno, una</i> + <i>cualquiera</i>"},{"k":"eg","t":"Es igual. Deme <b>uno cualquiera</b>."},{"k":"p","t":"<i>Uno, una, unos, unas, otro, otra, otros, otras</i> y <i>cualquiera</i> pueden ir solos cuando está claro de quién o de qué se está hablando."},{"k":"eg","t":"—Necesitamos sillas nuevas. —He visto <b>unas</b> preciosas. Hay muchos bocadillos. Toma <b>otro</b>."}],"ex":[{"id":"gram:21.1","type":"cloze","lab":"21.1","title":"21.1","instr":"Observe las situaciones y complete las frases con un, una… u otro, otros…","items":[{"tpl":"___ tónica, por favor.","blanks":1,"ans":["una"],"img":"img/gram/u21_ej21-1_01.png","alt":"Una clienta pide en un bar.","example":true},{"tpl":"Deme ___ bolsa, por favor. Esta está rota.","blanks":1,"ans":["otra"],"img":"img/gram/u21_ej21-1_02.png","alt":"Una clienta con una bolsa rota."},{"tpl":"Préstame ___ libro, por favor.","blanks":1,"ans":["un"],"img":"img/gram/u21_ej21-1_03.png","alt":"Dos chicas en una biblioteca."},{"tpl":"___ tónica, por favor.","blanks":1,"ans":["otra"],"img":"img/gram/u21_ej21-1_04.png","alt":"Una clienta pide en un bar."},{"tpl":"Préstame ___ libros. Estos los he leído.","blanks":1,"ans":["otros"],"img":"img/gram/u21_ej21-1_05.png","alt":"Una chica con un libro."},{"tpl":"Deme ___ bolsa, por favor.","blanks":1,"ans":["una"],"img":"img/gram/u21_ej21-1_06.png","alt":"Una clienta en una tienda."},{"tpl":"Tráiganos ___ cucharas, por favor. Estas están sucias.","blanks":1,"ans":["otras"],"img":"img/gram/u21_ej21-1_07.png","alt":"Dos clientes en un restaurante."},{"tpl":"¡Qué rica estaba! ¿Me das ___ manzana?","blanks":1,"ans":["otra"],"img":"img/gram/u21_ej21-1_08.png","alt":"Un chico con una manzana comida."}]},{"id":"gram:21.2","type":"cloze","lab":"21.2","title":"21.2","instr":"Utilice las expresiones del recuadro para completar las siguientes frases.","bank":["cualquier","cualquiera","cualquiera de"],"items":[{"tpl":"Esto lo puedes encontrar en ___ tienda.","blanks":1,"ans":["cualquier"],"mid":true,"example":true},{"tpl":"Eso es complicado. No lo puede hacer ___ nosotros.","blanks":1,"ans":["cualquiera de"],"mid":true},{"tpl":"Si quieres que te ayude, ven ___ mañana. Estoy siempre libre.","blanks":1,"ans":["cualquier"],"mid":true},{"tpl":"Usa ___ esos ordenadores. Todos funcionan.","blanks":1,"ans":["cualquiera de"],"mid":true},{"tpl":"Dale una excusa ___. No le importará.","blanks":1,"ans":["cualquiera"],"mid":true}]},{"id":"gram:21.3","type":"cloze","lab":"21.3","title":"21.3","instr":"Escriba uno, cualquier, otro… + de cuando sea necesario.","items":[{"tpl":"—¿Te gustan las galletas? Toma ___.","blanks":1,"ans":["una"],"mid":true,"example":true},{"tpl":"Este helado estaba riquísimo. Quiero ___.","blanks":1,"ans":["otro"],"mid":true},{"tpl":"Diez euros no son suficientes. Necesitamos ___ cinco.","blanks":1,"ans":["otros"],"mid":true},{"tpl":"—¿Dónde estabas? —Con ___ amigas.","blanks":1,"ans":["unas"],"mid":true},{"tpl":"Ayer jugué al tenis con ___ tus primos.","blanks":1,"ans":["uno de"],"mid":true},{"tpl":"Si vienen Arnaldo y Marta al concierto necesitaremos ___ dos entradas.","blanks":1,"ans":["otras"],"mid":true},{"tpl":"Quiero ___ esas corbatas.","blanks":1,"ans":["una de"],"mid":true},{"tpl":"Han llegado ___ libros para la biblioteca.","blanks":1,"ans":["unos"],"mid":true}]},{"id":"gram:21.4","type":"cloze","lab":"21.4","title":"21.4","instr":"Complete con otro, otra, otros, otras y cualquiera.","items":[{"tpl":"—¿Le gustan estos zapatos? —No, enséñeme ___, por favor.","blanks":1,"ans":["otros"],"mid":true,"example":true},{"tpl":"No es muy difícil. ___ puede hacerlo.","blanks":1,"ans":["Cualquiera"],"mid":true},{"tpl":"—¿Qué trabajo quieres hacer? —___. Necesito trabajar.","blanks":1,"ans":["Cualquiera"],"mid":true},{"tpl":"He perdido el tren a Cuzco. ¿Cuándo hay ___?","blanks":1,"ans":["otro"],"mid":true},{"tpl":"—¿Le gustan estos plátanos? —No, deme ___. Esos están muy verdes.","blanks":1,"ans":["otros"],"mid":true}]}]},{"id":22,"name":"Indefinidos (3)","motto":"mucho, poco, demasiado, suficiente…","theory":[{"k":"img","src":"img/gram/u22_teoria-dinero.png","alt":"Mucho dinero, poco dinero, demasiado dinero, suficiente dinero."},{"k":"p","t":"<i>Mucho, poco, demasiado</i> y <i>suficiente</i> se usan para indicar cantidad. <i>mucho</i> = una gran cantidad · <i>poco</i> = una cantidad pequeña · <i>demasiado</i> = más cantidad de lo necesario · <i>suficiente</i> = la cantidad necesaria."},{"k":"h","t":"mucho, poco, demasiado, suficiente"},{"k":"p","t":"<i>mucho, mucha; poco, poca; demasiado, demasiada; suficiente</i> + nombre singular no contable"},{"k":"eg","t":"No tengo <b>mucha hambre</b>. Martín tiene <b>poco tiempo</b> para estudiar. Rodri come <b>demasiado chocolate</b>. No tengo <b>suficiente dinero</b> para el avión."},{"k":"p","t":"<i>muchos, muchas; pocos, pocas; demasiados, demasiadas; suficientes</i> + nombre plural"},{"k":"eg","t":"Mis hijos duermen <b>muchas horas</b>. Marcela tiene <b>pocas amigas</b>. Alejo come <b>demasiados pasteles</b>. Tenemos <b>suficientes patatas</b> para hoy."},{"k":"note","h":"ATENCIÓN","rows":["<i>suficiente(s)</i> + nombre → Hay <b>suficiente agua</b>.","nombre + <i>suficiente(s)</i> → Hay <b>agua suficiente</b>."]},{"k":"h","t":"bastante, bastantes"},{"k":"img","src":"img/gram/u22_teoria-gente.png","alt":"Mucha gente, bastante gente."},{"k":"p","t":"Una gran cantidad, pero no mucho (en una escala: mucho – bastante – poco)."},{"k":"p","t":"La cantidad necesaria, suficiente."},{"k":"eg","t":"—¿Crees que hay <b>bastante comida</b>? —Sí, solo somos tres. No podemos ir de vacaciones. No tenemos <b>bastante dinero</b>."},{"k":"p","t":"<i>Mucho, poco, demasiado, suficiente, bastante</i> pueden ir solos cuando está claro de qué se está hablando."},{"k":"eg","t":"—¿Cuántos huevos hay? —Tres. Son <b>suficientes</b> para una tortilla. —¿Tienes tiempo? —No tengo <b>mucho</b>. Me voy en diez minutos."}],"ex":[{"id":"gram:22.1","type":"cloze","lab":"22.1","title":"22.1","instr":"Sustituya las cantidades subrayadas por mucho, mucha… o poco, pocos…","items":[{"tpl":"___.","blanks":1,"ans":["Sonia tiene muchos libros"],"ctx":"Sonia tiene <u>unos doscientos</u> libros.","wide":true,"full":true,"example":true,"exv":["Sonia tiene muchos libros"]},{"tpl":"___.","blanks":1,"ans":["Alberto tiene pocos amigos"],"ctx":"Alberto tiene <u>dos</u> amigos.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Ayer dormimos muchas horas"],"ctx":"Ayer dormimos <u>diez</u> horas.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Bebo mucha agua al día"],"ctx":"Bebo <u>tres litros de</u> agua al día.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Hemos comprado mucho aceite"],"ctx":"Hemos comprado <u>diez litros de</u> aceite.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Quedan pocas patatas"],"ctx":"Quedan <u>dos</u> patatas.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Luisa toma poco azúcar en el café"],"ctx":"Luisa toma <u>media cucharada de</u> azúcar en el café.","wide":true,"full":true}]},{"id":"gram:22.2","type":"cloze","lab":"22.2","title":"22.2","instr":"Indique si estas cantidades le parecen demasiado o suficiente.","items":[{"tpl":"Javier trabaja doce horas todos los días. ___.","blanks":1,"ans":["Trabaja demasiadas horas"],"wide":true,"full":true,"example":true,"exv":["Trabaja demasiadas horas"]},{"tpl":"Enrique duerme cuatro horas todos los días. ___.","blanks":1,"ans":["No duerme suficientes horas"],"wide":true,"full":true,"example":true,"exv":["No duerme suficientes horas"]},{"tpl":"Jacinta bebe un vaso de agua al día. ___.","blanks":1,"ans":["No bebe suficiente agua"],"wide":true,"full":true},{"tpl":"Como cinco plátanos al día. ___.","blanks":1,"ans":["Como demasiados plátanos"],"wide":true,"full":true},{"tpl":"Inés bebe litro y medio de agua al día. ___.","blanks":1,"ans":["Bebe suficiente agua"],"wide":true,"full":true},{"tpl":"Gabriel come medio kilo de carne todos los días. ___.","blanks":1,"ans":["Come demasiada carne"],"wide":true,"full":true},{"tpl":"Tenemos una patata para hacer una tortilla. ___.","blanks":1,"ans":["No tenemos suficientes patatas"],"wide":true,"full":true}]},{"id":"gram:22.3","type":"cloze","lab":"22.3","title":"22.3","instr":"Describa lo que hay en cada ilustración utilizando mucho, poco, bastante… y alguna de las palabras del recuadro.","bank":["agua","árboles","árboles","~coches","comida","gente","gente","gente"],"items":[{"tpl":"___.","blanks":1,"ans":["Muchos coches"],"img":"img/gram/u22_ej22-3_01.png","alt":"Una carretera llena de coches.","wide":true,"example":true,"exv":["Muchos coches"]},{"tpl":"___.","blanks":1,"ans":["Poca agua"],"img":"img/gram/u22_ej22-3_02.png","alt":"Un puente de piedra sobre un río.","wide":true},{"tpl":"___.","blanks":1,"ans":["Bastante comida"],"img":"img/gram/u22_ej22-3_03.png","alt":"Dos platos de comida.","wide":true},{"tpl":"___.","blanks":1,"ans":["Bastante gente"],"img":"img/gram/u22_ej22-3_04.png","alt":"Una playa con algunas personas.","wide":true},{"tpl":"___.","blanks":1,"ans":["Poca gente"],"img":"img/gram/u22_ej22-3_05.png","alt":"Una playa casi vacía.","wide":true},{"tpl":"___.","blanks":1,"ans":["Muchos árboles"],"img":"img/gram/u22_ej22-3_06.png","alt":"Un bosque con una casa.","wide":true},{"tpl":"___.","blanks":1,"ans":["Mucha gente"],"img":"img/gram/u22_ej22-3_07.png","alt":"Una playa llena de gente.","wide":true},{"tpl":"___.","blanks":1,"ans":["Pocos árboles"],"img":"img/gram/u22_ej22-3_08.png","alt":"Un campo con una casa y un árbol.","wide":true}]},{"id":"gram:22.4","type":"cloze","lab":"22.4","title":"22.4","instr":"Complete las frases con mucho, poco, demasiado, suficiente, bastante…","items":[{"tpl":"—¿Tienes hambre? —No tengo ___. Puedo esperar.","blanks":1,"ans":["mucha"],"mid":true,"example":true},{"tpl":"—¿Cuántas manzanas tienes? —Tres. Son ___ para una tarta.","blanks":1,"ans":["suficientes","bastantes"],"mid":true},{"tpl":"—¿Cuánto dinero tienes? —Veinticinco euros. Es ___. Las entradas cuestan veinte.","blanks":1,"ans":["suficiente","bastante"],"mid":true},{"tpl":"—¿Cuánta gente hay? —No hay ___. Unas diez personas.","blanks":1,"ans":["mucha"],"mid":true},{"tpl":"—¿Cuántas horas duermes al día? —___. Cinco o seis. Tengo que estudiar.","blanks":1,"ans":["Pocas"],"mid":true},{"tpl":"—¿Crees que veinte bocadillos serán suficientes? —Son ___. Solo somos tres.","blanks":1,"ans":["demasiados"],"mid":true}]}]},{"id":23,"name":"Indefinidos (4)","motto":"alguien, algo, nadie, nada","theory":[{"k":"img","src":"img/gram/u23_teoria-puertas.png","alt":"Hay alguien / No hay nadie / Hay algo / No hay nada detrás de la puerta."},{"k":"p","t":"Se usa <i>alguien, algo, nadie</i> y <i>nada</i> para referirse a personas o cosas de identidad desconocida. <i>alguien</i> = una persona (o varias), pero no se sabe quién · <i>algo</i> = una cosa (o varias), pero no se sabe qué cosa · <i>nadie</i> = ninguna persona · <i>nada</i> = ninguna cosa."},{"k":"h","t":"alguien, algo, nadie, nada"},{"k":"p","t":"<b>Frases afirmativas y preguntas:</b> personas → <i>alguien</i>; cosas → <i>algo</i>."},{"k":"eg","t":"<b>Alguien</b> ha roto la silla. ¿Hay <b>alguien</b> ahí dentro? Hay <b>algo</b> en la sopa. ¿Has dicho <b>algo</b>?"},{"k":"p","t":"<b>Frases negativas:</b> personas → <i>nadie</i>; cosas → <i>nada</i>."},{"k":"eg","t":"No ha venido <b>nadie</b>. Hoy no he vendido <b>nada</b>."},{"k":"note","h":"ATENCIÓN","rows":["<i>nadie, nada</i> + verbo afirmativo → <b>Nadie</b> me ha visto. <b>Nada</b> le importa.","verbo negativo + <i>nadie, nada</i> → No me ha visto <b>nadie</b>. No le importa <b>nada</b>."]},{"k":"p","t":"Se usan <i>algo de, nada de</i> + nombres no contables (agua, queso…) para indicar cantidad."},{"k":"img","src":"img/gram/u23_teoria-queso.png","alt":"«Hay algo de queso en la nevera» (un poco). «No hay nada de queso»."},{"k":"p","t":"Se puede usar <i>algo</i> y <i>nada</i> solos, cuando el nombre al que se refieren se ha mencionado anteriormente."},{"k":"eg","t":"—¿Tienes dinero? —Tengo <b>algo</b>. —Pues yo no tengo <b>nada</b>."}],"ex":[{"id":"gram:23.1","type":"cloze","lab":"23.1","title":"23.1","instr":"Observe las ilustraciones y complete las frases con hay, no hay + alguien, algo, nadie o nada.","items":[{"tpl":"___ en la mesa.","blanks":1,"ans":["No hay nada"],"img":"img/gram/u23_ej23-1_01.png","alt":"Una mesa vacía.","mid":true,"example":true,"exv":["No hay nada"]},{"tpl":"___ en mi habitación.","blanks":1,"ans":["Hay alguien"],"img":"img/gram/u23_ej23-1_02.png","alt":"Una silueta detrás de la puerta.","mid":true},{"tpl":"___ detrás del árbol.","blanks":1,"ans":["Hay alguien"],"img":"img/gram/u23_ej23-1_03.png","alt":"Algo detrás de un árbol.","mid":true},{"tpl":"___ en el salón.","blanks":1,"ans":["No hay nadie"],"img":"img/gram/u23_ej23-1_04.png","alt":"Un salón sin nadie.","mid":true},{"tpl":"___ en el libro.","blanks":1,"ans":["Hay algo"],"img":"img/gram/u23_ej23-1_05.png","alt":"Un libro con algo dentro.","mid":true},{"tpl":"___ en la piscina.","blanks":1,"ans":["No hay nadie"],"img":"img/gram/u23_ej23-1_06.png","alt":"Una piscina vacía.","mid":true},{"tpl":"___ en la caja.","blanks":1,"ans":["No hay nada"],"img":"img/gram/u23_ej23-1_07.png","alt":"Una caja vacía.","mid":true},{"tpl":"___ en el árbol.","blanks":1,"ans":["Hay algo"],"img":"img/gram/u23_ej23-1_08.png","alt":"Un árbol con algo en la copa.","mid":true}]},{"id":"gram:23.2","type":"cloze","lab":"23.2","title":"23.2","instr":"Complete las frases con alguien, algo, nadie o nada.","items":[{"tpl":"Hay ___ esperándole en recepción.","blanks":1,"ans":["alguien"],"example":true},{"tpl":"Me han dado ___ para ti.","blanks":1,"ans":["algo"]},{"tpl":"___ huele mal en la cocina.","blanks":1,"ans":["Algo"]},{"tpl":"Hoy no he hecho ___.","blanks":1,"ans":["nada"]},{"tpl":"¿Ha visto ___ mi bolígrafo?","blanks":1,"ans":["alguien"]},{"tpl":"___ quiere acompañarme al cine.","blanks":1,"ans":["Nadie"]},{"tpl":"Necesito que ___ me ayude con este ejercicio.","blanks":1,"ans":["alguien"]},{"tpl":"Hay mucha gente en la calle. ¿Ha pasado ___?","blanks":1,"ans":["algo"]},{"tpl":"No ha pasado ___. Ha sido una falsa alarma.","blanks":1,"ans":["nada"]},{"tpl":"No hay ___ en casa de Tomás. No contestan el teléfono.","blanks":1,"ans":["nadie"]}]},{"id":"gram:23.3","type":"cloze","lab":"23.3","title":"23.3","instr":"Conteste a las preguntas usando algo, nada, algo de o nada de.","items":[{"tpl":"No queda ___ queso, pero queda ___ jamón.","blanks":2,"ans":["nada de algo de"],"ctx":"¿Hay comida?","mid":true,"example":true,"exv":["nada de","algo de"]},{"tpl":"Queda ___, pero poco.","blanks":1,"ans":["algo"],"ctx":"¿Queda pan?","mid":true},{"tpl":"No queda ___, pero queda ___ zumo.","blanks":2,"ans":["nada algo de"],"ctx":"¿Y leche?","mid":true},{"tpl":"Tenemos ___, pero poco.","blanks":1,"ans":["algo"],"ctx":"Necesitamos comprar comida. ¿Tenéis dinero?","mid":true},{"tpl":"Bueno, podemos comprar ___ pan y ___ queso.","blanks":2,"ans":["algo de algo de"],"ctx":"¿Qué podemos comprar?","mid":true},{"tpl":"No podemos comprar ___ fruta. No tenemos suficiente dinero.","blanks":1,"ans":["nada de"],"ctx":"¿Y fruta?","mid":true}]}]},{"id":24,"name":"Comparación con nombres","motto":"más, menos, tanto","theory":[{"k":"img","src":"img/gram/u24_teoria-comics.png","alt":"«Belén tiene más libros que yo». «Ahora tengo menos pelo que cuando era joven». «Hoy no tengo tanto trabajo como ayer»."},{"k":"p","t":"<i>Más, menos, tanto</i> se usan para hacer comparaciones con nombres. <i>más</i> = mayor cantidad (+) · <i>menos</i> = menor cantidad (–) · <i>tanto</i> = igual cantidad (=)."},{"k":"h","t":"Comparación con nombres"},{"k":"p","t":"<b>(+)</b> <i>más</i> + nombre (+ <i>que</i>)"},{"k":"eg","t":"Ernesto tiene <b>más alumnos que</b> Guadalupe. Pedro tiene <b>más amigos que</b> Antonio."},{"k":"p","t":"<b>(–)</b> <i>menos</i> + nombre (+ <i>que</i>)"},{"k":"eg","t":"Antes había <b>menos coches que</b> ahora. Ahora tengo <b>menos sueño</b> (que antes)."},{"k":"p","t":"<b>(=)</b> <i>tanto, tanta, tantos, tantas</i> + nombre (+ <i>como</i>)"},{"k":"eg","t":"Hoy no hay <b>tanta gente como</b> ayer. No tengo <b>tantos amigos como</b> mi hermana."},{"k":"p","t":"<i>que, como</i> + pronombre personal de sujeto"},{"k":"eg","t":"Rodolfo tiene más vacaciones <b>que tú</b>, pero tú haces más viajes <b>que él</b>. ¿Tienes tanta hambre <b>como yo</b>?"},{"k":"p","t":"Normalmente no se usa <i>que, como</i> + término de comparación cuando está claro con qué se compara."},{"k":"eg","t":"Ahora tengo <b>menos hambre</b>. (que antes de la comida) Hoy no hay <b>tanta gente</b>. (como ayer)"},{"k":"p","t":"<i>Más, menos, tanto…</i> se pueden usar solos cuando el nombre al que se refieren se ha mencionado anteriormente."},{"k":"eg","t":"—Sonia tiene cerca de cien CD. —Yo tengo <b>más</b>. —Pues yo no tengo <b>tantos</b>."},{"k":"p","t":"Sin embargo, en frases afirmativas, <i>tanto, tanta, tantos, tantas</i> van siempre con <i>como</i> + término de comparación."},{"k":"eg","t":"—Elisa tiene una gran colección de CD. —<s>Yo tengo tantos.</s> → Yo tengo <b>tantos como ella</b>."}],"ex":[{"id":"gram:24.1","type":"cloze","lab":"24.1","title":"24.1","instr":"Complete las frases con más, menos o tanto, tanta, tantos, tantas.","items":[{"tpl":"Buenos Aires tiene (+) ___ habitantes que Madrid.","blanks":1,"ans":["más"],"example":true},{"tpl":"Ahora bebo (–) ___ leche que cuando era pequeño.","blanks":1,"ans":["menos"]},{"tpl":"Sol ha leído (+) ___ libros que yo.","blanks":1,"ans":["más"]},{"tpl":"No tengo (=) ___ amigos como mi hermana.","blanks":1,"ans":["tantos"]},{"tpl":"En Canarias no hace (=) ___ calor como en Cuba.","blanks":1,"ans":["tanto"]},{"tpl":"José Manuel trabaja (–) ___ horas que tú.","blanks":1,"ans":["menos"]},{"tpl":"Tenemos (=) ___ prisa como tú.","blanks":1,"ans":["tanta"]},{"tpl":"Samuel tiene (+) ___ ropa que yo.","blanks":1,"ans":["más"]},{"tpl":"En La Paz hace (+) ___ frío que en Caracas.","blanks":1,"ans":["más"]}]},{"id":"gram:24.2","type":"cloze","lab":"24.2","title":"24.2","instr":"Establezca comparaciones utilizando las palabras del recuadro.","bank":["años","calor","corbatas","~dinero","estudiantes","frío","habitantes","hambre","~leche","postales"],"items":[{"tpl":"Roberto tiene 200 pesos. Clara tiene 20. Clara tiene ___.","blanks":1,"ans":["menos dinero que Roberto"],"wide":true,"full":true,"example":true,"exv":["menos dinero que Roberto"]},{"tpl":"Elsa bebe 1/2 litro de leche al día. Eloy bebe 1 litro. Elsa no bebe ___.","blanks":1,"ans":["tanta leche como Eloy"],"wide":true,"full":true,"example":true,"exv":["tanta leche como Eloy"]},{"tpl":"Hoy hace 30°. Ayer hizo 25°. Hoy hace ___.","blanks":1,"ans":["más calor que ayer"],"wide":true,"full":true},{"tpl":"Rosario tiene un millón de habitantes; Mendoza tiene un millón y medio de habitantes. Rosario no tiene ___.","blanks":1,"ans":["tantos habitantes como Mendoza"],"wide":true,"full":true},{"tpl":"Simón tiene 30 años; yo tengo 28. Simón tiene ___.","blanks":1,"ans":["más años que yo"],"wide":true,"full":true},{"tpl":"Ayer vinieron doce estudiantes; hoy han venido diez. Hoy no han venido ___.","blanks":1,"ans":["tantos estudiantes como ayer"],"wide":true,"full":true},{"tpl":"Ayer hizo 5°. Hoy hace 10°. Hoy no hace ___.","blanks":1,"ans":["tanto frío como ayer"],"wide":true,"full":true},{"tpl":"No he comido nada desde esta mañana; Irene no ha comido nada desde anoche. Irene tiene ___.","blanks":1,"ans":["más hambre que yo"],"wide":true,"full":true},{"tpl":"Tengo dos corbatas; tú también tienes dos corbatas. Tengo ___.","blanks":1,"ans":["tantas corbatas como tú"],"wide":true,"full":true},{"tpl":"Habéis recibido cinco postales este verano; yo he recibido tres. He recibido ___.","blanks":1,"ans":["menos postales que vosotros"],"wide":true,"full":true}]},{"id":"gram:24.3","type":"cloze","lab":"24.3","title":"24.3","instr":"Complete las respuestas como en el ejemplo.","items":[{"tpl":"—Felipe tiene dos hijos. —Yo tengo ___. Tengo cuatro.","blanks":1,"ans":["más"],"mid":true,"example":true},{"tpl":"—Tengo siete hermanos. —Yo tengo casi ___. Tengo seis.","blanks":1,"ans":["tantos como tú"],"mid":true,"example":true,"exv":["tantos como tú"]},{"tpl":"—Aurora tiene 30 días de vacaciones. —Yo tengo ___. Tengo 22.","blanks":1,"ans":["menos"],"mid":true},{"tpl":"—Tengo unos quinientos libros. —Yo no tengo ___. Tengo unos trescientos.","blanks":1,"ans":["tantos"],"mid":true},{"tpl":"—Tengo sueño. He dormido solo cuatro horas. —Yo tengo ___. He dormido solo dos horas.","blanks":1,"ans":["más"],"mid":true},{"tpl":"—Hoy hay cerca de doscientos espectadores. —Ayer había ___. Había solo cincuenta.","blanks":1,"ans":["menos"],"mid":true},{"tpl":"—Hemos estado en diez países diferentes. —Yo he estado en ___. He estado en doce.","blanks":1,"ans":["más"],"mid":true},{"tpl":"—Trabajo ocho horas al día. —Yo trabajo ___. También trabajo ocho.","blanks":1,"ans":["tanto como tú"],"mid":true}]}]},{"id":25,"name":"Números cardinales (1)","motto":"uno, dos, tres…","theory":[{"k":"h","t":"Números cardinales 0–99"},{"k":"p","t":"<b>0</b> cero · <b>1</b> uno/un, una · <b>2</b> dos · <b>3</b> tres · <b>4</b> cuatro · <b>5</b> cinco · <b>6</b> seis · <b>7</b> siete · <b>8</b> ocho · <b>9</b> nueve · <b>10</b> diez"},{"k":"p","t":"<b>11</b> once · <b>12</b> doce · <b>13</b> trece · <b>14</b> catorce · <b>15</b> quince · <b>16</b> dieciséis · <b>17</b> diecisiete · <b>18</b> dieciocho · <b>19</b> diecinueve · <b>20</b> veinte"},{"k":"p","t":"<b>21</b> veintiuno/veintiún, veintiuna · <b>22</b> veintidós · <b>23</b> veintitrés · <b>24</b> veinticuatro · <b>25</b> veinticinco · <b>26</b> veintiséis · <b>27</b> veintisiete · <b>28</b> veintiocho · <b>29</b> veintinueve"},{"k":"p","t":"<b>30</b> treinta · <b>40</b> cuarenta · <b>50</b> cincuenta · <b>60</b> sesenta · <b>70</b> setenta · <b>80</b> ochenta · <b>90</b> noventa"},{"k":"p","t":"<b>31</b> treinta y uno / treinta y un / treinta y una · <b>32</b> treinta y dos · <b>43</b> cuarenta y tres · <b>44</b> cuarenta y cuatro · <b>56</b> cincuenta y seis · <b>67</b> sesenta y siete · <b>78</b> setenta y ocho · <b>89</b> ochenta y nueve · <b>99</b> noventa y nueve"},{"k":"note","h":"ATENCIÓN","rows":["<i>uno, una</i> → —¿Cuántos años tienes? —Treinta y <b>uno</b>. —¿Cuántas chicas hay en tu clase? —Veintiuna.","<i>un</i> + nombre masculino → En mi oficina hay veintiún hombres.","<i>un</i> + nombre femenino singular que empieza por á-, há- → En esa montaña vive un águila.","<i>una</i> + nombre femenino → Tengo treinta y una libras."]},{"k":"p","t":"Los números cardinales se usan para indicar:"},{"k":"eg","t":"<b>Cantidad exacta:</b> En mi clase hay catorce alumnos. Solo tengo quince pesos."},{"k":"eg","t":"<b>Medidas, pesos y distancias:</b> Peso setenta y cinco kilos."},{"k":"img","src":"img/gram/u25_teoria-madrid-toledo.png","alt":"De Madrid a Toledo hay ochenta kilómetros."},{"k":"eg","t":"<b>Edad:</b> —¿Cuántos años tienes? —Veinticuatro."},{"k":"eg","t":"<b>Fechas:</b> Hoy es cuatro de febrero. La boda es el día trece."},{"k":"eg","t":"<b>La hora:</b> Las tres y veinte. / Las quince veinte."},{"k":"img","src":"img/gram/u25_teoria-relojes.png","alt":"La una en punto, las tres y diez, las cuatro y cuarto, las cinco menos cuarto."},{"k":"eg","t":"<b>Números de teléfono:</b> 46596703 = cuatro, seis, cinco, nueve, seis, siete, cero, tres. 902 32 46 01 = nueve cero dos, treinta y dos, cuarenta y seis, cero uno."}],"ex":[{"id":"gram:25.1","type":"cloze","lab":"25.1","title":"25.1","instr":"Escriba los siguientes números con palabras.","items":[{"tpl":"21 euros = ___","blanks":1,"ans":["Veintiún euros"],"wide":true,"full":true,"example":true,"exv":["Veintiún euros"]},{"tpl":"10 de enero = ___","blanks":1,"ans":["Diez de enero"],"wide":true,"full":true},{"tpl":"31 días = ___","blanks":1,"ans":["Treinta y un días"],"wide":true,"full":true},{"tpl":"49 kilos = ___","blanks":1,"ans":["Cuarenta y nueve kilos"],"wide":true,"full":true},{"tpl":"15 de diciembre = ___","blanks":1,"ans":["Quince de diciembre"],"wide":true,"full":true},{"tpl":"88 centímetros = ___","blanks":1,"ans":["Ochenta y ocho centímetros"],"wide":true,"full":true},{"tpl":"31 aulas = ___","blanks":1,"ans":["Treinta y un aulas"],"wide":true,"full":true},{"tpl":"28 de febrero = ___","blanks":1,"ans":["Veintiocho de febrero"],"wide":true,"full":true},{"tpl":"25 años = ___","blanks":1,"ans":["Veinticinco años"],"wide":true,"full":true},{"tpl":"61 semanas = ___","blanks":1,"ans":["Sesenta y una semanas"],"wide":true,"full":true},{"tpl":"1 de mayo = ___","blanks":1,"ans":["Uno de mayo","Primero de mayo"],"wide":true,"full":true},{"tpl":"45 kilómetros = ___","blanks":1,"ans":["Cuarenta y cinco kilómetros"],"wide":true,"full":true},{"tpl":"34 metros = ___","blanks":1,"ans":["Treinta y cuatro metros"],"wide":true,"full":true},{"tpl":"53 años = ___","blanks":1,"ans":["Cincuenta y tres años"],"wide":true,"full":true},{"tpl":"92 kilos = ___","blanks":1,"ans":["Noventa y dos kilos"],"wide":true,"full":true},{"tpl":"21 alumnas = ___","blanks":1,"ans":["Veintiuna alumnas"],"wide":true,"full":true},{"tpl":"5 de agosto = ___","blanks":1,"ans":["Cinco de agosto"],"wide":true,"full":true},{"tpl":"11 alumnos = ___","blanks":1,"ans":["Once alumnos"],"wide":true,"full":true},{"tpl":"76 años = ___","blanks":1,"ans":["Setenta y seis años"],"wide":true,"full":true},{"tpl":"51 libras = ___","blanks":1,"ans":["Cincuenta y una libras"],"wide":true,"full":true}]},{"id":"gram:25.2","type":"cloze","lab":"25.2","title":"25.2","instr":"¿Qué hora es? Observe y anote.","items":[{"tpl":"___","blanks":1,"ans":["las tres y veinte"],"img":"img/gram/u25_ej25-2_01.png","alt":"Reloj: las tres y veinte.","wide":true,"example":true,"exv":["las tres y veinte"]},{"tpl":"___","blanks":1,"ans":["la una y cuarto"],"img":"img/gram/u25_ej25-2_02.png","alt":"Reloj: la una y cuarto.","wide":true},{"tpl":"___","blanks":1,"ans":["las nueve y media"],"img":"img/gram/u25_ej25-2_03.png","alt":"Reloj: las nueve y media.","wide":true},{"tpl":"___","blanks":1,"ans":["las seis menos cuarto"],"img":"img/gram/u25_ej25-2_04.png","alt":"Reloj: las seis menos cuarto.","wide":true},{"tpl":"___","blanks":1,"ans":["las once menos veinticinco"],"img":"img/gram/u25_ej25-2_05.png","alt":"Reloj: las once menos veinticinco.","wide":true},{"tpl":"___","blanks":1,"ans":["las ocho quince","las ocho y cuarto","las ocho y quince"],"img":"img/gram/u25_ej25-2_06.png","alt":"Despertador digital: 8:15.","wide":true},{"tpl":"___","blanks":1,"ans":["las nueve cincuenta","las diez menos diez","las nueve y cincuenta"],"img":"img/gram/u25_ej25-2_07.png","alt":"Despertador digital: 9:50.","wide":true},{"tpl":"___","blanks":1,"ans":["las veintiuna veinte","las veintiuna y veinte","las nueve y veinte"],"img":"img/gram/u25_ej25-2_08.png","alt":"Despertador digital: 21:20.","wide":true},{"tpl":"___","blanks":1,"ans":["las doce y treinta y siete","las doce treinta y siete"],"img":"img/gram/u25_ej25-2_09.png","alt":"Despertador digital: 12:37.","wide":true},{"tpl":"___","blanks":1,"ans":["las dieciocho cincuenta y dos","las dieciocho y cincuenta y dos","las seis cincuenta y dos","las siete menos ocho"],"img":"img/gram/u25_ej25-2_10.png","alt":"Despertador digital: 18:52.","wide":true}]},{"id":"gram:25.3","type":"cloze","lab":"25.3","title":"25.3","instr":"Escriba los números de teléfono como en el ejemplo (en el orden de la agenda).","img":"img/gram/u25_ej25-3_agenda.png","alt":"Agenda: 1. Pilar 93 547 89 02; 2. Elvira 92 478 90 16; 3. Tomás 512 02 96; 4. José Luis 91 464 33 58; 5. Antonia 96 352 63 61; 6. Virginia (01) 823 71 92; 7. Ramón 55 43 12 98; 8. Alicia 650 22 34 59.","items":[{"tpl":"Teléfono 1 = ___","blanks":1,"ans":["nueve tres, cinco cuarenta y siete, ochenta y nueve, cero dos"],"wide":true,"full":true,"example":true,"exv":["nueve tres, cinco cuarenta y siete, ochenta y nueve, cero dos"]},{"tpl":"Teléfono 2 = ___","blanks":1,"ans":["nueve dos, cuatro setenta y ocho, noventa, dieciséis"],"wide":true,"full":true},{"tpl":"Teléfono 3 = ___","blanks":1,"ans":["cinco doce, cero dos, noventa y seis"],"wide":true,"full":true},{"tpl":"Teléfono 4 = ___","blanks":1,"ans":["nueve uno, cuatro sesenta y cuatro, treinta y tres, cincuenta y ocho"],"wide":true,"full":true},{"tpl":"Teléfono 5 = ___","blanks":1,"ans":["nueve seis, tres cincuenta y dos, sesenta y tres, sesenta y uno"],"wide":true,"full":true},{"tpl":"Teléfono 6 = ___","blanks":1,"ans":["cero uno, ocho veintitrés, setenta y uno, noventa y dos"],"wide":true,"full":true},{"tpl":"Teléfono 7 = ___","blanks":1,"ans":["cincuenta y cinco, cuarenta y tres, doce, noventa y ocho"],"wide":true,"full":true},{"tpl":"Teléfono 8 = ___","blanks":1,"ans":["seis cincuenta, veintidós, treinta y cuatro, cincuenta y nueve"],"wide":true,"full":true}]}]},{"id":26,"name":"Números cardinales (2)","motto":"cien, mil, un millón…","theory":[{"k":"h","t":"Números cardinales: 100, 1 000…"},{"k":"p","t":"<b>100</b> cien · <b>101</b> ciento uno/un, ciento una · <b>125</b> ciento veinticinco"},{"k":"p","t":"<b>200</b> doscientos, doscientas · <b>300</b> trescientos, trescientas · <b>400</b> cuatrocientos, cuatrocientas · <b>500</b> quinientos, quinientas · <b>600</b> seiscientos, seiscientas · <b>700</b> setecientos, setecientas · <b>800</b> ochocientos, ochocientas · <b>900</b> novecientos, novecientas"},{"k":"p","t":"<b>1 000</b> mil · <b>2 000</b> dos mil · <b>10 000</b> diez mil · <b>100 000</b> cien mil · <b>1 000 000</b> un millón · <b>2 000 000</b> dos millones"},{"k":"eg","t":"137 → ciento treinta y siete · 2 079 → dos mil setenta y nueve · 864 325 → ochocientos sesenta y cuatro mil trescientos veinticinco"},{"k":"eg","t":"1 537 982 → un millón quinientos treinta y siete mil novecientos ochenta y dos · 10 410 212 → diez millones cuatrocientos diez mil doscientos doce"},{"k":"note","h":"ATENCIÓN","rows":["un millón <b>de</b> euros · tres millones <b>de</b> habitantes","PERO: un millón doscientos mil euros · tres millones cien mil habitantes"]},{"k":"img","src":"img/gram/u26_teoria-monedas.png","alt":"«¡Un millón de pesos!»"},{"k":"p","t":"<i>cien</i> + nombre masculino/femenino → cien euros; cien personas. <i>doscientos, trescientos…</i> + nombre masculino → doscientos euros. <i>doscientas, trescientas…</i> + nombre femenino → doscientas personas."},{"k":"p","t":"<i>mil, millón:</i> 1 212 → mil doscientos doce · 2 400 000 → dos millones cuatrocientos mil"},{"k":"p","t":"<b>(,) coma:</b> 3,1416 → tres coma catorce dieciséis · 6,10 → seis (con) diez"},{"k":"p","t":"Recuerde que los números cardinales se usan para indicar:"},{"k":"eg","t":"<b>Cantidad:</b> Jorge gana ciento veinticinco mil pesos al mes. Este piso cuesta cerca de ciento cincuenta mil euros."},{"k":"eg","t":"<b>Medidas, pesos y distancias:</b> Esta mesa mide ciento cincuenta centímetros. De Barcelona a Madrid hay casi seiscientos kilómetros."},{"k":"eg","t":"<b>Edad:</b> El hombre más viejo del mundo tiene ciento doce años. La catedral de Lima tiene más de cuatrocientos años."},{"k":"eg","t":"<b>Los años:</b> 1989 → mil novecientos ochenta y nueve · 2002 → dos mil dos"},{"k":"img","src":"img/gram/u26_teoria-calendario.png","alt":"Calendario de marzo de 2003: «Doce de marzo de dos mil tres»."}],"ex":[{"id":"gram:26.1","type":"cloze","lab":"26.1","title":"26.1","instr":"Transcriba los siguientes números.","items":[{"tpl":"183 = ___","blanks":1,"ans":["ciento ochenta y tres"],"wide":true,"full":true,"example":true,"exv":["ciento ochenta y tres"]},{"tpl":"1 070 = ___","blanks":1,"ans":["mil setenta"],"wide":true,"full":true},{"tpl":"3 561 = ___","blanks":1,"ans":["tres mil quinientos sesenta y uno"],"wide":true,"full":true},{"tpl":"115,10 = ___","blanks":1,"ans":["ciento quince coma diez","ciento quince con diez"],"wide":true,"full":true},{"tpl":"1 231 758 = ___","blanks":1,"ans":["un millón doscientos treinta y un mil setecientos cincuenta y ocho"],"wide":true,"full":true},{"tpl":"3 050 947 = ___","blanks":1,"ans":["tres millones cincuenta mil novecientos cuarenta y siete"],"wide":true,"full":true},{"tpl":"415,25 = ___","blanks":1,"ans":["cuatrocientos quince coma veinticinco","cuatrocientos quince con veinticinco"],"wide":true,"full":true},{"tpl":"22 891 604 = ___","blanks":1,"ans":["veintidós millones ochocientos noventa y un mil seiscientos cuatro"],"wide":true,"full":true}]},{"id":"gram:26.2","type":"cloze","lab":"26.2","title":"26.2","instr":"Escriba con letras los siguientes precios. (1 $ = un dólar, 1 € = un euro, 1 ¥ = un yen, 1 BRL = un real, 1 DKK = una corona danesa, 1 TRL = una lira turca, 1 MXN = un peso mexicano)","items":[{"tpl":"$ 205 = ___","blanks":1,"ans":["Doscientos cinco dólares"],"wide":true,"full":true,"example":true,"exv":["Doscientos cinco dólares"]},{"tpl":"€ 301 = ___","blanks":1,"ans":["Trescientos un euros"],"wide":true,"full":true},{"tpl":"¥ 2 612 = ___","blanks":1,"ans":["Dos mil seiscientos doce yenes"],"wide":true,"full":true},{"tpl":"€ 83 195 = ___","blanks":1,"ans":["Ochenta y tres mil ciento noventa y cinco euros"],"wide":true,"full":true},{"tpl":"BRL 568 = ___","blanks":1,"ans":["Quinientos sesenta y ocho reales"],"wide":true,"full":true},{"tpl":"DKK 1 421 = ___","blanks":1,"ans":["Mil cuatrocientas veintiuna coronas danesas"],"wide":true,"full":true},{"tpl":"TRL 833 = ___","blanks":1,"ans":["Ochocientas treinta y tres liras turcas"],"wide":true,"full":true},{"tpl":"MXN 471 950 = ___","blanks":1,"ans":["Cuatrocientos setenta y un mil novecientos cincuenta pesos mexicanos"],"wide":true,"full":true}]},{"id":"gram:26.3","type":"cloze","lab":"26.3","title":"26.3","instr":"Complete las frases escribiendo los números entre paréntesis.","items":[{"tpl":"La Habana tiene (2 000 000) ___ de habitantes.","blanks":1,"ans":["dos millones"],"wide":true,"example":true,"exv":["dos millones"]},{"tpl":"María gana (2 085) ___ euros al mes.","blanks":1,"ans":["dos mil ochenta y cinco"],"wide":true},{"tpl":"Rafael tiene una colección de más de (300) ___ mariposas.","blanks":1,"ans":["trescientas"],"wide":true},{"tpl":"La mujer más vieja del mundo tiene (118) ___ años.","blanks":1,"ans":["ciento dieciocho"],"wide":true},{"tpl":"De Cartagena a Bogotá hay (1 274) ___ kilómetros.","blanks":1,"ans":["mil doscientos setenta y cuatro"],"wide":true},{"tpl":"Alberto pesa (108) ___ kilos.","blanks":1,"ans":["ciento ocho"],"wide":true},{"tpl":"Machu Picchu tiene más de (500) ___ años.","blanks":1,"ans":["quinientos"],"wide":true},{"tpl":"Esta televisión cuesta (310) ___ bolívares.","blanks":1,"ans":["trescientos diez"],"wide":true}]},{"id":"gram:26.4","type":"cloze","lab":"26.4","title":"26.4","instr":"Escriba las fechas con palabras (en el orden de las hojas del calendario).","img":"img/gram/u26_ej26-4_fechas.png","alt":"Cinco hojas de calendario: 21 de enero de 1812; 2 de mayo de 2001; 25 de octubre de 1954; 31 de diciembre de 2008; 10 de julio de 1613.","items":[{"tpl":"Fecha 1 = ___","blanks":1,"ans":["Veintiuno de enero de mil ochocientos doce"],"wide":true,"full":true,"example":true,"exv":["Veintiuno de enero de mil ochocientos doce"]},{"tpl":"Fecha 2 = ___","blanks":1,"ans":["Dos de mayo de dos mil uno"],"wide":true,"full":true},{"tpl":"Fecha 3 = ___","blanks":1,"ans":["Veinticinco de octubre de mil novecientos cincuenta y cuatro"],"wide":true,"full":true},{"tpl":"Fecha 4 = ___","blanks":1,"ans":["Treinta y uno de diciembre de dos mil ocho"],"wide":true,"full":true},{"tpl":"Fecha 5 = ___","blanks":1,"ans":["Diez de julio de mil seiscientos trece"],"wide":true,"full":true}]}]},{"id":27,"name":"Números ordinales","motto":"primero, segundo, tercero…","theory":[{"k":"img","src":"img/gram/u27_teoria-comics.png","alt":"«Yo vivo allí, en el cuarto piso». «Ángeles tiene siete hermanos. Ella es la segunda»."},{"k":"p","t":"<i>Cuarto</i> y <i>segunda</i> son números ordinales. Se usan para indicar el orden en una clasificación o secuencia."},{"k":"eg","t":"Javier acabó <b>sexto</b> en el maratón. Ana es mi <b>tercera</b> profesora de español."},{"k":"h","t":"Números ordinales"},{"k":"p","t":"<b>1.º/1.ª</b> primero/primer, primera · <b>2.º/2.ª</b> segundo, segunda · <b>3.º/3.ª</b> tercero/tercer, tercera · <b>4.º/4.ª</b> cuarto, cuarta · <b>5.º/5.ª</b> quinto, quinta"},{"k":"p","t":"<b>6.º/6.ª</b> sexto, sexta · <b>7.º/7.ª</b> séptimo, séptima · <b>8.º/8.ª</b> octavo, octava · <b>9.º/9.ª</b> noveno, novena · <b>10.º/10.ª</b> décimo, décima"},{"k":"note","h":"ATENCIÓN","rows":["<i>primero, tercero</i> + sustantivo masculino singular = <i>primer, tercer</i>","El <b>primer</b> tren sale a las 7.20. Hoy es nuestro <b>tercer</b> día en Bolivia."]},{"k":"p","t":"A partir del 11.º se usan normalmente los números cardinales."},{"k":"eg","t":"Alfonso XIII (trece) es el abuelo de Juan Carlos I (primero). La oficina de Maribel está en el piso diecisiete. Federico García Lorca nació a finales del siglo XIX (diecinueve)."},{"k":"p","t":"Los ordinales tienen la misma forma (masculino, femenino, singular o plural) que el nombre al que se refieren."},{"k":"eg","t":"Las oficinas de Intersa están en la <b>tercera</b> planta. Chus y yo quedamos <b>segundos</b> en un campeonato de tenis."},{"k":"p","t":"En algunos casos, los ordinales pueden ir delante o detrás del nombre."},{"k":"eg","t":"Vivo en el <b>segundo</b> piso. / Vivo en el piso <b>segundo</b>. PERO: no con nombres propios: Carlos V (quinto)."},{"k":"p","t":"Los ordinales pueden ir solos cuando está claro el nombre al que se refieren."},{"k":"eg","t":"La Universidad de Chile va <b>primero</b> en la liga. —¿Por qué capítulo vas? —Por el <b>quinto</b>."},{"k":"p","t":"Cuando se escriben con números, se añade <sup>o</sup> para el masculino y <sup>a</sup> para el femenino; o se usan números romanos."},{"k":"img","src":"img/gram/u27_teoria-cartel.png","alt":"Cartel: «Peluquería Rodolfo, 1.º dcha.»"},{"k":"eg","t":"Fernando III · Capítulo VIII"}],"ex":[{"id":"gram:27.1","type":"cloze","lab":"27.1","title":"27.1","instr":"Observe las ilustraciones y complete las frases.","img":"img/gram/u27_ej27-1_buzones.png","alt":"Rótulos de un portal: Antonio Oliva 2.º C; Servicios de Gas 11.º A; Sastrería Moderna 10.º D; Moreno-Arribas abogados 3.º D; Molina Cardoso 12.º A; Gestoría Salvado 1.º A; Hispanosa 14.º D; Academia Cervantes 4.º B; Julia Salinas 7.º C; Editorial Mundisa 9.º D.","items":[{"tpl":"Antonio Oliva vive en el ___ piso.","blanks":1,"ans":["segundo"],"mid":true,"example":true},{"tpl":"Las oficinas de Servicios de Gas están en el piso ___.","blanks":1,"ans":["once"],"mid":true},{"tpl":"La sastrería Moderna está en la ___ planta.","blanks":1,"ans":["décima"],"mid":true},{"tpl":"Hay un despacho de abogados en el ___ piso.","blanks":1,"ans":["tercer"],"mid":true},{"tpl":"La familia Molina Cardoso vive en el piso ___.","blanks":1,"ans":["doce"],"mid":true},{"tpl":"La gestoría Salvado está en el ___ piso.","blanks":1,"ans":["primer"],"mid":true},{"tpl":"Las oficinas de Hispanosa están en el piso ___.","blanks":1,"ans":["catorce"],"mid":true},{"tpl":"La academia Cervantes está en la ___ planta.","blanks":1,"ans":["cuarta"],"mid":true},{"tpl":"Julia Salinas vive en el piso ___.","blanks":1,"ans":["séptimo"],"mid":true},{"tpl":"La editorial Mundisa está en el ___ piso.","blanks":1,"ans":["noveno"],"mid":true}]},{"id":"gram:27.2","type":"cloze","lab":"27.2","title":"27.2","instr":"Escriba los nombres de los personajes con palabras.","items":[{"tpl":"Juan Carlos I = ___","blanks":1,"ans":["Juan Carlos primero"],"wide":true,"example":true,"exv":["Juan Carlos primero"]},{"tpl":"Isabel I = ___","blanks":1,"ans":["Isabel primera"],"wide":true},{"tpl":"Juan XXIII = ___","blanks":1,"ans":["Juan veintitrés"],"wide":true},{"tpl":"Alfonso XII = ___","blanks":1,"ans":["Alfonso doce"],"wide":true},{"tpl":"Luis XV = ___","blanks":1,"ans":["Luis quince"],"wide":true},{"tpl":"Iván IV = ___","blanks":1,"ans":["Iván cuarto"],"wide":true},{"tpl":"Margarita II = ___","blanks":1,"ans":["Margarita segunda"],"wide":true},{"tpl":"Pío XI = ___","blanks":1,"ans":["Pío once"],"wide":true},{"tpl":"Juana III = ___","blanks":1,"ans":["Juana tercera"],"wide":true},{"tpl":"Juan Pablo II = ___","blanks":1,"ans":["Juan Pablo segundo"],"wide":true}]},{"id":"gram:27.3","type":"cloze","lab":"27.3","title":"27.3","instr":"Escriba los números que aparecen entre paréntesis.","items":[{"tpl":"Estudio (2.º) ___ curso de Arquitectura.","blanks":1,"ans":["segundo"],"mid":true,"example":true},{"tpl":"Enero es el (1.º) ___ mes del año.","blanks":1,"ans":["primer"],"mid":true},{"tpl":"Estoy leyendo un libro con (15) ___ capítulos. Voy por el capítulo (11.º) ___.","blanks":2,"ans":["quince once"],"mid":true},{"tpl":"El Valencia es el (1.º) ___ en la Liga de fútbol.","blanks":1,"ans":["primero"],"mid":true},{"tpl":"Javi es el (3.º) ___ de sus hermanos.","blanks":1,"ans":["tercero"],"mid":true},{"tpl":"Ellas han sido las (1.ªs) ___ en llegar.","blanks":1,"ans":["primeras"],"mid":true},{"tpl":"La ñ es la letra (15.ª) ___ del alfabeto.","blanks":1,"ans":["quince"],"mid":true},{"tpl":"El despacho de José está en el (8.º) ___ piso.","blanks":1,"ans":["octavo"],"mid":true},{"tpl":"Tuerza por la (2.ª) ___ calle a la izquierda.","blanks":1,"ans":["segunda"],"mid":true},{"tpl":"Nos vamos de vacaciones la (3.ª) ___ semana de agosto.","blanks":1,"ans":["tercera"],"mid":true},{"tpl":"El siglo XVIII ___ fue el Siglo de las Luces.","blanks":1,"ans":["dieciocho"],"mid":true},{"tpl":"Tina y Carla acabaron (4.ªs) ___ en el campeonato de tenis.","blanks":1,"ans":["cuartas"],"mid":true}]}]},{"id":28,"name":"Relativos (1)","motto":"que, el que, quien…","theory":[{"k":"img","src":"img/gram/u28_teoria-comics.png","alt":"«¿Has visto el paquete que ha llegado?». «El chico con el que sale Nieves es bombero»."},{"k":"p","t":"<i>Que, el que</i> son relativos. Se usan para dar información sobre un nombre anterior sin volver a mencionarlo."},{"k":"eg","t":"Tengo un loro. El loro habla. → Tengo un loro <b>que habla</b>."},{"k":"eg","t":"He recibido una revista. Clara escribe en esta revista. → He recibido una revista <b>en la que escribe Clara</b>."},{"k":"p","t":"En algunos casos, la información sirve para identificar el nombre al que se refiere."},{"k":"eg","t":"—¿Quién es Begoña? —Es <b>la chica que está bailando</b> con Pedro. <b>El coche que está delante del banco</b> es el mío."},{"k":"p","t":"En otros, sirve para definir el nombre al que se refiere."},{"k":"eg","t":"Un carnicero es <b>una persona que vende carne</b>."},{"k":"h","t":"Formas de los relativos"},{"k":"p","t":"(preposición +) <i>que</i> · <i>el que, la que, los que, las que</i> · <i>quien, quienes</i>"},{"k":"p","t":"<i>Que</i> sirve para referirse a personas, animales o cosas."},{"k":"eg","t":"Las chicas <b>que</b> conocimos ayer son de Córdoba. El cóndor es un ave <b>que</b> procede de América del Sur. No me gusta el libro <b>que</b> estoy leyendo."},{"k":"p","t":"Después de una preposición se usa <i>el que, la que, los que, las que</i> para referirse a personas, animales o cosas. Tienen la misma forma (masculino, femenino, singular o plural) que el nombre al que se refieren."},{"k":"eg","t":"Ese es el perro <b>del que</b> te hablé. Las chicas <b>con las que</b> estaba jugando son mis sobrinas."},{"k":"p","t":"Después de una preposición se puede usar también <i>quien</i> o <i>quienes</i> para referirse únicamente a personas."},{"k":"eg","t":"El chico <b>con quien</b> sale Nieves es bombero. Las chicas <b>con quienes</b> estaba jugando son mis sobrinas."},{"k":"p","t":"Se usa <i>el que, la que, los que, las que</i> en lugar de un nombre mencionado anteriormente."},{"k":"eg","t":"—¿Cuál es tu maleta? —<b>La que</b> tiene ruedas. (La maleta que tiene ruedas.) Me gusta más este libro que <b>el que</b> me recomendó Luis."},{"k":"p","t":"Se usa <i>lo que</i> para referirse a una afirmación anterior o a una idea."},{"k":"eg","t":"<b>Lo que</b> has dicho es una tontería. <b>Lo que</b> tú necesitas es mucho cariño."}],"ex":[{"id":"gram:28.1","type":"pick","lab":"28.1","title":"28.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"Ese es el señor con [que|quien] tienes que hablar.","ans":["quien"],"example":true},{"tpl":"Necesito el libro [que|el que] te presté.","ans":["que"]},{"tpl":"Tengo un amigo [que|quien] vive en Panamá.","ans":["que"]},{"tpl":"Este es el restaurante [que|el que] me han recomendado.","ans":["que"]},{"tpl":"Este es el agujero por [que|el que] entran los ratones.","ans":["el que"]},{"tpl":"Sebastián es el chico [que|quien] está hablando con Lola.","ans":["que"]},{"tpl":"¿Conoces a la señora [que|la que] nos ha saludado?","ans":["que"]},{"tpl":"Ese es el equipo contra [que|el que] jugamos el domingo.","ans":["el que"]},{"tpl":"Usa los pañuelos [que|los que] están en el baño.","ans":["que"]},{"tpl":"La academia a [que|la que] voy está en el centro.","ans":["la que"]}]},{"id":"gram:28.2","type":"cloze","lab":"28.2","title":"28.2","instr":"Una las dos frases en una sola con que, quien, quienes, el que, la que, los que o las que.","items":[{"tpl":"Tengo un ventilador. Funciona con pilas. Tengo ___.","blanks":1,"ans":["un ventilador que funciona con pilas"],"wide":true,"full":true,"example":true,"exv":["un ventilador que funciona con pilas"]},{"tpl":"La vicuña es un mamífero. Vive en los Andes. La vicuña ___.","blanks":1,"ans":["es un mamífero que vive en los Andes"],"wide":true,"full":true},{"tpl":"Ayer comimos ostras. ¿Te gustaron? ¿Te gustaron ___?","blanks":1,"ans":["las ostras que comimos ayer"],"wide":true,"full":true},{"tpl":"Estoy leyendo un libro. Me gusta mucho. Me gusta mucho ___.","blanks":1,"ans":["el libro que estoy leyendo"],"wide":true,"full":true},{"tpl":"Paco sale con una chica. La chica es piloto. La chica ___.","blanks":1,"ans":["que sale con Paco es piloto","con la que sale Paco es piloto","con quien sale Paco es piloto"],"wide":true,"full":true},{"tpl":"He comprado unos cuadros. Te había hablado de ellos. He comprado ___.","blanks":1,"ans":["los cuadros de los que te había hablado"],"wide":true,"full":true},{"tpl":"Ayer conocí a unas chicas. Ana vivía con ellas. Ayer ___.","blanks":1,"ans":["conocí a unas chicas con las que vivía Ana","conocí a unas chicas con quienes vivía Ana","a unas chicas con las que vivía Ana"],"wide":true,"full":true}]},{"id":"gram:28.3","type":"cloze","lab":"28.3","title":"28.3","instr":"Escriba las respuestas con las palabras entre paréntesis y el relativo adecuado.","items":[{"tpl":"___.","blanks":1,"ans":["Un chico que conocí en el parque"],"ctx":"¿Quién es Roberto? (Un chico. Lo conocí en el parque.)","wide":true,"full":true,"example":true,"exv":["Un chico que conocí en el parque"]},{"tpl":"___.","blanks":1,"ans":["Una persona que no bebe alcohol"],"ctx":"¿Qué es un «abstemio»? (Una persona. No bebe alcohol.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Un cuadro que he pintado yo"],"ctx":"¿Qué le has regalado a Cristóbal? (Un cuadro. Lo he pintado yo.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Unos obreros que están arreglando la calle"],"ctx":"¿Quién hace tanto ruido? (Unos obreros. Están arreglando la calle.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Un chico con el que trabajo","Un chico con quien trabajo"],"ctx":"¿Quién es Óscar? (Un chico. Trabajo con él.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Una persona que no cree en Dios"],"ctx":"¿Qué es un «ateo»? (Una persona. No cree en Dios.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Una persona que cuida niños"],"ctx":"¿Qué es un «canguro»? (Una persona. Cuida niños.)","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Una pluma con la que escribía Quevedo","Una pluma con la cual escribía Quevedo"],"ctx":"¿Qué te ha enseñado? (Una pluma. Quevedo escribía con ella.)","wide":true,"full":true}]},{"id":"gram:28.4","type":"cloze","lab":"28.4","title":"28.4","instr":"Complete las frases con que, el que, la que, los que, las que o lo que.","items":[{"tpl":"—¿Quién es esa chica? —___ trabaja con Eduardo.","blanks":1,"ans":["La que"],"mid":true,"example":true},{"tpl":"___ tú quieres es imposible.","blanks":1,"ans":["Lo que"],"mid":true},{"tpl":"—¿Qué libro estás leyendo? —___ me prestó Antonio.","blanks":1,"ans":["El que"],"mid":true},{"tpl":"Mi casa es ___ está en aquella esquina.","blanks":1,"ans":["la que"],"mid":true},{"tpl":"¿Recuerdas ___ dijiste ayer?","blanks":1,"ans":["lo que"],"mid":true},{"tpl":"—¿Quiénes son esas chicas? —___ estuvieron en mi fiesta.","blanks":1,"ans":["Las que"],"mid":true},{"tpl":"—¿Quiénes son Guille y Silverio? —___ viven en el sexto.","blanks":1,"ans":["Los que"],"mid":true}]}]},{"id":29,"name":"Relativos (2)","motto":"cuyo, donde, cuando…","theory":[{"k":"img","src":"img/gram/u29_teoria-perro.png","alt":"«Esa es la persona cuyo perro ganó el concurso»."},{"k":"p","t":"Se usa <i>cuyo, cuya, cuyos, cuyas</i> para indicar posesión y otro tipo de relaciones: parentesco, procedencia, etc."},{"k":"eg","t":"Tengo un amigo. Su padre es fotógrafo. → Tengo un amigo <b>cuyo padre</b> es fotógrafo. Los alumnos <b>cuyos nombres</b> diga pueden salir."},{"k":"p","t":"(preposición +) <i>cuyo, cuya, cuyos, cuyas</i> + nombre"},{"k":"eg","t":"Ese señor es un escritor. Te he hablado de sus libros. → Ese es el escritor <b>de cuyos libros</b> te he hablado. Ese es el profesor <b>en cuya casa</b> fue la fiesta."},{"k":"p","t":"<i>Cuyo, cuya, cuyos, cuyas</i> tienen la misma forma (masculino, femenino, singular o plural) que el nombre al que acompañan."},{"k":"eg","t":"Conozco a una chica <b>cuya hermana</b> ha escalado el Aconcagua. Conozco a un señor <b>cuyos hijos</b> han estudiado Físicas."},{"k":"h","t":"donde, adonde, cuando"},{"k":"img","src":"img/gram/u29_teoria-curva.png","alt":"«Esta es la curva donde tuve el accidente»."},{"k":"p","t":"Se puede usar <i>donde</i> y <i>adonde</i> para referirse a lugares."},{"k":"p","t":"<i>donde:</i> en lugar de en el que, en la que, en los que, en las que."},{"k":"eg","t":"Esta es la casa <b>donde</b> nació Cervantes. (en la que nació Cervantes) Me gustó mucho el restaurante <b>donde</b> comimos ayer. (en el que comimos ayer)"},{"k":"p","t":"<i>adonde:</i> en lugar de al que, a la que, a los que, a las que."},{"k":"eg","t":"Esta es la piscina <b>adonde</b> van los niños en verano. (a la que van los niños en verano)"},{"k":"p","t":"Se puede usar <i>cuando</i> para referirse a una expresión de tiempo."},{"k":"eg","t":"El verano <b>cuando</b> nos conocimos fue muy especial."}],"ex":[{"id":"gram:29.1","type":"cloze","lab":"29.1","title":"29.1","instr":"Una las frases con cuyo, cuya, cuyos, cuyas como en el ejemplo.","items":[{"tpl":"___.","blanks":1,"ans":["Esa es la tienda cuyo dueño es mi tío"],"ctx":"Esa es la tienda. Su dueño es mi tío.","wide":true,"full":true,"example":true,"exv":["Esa es la tienda cuyo dueño es mi tío"]},{"tpl":"___.","blanks":1,"ans":["Mi madre tiene una amiga cuya hija está en mi clase"],"ctx":"Mi madre tiene una amiga. Su hija está en mi clase.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Conozco a un chico cuya madre es capitán del ejército"],"ctx":"Conozco a un chico. Su madre es capitán del ejército.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Lorenzo conoce a un profesor cuyos hijos hablan cuatro idiomas"],"ctx":"Lorenzo conoce a un profesor. Sus hijos hablan cuatro idiomas.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Tengo un primo cuya mujer dirige una multinacional"],"ctx":"Tengo un primo. Su mujer dirige una multinacional.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Tengo una abuela en cuyo pueblo paso las vacaciones"],"ctx":"Tengo una abuela. Paso las vacaciones en su pueblo.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["El verano pasado ayudamos a una familia cuyo coche se había averiado"],"ctx":"El verano pasado ayudamos a una familia. Su coche se había averiado.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Tengo unas amigas cuyos padres veranean en Asturias"],"ctx":"Tengo unas amigas. Sus padres veranean en Asturias.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Me encontré con un chico con cuya hermana viajé a Guatemala"],"ctx":"Me encontré con un chico. Viajé a Guatemala con su hermana.","wide":true,"full":true},{"tpl":"___.","blanks":1,"ans":["Me he encontrado con una señora para cuyas hijas estoy haciendo un mueble"],"ctx":"Me he encontrado con una señora. Estoy haciendo un mueble para sus hijas.","wide":true,"full":true}]},{"id":"gram:29.2","type":"cloze","lab":"29.2","title":"29.2","instr":"Lea la información sobre los vecinos de un edificio y responda a las preguntas.","items":[{"tpl":"¿Quién es el Sr. Palacios? Es el hombre ___.","blanks":1,"ans":["cuya mujer da clases en la universidad"],"ctx":"Sr. Palacios: «Su mujer da clases en la universidad.»","wide":true,"full":true,"example":true,"exv":["cuya mujer da clases en la universidad"]},{"tpl":"¿Quiénes son Alba y Silvia? Son las chicas ___.","blanks":1,"ans":["cuyo piso está enfrente del nuestro"],"ctx":"Alba y Silvia: «Su piso está enfrente del nuestro.»","wide":true,"full":true},{"tpl":"¿Quiénes son los Torroja? Son la familia ___.","blanks":1,"ans":["cuyos perros ladran por las noches"],"ctx":"Familia Torroja: «Sus perros ladran por las noches.»","wide":true,"full":true},{"tpl":"¿Quién es Alberto? Es el chico ___.","blanks":1,"ans":["en cuya casa hicimos una fiesta"],"ctx":"Alberto: «Hicimos una fiesta en su casa.»","wide":true,"full":true},{"tpl":"¿Quién es la Sra. Albéniz? Es la señora ___.","blanks":1,"ans":["cuyas hijas bailan muy bien"],"ctx":"Sra. Albéniz: «Sus hijas bailan muy bien.»","wide":true,"full":true},{"tpl":"¿Quiénes son Pablo y Teresa? Son los señores ___.","blanks":1,"ans":["cuya gata nos visita todas las tardes"],"ctx":"Pablo y Teresa: «Su gata nos visita todas las tardes.»","wide":true,"full":true}]},{"id":"gram:29.3","type":"cloze","lab":"29.3","title":"29.3","instr":"Complete las frases con donde, adonde o cuando.","items":[{"tpl":"Rocío es la dueña de la casa ___ vive Matías.","blanks":1,"ans":["donde"],"mid":true,"example":true},{"tpl":"Esta es la escuela ___ estudié.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"Son los domingos ___ más gente viene.","blanks":1,"ans":["cuando"],"mid":true},{"tpl":"Este es el edificio ___ trabaja Marisa.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"Lima es la ciudad ___ está enterrado Pizarro.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"Esta es la dirección ___ tienes que mandar el paquete.","blanks":1,"ans":["adonde"],"mid":true},{"tpl":"Normalmente es a las dos ___ comemos.","blanks":1,"ans":["cuando"],"mid":true},{"tpl":"El país ___ conocí a mi marido fue Colombia.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"El pueblo ___ nació Adolfo ya no existe.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"¿Cuál es el pueblo ___ vais en verano?","blanks":1,"ans":["adonde"],"mid":true},{"tpl":"Este es el hotel ___ nos alojamos el año pasado.","blanks":1,"ans":["donde"],"mid":true},{"tpl":"Recuerdo una época ___ no había muchos coches en Madrid.","blanks":1,"ans":["cuando"],"mid":true}]}]},{"id":30,"name":"Interrogativos (1)","motto":"¿quién?, ¿qué?…","theory":[{"k":"img","src":"img/gram/u30_teoria-comics.png","alt":"«¿Quién vive en esa casa? – Un actor famoso». «¿Qué va a tomar? – Un café, por favor»."},{"k":"p","t":"<i>Quién</i> y <i>qué</i> son interrogativos. Se usan para pedir información sobre personas, animales o cosas."},{"k":"p","t":"(preposición: a, de, con… +) <i>quién</i> · <i>quiénes</i> · <i>qué</i> · <i>qué</i> + nombre"},{"k":"eg","t":"¿<b>Quién</b> ha llamado por teléfono? ¿<b>Quiénes</b> son los ganadores? ¿<b>Qué</b> vende esa señora? ¿<b>Qué queso</b> prefieres? ¿<b>Para quién</b> es esta carta? ¿<b>Con qué</b> has hecho el caldo?"},{"k":"note","h":"ATENCIÓN","rows":["interrogativo sujeto (quién, qué) + verbo (+ complementos): ¿<b>Quién</b> ha vendido el ordenador? ¿<b>Qué</b> pasa?","interrogativo complemento (a quién, qué…) + verbo + sujeto (+ complementos): ¿<b>A quién</b> ha vendido Alejo el ordenador? ¿<b>Qué</b> ha vendido Alejo?"]},{"k":"p","t":"Se usa <i>quién</i> o <i>quiénes</i> para preguntar por la identidad de personas."},{"k":"eg","t":"—¿Quién es esa señora? —Es mi profesora de piano. —¿Quiénes son los hermanos de Mercedes? —Los que están en la mesa del centro. —¿Con quién está hablando Pablo? —Con un vecino."},{"k":"p","t":"Se usa <i>qué</i> para preguntar por cosas o acciones."},{"k":"eg","t":"—¿Qué tienes en la mano? —Unas monedas. —¿Qué hacéis? —Estamos estudiando un poco. —¿De qué están hablando? —De fútbol, como siempre."},{"k":"p","t":"Se usa <i>qué</i> + nombre singular o plural para preguntar por una clase de cosas o animales (¿qué clase de…?)."},{"k":"eg","t":"—¿Qué queso habéis comprado? (¿Qué clase de queso?) —Queso de bola. —¿Qué animales viven en la tierra y en el agua? —Los anfibios."}],"ex":[{"id":"gram:30.1","type":"cloze","lab":"30.1","title":"30.1","instr":"Ordene las palabras de las siguientes preguntas.","items":[{"tpl":"___","blanks":1,"ans":["¿Qué tiene Julián en la mano?"],"ctx":"¿tiene / en la mano / Julián / qué?","wide":true,"full":true,"example":true,"exv":["¿Qué tiene Julián en la mano?"]},{"tpl":"___","blanks":1,"ans":["¿Con quién está bailando Eloísa?"],"ctx":"¿quién / Eloísa / está bailando / con?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Para quién es ese anillo?"],"ctx":"¿ese anillo / para / es / quién?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Qué pasó anoche?"],"ctx":"¿anoche / pasó / qué?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿De quién es esa bolsa?"],"ctx":"¿quién / esa bolsa / de / es?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Qué te han regalado tus padres?"],"ctx":"¿tus padres / te / qué / han regalado?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Con qué has abierto la puerta?"],"ctx":"¿la puerta / qué / has abierto / con?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Quién está escribiendo una novela?"],"ctx":"¿está escribiendo / una novela / quién?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Qué quiere María?"],"ctx":"¿María / qué / quiere?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Quién quiere a María?"],"ctx":"¿quiere / a María / quién?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿De qué es la sopa?"],"ctx":"¿es / la sopa / qué / de?","wide":true,"full":true}]},{"id":"gram:30.2","type":"cloze","lab":"30.2","title":"30.2","instr":"Complete las preguntas con quién, quiénes o qué.","items":[{"tpl":"¿___ te ha regalado ese collar?","blanks":1,"ans":["Quién"],"mid":true,"example":true},{"tpl":"¿De ___ es esta pluma?","blanks":1,"ans":["quién"],"mid":true},{"tpl":"¿___ miel tomas normalmente?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿Con ___ fuiste a Bolivia?","blanks":1,"ans":["quién"],"mid":true},{"tpl":"¿___ estás haciendo?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿___ van a jugar en el equipo esta semana?","blanks":1,"ans":["Quiénes"],"mid":true},{"tpl":"¿___ libros le gustan a Teresa?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿Con ___ has abierto el paquete?","blanks":1,"ans":["qué"],"mid":true},{"tpl":"¿A ___ visteis anoche en la fiesta?","blanks":1,"ans":["quién"],"mid":true},{"tpl":"¿___ visteis anoche en la tele?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿___ quería Julián?","blanks":1,"ans":["Qué"],"mid":true}]},{"id":"gram:30.3","type":"cloze","lab":"30.3","title":"30.3","instr":"Formule preguntas sobre la información subrayada en cada caso.","items":[{"tpl":"—¿___ estuviste ayer?","blanks":1,"ans":["Con quién"],"ctx":"—Ayer estuve <u>con Águeda</u>.","mid":true,"example":true},{"tpl":"—¿___ está hecha esa silla?","blanks":1,"ans":["De qué"],"ctx":"—Esa silla está hecha <u>de cuerda</u>.","mid":true},{"tpl":"—¿___ pan coméis?","blanks":1,"ans":["Con qué"],"ctx":"—Normalmente comemos con pan <u>de molde</u>.","mid":true},{"tpl":"—¿___ quiere comprarse Alfonso?","blanks":1,"ans":["Qué"],"ctx":"—Alfonso quiere comprarse <u>un CD</u>.","mid":true},{"tpl":"—¿___ son esas gafas?","blanks":1,"ans":["De quién"],"ctx":"—Estas gafas son <u>de Pablo</u>.","mid":true},{"tpl":"—¿___ está trabajando Georgina?","blanks":1,"ans":["Con quién"],"ctx":"—Georgina está trabajando <u>con su madre</u>.","mid":true},{"tpl":"—¿___ han ganado?","blanks":1,"ans":["Quiénes"],"ctx":"—Han ganado <u>Eduardo y Marisa</u>.","mid":true},{"tpl":"—¿___ están haciendo esos chicos?","blanks":1,"ans":["Qué"],"ctx":"—Mira. Esos chicos están <u>bailando</u>.","mid":true},{"tpl":"—¿___ no quiere Belinda?","blanks":1,"ans":["A quién"],"ctx":"—Belinda no quiere <u>a Ariel</u>.","mid":true},{"tpl":"—¿___ son esas flores?","blanks":1,"ans":["Para quién"],"ctx":"—Estas flores son <u>para mi abuela</u>.","mid":true},{"tpl":"—¿___ te han regalado?","blanks":1,"ans":["Qué"],"ctx":"—Me han regalado <u>unos bombones</u>.","mid":true}]}]},{"id":31,"name":"Interrogativos (2)","motto":"¿cuál?, ¿qué?…","theory":[{"k":"img","src":"img/gram/u31_teoria-comics.png","alt":"«¿Cuál es tu coche? – El que tiene muchas pegatinas». «¿Cuáles de estos países no tienen costa: Uruguay, Paraguay, Bolivia…?»"},{"k":"p","t":"<i>Cuál, cuáles</i> son interrogativos. Se usan para pedir información sobre personas, animales o cosas."},{"k":"p","t":"(preposición: a, de, con… +) <i>cuál, cuáles</i> · <i>cuál, cuáles</i> + <i>de</i> + estos, esos (+ nombre) / mis, tus + nombre / los + nombre / nosotros, vosotras, ustedes, ellos…"},{"k":"eg","t":"¿<b>Cuál</b> es tu color preferido? ¿<b>Cuáles</b> son tus deportes preferidos? ¿<b>Cuál de tus hermanos</b> vive en La Habana? ¿<b>Cuál de vosotros</b> habla ruso? ¿<b>Cuál de estas ciudades</b> está en Argentina: Tucumán, Guayaquil o Arequipa?"},{"k":"p","t":"Se usa <i>cuál, cuáles</i> para pedir información sobre un grupo específico de cosas o personas. La pregunta da a elegir entre dos o más elementos de ese grupo."},{"k":"eg","t":"—¿Tienes un boli? —Sí. Tengo uno azul y otro negro. ¿<b>Cuál</b> prefieres? —El negro. —¿<b>Cuál de</b> esas chicas es la hermana de Toni? —La del pelo largo."},{"k":"eg","t":"—¿<b>Cuál</b> es el río más largo del mundo? —El Nilo. —¿Por <b>cuál de</b> estas ciudades pasa el Ebro: Barcelona, Zaragoza o Valencia? —Por Zaragoza."},{"k":"p","t":"También se puede usar <i>qué</i> + nombre para pedir información sobre un grupo específico."},{"k":"img","src":"img/gram/u31_teoria-alcala.png","alt":"«¿En qué ciudad española está la Puerta de Alcalá?»"},{"k":"eg","t":"—¿<b>Qué libro</b> prefieres: el de Borges o el de Cortázar? —¿<b>Qué médico</b> te ha visto? —La doctora Martín."},{"k":"h","t":"Compare"},{"k":"p","t":"<b>Respuesta abierta</b> (<i>qué, quién, quiénes</i>): ¿Qué quieres? ¿Qué es un OVNI? ¿Quién inventó el teléfono? ¿Quiénes han venido?"},{"k":"p","t":"<b>Respuesta limitada</b> (<i>qué</i> + nombre): ¿Qué libro quieres? ¿Qué poeta famoso nació en Chile? (no se dice <s>¿Qué es tu apellido?</s>)"},{"k":"p","t":"<b>Respuesta limitada</b> (<i>cuál, cuáles</i>): ¿Cuál de estos libros quieres? ¿Cuál es tu apellido? ¿Cuáles de estas cajas son nuestras? (no se dice <s>¿Cuál libro quieres?</s>)"},{"k":"note","h":"PERO","rows":["Se usa <i>¿qué?</i> para cosas y <i>¿quién?</i> para personas cuando se dicen los elementos entre los que se da a elegir.","¿<b>Qué</b> prefieren, carne o pescado? ¿<b>Quién</b> es más alta, Rosana o Leila?"]}],"ex":[{"id":"gram:31.1","type":"pick","lab":"31.1","title":"31.1","instr":"Una los interrogativos con el resto de las preguntas.","items":[{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] esos chicos es el hijo de Guillermo?","ans":["Cuál de"],"example":true},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] es tu bebida preferida?","ans":["Cuál"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] tus padres nació en Panamá?","ans":["Cuál de"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] tus hermanos nacieron en Ecuador?","ans":["Cuáles de"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] ustedes ha estado en la Patagonia?","ans":["Cuál de"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] los dos diccionarios prefieres?","ans":["Cuál de"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] es la montaña más alta del mundo?","ans":["Cuál"]},{"tpl":"¿[Cuál|Cuáles|Cuál de|Cuáles de] son las cinco ciudades más pobladas de América?","ans":["Cuáles"]}]},{"id":"gram:31.2","type":"cloze","lab":"31.2","title":"31.2","instr":"Complete las frases con cuál, cuáles, cuál de, cuáles de o qué.","items":[{"tpl":"—¿___ tus hermanos trabaja en Aerolíneas? —Jaime.","blanks":1,"ans":["Cuál de"],"mid":true,"example":true},{"tpl":"—¿___ es tu comida preferida? —El pescado.","blanks":1,"ans":["Cuál"],"mid":true},{"tpl":"—¿___ son tus deportes preferidos? —El baloncesto y el tenis.","blanks":1,"ans":["Cuáles"],"mid":true},{"tpl":"—¿___ deportes practicas? —Tenis y natación.","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"—¿___ quieres estudiar? —Aún no lo sé.","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"—¿___ es tu película preferida? —Casablanca.","blanks":1,"ans":["Cuál"],"mid":true},{"tpl":"—¿___ tus hermanas vive en Rosario? —Cecilia.","blanks":1,"ans":["Cuál de"],"mid":true},{"tpl":"—¿En ___ ciudad de México vive María? —En Tijuana.","blanks":1,"ans":["qué"],"mid":true},{"tpl":"—¿Con ___ líneas aéreas va a viajar Sol? —Con Iberia.","blanks":1,"ans":["qué"],"mid":true},{"tpl":"—¿___ son nuestras habitaciones? —Las tres de la derecha.","blanks":1,"ans":["Cuáles"],"mid":true},{"tpl":"—¿En ___ trabaja Mariano? —Es cocinero.","blanks":1,"ans":["qué"],"mid":true},{"tpl":"—¿___ prefieres, té o café? —Té.","blanks":1,"ans":["Qué"],"mid":true}]},{"id":"gram:31.3","type":"cloze","lab":"31.3","title":"31.3","instr":"Complete las preguntas de un concurso de cultura de España y América Latina. Utilice quién, quiénes, qué, cuál, cuál de.","items":[{"tpl":"¿___ es la ciudad más antigua de América Latina?","blanks":1,"ans":["Cuál"],"mid":true,"example":true},{"tpl":"¿___ es un «huaino»?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿En ___ ciudad española está el Museo del Prado?","blanks":1,"ans":["qué"],"mid":true},{"tpl":"¿___ es la capital de Colombia?","blanks":1,"ans":["Cuál"],"mid":true},{"tpl":"¿___ escribió Trilce?","blanks":1,"ans":["Quién"],"mid":true},{"tpl":"¿___ río atraviesa Santiago de Chile?","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¿Entre ___ países está el lago Titicaca?","blanks":1,"ans":["qué"],"mid":true},{"tpl":"¿En ___ estas ciudades está la Sagrada Familia: Barcelona, Sevilla o Valladolid?","blanks":1,"ans":["cuál de"],"mid":true},{"tpl":"¿___ construyeron Machu Picchu?","blanks":1,"ans":["Quiénes"],"mid":true},{"tpl":"¿En ___ país suramericano está el volcán Inti?","blanks":1,"ans":["qué"],"mid":true},{"tpl":"¿___ es la ciudad más poblada de América Latina?","blanks":1,"ans":["Cuál"],"mid":true},{"tpl":"¿___ es un «poncho»?","blanks":1,"ans":["Qué"],"mid":true}]}]},{"id":32,"name":"Interrogativos (3)","motto":"¿cuándo?, ¿dónde?…","theory":[{"k":"p","t":"<b>dónde</b> → para pedir información sobre un lugar (por, de… dónde)."},{"k":"eg","t":"—¿<b>Dónde</b> vive Graciela? —En Rosario. —¿Por <b>dónde</b> pasa el Guadalquivir? —Por Sevilla."},{"k":"p","t":"<b>adónde</b> → para preguntar por el lugar al que va alguien o algo."},{"k":"eg","t":"—¿<b>Adónde</b> vais a ir este verano? —A Ica. —¿<b>Adónde</b> hay que enviar este paquete?"},{"k":"p","t":"<b>cuándo</b> → para pedir información sobre el momento de realización de una acción (desde, hasta… cuándo)."},{"k":"eg","t":"—¿<b>Cuándo</b> se casa Sebastián? —El mes que viene. —¿Desde <b>cuándo</b> estudias español? —Desde hace un año."},{"k":"p","t":"<b>cuánto, cuánta, cuántos, cuántas</b> (+ nombre) → para pedir información sobre cantidad (con, en… cuánto)."},{"k":"eg","t":"—¿<b>Cuántos</b> años tiene Rosario? —Doce. —¿Con <b>cuántos</b> amigos vas?"},{"k":"p","t":"Se puede usar <i>cuánto</i> solo cuando está claro de qué estamos hablando."},{"k":"eg","t":"¿<b>Cuánto</b> vale esa revista? (¿Cuánto dinero?) —Cinco pesos. ¿<b>Cuánto</b> pesas? (¿Cuántos kilos?) —Sesenta y cinco kilos."},{"k":"p","t":"<b>cómo</b> → para pedir información sobre el modo o la manera en que se realiza una acción; sobre el estado de alguien o algo; o sobre sus características."},{"k":"eg","t":"¿<b>Cómo</b> conduce Alberto? —Bastante mal. ¿<b>Cómo</b> está la madre de Julia? —Ya está mejor. ¿<b>Cómo</b> son los padres de Aurora? —Son muy simpáticos."},{"k":"p","t":"<b>por qué</b> → para pedir información sobre las causas o los motivos de una acción."},{"k":"eg","t":"—¿<b>Por qué</b> no viniste ayer? —Estaba un poco cansada."},{"k":"p","t":"<b>para qué</b> → para pedir información sobre el objetivo o la finalidad de una acción o sobre el uso de un objeto."},{"k":"eg","t":"—¿<b>Para qué</b> quieres la plancha? —Quiero plancharme una camisa. —¿<b>Para qué</b> sirve esa máquina? —Para moler café."},{"k":"note","h":"ATENCIÓN","rows":["interrogativo (dónde, cuándo…) + verbo + sujeto","¿Dónde vive <b>Graciela</b>? ¿Por qué se ríe <b>Juanjo</b>?"]}],"ex":[{"id":"gram:32.1","type":"cloze","lab":"32.1","title":"32.1","instr":"Ordene las palabras para formar frases.","items":[{"tpl":"___","blanks":1,"ans":["¿Hasta cuándo vais a estar en Santander?"],"ctx":"¿en Santander / cuándo / hasta / vais a estar?","wide":true,"full":true,"example":true,"exv":["¿Hasta cuándo vais a estar en Santander?"]},{"tpl":"___","blanks":1,"ans":["¿Cómo fue Javier a Brasil?"],"ctx":"¿a Brasil / cómo / Javier / fue?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Por qué lloran los niños?"],"ctx":"¿los niños / lloran / por qué?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde trabaja Sebastián?"],"ctx":"¿trabaja / Sebastián / dónde?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Para qué sirve este botón?"],"ctx":"¿este botón / para qué / sirve?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿De dónde es Peter?"],"ctx":"¿dónde / Peter / de / es?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Para cuántos es la comida?"],"ctx":"¿la comida / para / es / cuántos?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Cómo están los enfermos?"],"ctx":"¿están / los enfermos / cómo?","wide":true,"full":true}]},{"id":"gram:32.2","type":"cloze","lab":"32.2","title":"32.2","instr":"Formule preguntas sobre la información marcada en cada caso.","items":[{"tpl":"—¿___ estuviste en Antigua?","blanks":1,"ans":["Cuándo"],"ctx":"—<b>El año pasado</b> estuve en Antigua.","mid":true,"example":true},{"tpl":"—¿___ vais a ir el domingo?","blanks":1,"ans":["Adónde"],"ctx":"—El domingo vamos a ir <b>al campo</b>.","mid":true},{"tpl":"—¿___ es el novio de Carla?","blanks":1,"ans":["Cómo"],"ctx":"—El novio de Carla es <b>muy agradable</b>.","mid":true},{"tpl":"—¿___ pesos necesitas?","blanks":1,"ans":["Cuántos"],"ctx":"—Necesito <b>veinte</b> pesos.","mid":true},{"tpl":"—¿___ estudias?","blanks":1,"ans":["Cuándo"],"ctx":"—Normalmente estudio <b>por la tarde</b>.","mid":true},{"tpl":"—¿___ está Ramón?","blanks":1,"ans":["Dónde"],"ctx":"—Ramón está <b>en la playa</b>.","mid":true},{"tpl":"—¿___ necesitas un cuchillo?","blanks":1,"ans":["Para qué"],"ctx":"—Necesito un cuchillo <b>para la carne</b>.","mid":true},{"tpl":"—¿___ no pudiste venir anoche?","blanks":1,"ans":["Por qué"],"ctx":"—No pude venir anoche. <b>Estaba cansado</b>.","mid":true},{"tpl":"—¿___ vives en Quito?","blanks":1,"ans":["Desde cuándo"],"ctx":"—Vivo en Quito <b>desde 1999</b>.","mid":true},{"tpl":"—¿___ es Martina?","blanks":1,"ans":["De dónde"],"ctx":"—Martina es <b>de Bolivia</b>.","mid":true}]},{"id":"gram:32.3","type":"cloze","lab":"32.3","title":"32.3","instr":"Complete la entrevista con los interrogativos adecuados.","items":[{"tpl":"¿___ vive actualmente?","blanks":1,"ans":["Dónde"],"ctx":"Respuesta: «En Barcelona.»","mid":true,"example":true},{"tpl":"¿___ vive allí?","blanks":1,"ans":["Por qué"],"ctx":"Respuesta: «Me gusta la ciudad.»","mid":true},{"tpl":"¿___ está aprendiendo español?","blanks":1,"ans":["Por qué"],"ctx":"Respuesta: «Quiero trabajar en España.»","mid":true},{"tpl":"¿___ empezó a estudiarlo?","blanks":1,"ans":["Cuándo"],"ctx":"Respuesta: «Hace seis meses.»","mid":true},{"tpl":"¿___ empieza el rodaje de la próxima película?","blanks":1,"ans":["Cuándo"],"ctx":"Respuesta: «Dentro de una semana.»","mid":true},{"tpl":"¿___ va a ser?","blanks":1,"ans":["Dónde"],"ctx":"Respuesta: «En Brasil y Paraguay.»","mid":true},{"tpl":"¿___ se va a titular la película?","blanks":1,"ans":["Cómo"],"ctx":"Respuesta: «Ruta peligrosa.»","mid":true}]},{"id":"gram:32.4","type":"cloze","lab":"32.4","title":"32.4","instr":"Complete con cuánto, cuánta, cuántos o cuántas.","items":[{"tpl":"—¿___ años tienes? —Veinticuatro.","blanks":1,"ans":["Cuántos"],"mid":true,"example":true},{"tpl":"—¿___ tiempo necesitas para hacer la comida? —Una hora.","blanks":1,"ans":["Cuánto"],"mid":true},{"tpl":"—En mi clase hay muy pocas chicas. —¿___ hay?","blanks":1,"ans":["Cuántas"],"mid":true},{"tpl":"—¿___ se tarda en hacer el test? —Media hora.","blanks":1,"ans":["Cuánto"],"mid":true},{"tpl":"—¿___ gente ha venido a la conferencia? —Unas treinta personas.","blanks":1,"ans":["Cuánta"],"mid":true}]}]},{"id":33,"name":"Exclamativos","motto":"¡qué!, ¡cuánto!, ¡cómo!…","theory":[{"k":"img","src":"img/gram/u33_teoria-comics.png","alt":"«¡Qué alegría! ¡Cuánto tiempo sin vernos!» · «¡Cómo bailan! Parecen profesionales.»"},{"k":"p","t":"<i>Qué, cuánto</i> y <i>cómo</i> son exclamativos. Se usan para expresar diferentes sentimientos: alegría, sorpresa, admiración, desagrado…"},{"k":"eg","t":"<i>sorpresa:</i> ¡<b>Qué</b> casa más grande! Pensé que sería más pequeña.<br><i>admiración:</i> ¡<b>Qué</b> salón más bonito! Es muy moderno.<br><i>desagrado:</i> ¡<b>Cuánta</b> gente hay! No vamos a tener sitio."},{"k":"p","t":"<b>Qué</b> sirve para expresar sentimientos sobre las características de alguien o algo o sobre la manera de hacer algo."},{"k":"p","t":"<i>qué</i> + adjetivo / adverbio / nombre (+ verbo) (+ sujeto)"},{"k":"eg","t":"¡Qué <b>alta</b> (es) Linda!<br>¡Qué <b>bien</b> conduces!<br>¡Qué <b>frío</b> (hace)!<br>¡Qué <b>suerte</b> tiene Pablo!"},{"k":"p","t":"<i>qué</i> + nombre + <i>tan, más</i> + adjetivo (+ verbo) (+ sujeto)"},{"k":"eg","t":"¡Qué pendientes <b>tan/más</b> caros!<br>¡Qué casa <b>tan/más</b> bonita (tiene Lola)!"},{"k":"p","t":"<b>Cuánto, cuánta, cuántos, cuántas</b> sirve para expresar sentimientos de sorpresa, admiración, desagrado, etc., ante una cantidad o ante la intensidad de alguna acción."},{"k":"p","t":"<i>cuánto, -a, -os, -as</i> + nombre (+ verbo)"},{"k":"eg","t":"¡Cuánto dinero se gasta Pili!<br>¡Cuántos sellos tienes!"},{"k":"p","t":"<i>cuánto</i> + verbo (+ sujeto)"},{"k":"eg","t":"¡Cuánto trabaja Lidia!"},{"k":"note","h":"ATENCIÓN","rows":["<i>Cuánto, cuánta, cuántos, cuántas</i> tiene la misma forma (masculino, femenino, singular o plural) que el nombre al que se refiere."]},{"k":"p","t":"<b>Cómo</b> sirve para indicar sentimientos de sorpresa, admiración, desagrado, etc., ante la manera de hacer algo o ante la intensidad de alguna acción."},{"k":"p","t":"<i>cómo</i> + verbo (+ sujeto)"},{"k":"eg","t":"¡Cómo canta Ángela! Tiene una voz preciosa.<br>¡Cómo come! Se nota que tiene hambre.<br>¡Cómo nieva!"}],"ex":[{"id":"gram:33.1","type":"cloze","lab":"33.1","title":"33.1","instr":"Observe las ilustraciones y escriba las exclamaciones oportunas con qué y los nombres y adjetivos dados.","img":"img/gram/u33_ej33-1_ilustraciones.png","alt":"Cinco ilustraciones: un coche largo, una camisa de 200 €, unos pendientes en una caja, un chico alto junto a una puerta y unos relojes a 5 €.","bank":["camisa","chico","~coche","pendientes","relojes","alto","barato","bonito","caro","~largo"],"items":[{"tpl":"___","blanks":1,"ans":["Qué coche más largo","Qué coche tan largo"],"wide":true,"full":true,"example":true,"exv":["¡Qué coche más/tan largo!"]},{"tpl":"___","blanks":1,"ans":["Qué camisa más cara","Qué camisa tan cara"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué pendientes más bonitos","Qué pendientes tan bonitos"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué chico más alto","Qué chico tan alto"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué relojes más baratos","Qué relojes tan baratos"],"wide":true,"full":true}]},{"id":"gram:33.2","type":"cloze","lab":"33.2","title":"33.2","instr":"Complete las frases con qué, cómo o cuánto, cuánta…","items":[{"tpl":"¡___ duerme José!","blanks":1,"ans":["Cuánto"],"mid":true,"example":true},{"tpl":"¡___ noche tan fría!","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¡___ estrellas!","blanks":1,"ans":["Cuántas"],"mid":true},{"tpl":"¡___ corren tus hijos!","blanks":1,"ans":["Cómo","Cuánto"],"mid":true},{"tpl":"¡___ barbaridad! ¡___ cuesta ese cuadro!","blanks":2,"ans":["Qué Cuánto"],"mid":true},{"tpl":"¡___ llueve! Parece el diluvio.","blanks":1,"ans":["Cómo","Cuánto"],"mid":true},{"tpl":"¡___ libros tiene Marisa!","blanks":1,"ans":["Cuántos"],"mid":true},{"tpl":"¡___ lloran! ¡Pobrecillos!","blanks":1,"ans":["Cómo"],"mid":true},{"tpl":"¡___ vago es Lolo! No le gusta nada trabajar.","blanks":1,"ans":["Qué"],"mid":true},{"tpl":"¡___ tarde es! Tengo que irme.","blanks":1,"ans":["Qué"],"mid":true}]},{"id":"gram:33.3","type":"cloze","lab":"33.3","title":"33.3","instr":"Exprese sus sentimientos ante las siguientes afirmaciones utilizando qué, cómo o cuánto, cuánta…","items":[{"tpl":"___","blanks":1,"ans":["Qué mala suerte tiene Jorge"],"ctx":"Jorge tiene muy mala suerte.","wide":true,"full":true,"example":true,"exv":["¡Qué mala suerte tiene Jorge!"]},{"tpl":"___","blanks":1,"ans":["Qué calor hace hoy","Cuánto calor hace hoy","Qué calor hace","Cuánto calor hace"],"ctx":"Hoy hace mucho calor.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué bien habla Lotta español","Qué bien habla español Lotta"],"ctx":"Lotta habla español muy bien.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué cansadas estamos"],"ctx":"Estamos muy cansadas.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué mal conduce Alfonso"],"ctx":"Alfonso conduce muy mal.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué listas son Sara y Eva"],"ctx":"Sara y Eva son muy listas.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué deprisa come Rodri"],"ctx":"Rodri come muy deprisa.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué guapo es Lucio"],"ctx":"Lucio es muy guapo.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánto duerme Rosario","Cómo duerme Rosario"],"ctx":"Rosario duerme mucho.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánto gasta Alberto","Cuánto dinero gasta Alberto"],"ctx":"Alberto gasta mucho dinero.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánta gente hay en la playa"],"ctx":"Hay mucha gente en la playa.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Qué suerte tengo","Cuánta suerte tengo"],"ctx":"Tengo mucha suerte.","wide":true,"full":true}]}]},{"id":34,"name":"Pronombres personales de sujeto","motto":"yo, tú, él…","theory":[{"k":"img","src":"img/gram/u34_teoria-pronombres.png","alt":"yo · tú · usted · él / ella · nosotros / nosotras · vosotros / vosotras · ustedes · ellos / ellas"},{"k":"note","h":"ATENCIÓN","rows":["masculino + femenino = plural masculino","Luisa, José y <b>yo</b> → <b>nosotros</b> · Luisa, José y <b>tú</b> → <b>vosotros</b> · Luisa y José → <b>ellos</b>"]},{"k":"h","t":"Tú, usted; vosotros, vosotras, ustedes"},{"k":"table","head":["","Con familia, amigos, compañeros, gente joven…","Con desconocidos, gente mayor, superiores…"],"rows":[["España","tú · vosotros, vosotras","usted · ustedes"],["América Latina¹","tú/usted · ustedes","usted · ustedes"]]},{"k":"p","t":"¹ También en ciertas zonas de España (Canarias y sur de la Península)."},{"k":"img","src":"img/gram/u34_teoria-tu-usted.png","alt":"Un chico dice «tú» a un compañero y «usted» a una señora mayor."},{"k":"p","t":"En algunas zonas de América Latina como Argentina, Paraguay y Uruguay se usa <i>vos</i> en lugar de <i>tú</i>."},{"k":"p","t":"Normalmente no es necesario usar <i>yo, tú, ellos…</i> con los verbos."},{"k":"eg","t":"<s>Yo</s> vivo en Bogotá. ¿Cómo te llamas <s>tú</s>?"},{"k":"note","h":"PERO","rows":["<i>Usted, ustedes</i> se usan con más frecuencia.","Arlindo, ¿dónde vive <b>usted</b>? —<b>Usted</b> no es peruano, ¿verdad? —No, soy boliviano.","Se usa <i>yo, tú, ellos…</i>:","• para indicar contraste: <b>Yo</b> compro fruta y <b>tú</b> te la comes.","• para dar énfasis: <b>Yo</b> quiero trabajar, pero mis padres quieren que estudie.","• para dejar claro de quién se está hablando: Mira, allí van Silvia y Jorge. Son peruanos. <b>Él</b> es de Arequipa y <b>ella</b> es de Lima.","• cuando van con palabras que se refieren a otras personas: Alicia y <b>tú</b> parecéis hermanas. Mi padre y <b>yo</b> somos buenos amigos."]}],"ex":[{"id":"gram:34.1","type":"cloze","lab":"34.1","title":"34.1","instr":"Escriba el pronombre correspondiente.","img":"img/gram/u34_ej34-1_globos.png","alt":"Diez viñetas numeradas con globos de diálogo vacíos; en la primera dice «Ellas».","items":[{"tpl":"___","blanks":1,"ans":["Ellas"],"mid":true,"example":true},{"tpl":"___","blanks":1,"ans":["Nosotros"],"mid":true},{"tpl":"___","blanks":1,"ans":["Usted"],"mid":true},{"tpl":"___","blanks":1,"ans":["Yo"],"mid":true},{"tpl":"___","blanks":1,"ans":["Vosotros"],"mid":true},{"tpl":"___","blanks":1,"ans":["Nosotras"],"mid":true},{"tpl":"___","blanks":1,"ans":["Tú"],"mid":true},{"tpl":"___","blanks":1,"ans":["Ustedes"],"mid":true},{"tpl":"___","blanks":1,"ans":["Él"],"mid":true},{"tpl":"___","blanks":1,"ans":["Ellos"],"mid":true}]},{"id":"gram:34.2","type":"cloze","lab":"34.2","title":"34.2","instr":"Observe y escriba España, América Latina o España y América Latina.","img":"img/gram/u34_ej34-2_situaciones.png","alt":"Cuatro situaciones: «¿Cómo están ustedes?», «Tengo hambre. ¿Y vosotras?», «Pasen ustedes, por favor» y «¿Son ustedes estudiantes?».","items":[{"tpl":"___","blanks":1,"ans":["América Latina"],"wide":true,"example":true},{"tpl":"___","blanks":1,"ans":["España"],"wide":true},{"tpl":"___","blanks":1,"ans":["América Latina y España","España y América Latina"],"wide":true},{"tpl":"___","blanks":1,"ans":["América Latina"],"wide":true}]},{"id":"gram:34.3","type":"cloze","lab":"34.3","title":"34.3","instr":"Lea la información y complete las frases con yo, tú… solo cuando sea necesario.","tbl":{"head":["","nacion.","ciudad","ocupación"],"rows":[["Pep","española","Barcelona","periodista"],["Concha","española","Murcia","estudiante"],["Adriana","argentina","Córdoba","enfermera"],["Gabriel","mexicana","Monterrey","periodista"],["Rosita","mexicana","Mérida","estudiante"]]},"items":[{"tpl":"Pep: Concha y ___ somos españoles. ___ es de Murcia y ___ soy de Barcelona.","blanks":3,"ans":["yo Ella yo"],"mid":true,"example":true,"exv":["yo","Ella","yo"]},{"tpl":"Concha: Gabriel y Rosita son mexicanos. ___ es de Mérida y ___ es de Monterrey.","blanks":2,"ans":["Ella él"],"mid":true},{"tpl":"Gabriel: ¿De dónde es Adriana? Pep: ___ es argentina.","blanks":1,"ans":["Ø"],"mid":true},{"tpl":"Rosita: Concha y ___ somos estudiantes. ___ es española y ___ soy mexicana.","blanks":3,"ans":["yo Ella yo"],"mid":true},{"tpl":"Adriana: ¿De dónde son Pep y Concha? Gabriel: ___ son españoles. ___ es estudiante y ___ es periodista.","blanks":3,"ans":["Ø Él ella","Ø Ella él"],"mid":true}]},{"id":"gram:34.4","type":"cloze","lab":"34.4","title":"34.4","instr":"Complete las frases con el pronombre personal cuando sea necesario. Escriba Ø cuando no haga falta.","items":[{"tpl":"—¿De dónde sois Adolfo y ___? —___ somos de Uruguay.","blanks":2,"ans":["tú Ø"],"mid":true,"example":true,"exv":["tú","Ø"]},{"tpl":"—¿Dónde vives ___? —___ vivo en Murcia. ¿Y ___? —___ vivo en Granada.","blanks":4,"ans":["Ø Ø tú Ø"],"mid":true},{"tpl":"—Perdone, ¿de dónde son ___? —___ somos de Arequipa.","blanks":2,"ans":["ustedes Ø"],"mid":true},{"tpl":"___ estudiamos Medicina.","blanks":1,"ans":["Ø"],"mid":true},{"tpl":"___ quiero un café, y ___ ¿qué queréis?","blanks":2,"ans":["yo vosotros","yo vosotras","Ø vosotros","Ø vosotras"],"mid":true},{"tpl":"Mira, Lucía y Ana. ___ son amigas de Blanca.","blanks":1,"ans":["Ø"],"mid":true},{"tpl":"___ quiero ser abogada, pero mis padres quieren que estudie Medicina.","blanks":1,"ans":["yo","Ø"],"mid":true}]}]},{"id":35,"name":"Pronombres personales de complemento directo","motto":"te amo","theory":[{"k":"img","src":"img/gram/u35_teoria-comics.png","alt":"«¿Me amas, Lola? – Sí, Carlos, te amo.» · «¿Dónde está el pan? No lo encuentro.» · «¿Ves a Jesús? – Sí, pero él no nos ve a nosotros.»"},{"k":"p","t":"<i>Me, te, lo, nos…</i> se usan como complemento directo de un verbo para referirse a una persona, animal o cosa conocida o mencionada."},{"k":"eg","t":"Lola ama a Carlos. (<i>A Carlos</i> es el complemento directo.) → Lola <b>lo</b> ama.<br>No encuentro el pan. (<i>El pan</i> es el complemento directo.) → No <b>lo</b> encuentro."},{"k":"h","t":"Pronombres personales de complemento directo"},{"k":"table","head":["SINGULAR","PLURAL"],"rows":[["<b>me</b> (a mí)","<b>nos</b> (a nosotros, a nosotras)"],["<b>te</b> (a ti)","<b>os</b> (a vosotros, a vosotras)"],["<b>lo</b> (a él; a usted, masculino; una cosa, masculino)","<b>los</b> (a ellos; a ustedes, masculino; cosas, masculino)"],["<b>la</b> (a ella; a usted, femenino; una cosa, femenino)","<b>las</b> (a ellas; a ustedes, femenino; cosas, femenino)"]]},{"k":"eg","t":"—¿Quién eres? No <b>te</b> conozco.<br>—¿<b>Nos</b> recuerdas? <b>Nos</b> conocimos en Mallorca. —¡Ah, sí! Ahora <b>os</b> recuerdo.<br>—¿Quieres este libro, Héctor? —No, no <b>lo</b> quiero. Gracias.<br>—¿Quieres a tus padres? —Sí, <b>los</b> quiero."},{"k":"note","h":"ATENCIÓN","rows":["masculino + femenino = plural masculino","—¿Veis mucho a Almudena y a Luis? —No, no <b>los</b> vemos mucho."]},{"k":"h","t":"Colocación"},{"k":"p","t":"(no) <i>me, te, lo…</i> + verbo"},{"k":"eg","t":"Yo <b>os</b> conozco. Vosotros sois los hermanos de Lucía.<br>¿Dónde está Marisa? No <b>la</b> veo."},{"k":"p","t":"Cuando se habla de personas se usa <i>a mí, a ti, a él…</i>, además de <i>me, te, lo…</i>:"},{"k":"p","t":"• para dejar claro a quién nos referimos."},{"k":"eg","t":"Ayer las vi en el parque. (¿A ustedes o a ellas?)<br>Ayer las vi <b>a ellas</b> en el parque."},{"k":"p","t":"• para indicar contraste."},{"k":"eg","t":"Ramón ama a María, pero María no lo ama <b>a él</b>."},{"k":"p","t":"• para dar énfasis."},{"k":"eg","t":"<b>A mí</b> no me conoce. (Puede que conozca a otros, pero a mí no.)<br><b>A nosotros</b> no nos ven. (Puede que vean a otros, pero a nosotros no.)"}],"ex":[{"id":"gram:35.1","type":"cloze","lab":"35.1","title":"35.1","instr":"Utilice lo, la, los, las para completar las siguientes frases.","items":[{"tpl":"¿Dónde está Andrés? No ___ veo.","blanks":1,"ans":["lo"],"example":true},{"tpl":"¿Dónde están las cucharas? No ___ veo.","blanks":1,"ans":["las"]},{"tpl":"¿Dónde están tus amigos? No ___ veo.","blanks":1,"ans":["los"]},{"tpl":"¿Dónde está el teléfono? No ___ veo.","blanks":1,"ans":["lo"]},{"tpl":"¿Dónde está Julia? No ___ veo.","blanks":1,"ans":["la"]},{"tpl":"¿Dónde están tus padres? No ___ veo.","blanks":1,"ans":["los"]},{"tpl":"¿Dónde está la entrada? No ___ veo.","blanks":1,"ans":["la"]},{"tpl":"¿Dónde están las naranjas? No ___ veo.","blanks":1,"ans":["las"]}]},{"id":"gram:35.2","type":"cloze","lab":"35.2","title":"35.2","instr":"Complete con me, te, lo…","items":[{"tpl":"Yo ___ conozco. Tú eres amigo de Ana.","blanks":1,"ans":["te"],"example":true},{"tpl":"Yo ___ conozco. Ustedes son los padres de Jesús.","blanks":1,"ans":["los"]},{"tpl":"Yo ___ conozco. Vosotros sois compañeros de Ramón.","blanks":1,"ans":["os"]},{"tpl":"Yo ___ conozco. Usted es la madre de Rosario.","blanks":1,"ans":["la"]},{"tpl":"Yo ___ conozco. Ustedes son las tías de Pepe.","blanks":1,"ans":["las"]},{"tpl":"Yo ___ conozco. Vosotras sois amigas de Raquel.","blanks":1,"ans":["os"]},{"tpl":"Yo ___ conozco. Usted es el padre de Pedro.","blanks":1,"ans":["lo"]},{"tpl":"Yo ___ conozco. Tú vives en la calle Arenal.","blanks":1,"ans":["te"]}]},{"id":"gram:35.3","type":"cloze","lab":"35.3","title":"35.3","instr":"Utilice me, te, lo… y las formas verbales correspondientes para completar las respuestas.","items":[{"tpl":"—¿Amas a Luis? —Sí, ___.","blanks":1,"ans":["lo amo"],"mid":true,"example":true},{"tpl":"—¿Quieres esta foto? —No, ___.","blanks":1,"ans":["no la quiero"],"mid":true,"example":true},{"tpl":"—¿Has comprado el periódico? —No, ___.","blanks":1,"ans":["no lo he comprado"],"mid":true},{"tpl":"—¿Nos quieres, mamá? —Sí, ___ mucho.","blanks":1,"ans":["os quiero"],"mid":true},{"tpl":"—¿Has visto mis zapatillas? —No, ___.","blanks":1,"ans":["no las he visto"],"mid":true},{"tpl":"—¿Me recuerdas? —Sí, ___. Tú eres Julián.","blanks":1,"ans":["te recuerdo"],"mid":true},{"tpl":"—¿Ves mucho a Pepe y a Luisa? —Sí, ___ mucho.","blanks":1,"ans":["los veo"],"mid":true},{"tpl":"—¿Te quiere Elena? —No, ___.","blanks":1,"ans":["no me quiere"],"mid":true},{"tpl":"—¿Conoces a los Sres. Pardo? —No, ___.","blanks":1,"ans":["no los conozco"],"mid":true},{"tpl":"—¿Te conocen en esta tienda? —Sí, ___ mucho.","blanks":1,"ans":["me conocen"],"mid":true}]},{"id":"gram:35.4","type":"cloze","lab":"35.4","title":"35.4","instr":"Complete las frases con me, te, lo… y a mí, a ti, a él…","items":[{"tpl":"Yo conozco a esa chica, pero ella no ___ conoce ___.","blanks":2,"ans":["me a mí"],"mid":true,"example":true,"exv":["me","a mí"]},{"tpl":"Desde aquí vemos a Roberto, pero él no ___ ve ___.","blanks":2,"ans":["nos a nosotros"],"mid":true},{"tpl":"Teresa quiere a Alfredo, pero él no ___ quiere ___.","blanks":2,"ans":["la a ella"],"mid":true},{"tpl":"Esas señoras me conocen, pero yo no ___ conozco ___.","blanks":2,"ans":["las a ellas"],"mid":true},{"tpl":"Ustedes me conocen, pero yo no ___ conozco ___.","blanks":2,"ans":["los a ustedes"],"mid":true},{"tpl":"Esos chicos conocen a Miguel, pero Miguel no ___ conoce ___.","blanks":2,"ans":["los a ellos"],"mid":true}]}]},{"id":36,"name":"Pronombres personales de complemento indirecto","motto":"Me han regalado un reloj","theory":[{"k":"img","src":"img/gram/u36_teoria-comics.png","alt":"«¿Qué te ha regalado Luis? – Me ha regalado un reloj.» «Y tú, ¿qué le has regalado a él? – Le he regalado una corbata.»"},{"k":"p","t":"<i>Me, te, le</i> se usan como complemento indirecto de un verbo para referirse a una persona, animal o cosa conocida o mencionada."},{"k":"eg","t":"Luis ha regalado un reloj <b>a Chus</b>. (<i>A Chus</i> es el complemento indirecto.) → Luis <b>le</b> ha regalado un reloj.<br>He preguntado <b>a Ana</b> por sus padres. (<i>A Ana</i> es el complemento indirecto.) → <b>Le</b> he preguntado por sus padres."},{"k":"h","t":"Pronombres personales de complemento indirecto"},{"k":"table","head":["SINGULAR","PLURAL"],"rows":[["<b>me</b> (a mí)","<b>nos</b> (a nosotros, a nosotras)"],["<b>te</b> (a ti)","<b>os</b> (a vosotros, a vosotras)"],["<b>le</b> (a él; a ella; a usted; a una cosa)","<b>les</b> (a ellos; a ellas; a ustedes; a unas cosas)"]]},{"k":"eg","t":"—Ayer vi a Rodolfo. —¿<b>Le</b> dijiste que quiero verlo?<br>—¿Qué <b>os</b> ha preguntado Leonor? —<b>Nos</b> ha preguntado dónde vivimos."},{"k":"h","t":"Colocación"},{"k":"p","t":"(no) <i>me, te, le…</i> + verbo"},{"k":"eg","t":"—¿Qué <b>te ha dicho</b> el médico? —<b>Me ha dicho</b> que estoy bien.<br>—¿Qué <b>te ha preguntado</b> Charo? —No <b>me ha preguntado</b> nada."},{"k":"p","t":"Cuando se habla de personas se usa <i>a mí, a ti, a él…</i>, además de <i>me, te, le…</i>:"},{"k":"p","t":"• para dejar claro a quién nos referimos."},{"k":"eg","t":"<i>Le dije que no era verdad.</i> (¿A usted, a él, a ella?) → Le dije <b>a usted</b> que no era verdad. / Le dije <b>a él</b> que no era verdad. / Le dije <b>a ella</b> que no era verdad."},{"k":"p","t":"• para dar énfasis."},{"k":"eg","t":"—¿Te ha dado el dinero? —<b>A mí</b> no <b>me</b> ha dado nada. (Puede que lo haya dado a otros, pero a mí no.)"},{"k":"note","h":"ATENCIÓN","rows":["Normalmente, cuando se habla de personas, se usa <i>me, te, le…</i>, además de la persona a la que se refiere, cuando se menciona por primera vez.","—¿<b>Le</b> has regalado algo <b>a Pedro</b>? —Sí, <b>le</b> he regalado una cartera.","—¿Qué <b>le</b> has regalado <b>a tu familia</b>? —<b>A Juana le</b> he regalado un collar y <b>a los niños les</b> he comprado juguetes.","<b>Les</b> he comprado unos bombones <b>a mis hermanas</b>."]}],"ex":[{"id":"gram:36.1","type":"cloze","lab":"36.1","title":"36.1","instr":"Complete con me, te, le…","img":"img/gram/u36_ej36-1_ilustraciones.png","alt":"Siete viñetas numeradas con globos: «¿Qué te ha regalado?», «… ha regalado un pañuelo», «… ha regalado unos libros», «… ha regalado una bufanda», «¿Qué … ha regalado a usted?», «… ha regalado perfume», «¿Qué … ha regalado?», «… ha regalado un paraguas».","items":[{"tpl":"¿Qué ___ ha regalado? ___ ha regalado un pañuelo.","blanks":2,"ans":["te Me"],"mid":true,"example":true,"exv":["te","Me"]},{"tpl":"___ ha regalado unos libros.","blanks":1,"ans":["Nos"],"mid":true},{"tpl":"___ ha regalado una bufanda.","blanks":1,"ans":["Le"],"mid":true},{"tpl":"¿Qué ___ ha regalado a usted?","blanks":1,"ans":["le"],"mid":true},{"tpl":"___ ha regalado perfume.","blanks":1,"ans":["Les"],"mid":true},{"tpl":"¿Qué ___ ha regalado?","blanks":1,"ans":["os"],"mid":true},{"tpl":"___ ha regalado un paraguas.","blanks":1,"ans":["Le"],"mid":true}]},{"id":"gram:36.2","type":"cloze","lab":"36.2","title":"36.2","instr":"Responda a estas preguntas siguiendo el modelo.","items":[{"tpl":"___","blanks":1,"ans":["No me han dicho nada"],"ctx":"¿Qué te han dicho?","wide":true,"full":true,"example":true,"exv":["No me han dicho nada"]},{"tpl":"___","blanks":1,"ans":["No me ha dicho nada"],"ctx":"¿Qué le ha dicho a usted?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No nos ha dado nada"],"ctx":"¿Qué os ha dado?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No le han preguntado nada"],"ctx":"¿Qué le han preguntado a Susana?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No te ha dicho nada"],"ctx":"¿Qué me ha dicho?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No os han preguntado nada","No nos han preguntado nada"],"ctx":"¿Qué nos han preguntado?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No me ha vendido nada"],"ctx":"¿Qué te ha vendido?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No nos han dado nada"],"ctx":"¿Qué les han dado a ustedes?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No le han preguntado nada"],"ctx":"¿Qué le han preguntado a Alberto?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No les han regalado nada"],"ctx":"¿Qué les han regalado a tus hijas?","wide":true,"full":true}]},{"id":"gram:36.3","type":"cloze","lab":"36.3","title":"36.3","instr":"Escriba preguntas y respuestas como en el ejemplo.","items":[{"tpl":"___ (¿a ustedes?) ___ ___ (¿a Marcela?) ___ ___","blanks":5,"ans":["A mí no me dijo nada Les dijo algo a ustedes A nosotros no nos dijo nada Le dijo algo a Marcela A Marcela no le dijo nada","A mí no me dijo nada Les dijo algo a ustedes A nosotros no nos dijo nada Le dijo algo a Marcela A ella no le dijo nada"],"ctx":"¿Te dijo algo Luis?","wide":true,"full":true,"example":true,"exv":["A mí no me dijo nada","Les dijo algo a ustedes","A nosotros no nos dijo nada","Le dijo algo a Marcela","A Marcela no le dijo nada"]},{"tpl":"___ (¿a Tomás?) ___ ___ (¿a usted?) ___ ___","blanks":5,"ans":["A nosotros no nos ha preguntado nada Le ha preguntado algo a Tomás A Tomás no le ha preguntado nada Le ha preguntado algo a usted A mí no me ha preguntado nada","A nosotros no nos ha preguntado nada Le ha preguntado algo a Tomás A él no le ha preguntado nada Le ha preguntado algo a usted A mí no me ha preguntado nada"],"ctx":"¿Os ha preguntado algo Lola?","wide":true,"full":true},{"tpl":"___ (¿a nosotros?) ___ ___ (¿a su hermano?) ___ ___","blanks":5,"ans":["A ti no te ha comprado nada Nos ha comprado algo a nosotros A vosotros no os ha comprado nada Le ha comprado algo a su hermano A su hermano no le ha comprado nada","A ti no te ha comprado nada Nos ha comprado algo a nosotros A nosotros no nos ha comprado nada Le ha comprado algo a su hermano A él no le ha comprado nada"],"ctx":"¿Me ha comprado algo Yvonne?","wide":true,"full":true}]}]},{"id":37,"name":"Pronombres de complemento indirecto y directo","motto":"Se lo he dado. Te lo he dado","theory":[{"k":"img","src":"img/gram/u37_p82_fig01_dialogo-bombones.png","alt":"Dos personas conversan: «¡Qué corbata más bonita!» – «Me la regaló Andrea»."},{"k":"img","src":"img/gram/u37_p82_fig02_dialogo-telefono.png","alt":"En una fiesta: «¿Le has dado tu teléfono a Rafa?» – «Sí, se lo he dado»."},{"k":"p","t":"A veces hay dos complementos en la frase, un complemento directo (CD) y un complemento indirecto (CI)."},{"k":"img","src":"img/gram/u37_p82_fig03_cd-ci-esquema.png","alt":"Esquema: «¿Le has dado tu teléfono a Rafa?» (tu teléfono = CD, a Rafa = CI) → «¿Se lo has dado?» (Se = CI, lo = CD)."},{"k":"h","t":"Formas y orden de los pronombres en la frase"},{"k":"cols","l":{"h":"PRONOMBRES DE CI","rows":["me (a mí)","te (a ti)","se (a usted)","se (a él, a ella; a una cosa)","nos (a nosotros, a nosotras)","os (a vosotros, a vosotras)","se (a ustedes)","se (a ellos, a ellas; a unas cosas)"]},"mid":"+","r":{"h":"PRONOMBRES DE CD","rows":["lo (masculino singular)","la (femenino singular)","los (masculino plural)","las (femenino plural)"]}},{"k":"eg","t":"¿Les has presentado <u>tu novia</u> <u>a tus padres</u>? – No, no <u>se</u> <u>la</u> he presentado.","n":"tu novia = CD, a tus padres = CI; se = CI, la = CD"},{"k":"note","h":"ATENCIÓN","rows":["Se utiliza <i>se</i> (no <i>le, les</i>) para <i>usted, ustedes, él, ella, ellos</i> y <i>ellas</i>.","<s>Le</s> lo he dado. → <b>Se</b> lo he dado."]},{"k":"h","t":"Se usa:"},{"k":"p","t":"<i>se</i> además de la persona a la que se refiere cuando se menciona por primera vez."},{"k":"eg","t":"–¿Qué has hecho con el coche? ¿<b>Se lo</b> has regalado <b>a Pepe</b>? –No, <b>se lo</b> he vendido."},{"k":"p","t":"<i>lo, la, los, las</i> además de la persona o cosa a la que se refiere cuando se dice esta en primer lugar."},{"k":"eg","t":"<b>Esta corbata</b> me <b>la</b> regaló Andrea."},{"k":"eg","t":"<b>Esos libros</b> se <b>los</b> regalé yo."},{"k":"h","t":"Cuando se habla de personas se usa a mí, a ti, a él... además de me, te, se...:"},{"k":"p","t":"para dejar claro de quién se habla."},{"k":"img","src":"img/gram/u37_p82_fig04_se-lo-ha-ensenado.png","alt":"Esquema: «Se lo ha enseñado» puede referirse a usted, a él, a ella, a ustedes, a ellos o a ellas: Se lo ha enseñado a usted / a él / a ella / a ustedes / a ellos / a ellas."},{"k":"p","t":"para dar énfasis."},{"k":"eg","t":"–¿<b>Te</b> ha dado el dinero? –<b>A mí</b> no <b>me</b> lo ha dado."}],"ex":[{"id":"gram:37.1","type":"cloze","lab":"37.1","title":"37.1","instr":"Complete las respuestas con me, te, se... y lo, la, los, las.","items":[{"tpl":"–¿Quién te ha regalado esos bombones? –___ ___ ha regalado Anita.","blanks":2,"ans":["me los"],"example":true},{"tpl":"–¿Quién les ha prestado el dinero a tus padres? –___ ___ ha prestado Juan.","blanks":2,"ans":["se lo"]},{"tpl":"–¿Quién os ha enviado ese paquete? –___ ___ ha enviado mi tía Rosa.","blanks":2,"ans":["nos lo"]},{"tpl":"–¿Quién me envía estas flores? –___ ___ envía Raúl.","blanks":2,"ans":["te las"]},{"tpl":"–¿Quién le ha regalado esa corbata, Antonio? –___ ___ ha regalado mi mujer.","blanks":2,"ans":["me la"]},{"tpl":"–¿Quién les ha enseñado el museo a ustedes? –___ ___ ha enseñado un guía turístico.","blanks":2,"ans":["nos lo"]}]},{"id":"gram:37.2","type":"type","lab":"37.2","title":"37.2","instr":"Conteste a las preguntas.","items":[{"q":"–¿Te ha dado Pepe el regalo? –No,","ans":["no me lo ha dado"],"example":true},{"q":"–¿Os ha prestado Pablo el dinero? –Sí,","ans":["nos lo ha prestado"]},{"q":"–¿Les ha presentado Sara su novio a sus padres? –No,","ans":["no se lo ha presentado"]},{"q":"–¿Le ha enseñado a usted su casa Marta? –Sí,","ans":["me la ha enseñado"]},{"q":"–¿Les ha presentado Hugo sus amigos a sus padres? –Sí,","ans":["se los ha presentado"]},{"q":"–¿Le ha vendido Jesús su coche a Antonia? –No,","ans":["no se lo ha vendido"]},{"q":"–¿Les ha enseñado a ustedes los cuadros Ramón? –Sí,","ans":["nos los ha enseñado"]},{"q":"–¿Me ha traído Rita las entradas? –Sí,","ans":["te las ha traído"]}]},{"id":"gram:37.3","type":"cloze","lab":"37.3","title":"37.3","instr":"Complete con me, te, se... y lo, la, los, las.","items":[{"tpl":"Este paraguas (a él) ___ ___ regaló Andrea.","blanks":2,"ans":["se lo"],"example":true},{"tpl":"Esta corbata (a mí) ___ ___ regaló mi novia.","blanks":2,"ans":["me la"]},{"tpl":"Ese coche (a ellos) ___ ___ ha vendido un amigo.","blanks":2,"ans":["se lo"]},{"tpl":"Esa lámpara (a nosotros) ___ ___ ha regalado una tía de Alberto.","blanks":2,"ans":["nos la"]},{"tpl":"Esas flores (a ella) ___ ___ ha traído su novio.","blanks":2,"ans":["se las"]},{"tpl":"Este paquete (a usted) ___ ___ ha traído un mensajero.","blanks":2,"ans":["se lo"]},{"tpl":"Esos bombones (a ellas) ___ ___ ha comprado su hermano.","blanks":2,"ans":["se los"]},{"tpl":"Este libro (a ti) ___ ___ ha traído Víctor.","blanks":2,"ans":["te lo"]},{"tpl":"Esta carta (a mí) ___ ___ envía una amiga de Perú.","blanks":2,"ans":["me la"]},{"tpl":"Estos helados (a vosotros) ___ ___ compro yo.","blanks":2,"ans":["os los"]}]},{"id":"gram:37.4","type":"mixed","lab":"37.4","title":"37.4","instr":"Responda como en el ejemplo.","items":[{"q":"–¿Te ha dado las entradas? –No,","ans":["a mí no me las ha dado"],"example":true},{"q":"–¿Le ha dado a usted el dinero? –No,","ans":["a mí no me lo ha dado"]},{"q":"–¿Os ha dado las llaves? –No,","ans":["a nosotros no nos las ha dado"]},{"tpl":"–¿Me ha enviado el paquete? –No, ___, don Antonio.","blanks":1,"ans":["a usted no se lo ha enviado"]},{"q":"–¿Nos han aprobado? –No,","ans":["a nosotros no nos han aprobado","a vosotros no os han aprobado"]},{"q":"–¿La han aprobado a Teresa? –Sí,","ans":["a ella la han aprobado"]},{"q":"–¿Y lo han aprobado a Alfonso? –No,","ans":["a él no lo han aprobado"]},{"q":"–¿Nos han invitado a la fiesta? –No,","ans":["a nosotros no nos han invitado","a vosotros no os han invitado"]}]}]},{"id":38,"name":"lo / la / le","motto":"Confusión entre pronombres personales de complemento","theory":[{"k":"img","src":"img/gram/u38_teoria-coche.png","alt":"«¿Me dejas el coche? – No puedo. Lo necesito.»"},{"k":"p","t":"<i>Lo, la, los, las</i> se usan como complemento directo de un verbo para referirse a personas, animales o cosas mencionadas anteriormente."},{"k":"p","t":"<i>lo, los</i> → masculino · <i>la, las</i> → femenino"},{"k":"eg","t":"—¿Me dejas <b>el diccionario</b>? —No puedo. <b>Lo</b> necesito.<br>—¿Me dejas <b>la pluma</b>? —No puedo. <b>La</b> necesito.<br>—¿Amas a <b>Juan</b>? —Sí, <b>lo</b> amo.<br>—¿Quieres a <b>tus padres</b>? —Sí, <b>los</b> quiero."},{"k":"note","h":"PERO","rows":["Algunas personas usan <i>le</i> y <i>les</i> en lugar de <i>lo</i> y <i>los</i> para referirse a personas.","—¿Amas a Juan? —Sí, <b>le</b> amo.","—¿Quieres a tus padres? —Sí, <b>les</b> quiero."]},{"k":"note","h":"ATENCIÓN","rows":["—¿Me dejas el diccionario? —No puedo. <s>Le</s> necesito. → —¿Me dejas el diccionario? —No puedo. <b>Lo</b> necesito.","—Di a Sofía que <s>le</s> llaman por teléfono. → —Di a Sofía que <b>la</b> llaman por teléfono."]},{"k":"img","src":"img/gram/u38_teoria-muelas.png","alt":"«¿Qué le pasa? – Le duelen las muelas.»"},{"k":"p","t":"<i>Le, les</i> se usan como complemento indirecto de un verbo para referirse a personas (hombres o mujeres)."},{"k":"eg","t":"—¿Qué <b>le</b> has regalado a Pedro? —<b>Le</b> he regalado una cartera.<br>—¿Y a María? —<b>Le</b> he regalado unos pendientes.<br>A Elena <b>le</b> duele la cabeza."},{"k":"note","h":"ATENCIÓN","rows":["A María <s>la</s> he regalado unos pendientes. → A María <b>le</b> he regalado unos pendientes.","A Juan <s>lo</s> han regalado un disco. → A Juan <b>le</b> han regalado un disco."]},{"k":"p","t":"<i>le, les</i> → <i>se</i> cuando hay dos pronombres."},{"k":"eg","t":"—¿<b>Le</b> has dado la carta a Joaquín? —Sí, <b>se la</b> he dado.<br>—¿<b>Les</b> has enseñado las notas a tus padres? —Sí, <b>se las</b> he enseñado."},{"k":"p","t":"<i>Lo</i> se usa como complemento directo de un verbo para referirse a una información dada anteriormente."},{"k":"eg","t":"—¿Le has dicho a Juan <b>que me caso</b>? —Sí, <b>se lo</b> he dicho, pero no <b>se lo</b> cree.<br>—¿Sabes que <b>Chávez está muy enfermo</b>? —Sí, <b>lo</b> sé."},{"k":"p","t":"A veces se usa <i>lo</i> en expresiones que indican oposición o sorpresa ante una información anterior."},{"k":"eg","t":"—Felipe no es argentino. —Claro que <b>lo</b> es."}],"ex":[{"id":"gram:38.1","type":"pick","lab":"38.1","title":"38.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"—¿Quieres este libro? —No, no [le|lo] quiero. Gracias.","ans":["lo"],"example":true},{"tpl":"—¿Me dejas el lápiz? —No puedo. [Le|Lo] necesito.","ans":["Lo"]},{"tpl":"—¿Quieres a Ana? —Sí, [la|le] quiero.","ans":["la"]},{"tpl":"—¿Ha visto usted mis gafas? —No, no [las|les] he visto.","ans":["las"]},{"tpl":"—¿[La|Le] has regalado tu chaqueta roja a Luisa? —No, no [se|le] [la|le] he regalado. [Se|Le] [la|le] he prestado.","ans":["Le","se","la","Se","la"]},{"tpl":"—¿Han visto ustedes a mis padres? —No, no [se|los] hemos visto.","ans":["los"]},{"tpl":"[Le|La] he prestado cien euros a Ivana.","ans":["Le"]},{"tpl":"—¿[Les|Los] has dejado el coche a tus hermanos? —No, no [se|les] [le|lo] he dejado.","ans":["Les","se","lo"]},{"tpl":"—¿Has visto a mis hermanas? —Sí, [las|les] he visto.","ans":["las"]},{"tpl":"Inés, [la|le] llaman por teléfono.","ans":["la"]},{"tpl":"¿Quiere ver a Andrés? —No, no quiero [verla|verlo].","ans":["verlo"]},{"tpl":"[Les|Los] he comprado una televisión a mis padres.","ans":["Les"]},{"tpl":"[La|Le] dije a Juana que no tengo dinero.","ans":["Le"]},{"tpl":"Ayer [la|le] vi en el parque, Elisa.","ans":["la"]},{"tpl":"—¿Qué [la|le] pasa a Elsa? —[La|Le] duele la cabeza.","ans":["le","Le"]}]},{"id":"gram:38.2","type":"cloze","lab":"38.2","title":"38.2","instr":"Complete las frases con lo, la, los, las, le, les o se.","items":[{"tpl":"—¿Has visto a Juana? —Sí, ___ he visto.","blanks":1,"ans":["la"],"mid":true,"example":true},{"tpl":"___ he regalado unos bombones a Sarita.","blanks":1,"ans":["Le"],"mid":true},{"tpl":"—¿Has llamado a tu padre, Héctor? —Sí, ___ he llamado.","blanks":1,"ans":["lo","le"],"mid":true},{"tpl":"¿Qué ___ has dicho a la profesora?","blanks":1,"ans":["le"],"mid":true},{"tpl":"¿___ has regalado tus discos a Enrique? —Sí, ___ ___ he regalado.","blanks":3,"ans":["Le se los"],"mid":true},{"tpl":"—¿Has visto a Concha? —No, hoy no ___ he visto.","blanks":1,"ans":["la"],"mid":true},{"tpl":"A Pili ___ duelen las muelas.","blanks":1,"ans":["le"],"mid":true},{"tpl":"—¿Qué ___ has comprado a tus padres? —A mi padre ___ he comprado un libro y a mi madre ___ he comprado un pañuelo.","blanks":3,"ans":["les le le"],"mid":true}]},{"id":"gram:38.3","type":"cloze","lab":"38.3","title":"38.3","instr":"Utilice los pronombres adecuados para completar estas frases.","items":[{"tpl":"—¿___ has dicho a Juan que necesito el coche? —Sí, ___ ___ he dicho, pero dice que él también ___ necesita.","blanks":4,"ans":["Le se lo lo"],"mid":true,"example":true,"exv":["Le","se","lo","lo"]},{"tpl":"—¿Sabes que me voy a Colombia? —No, no ___ sabía.","blanks":1,"ans":["lo"],"mid":true},{"tpl":"—¿Es verdad que Ángela tiene mucho dinero? —___ es, pero no ___ parece.","blanks":2,"ans":["Lo lo"],"mid":true},{"tpl":"—¿Sabe papá que necesito dinero? —___ sabe, pero dice que ___ ___ pidas luego.","blanks":3,"ans":["Lo se lo"],"mid":true},{"tpl":"No ___ entiendo. ___ he ofrecido ayuda a Teresa, pero no ___ ha aceptado.","blanks":3,"ans":["lo Le la"],"mid":true},{"tpl":"—¿De verdad que Ana es escritora? —Claro que ___ es, pero no ___ sabe nadie.","blanks":2,"ans":["lo lo"],"mid":true},{"tpl":"—Juan y Lola se han casado. —Ya sabía que ___ harían. Él ___ quiere mucho.","blanks":2,"ans":["lo la"],"mid":true},{"tpl":"—Se ha muerto Momo. —¡Cuánto ___ siento! Yo ___ quería mucho.","blanks":2,"ans":["lo lo","lo le"],"mid":true}]}]},{"id":39,"name":"Pronombres con imperativo, infinitivo y gerundio","motto":"ámame, dámelo","theory":[{"k":"h","t":"Con el imperativo afirmativo"},{"k":"img","src":"img/gram/u39_teoria-cuadro.png","alt":"«Este cuadro es muy interesante. Míralo.»"},{"k":"p","t":"Con pronombres de CD: imperativo afirmativo + <i>me / te / lo…</i>"},{"k":"eg","t":"<b>Ámame</b>. Ese coche ya está muy viejo. <b>Véndelo</b>."},{"k":"p","t":"Con pronombres de CI: imperativo afirmativo + <i>me / te / le…</i>"},{"k":"eg","t":"Roberto necesita el coche. <b>Dale</b> las llaves. <b>Dime</b> la verdad."},{"k":"p","t":"Con pronombres de CI y CD: imperativo afirmativo + <i>me / te / se…</i> + <i>lo / la / los / las</i>"},{"k":"eg","t":"Esas gafas son de Lola. <b>Dáselas</b>. —¿Es tuyo este libro? —Sí, <b>dámelo</b>."},{"k":"h","t":"Con el infinitivo"},{"k":"p","t":"Con pronombres de CD: infinitivo + <i>me / te / lo…</i>"},{"k":"eg","t":"Está enfadada con nosotros. No quiere <b>vernos</b>. No hay leche. He olvidado <b>comprarla</b>."},{"k":"p","t":"Con pronombres de CI: infinitivo + <i>me / te / le…</i>"},{"k":"eg","t":"Venid aquí. Quiero <b>deciros</b> algo. Me gustaría <b>preguntarte</b> algo."},{"k":"p","t":"Con pronombres de CI y CD: infinitivo + <i>me / te / se…</i> + <i>lo / la / los / las</i>"},{"k":"eg","t":"La entrada no es nuestra, pero él quiere <b>dárnosla</b>."},{"k":"img","src":"img/gram/u39_teoria-boli.png","alt":"«¿Puedes prestarme un boli? – No, pero puedo prestarte un lápiz.»"},{"k":"note","h":"PERO","rows":["También con algunos verbos: <b>No los</b> puedo ver. <b>Te</b> quiero decir algo. ¿<b>Me lo</b> vais a regalar?"]},{"k":"h","t":"Con el gerundio"},{"k":"p","t":"Con pronombres de CD: gerundio + <i>me / te / lo…</i>"},{"k":"eg","t":"—¿Qué hace con el regalo? —Está <b>envolviéndolo</b>."},{"k":"p","t":"Con pronombres de CI: gerundio + <i>me / te / le…</i>"},{"k":"eg","t":"¿Qué está <b>diciéndole</b>? —¿Qué haces? —Estoy <b>escribiéndole</b> a Laura."},{"k":"p","t":"Con pronombres de CI y CD: gerundio + <i>me / te / se…</i> + <i>lo / la / los / las</i>"},{"k":"eg","t":"—¿Por qué tiene Susana la carta de Jaime? —Está <b>leyéndomela</b>. Yo no veo bien."},{"k":"note","h":"PERO","rows":["También: <b>Lo</b> está envolviendo. ¿Qué <b>te</b> está diciendo? <b>Me lo</b> está leyendo."]},{"k":"note","h":"ATENCIÓN","rows":["ama → <b>ámame</b> · dame → <b>dámelo</b>","dar → <b>dárnosla</b> · prestar → <b>prestármelo</b>","arreglando → <b>arreglándola</b> · preguntando → <b>preguntándote</b>"]}],"ex":[{"id":"gram:39.1","type":"cloze","lab":"39.1","title":"39.1","instr":"Sustituya las palabras subrayadas por pronombres y haga los cambios necesarios.","items":[{"tpl":"___","blanks":1,"ans":["Ámalos"],"ctx":"Ama <u>a tus padres</u>.","mid":true,"example":true},{"tpl":"___","blanks":1,"ans":["Compradlo"],"ctx":"Comprad <u>el periódico</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Dáselo"],"ctx":"Dale <u>su dinero a Elvira</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Házsela"],"ctx":"Hazle <u>la pregunta a Carlos</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Pregúntale"],"ctx":"Pregunta <u>a tu madre</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Véndala"],"ctx":"Venda <u>la casa</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Pásasela"],"ctx":"Pasa <u>el agua a Ramón</u>.","mid":true},{"tpl":"___","blanks":1,"ans":["Escríbele"],"ctx":"Escribe <u>a Sheila</u>.","mid":true}]},{"id":"gram:39.2","type":"cloze","lab":"39.2","title":"39.2","instr":"Complete las frases con los infinitivos del recuadro y los pronombres adecuados.","bank":["ayudar","~comprar","devolver","escribir","preguntar","tirar","vender","ver","visitar"],"items":[{"tpl":"—¿Has comprado el periódico? —He olvidado ___.","blanks":1,"ans":["comprarlo"],"mid":true,"example":true},{"tpl":"Ese libro es mío, pero Carlos no quiere ___.","blanks":1,"ans":["devolvérmelo"],"mid":true},{"tpl":"Sonia está enfadada con vosotros. No quiere ___.","blanks":1,"ans":["veros"],"mid":true},{"tpl":"Estos zapatos están muy viejos. Voy a ___.","blanks":1,"ans":["tirarlos"],"mid":true},{"tpl":"Ven aquí, Gabriel. Quiero ___ algo.","blanks":1,"ans":["preguntarte"],"mid":true},{"tpl":"Ramón quiere comprarme ese cuadro, pero yo no quiero ___.","blanks":1,"ans":["vendérselo"],"mid":true},{"tpl":"He tenido carta de Antón. Tengo que ___.","blanks":1,"ans":["escribirle"],"mid":true},{"tpl":"No sabemos hacer el ejercicio, pero Hans quiere ___.","blanks":1,"ans":["ayudarnos"],"mid":true},{"tpl":"Mis tías viven en este barrio. Me gustaría ___.","blanks":1,"ans":["visitarlas"],"mid":true}]},{"id":"gram:39.3","type":"cloze","lab":"39.3","title":"39.3","instr":"Sustituya las palabras subrayadas por pronombres y haga los cambios necesarios.","items":[{"tpl":"___","blanks":1,"ans":["Está limpiándolas","Las está limpiando"],"ctx":"Está limpiando <u>las ventanas</u>.","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Estoy acabándola","La estoy acabando"],"ctx":"Estoy acabando <u>la novela</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Están preguntándole","Le están preguntando"],"ctx":"Están preguntando <u>al Sr. Oliva</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Estamos lavándolas","Las estamos lavando"],"ctx":"Estamos lavando <u>las camisas</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Están haciéndosela","Se la están haciendo"],"ctx":"Están haciendo <u>la pregunta a Carla</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Está lavándoselo","Se lo está lavando"],"ctx":"Está lavando <u>el pelo a su hijo</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Está hablándole","Le está hablando"],"ctx":"Está hablando <u>a Pepa</u>.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Está arreglándola","La está arreglando"],"ctx":"Está arreglando <u>la radio</u>.","wide":true,"full":true}]},{"id":"gram:39.4","type":"cloze","lab":"39.4","title":"39.4","instr":"Ordene las palabras y ponga las tildes necesarias.","items":[{"tpl":"___","blanks":1,"ans":["Pásame la sal"],"ctx":"la sal / me / pasa","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["La directora quiere vernos","La directora nos quiere ver"],"ctx":"la directora / nos / ver / quiere","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["He olvidado comprarlo"],"ctx":"no tengo pan. He olvidado / lo / comprar","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Puedes ayudarme","¿Me puedes ayudar"],"ctx":"¿me / ayudar / puedes?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Pregúntaselo a Julio"],"ctx":"a Julio / se / pregunta / lo","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Quién está haciéndolo","¿Quién lo está haciendo"],"ctx":"¿quién / lo / está haciendo?","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Me gustaría decírselo a Sandra"],"ctx":"me gustaría / a Sandra / lo / se / decir","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Pásame la pelota"],"ctx":"me / la pelota / pasa","wide":true,"full":true}]}]},{"id":40,"name":"Pronombres reflexivos y con valor recíproco","motto":"me ducho, nos queremos","theory":[{"k":"img","src":"img/gram/u40_teoria-top.png","alt":"«Me ducho todos los días.» · «Ricardo se afeita todas las mañanas.»"},{"k":"p","t":"<i>Me, se</i> son pronombres reflexivos. Se usan para indicar que la acción del verbo (<i>ducharse, afeitarse</i>) la recibe:"},{"k":"p","t":"• la misma persona que la hace."},{"k":"img","src":"img/gram/u40_teoria-ducho.png","alt":"Una persona se ducha. «Me ducho.»"},{"k":"eg","t":"<b>Me</b> ducho."},{"k":"p","t":"• una parte del cuerpo o la ropa de esa persona."},{"k":"img","src":"img/gram/u40_teoria-pelo-bata.png","alt":"«Me lavo el pelo.» · «Nos ponemos una bata para trabajar.»"},{"k":"h","t":"Pronombres reflexivos"},{"k":"table","rows":[["(yo) <b>me</b>","(tú) <b>te</b>","(usted) <b>se</b>"],["(él, ella) <b>se</b>","(nosotros, -as) <b>nos</b>","(vosotros, -as) <b>os</b>"],["(ustedes) <b>se</b>","(ellos, -as) <b>se</b>",""]]},{"k":"h","t":"Compare"},{"k":"img","src":"img/gram/u40_teoria-afeito1.png","alt":"Un hombre se afeita: «Me afeito todas las mañanas.»"},{"k":"eg","t":"Rut <b>se viste</b> después de desayunar.<br>Antón y yo <b>nos quemamos</b> con unas cerillas."},{"k":"img","src":"img/gram/u40_teoria-afeito2.png","alt":"Un barbero: «Afeito a unas seis personas todas las mañanas.»"},{"k":"eg","t":"Rut viste <b>a los niños</b> después de desayunar.<br>Ayer quemamos <b>unos troncos</b> en la chimenea."},{"k":"p","t":"<i>Nos, os</i> y <i>se</i> se usan también para indicar que la acción la realizan dos o más personas de manera recíproca («yo a ti y tú a mí»)."},{"k":"eg","t":"<b>Nos</b> queremos. (Ella me quiere a mí y yo la quiero a ella.)<br>¿<b>Os</b> conocéis Marisa y tú? (¿Conoces tú a Marisa y te conoce ella a ti?)<br>Juan y su padre <b>se</b> entienden muy bien. (Juan entiende a su padre y su padre entiende a Juan.)"}],"ex":[{"id":"gram:40.1","type":"cloze","lab":"40.1","title":"40.1","instr":"Complete las frases con me, te, se… solo cuando sea necesario. Escriba Ø cuando no haga falta.","items":[{"tpl":"Rosa ___ cortó con un cuchillo ayer.","blanks":1,"ans":["se"],"example":true},{"tpl":"Sandra ___ mira mucho al espejo.","blanks":1,"ans":["se"]},{"tpl":"Juan ___ cortó el pan con su navaja.","blanks":1,"ans":["Ø"]},{"tpl":"No ___ mires tanto al espejo, Saúl.","blanks":1,"ans":["te"]},{"tpl":"¿Cuándo ___ duchan los niños?","blanks":1,"ans":["se"]},{"tpl":"Mi hermana y yo ___ quemamos cocinando.","blanks":1,"ans":["nos"]},{"tpl":"Roberto ___ ha quemado las cartas de Aurora.","blanks":1,"ans":["Ø"]},{"tpl":"Julio y Pedro ___ saludaron en la fiesta.","blanks":1,"ans":["se"]},{"tpl":"¿Quién ___ ha tirado mis gafas a la basura?","blanks":1,"ans":["Ø"]},{"tpl":"¿Por qué ___ pone usted el sombrero?","blanks":1,"ans":["se"]},{"tpl":"Mira. (Yo) ___ veo en el agua.","blanks":1,"ans":["me"]},{"tpl":"¿Qué ___ ves en el agua?","blanks":1,"ans":["Ø"]},{"tpl":"¿Cuándo ___ lavas el pelo, Sonia?","blanks":1,"ans":["te"]},{"tpl":"¿Vosotros ___ afeitáis todos los días?","blanks":1,"ans":["os"]},{"tpl":"Alicia ___ rompió una pierna esquiando.","blanks":1,"ans":["se"]}]},{"id":"gram:40.2","type":"cloze","lab":"40.2","title":"40.2","instr":"Vuelva a escribir las frases con nos, os o se. Atención con el verbo.","items":[{"tpl":"___","blanks":1,"ans":["Felipe y David se saludaron","David y Felipe se saludaron"],"ctx":"Felipe saludó a David y David saludó a Felipe.","wide":true,"full":true,"example":true,"exv":["Felipe y David se saludaron"]},{"tpl":"___","blanks":1,"ans":["Roque y Julio no se hablan","Julio y Roque no se hablan"],"ctx":"Roque no habla a Julio y Julio no habla a Roque.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Roque y tú os queréis","Tú y Roque os queréis"],"ctx":"Roque te quiere a ti y tú quieres a Roque.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Sofía y Lina se escriben","Lina y Sofía se escriben"],"ctx":"Sofía escribe a Lina y Lina escribe a Sofía.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Andrés y yo nos conocemos muy bien","Yo y Andrés nos conocemos muy bien"],"ctx":"Andrés me conoce muy bien a mí y yo conozco muy bien a Andrés.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Rodrigo y su hermana se ayudan","Su hermana y Rodrigo se ayudan"],"ctx":"Rodrigo ayuda a su hermana y su hermana ayuda a Rodrigo.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["En Navidad, mi mujer y yo nos hacemos un regalo","Mi mujer y yo nos hacemos un regalo en Navidad","En Navidad mi mujer y yo nos hacemos un regalo"],"ctx":"En Navidad, mi mujer me hace un regalo y yo le hago un regalo a ella.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Tus amigos y tú os veis los domingos","Los domingos tus amigos y tú os veis"],"ctx":"Tus amigos te ven a ti y tú los ves a ellos los domingos.","wide":true,"full":true}]},{"id":"gram:40.3","type":"cloze","lab":"40.3","title":"40.3","instr":"Complete las siguientes frases con me, te, se… cuando sea necesario. Escriba Ø cuando no haga falta.","items":[{"tpl":"(Yo) ___ conozco muy bien.","blanks":1,"ans":["Me"],"example":true},{"tpl":"Teresa y Antonio ___ conocen muy bien.","blanks":1,"ans":["se"]},{"tpl":"___ conozco muy bien a mis hijos.","blanks":1,"ans":["Ø"]},{"tpl":"¿Por qué no ___ quieren Isabel y Leo?","blanks":1,"ans":["se"]},{"tpl":"¿Por qué no ___ quieres a tu hermano?","blanks":1,"ans":["Ø"]},{"tpl":"¿Por qué ___ peleáis tú y Juan?","blanks":1,"ans":["os"]},{"tpl":"¿___ veis mucho Alfonso y tú?","blanks":1,"ans":["Os"]},{"tpl":"Raúl y Teresa no ___ hablan.","blanks":1,"ans":["se"]},{"tpl":"¿___ ve usted en el espejo?","blanks":1,"ans":["Se"]},{"tpl":"María y Alfredo ___ ven todos los días.","blanks":1,"ans":["se"]},{"tpl":"¿Por qué no ___ vistes, Rosa? Es tarde.","blanks":1,"ans":["te"]},{"tpl":"¿___ has vestido ya a los niños, Jaime?","blanks":1,"ans":["Ø"]}]}]},{"id":41,"name":"Pronombres personales con preposiciones","motto":"para mí, contigo…","theory":[{"k":"img","src":"img/gram/u41_teoria-comics.png","alt":"«Toma. Es para ti.» «¿Para mí? Gracias.» · «Irene, ¿quieres venir al cine conmigo?» · «¿Has visto a Luis? Quiero hablar con él.»"},{"k":"h","t":"Preposiciones + pronombres"},{"k":"table","head":["PREPOSICIONES","PRONOMBRES"],"rows":[["a · de · para · por · sin …","mí · ti · usted · él, ella · nosotros, nosotras · vosotros, vosotras · ustedes · ellos, ellas"]]},{"k":"note","h":"PERO","rows":["con + mí → <b>conmigo</b>","con + ti → <b>contigo</b>","¿Te quieres venir <b>conmigo</b> al cine?","Soy muy feliz <b>contigo</b>."]},{"k":"eg","t":"No pueden vivir sin <b>mí</b>.<br>No quiero nada de <b>ti</b>.<br>Hay una llamada para <b>usted</b>.<br>—Ya no tengo coche. —¿Qué has hecho con <b>él</b>?<br>¿Has visto a Dana? Quiero hablar con <b>ella</b>.<br>Siéntate junto a <b>nosotras</b>.<br>¿Me dejáis jugar con <b>vosotros</b>?<br>Tengo algo para <b>ustedes</b>.<br>¿Dónde están los gatos? Tengo algo de comida para <b>ellos</b>."},{"k":"img","src":"img/gram/u41_teoria-todos.png","alt":"Un grupo de personas: «Todos hablan idiomas menos yo.»"},{"k":"note","h":"ATENCIÓN","rows":["entre · excepto · hasta (= incluso) · incluso · menos · según + <b>yo, tú</b>","Siéntate aquí, entre Ivana y <b>yo</b>.","Saben nadar todos menos <b>yo</b>.","Según <b>tú</b>, ¿quién es el culpable?"]}],"ex":[{"id":"gram:41.1","type":"cloze","lab":"41.1","title":"41.1","instr":"Complete las frases utilizando pronombres.","img":"img/gram/u41_ej41-1_ilustraciones.png","alt":"Ocho viñetas con globos: «Para ti», «Para …», «Estoy enfadada con …», «Para …», «¿Es para …? Gracias.», «Buenos días, don Salvador. Me gustaría hablar con …», «Está hecha por …», «¿Para …? Gracias.»","items":[{"tpl":"Para ___.","blanks":1,"ans":["ti"],"mid":true,"example":true},{"tpl":"Para ___.","blanks":1,"ans":["ustedes"],"mid":true},{"tpl":"Estoy enfadada con ___.","blanks":1,"ans":["contigo"],"mid":true},{"tpl":"Para ___.","blanks":1,"ans":["vosotras"],"mid":true},{"tpl":"¿Es para ___? Gracias.","blanks":1,"ans":["nosotros"],"mid":true},{"tpl":"Buenos días, don Salvador. Me gustaría hablar con ___.","blanks":1,"ans":["usted"],"mid":true},{"tpl":"Está hecha por ___.","blanks":1,"ans":["nosotras"],"mid":true},{"tpl":"¿Para ___? Gracias.","blanks":1,"ans":["mí"],"mid":true}]},{"id":"gram:41.2","type":"cloze","lab":"41.2","title":"41.2","instr":"Complete las frases con el pronombre adecuado.","items":[{"tpl":"¿Has visto a Adolfo? Quiero hablar con ___.","blanks":1,"ans":["él"],"mid":true,"example":true},{"tpl":"¿Has visto a Petra? Quiero hablar con ___.","blanks":1,"ans":["ella"],"mid":true},{"tpl":"¿Has visto al señor Carmona? Tengo algo para ___.","blanks":1,"ans":["él"],"mid":true},{"tpl":"Antonio te está buscando. Quiere hablar con ___.","blanks":1,"ans":["contigo"],"mid":true},{"tpl":"¿Dónde están Pepe y Susana? Mercedes quiere hablar con ___.","blanks":1,"ans":["ellos"],"mid":true},{"tpl":"Aurora nos está buscando. No puede estar un momento sin ___.","blanks":1,"ans":["nosotros","nosotras"],"mid":true},{"tpl":"Mi jefe me necesita. No sabe hacer nada sin ___.","blanks":1,"ans":["mí"],"mid":true}]},{"id":"gram:41.3","type":"cloze","lab":"41.3","title":"41.3","instr":"Complete las frases con yo, mí, conmigo o tú, ti, contigo.","items":[{"tpl":"Estoy triste. Luisa no quiere salir ___.","blanks":1,"ans":["conmigo"],"mid":true,"example":true},{"tpl":"Lo siento, Jaime. Han aprobado todos menos ___.","blanks":1,"ans":["tú"],"mid":true},{"tpl":"Toma, un regalo para ___ de parte de Ana.","blanks":1,"ans":["ti"],"mid":true},{"tpl":"Oye, Luis, según ___, ¿quién va a ganar el domingo?","blanks":1,"ans":["tú"],"mid":true},{"tpl":"¿Esto es para ___? Gracias.","blanks":1,"ans":["mí"],"mid":true},{"tpl":"Ven con ___, por favor. Necesito ayuda.","blanks":1,"ans":["conmigo"],"mid":true},{"tpl":"¿Está Berta con ___, María?","blanks":1,"ans":["contigo"],"mid":true}]},{"id":"gram:41.4","type":"pick","lab":"41.4","title":"41.4","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"Según [ti|tú], ¿quién es el mejor cantante del mundo?","ans":["tú"],"example":true},{"tpl":"Toma. Este disco es para [ti|tú].","ans":["ti"]},{"tpl":"Ven. Siéntate junto a [mí|yo].","ans":["mí"]},{"tpl":"Luisa se sienta entre Jorge y [mí|yo].","ans":["yo"]},{"tpl":"¿Quieres venir [conmigo|con yo], Sonia?","ans":["conmigo"]},{"tpl":"Sebastián se sienta delante de [mí|yo].","ans":["mí"]},{"tpl":"A todos les gusta el pescado menos a [mí|yo].","ans":["mí"]},{"tpl":"Han leído todos el <i>Quijote</i> menos [mí|yo].","ans":["yo"]}]}]},{"id":42,"name":"Presente de indicativo de ser","motto":"soy, eres, es…","theory":[{"k":"h","t":"Ser: presente de indicativo"},{"k":"table","head":["","ser"],"rows":[["(yo)","<b>soy</b>"],["(tú)","<b>eres</b>"],["(usted)","<b>es</b>"],["(él, ella)","<b>es</b>"],["(nosotros, -as)","<b>somos</b>"],["(vosotros, -as)","<b>sois</b>"],["(ustedes)","<b>son</b>"],["(ellos, -as)","<b>son</b>"]]},{"k":"img","src":"img/gram/u42_teoria-peruana.png","alt":"«¿De dónde eres? – Soy peruana.»"},{"k":"p","t":"Se usa <i>ser</i>:"},{"k":"p","t":"– para identificar a personas o cosas."},{"k":"img","src":"img/gram/u42_teoria-sombrero.png","alt":"«¿Qué es eso? – Es un sombrero.»"},{"k":"eg","t":"Mira. Ese <b>es</b> Andrés.<br>—¿Qué <b>es</b> eso? —<b>Es</b> una cámara digital."},{"k":"img","src":"img/gram/u42_teoria-alberto.png","alt":"«¿Quién es Alberto? – Soy yo.»"},{"k":"p","t":"– para decir la profesión, la nacionalidad o la ideología."},{"k":"eg","t":"<b>Soy</b> estudiante. · El hermano de Ana <b>es</b> médico.<br>Chelo <b>es</b> peruana. · Laika y yo <b>somos</b> musulmanes."},{"k":"p","t":"– para indicar la relación o el parentesco."},{"k":"eg","t":"Luis y María <b>son</b> amigos. · Pedro y yo <b>somos</b> primos."},{"k":"p","t":"– para expresar cualidades."},{"k":"eg","t":"Diana <b>es</b> muy inteligente.<br>Estos libros no <b>son</b> muy interesantes.<br>El coche de Eduardo <b>es</b> rojo."},{"k":"img","src":"img/gram/u42_teoria-hora.png","alt":"«¿Qué hora es, por favor? – Son las cinco.»"},{"k":"p","t":"– para indicar tiempo, cantidad o precio."},{"k":"eg","t":"—¿Qué día <b>es</b> hoy? —<b>Es</b> martes.<br>En mi clase <b>somos</b> veintidós.<br>—¿Cuánto <b>es</b> esto? —<b>Son</b> sesenta euros."},{"k":"note","h":"ATENCIÓN","rows":["<b>Es</b> la una. · <b>Son</b> las dos."]},{"k":"p","t":"– para decir el lugar o el momento de un acontecimiento."},{"k":"eg","t":"¿Dónde <b>es</b> la fiesta? · El partido <b>es</b> a las diez."},{"k":"p","t":"Se usa <i>ser + de</i> para indicar origen, materia o posesión."},{"k":"eg","t":"<i>origen:</i> ¿De dónde <b>son</b> ustedes? <b>Somos de</b> Santander.<br><i>materia:</i> Esta silla <b>es de</b> plástico.<br><i>posesión:</i> Ese coche <b>es de</b> Eduardo."}],"ex":[{"id":"gram:42.1","type":"cloze","lab":"42.1","title":"42.1","instr":"Observe las ilustraciones y complete las frases con soy, eres, es…","img":"img/gram/u42_ej42-1_ilustraciones.png","alt":"Seis viñetas: «¿De dónde sois? – … mexicanos», «¿Quién … Liz? – … yo», «… hermanas», «¿… ustedes médicos? – No, … enfermeros», «¿De dónde …? – … de Barcelona», «… 25 euros».","items":[{"tpl":"¿De dónde ___? ___ mexicanos.","blanks":2,"ans":["sois Somos"],"mid":true,"example":true,"exv":["sois","Somos"]},{"tpl":"¿Quién ___ Liz? ___ yo.","blanks":2,"ans":["es Soy"],"mid":true},{"tpl":"___ hermanas.","blanks":1,"ans":["Somos"],"mid":true},{"tpl":"¿___ ustedes médicos? No, ___ enfermeros.","blanks":2,"ans":["Son somos"],"mid":true},{"tpl":"¿De dónde ___? ___ de Barcelona.","blanks":2,"ans":["eres Soy"],"mid":true},{"tpl":"___ 25 euros.","blanks":1,"ans":["Son"],"mid":true}]},{"id":"gram:42.2","type":"cloze","lab":"42.2","title":"42.2","instr":"Complete las preguntas y las respuestas con soy, eres, es…","items":[{"tpl":"¿De dónde ___ (tú)? — ___ de Quito.","blanks":2,"ans":["eres Soy"],"mid":true,"perBlank":true,"example":true},{"tpl":"¿De dónde ___ tus padres? — ___ de Guayaquil.","blanks":2,"ans":["son Son"],"mid":true,"perBlank":true},{"tpl":"¿Cuántos ___ en tu familia? — ___ cuatro.","blanks":2,"ans":["sois Somos"],"mid":true,"perBlank":true},{"tpl":"¿___ profesor? — No, ___ estudiante.","blanks":2,"ans":["Eres soy"],"mid":true,"perBlank":true},{"tpl":"¿Qué hora ___? — ___ las tres.","blanks":2,"ans":["es Son"],"mid":true,"perBlank":true},{"tpl":"¿Qué día ___ hoy? — ___ jueves.","blanks":2,"ans":["es Es"],"mid":true,"perBlank":true},{"tpl":"¿___ Rosa y tú hermanos? — No, ___ primos.","blanks":2,"ans":["Sois somos"],"mid":true,"perBlank":true},{"tpl":"¿A qué hora ___ la clase? — ___ a las ocho.","blanks":2,"ans":["es Es"],"mid":true,"perBlank":true},{"tpl":"¿Cuántos ___ en clase? — ___ doce.","blanks":2,"ans":["sois Somos"],"mid":true,"perBlank":true},{"tpl":"¿De quién ___ estos libros? — ___ de la profesora.","blanks":2,"ans":["son Son"],"mid":true,"perBlank":true}]},{"id":"gram:42.3","type":"cloze","lab":"42.3","title":"42.3","instr":"Escriba frases con soy, eres, es… en forma afirmativa o negativa.","items":[{"tpl":"___","blanks":1,"ans":["Elsa y Tomás son chilenos"],"ctx":"Elsa y Tomás / chilenos","wide":true,"full":true,"example":true,"exv":["Elsa y Tomás son chilenos"]},{"tpl":"___","blanks":1,"ans":["Usted es muy amable"],"ctx":"Usted / muy amable","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Esa mesa es de cristal"],"ctx":"Esa mesa / de cristal","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Mi hermano y yo no somos morenos"],"ctx":"Mi hermano y yo / no / morenos","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Vosotros sois muy alegres"],"ctx":"Vosotros / muy alegres","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Esos pantalones no son de lana"],"ctx":"Esos pantalones / no / de lana","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Ese libro es de Marta"],"ctx":"Ese libro / de Marta","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Ustedes no son muy altos"],"ctx":"Ustedes / no / muy altos","wide":true,"full":true}]}]},{"id":43,"name":"Presente de indicativo de estar","motto":"estoy, estás, está…","theory":[{"k":"img","src":"img/gram/u43_teoria-comics.png","alt":"«Estoy en Sevilla.» · «¿Dónde están mis llaves? – Están encima de la televisión.» · Luis está en la cama. Está enfermo."},{"k":"h","t":"Estar: presente de indicativo"},{"k":"table","head":["","estar"],"rows":[["(yo)","<b>estoy</b>"],["(tú)","<b>estás</b>"],["(usted)","<b>está</b>"],["(él, ella)","<b>está</b>"],["(nosotros, -as)","<b>estamos</b>"],["(vosotros, -as)","<b>estáis</b>"],["(ustedes)","<b>están</b>"],["(ellos, -as)","<b>están</b>"]]},{"k":"p","t":"Se usa <i>estar</i>:"},{"k":"p","t":"– para indicar la situación física de alguien o algo."},{"k":"eg","t":"Mis padres <b>están</b> en Caracas.<br>—¿Dónde <b>está</b> Monterrey? —<b>Está</b> en el norte de México."},{"k":"note","h":"ATENCIÓN","rows":["<i>estar</i> + nombre de persona → estar en casa o en un lugar habitual","¿<b>Está</b> Miguel? (¿Está Miguel en casa?)","Buenos días. ¿<b>Está</b> la señora Vasconcelos? (¿Está la señora Vasconcelos en la oficina?)"]},{"k":"img","src":"img/gram/u43_teoria-jefe.png","alt":"«El jefe está de mal humor hoy.»"},{"k":"p","t":"– para indicar algunos estados físicos y anímicos temporales: enfermo, resfriado, cansado, agotado, contento, triste, aburrido, de buen/mal humor…"},{"k":"eg","t":"<b>Estamos</b> aburridos.<br>—¿Cómo <b>estás</b> hoy, Mónica? —<b>Estoy</b> un poco cansada."},{"k":"p","t":"– para referirnos a situaciones temporales."},{"k":"eg","t":"La casa <b>está</b> sucia. (Normalmente está limpia.)<br>La sopa <b>está</b> caliente."},{"k":"img","src":"img/gram/u43_teoria-tiendas.png","alt":"Las tiendas están abiertas. · Las tiendas están cerradas."},{"k":"p","t":"Unidad 56: Presente de <i>estar</i> + gerundio."}],"ex":[{"id":"gram:43.1","type":"cloze","lab":"43.1","title":"43.1","instr":"¿Dónde están? Complete las frases con estoy, estás, está…","img":"img/gram/u43_ej43-1_ilustraciones.png","alt":"Tres viñetas: «Estoy en México», «¿Dónde …? – … en Paraguay», «¿Dónde …? – … en París».","items":[{"tpl":"___ en México.","blanks":1,"ans":["Estoy"],"mid":true,"example":true},{"tpl":"¿Dónde ___? ___ en Paraguay.","blanks":2,"ans":["estáis Estamos"],"mid":true},{"tpl":"¿Dónde ___? ___ en París.","blanks":2,"ans":["estás Estoy"],"mid":true}]},{"id":"gram:43.2","type":"cloze","lab":"43.2","title":"43.2","instr":"Complete las frases con estoy, estás, está… y las palabras del recuadro.","img":"img/gram/u43_ej43-2_ilustraciones.png","alt":"Ocho viñetas con globos vacíos: una mujer resfriada, una mujer ante el ordenador, dos jugadores perdiendo 0-4, dos hombres sudando, una mujer ante la tele, un jefe enfadado con Alberto, una mujer ante el ordenador, dos jugadores ganando 2-0.","bank":["aburrida","agotado","contento","de buen humor","de mal humor","enfadado","~resfriado","triste"],"items":[{"tpl":"Estoy ___.","blanks":1,"ans":["resfriado"],"wide":true,"example":true},{"tpl":"¿Por qué ___?","blanks":1,"ans":["está de buen humor"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Están tristes"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Estamos agotados"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Estoy aburrida"],"wide":true},{"tpl":"¿___, Alberto?","blanks":1,"ans":["Estás enfadado"],"wide":true},{"tpl":"Hoy ___.","blanks":1,"ans":["está de mal humor"],"wide":true},{"tpl":"¿Por qué ___?","blanks":1,"ans":["están contentos"],"wide":true}]},{"id":"gram:43.3","type":"cloze","lab":"43.3","title":"43.3","instr":"Describa cada ilustración utilizando está o están y las palabras del recuadro.","img":"img/gram/u43_ej43-3_ilustraciones.png","alt":"Seis dibujos: ventana, puerta, vasos, cielo, televisión y platos.","bank":["~abierta","apagada","cerrada","limpios","nublado","sucios"],"items":[{"tpl":"La ventana ___.","blanks":1,"ans":["está abierta"],"wide":true,"example":true},{"tpl":"La puerta ___.","blanks":1,"ans":["está cerrada"],"wide":true},{"tpl":"Los vasos ___.","blanks":1,"ans":["están sucios"],"wide":true},{"tpl":"El cielo ___.","blanks":1,"ans":["está nublado"],"wide":true},{"tpl":"La televisión ___.","blanks":1,"ans":["está apagada"],"wide":true},{"tpl":"Los platos ___.","blanks":1,"ans":["están limpios"],"wide":true}]},{"id":"gram:43.4","type":"cloze","lab":"43.4","title":"43.4","instr":"Complete los diálogos con estoy, estás, está…","items":[{"tpl":"—¿Cómo ___ usted, Elisa? —___ muy bien, gracias.","blanks":2,"ans":["está Estoy"],"mid":true,"example":true,"exv":["está","Estoy"]},{"tpl":"—¿___ Luisa? —Sí, pero ___ en la cama.","blanks":2,"ans":["Está está"],"mid":true},{"tpl":"—¿___ cansado, Virgilio? —No, no ___ cansado. ___ aburrido.","blanks":3,"ans":["Estás estoy Estoy"],"mid":true},{"tpl":"—¿Dónde ___ mi chaqueta nueva? —___ en el armario.","blanks":2,"ans":["está Está"],"mid":true},{"tpl":"—¿Dónde ___ las Islas Galápagos? —___ en el Pacífico.","blanks":2,"ans":["están Están"],"mid":true}]}]},{"id":44,"name":"Contraste entre ser y estar","motto":"soy alegre / estoy alegre","theory":[{"k":"h","t":"Compare: SER"},{"k":"p","t":"Se usa <i>ser</i> para hablar de las características o cualidades normales o permanentes de alguien o algo."},{"k":"img","src":"img/gram/u44_teoria-activa.png","alt":"Unas chicas activas: una al teléfono, una ante el ordenador y otra jugando al tenis."},{"k":"eg","t":"María <b>es</b> muy activa. (Es así normalmente.)<br>Julián <b>es</b> alegre. (Es así normalmente.)<br>El hielo <b>es</b> frío."},{"k":"img","src":"img/gram/u44_teoria-sofia.png","alt":"Una chica delgada."},{"k":"eg","t":"Sofía <b>es</b> delgada. (Es así siempre.)<br>Ana <b>es</b> muy elegante."},{"k":"p","t":"Se usa <i>ser</i> para indicar el lugar o el momento de un acontecimiento."},{"k":"eg","t":"La boda <b>es</b> en la iglesia de Santa Marta, a las cinco."},{"k":"h","t":"Compare: ESTAR"},{"k":"p","t":"Se usa <i>estar</i> para hablar de las características o estados anormales o temporales de alguien o algo."},{"k":"img","src":"img/gram/u44_teoria-sillon.png","alt":"Una mujer cansada en un sillón."},{"k":"eg","t":"Hoy <b>está</b> cansada. (Solo hoy.)<br>Hoy no <b>está</b> alegre. <b>Está</b> triste.<br>Este café <b>está</b> frío."},{"k":"note","h":"PERO","rows":["<b>Estar muerto.</b> Esta planta <b>está</b> muerta."]},{"k":"p","t":"Se usa <i>estar</i> para indicar cambios."},{"k":"img","src":"img/gram/u44_teoria-delgado.png","alt":"«Estás muy delgado, Pedro.»"},{"k":"p","t":"Se usa <i>estar</i> para enfatizar el momento."},{"k":"eg","t":"<b>Estás</b> muy elegante con ese vestido."},{"k":"p","t":"Se usa <i>estar</i> para indicar lugar o posición de alguien o algo."},{"k":"eg","t":"La iglesia de Santa Marta <b>está</b> en la Plaza de Córdoba."},{"k":"h","t":"Adjetivos con significado diferente"},{"k":"img","src":"img/gram/u44_teoria-perro.png","alt":"Un perro travieso."},{"k":"eg","t":"Este perro <b>es</b> muy malo. (Es travieso.)"},{"k":"img","src":"img/gram/u44_teoria-pepe.png","alt":"Un hombre enfermo en la cama."},{"k":"eg","t":"Pepe <b>está</b> malo. (Está enfermo.)"},{"k":"table","head":["ser","estar"],"rows":[["<i>ser malo</i> = de mal comportamiento o mala calidad","<i>estar malo</i> = estar enfermo"],["<i>ser aburrido</i> = soso, que no sabe divertirse","<i>estar aburrido</i> = no tener nada para divertirse"],["<i>ser bueno</i> = de buen comportamiento, de buena calidad","<i>estar bueno</i> = sabroso o recuperado de una enfermedad"],["<i>ser listo</i> = astuto, inteligente","<i>estar listo</i> = preparado"],["<i>ser moreno</i> = tener el pelo oscuro","<i>estar moreno</i> = bronceado"],["<i>ser rico</i> = tener dinero","<i>estar rico</i> = sabroso"]]},{"k":"p","t":"Unidad 56: Presente de <i>estar</i> + gerundio."}],"ex":[{"id":"gram:44.1","type":"pick","lab":"44.1","title":"44.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"[Soy|Estoy] cansado.","ans":["Estoy"],"example":true},{"tpl":"Este café [es|está] muy caliente.","ans":["está"]},{"tpl":"Algunas rosas [son|están] blancas.","ans":["son"]},{"tpl":"Esos cristales [son|están] sucios.","ans":["están"]},{"tpl":"Este árbol [es|está] muerto.","ans":["está"]},{"tpl":"Ana y Sergio [son|están] casados.","ans":["están"]},{"tpl":"Las margaritas [son|están] amarillas y blancas.","ans":["son"]},{"tpl":"¡Qué guapa [eres|estás] con ese sombrero, Lola!","ans":["estás"]},{"tpl":"Hoy no [soy|estoy] alegre.","ans":["estoy"]}]},{"id":"gram:44.2","type":"cloze","lab":"44.2","title":"44.2","instr":"Complete las frases con formas de ser o estar.","items":[{"tpl":"Las serpientes ___ peligrosas.","blanks":1,"ans":["son"],"mid":true,"example":true},{"tpl":"Este libro ___ muy interesante.","blanks":1,"ans":["es"],"mid":true},{"tpl":"La nieve ___ blanca.","blanks":1,"ans":["es"],"mid":true},{"tpl":"No os sentéis en esas sillas. ___ sucias.","blanks":1,"ans":["Están"],"mid":true},{"tpl":"Juan ___ muy guapo con uniforme.","blanks":1,"ans":["está"],"mid":true},{"tpl":"La sopa ___ fría. Caliéntala un poco.","blanks":1,"ans":["está"],"mid":true},{"tpl":"Los plátanos ___ amarillos.","blanks":1,"ans":["son"],"mid":true},{"tpl":"¡Qué guapo ___ Francisco! Tiene unos ojos grandísimos.","blanks":1,"ans":["es"],"mid":true},{"tpl":"Flor y Pili ___ muy guapas con el nuevo peinado.","blanks":1,"ans":["están"],"mid":true}]},{"id":"gram:44.3","type":"cloze","lab":"44.3","title":"44.3","instr":"Complete las frases con el presente de indicativo de ser o estar.","items":[{"tpl":"¿Dónde ___ la fiesta?","blanks":1,"ans":["es"],"mid":true,"example":true},{"tpl":"El examen ___ a las diez.","blanks":1,"ans":["es"],"mid":true},{"tpl":"¿Dónde ___ mis gafas?","blanks":1,"ans":["están"],"mid":true},{"tpl":"Mañana ___ mi cumpleaños.","blanks":1,"ans":["es"],"mid":true},{"tpl":"El examen ___ en el aula 15.","blanks":1,"ans":["es"],"mid":true},{"tpl":"¿Cuándo ___ la boda?","blanks":1,"ans":["es"],"mid":true},{"tpl":"¿Dónde ___ la discoteca Futuro?","blanks":1,"ans":["está"],"mid":true},{"tpl":"El examen ___ encima de la mesa.","blanks":1,"ans":["está"],"mid":true},{"tpl":"El concierto ___ en el Teatro Real.","blanks":1,"ans":["es"],"mid":true},{"tpl":"El Teatro Real ___ en la Plaza de la Ópera.","blanks":1,"ans":["está"],"mid":true}]},{"id":"gram:44.4","type":"cloze","lab":"44.4","title":"44.4","instr":"Utilice formas de ser o estar para completar las frases.","img":"img/gram/u44_ej44-4_ilustraciones.png","alt":"Ocho viñetas: «¿Estás lista?», «Carlos … muy moreno», «Felipe … muy rico», «… malo», «Isabel … muy morena», «Esta paella … muy rica», «Ángel y Nieves … muy buenos», «… aburridos».","items":[{"tpl":"¿___ lista?","blanks":1,"ans":["Estás"],"mid":true,"example":true},{"tpl":"Carlos ___ muy moreno.","blanks":1,"ans":["está"],"mid":true},{"tpl":"Felipe ___ muy rico.","blanks":1,"ans":["es"],"mid":true},{"tpl":"___ malo.","blanks":1,"ans":["Estoy"],"mid":true},{"tpl":"Isabel ___ muy morena.","blanks":1,"ans":["es"],"mid":true},{"tpl":"Esta paella ___ muy rica.","blanks":1,"ans":["está"],"mid":true},{"tpl":"Ángel y Nieves ___ muy buenos.","blanks":1,"ans":["son"],"mid":true},{"tpl":"___ aburridos.","blanks":1,"ans":["Estamos"],"mid":true}]}]},{"id":45,"name":"Presente de indicativo de tener","motto":"tengo, tienes, tiene…","theory":[{"k":"img","src":"img/gram/u45_teoria-dinero.png","alt":"«¿Tienes dinero?»"},{"k":"img","src":"img/gram/u45_teoria-sueno.png","alt":"«Es tarde. Tengo sueño.»"},{"k":"h","t":"Tener: presente de indicativo"},{"k":"table","head":["","tener"],"rows":[["(yo)","<b>tengo</b>"],["(tú)","<b>tienes</b>"],["(usted)","<b>tiene</b>"],["(él, ella)","<b>tiene</b>"],["(nosotros, -as)","<b>tenemos</b>"],["(vosotros, -as)","<b>tenéis</b>"],["(ustedes)","<b>tienen</b>"],["(ellos, -as)","<b>tienen</b>"]]},{"k":"img","src":"img/gram/u45_teoria-adela.png","alt":"Adela y Jorge no tienen hijos."},{"k":"eg","t":"Adela y Jorge <b>no tienen</b> hijos."},{"k":"p","t":"Se usa <i>tener</i> para:"},{"k":"p","t":"– indicar posesión."},{"k":"eg","t":"¿<b>Tienes</b> dinero?<br><b>Tengo</b> un ordenador nuevo.<br>Luis no <b>tiene</b> coche."},{"k":"p","t":"– pedir algo (en preguntas)."},{"k":"eg","t":"—¿<b>Tienes</b> un lápiz? —Sí, pero lo necesito."},{"k":"p","t":"– hablar de la familia."},{"k":"eg","t":"Cristina <b>tiene</b> siete hermanos.<br>¿Cuántos hijos <b>tenéis</b>? —No <b>tenemos</b> hijos."},{"k":"p","t":"– decir la edad."},{"k":"eg","t":"¿Cuántos años <b>tienes</b>?<br>Mis abuelos <b>tienen</b> noventa años."},{"k":"p","t":"– describir personas, cosas o lugares."},{"k":"eg","t":"Enrique <b>tiene</b> los ojos verdes.<br>Mi casa no <b>tiene</b> jardín."},{"k":"p","t":"– expresar algunos estados físicos y anímicos temporales: hambre, sed, frío, calor, miedo, sueño, fiebre, gripe…"},{"k":"eg","t":"<b>Tienes</b> mala cara.<br>¿<b>Tienes</b> fiebre?"},{"k":"img","src":"img/gram/u45_teoria-miedo.png","alt":"«¿Tenéis frío? – No, tenemos miedo.»"}],"ex":[{"id":"gram:45.1","type":"cloze","lab":"45.1","title":"45.1","instr":"Complete las frases con tengo, tienes… en forma afirmativa o negativa.","tbl":{"head":["","edad","hermanos","hijos","ojos"],"rows":[["Julio","23","—","—","marrones"],["Pepa","28","una hermana","3","verdes"],["Jorge","31","—","3","negros"],["Margarita","23","dos hermanos","—","marrones"]]},"items":[{"tpl":"Pepa: Jorge ___ treinta y un años, Julio y Margarita ___ veintitrés y yo ___ veintiocho.","blanks":3,"ans":["tiene tienen tengo"],"mid":true,"example":true,"exv":["tiene","tienen","tengo"]},{"tpl":"Jorge: Margarita ___ dos hermanos, Pepa ___ una hermana y Julio y yo ___ hermanos.","blanks":3,"ans":["tiene tiene no tenemos"],"mid":true},{"tpl":"Margarita: Pepa y Jorge ___ tres hijos, pero Julio y yo ___ hijos.","blanks":2,"ans":["tienen no tenemos"],"mid":true},{"tpl":"Pepa: Yo ___ los ojos marrones. Los ___ verdes.","blanks":2,"ans":["no tengo tengo"],"mid":true},{"tpl":"Julio: Jorge ___ los ojos negros y Margarita y yo los ___ marrones.","blanks":2,"ans":["tiene tenemos"],"mid":true}]},{"id":"gram:45.2","type":"cloze","lab":"45.2","title":"45.2","instr":"Escriba frases con tengo, tienes… y las palabras del recuadro.","img":"img/gram/u45_ej45-2_ilustraciones.png","alt":"Siete viñetas: un hombre sediento en el desierto, dos mujeres comiendo, un hombre con calor, una mujer asustada de noche, una conversación junto a una cama, un niño con el termómetro y personas con frío.","bank":["calor","fiebre","frío","gripe","hambre","miedo","~sed","sueño"],"items":[{"tpl":"___.","blanks":1,"ans":["Tengo sed"],"wide":true,"example":true},{"tpl":"___.","blanks":1,"ans":["Tenemos hambre"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Tengo calor"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Tengo miedo"],"wide":true},{"tpl":"¿___? No, ___.","blanks":2,"ans":["Tienes sueño tengo gripe"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Tienes fiebre"],"wide":true},{"tpl":"¿___?","blanks":1,"ans":["Tenéis frío"],"wide":true}]},{"id":"gram:45.3","type":"cloze","lab":"45.3","title":"45.3","instr":"Escriba frases con tengo, tienes…","items":[{"tpl":"___","blanks":1,"ans":["¿Tiene usted sueño?"],"ctx":"usted, sueño","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["¿Tienes dinero?"],"ctx":"(tú) dinero","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No tenemos coche"],"ctx":"(nosotros) no, coche","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Tienen ustedes hijos?","¿Tienen hijos ustedes?"],"ctx":"ustedes, hijos","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Mis abuelos tienen doce nietos"],"ctx":"mis abuelos, doce nietos","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Tiene usted una casa grande?"],"ctx":"usted, una casa grande","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Tenéis muchos amigos?"],"ctx":"(vosotras) muchos amigos","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Tienen ustedes perro?","¿Tienen perro ustedes?"],"ctx":"ustedes, perro","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Tienes un diccionario?"],"ctx":"(tú) un diccionario","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Mi casa no tiene ascensor"],"ctx":"mi casa, no, ascensor","wide":true,"full":true}]}]},{"id":46,"name":"Presente de indicativo de haber impersonal","motto":"Hay un vaso en la mesa","theory":[{"k":"img","src":"img/gram/u46_teoria-ilustraciones.png","alt":"Hay un vaso en la mesa. · Hay cinco alumnos en clase. · No hay leche."},{"k":"h","t":"Hay + nombres contables (vaso, alumno…)"},{"k":"table","rows":[["<i>hay</i> + <i>un, una</i> + nombre contable singular<br><i>hay</i> + <i>uno, una</i>","<b>Hay un pájaro</b> en el balcón.<br>—¿<b>Hay un hotel</b> por aquí? —<b>Hay uno</b> en la calle Arenal."],["<i>hay</i> (+ <i>unos, unas; dos, tres…; muchos, pocos…</i>) + nombre contable plural","<b>Hay naranjas</b> en la nevera.<br>En mi calle <b>hay muchos árboles</b>."],["<i>hay</i> + <i>dos, tres…</i> / <i>muchos, pocos…</i><br>¿<i>Cuántos, cuántas</i> + nombre contable plural + <i>hay</i>?","¿<b>Hay muchos cines</b> en tu barrio? —<b>Hay tres</b>.<br>—¿Cuántos chicos <b>hay</b> en tu clase? —<b>Hay nueve</b>."],["<i>no hay</i> (+ <i>ningún, ninguna</i>) + nombre contable singular","<b>No hay ningún hotel</b> en esta calle.<br>En Santa Marta <b>no hay aeropuerto</b>."],["<i>no hay</i> (+ <i>muchos</i>) + nombre contable plural","En mi calle <b>no hay árboles</b>.<br>En mi barrio <b>no hay muchos bares</b>."]]},{"k":"h","t":"Hay + nombres no contables (pan, agua…)"},{"k":"table","rows":[["(<i>no</i>) <i>hay</i> (+ <i>mucho, poco…</i>) + nombre no contable<br>¿<i>Cuánto, cuánta</i> + nombre no contable + <i>hay</i>?","<b>Hay agua</b> en el suelo.<br><b>No hay mucha mantequilla</b>.<br>—¿<b>Hay pan</b>? —<b>No hay mucho</b>.<br>¿Cuánta leche <b>hay</b> en la nevera?"]]},{"k":"p","t":"Se usa <i>hay</i>:"},{"k":"p","t":"– para indicar o preguntar por la existencia de algo o alguien en un lugar determinado."},{"k":"eg","t":"¿<b>Hay</b> una frutería por aquí?<br>—¿<b>Hay</b> pan (en casa)? —Sí, <b>hay</b> dos barras."},{"k":"img","src":"img/gram/u46_teoria-buzon.png","alt":"«Perdone, ¿dónde hay un buzón? – Hay uno en esa esquina.»"},{"k":"p","t":"– para preguntar por la situación de algo o alguien cuya existencia desconocemos."},{"k":"eg","t":"¿Dónde <b>hay</b> un estanco? (No conozco el barrio y no sé si hay un estanco.)"},{"k":"p","t":"Unidad 47: Contraste entre <i>haber</i> y <i>estar</i>. · Unidad 95: Expresiones con infinitivo (2)."}],"ex":[{"id":"gram:46.1","type":"cloze","lab":"46.1","title":"46.1","instr":"¿Qué hay en la habitación? Observe la ilustración y escriba frases con hay en forma afirmativa o negativa.","img":"img/gram/u46_ej46-1_habitacion.png","alt":"Una habitación con una mesa, sillas, una lámpara, un reloj de pie, cuadros y un sillón; no hay espejo ni televisor.","items":[{"tpl":"___","blanks":1,"ans":["Hay una mesa"],"ctx":"(mesa)","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["No hay espejo"],"ctx":"(espejo)","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Hay una alfombra"],"ctx":"(alfombra)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay tres sillas"],"ctx":"(sillas)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay una lámpara"],"ctx":"(lámpara)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay televisor"],"ctx":"(televisor)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay un reloj"],"ctx":"(reloj)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay dos cuadros"],"ctx":"(cuadros)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay ningún cojín","No hay cojines"],"ctx":"(cojín)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay un sillón"],"ctx":"(sillón)","wide":true,"full":true}]},{"id":"gram:46.2","type":"cloze","lab":"46.2","title":"46.2","instr":"Lea la información sobre Ciudad Nueva y escriba frases con hay en forma afirmativa o negativa.","tbl":{"head":["Ciudad Nueva",""],"rows":[["colegios","5"],["cines","1"],["hospitales","no"],["polideportivos","1"],["parques","2"],["estaciones de ferrocarril","no"],["estaciones de autobús","1"],["hoteles","no"],["iglesias","2"],["bibliotecas","1"]]},"items":[{"tpl":"___","blanks":1,"ans":["Hay cinco colegios"],"ctx":"colegios · 5","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Hay un cine"],"ctx":"cines · 1","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay ningún hospital","No hay hospitales"],"ctx":"hospitales · no","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay un polideportivo"],"ctx":"polideportivos · 1","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay dos parques","Hay 2 parques"],"ctx":"parques · 2","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay ninguna estación de ferrocarril","No hay estaciones de ferrocarril"],"ctx":"estaciones de ferrocarril · no","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay una estación de autobús"],"ctx":"estaciones de autobús · 1","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay ningún hotel","No hay hoteles"],"ctx":"hoteles · no","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay dos iglesias","Hay 2 iglesias"],"ctx":"iglesias · 2","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay una biblioteca"],"ctx":"bibliotecas · 1","wide":true,"full":true}]},{"id":"gram:46.3","type":"cloze","lab":"46.3","title":"46.3","instr":"¿Qué hay en la nevera? Observe la ilustración y escriba frases con hay en forma afirmativa o negativa.","img":"img/gram/u46_ej46-3_nevera.png","alt":"El interior de una nevera con queso, mantequilla, leche, huevos, uvas y naranjas.","items":[{"tpl":"___","blanks":1,"ans":["Hay leche"],"ctx":"(leche)","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["No hay agua"],"ctx":"(agua)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay mantequilla"],"ctx":"(mantequilla)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay queso"],"ctx":"(queso)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay seis huevos","Hay 6 huevos"],"ctx":"(seis huevos)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay uvas"],"ctx":"(uvas)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Hay naranjas"],"ctx":"(naranjas)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay plátanos"],"ctx":"(plátanos)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay zumo de naranja"],"ctx":"(zumo de naranja)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["No hay yogures"],"ctx":"(yogures)","wide":true,"full":true}]},{"id":"gram:46.4","type":"cloze","lab":"46.4","title":"46.4","instr":"Complete los diálogos con hay en forma afirmativa o negativa y las palabras entre paréntesis.","items":[{"tpl":"—¿Dónde (buzón) ___? —(uno) ___ en la esquina.","blanks":2,"ans":["hay un buzón Hay uno"],"wide":true,"example":true,"exv":["hay un buzón","Hay uno"]},{"tpl":"En mi barrio (no, metro) ___.","blanks":1,"ans":["no hay metro"],"wide":true},{"tpl":"—¿Dónde (estanco) ___? —(uno) ___ a cien metros.","blanks":2,"ans":["hay un estanco Hay uno"],"wide":true},{"tpl":"—¿(muchas tiendas) ___ en tu barrio? —No, (no, muchas) ___.","blanks":2,"ans":["Hay muchas tiendas no hay muchas"],"wide":true},{"tpl":"—¿Cuántos (huevos) ___ en la nevera? —___ ninguno.","blanks":2,"ans":["huevos hay No hay"],"wide":true},{"tpl":"—¿Cuánta (leche) ___? —(un litro) ___.","blanks":2,"ans":["leche hay Hay un litro"],"wide":true},{"tpl":"—¿(cafetería) ___ por aquí? —Sí, (una) ___ en la Plaza Mayor.","blanks":2,"ans":["Hay una cafetería hay una"],"wide":true},{"tpl":"—¿Cuántos (yogures) ___ en la nevera? —(tres) ___.","blanks":2,"ans":["yogures hay Hay tres"],"wide":true}]}]},{"id":47,"name":"Contraste entre haber y estar","motto":"Hay un cine. Está en la calle Mayor","theory":[{"k":"h","t":"Compare: HAY / ESTAR"},{"k":"table","head":["HAY (Unidad 46)","ESTAR (Unidad 43)"],"rows":[["Se usa <i>hay</i> para hablar de la <b>existencia</b> de algo o alguien no conocido (información nueva).<br><i><b>Hay un señor</b> que quiere hablar con usted.</i> (No sé quién es ese señor.)<br><i><b>Hay un restaurante nuevo</b> en el barrio.</i> (No conozco ese restaurante.)","Se usa <i>estar</i> para indicar la <b>situación</b> de algo o alguien mencionado anteriormente (información conocida).<br><i><b>Está</b> en la recepción.</i> (El señor del que le he hablado.)<br><i><b>Está</b> en la calle Apodaca.</i> (El restaurante del que te he hablado.)"],["Se usa <i>hay</i> para hablar de la existencia de algo o alguien indeterminado.<br><i><b>Hay un cine</b> en la calle Monterrey.</i><br><i>En Madrid <b>hay muchos museos</b>.</i>","Se usa <i>estar</i> para hablar de la situación de algo único o específico.<br><i>El cine América <b>está</b> en la calle Monterrey.</i><br><i>El Museo del Prado <b>está</b> en Madrid.</i>"],["Se usa <i>hay</i> para preguntar por la situación de algo o alguien desconocido.<br><i>¿Dónde <b>hay una farmacia</b>?</i> (No conozco ninguna farmacia en este barrio.)<br><i>¿Dónde <b>hay un restaurante</b>?</i>","Se usa <i>estar</i> para preguntar por la situación de algo conocido.<br><i>¿Dónde <b>está la farmacia de tu tía</b>?</i> (Sé que tu tía tiene una farmacia.)<br><i>¿Dónde <b>está Casa Pepe</b>?</i>"]]},{"k":"img","src":"img/gram/u47_teoria-farmacia.png","alt":"«Perdone, ¿dónde hay una farmacia?»"},{"k":"img","src":"img/gram/u47_teoria-marta.png","alt":"«Oye, Marta, ¿dónde está la farmacia de tu tía?»"},{"k":"note","h":"ATENCIÓN","rows":["Con <i>hay</i> no se usa <i>el/la/los/las</i>, ni <i>mi/tu/su/…</i>","<s>Hay el Museo del Táchira</s> en la Hacienda Paranillo. → Hay un museo en la Hacienda Paranillo <i>o</i> El Museo del Táchira está en la Hacienda Paranillo.","¿Dónde <s>hay la parada</s> de autobús? → ¿Dónde hay una parada de autobús? <i>o</i> ¿Dónde está la parada de autobús más próxima?","<s>—¿Dónde hay mis herramientas?</s> → —¿Dónde hay herramientas? (No sé si hay herramientas.) <i>o</i> ¿Dónde están mis herramientas? (Tengo herramientas, pero no sé dónde están.)","<i>Hay</i> + singular o plural: <b>Hay un supermercado</b> en el pueblo. En este pueblo <b>hay tres bares</b>.","Singular + <i>está</i>, plural + <i>están</i>: El supermercado <b>está</b> en la plaza. Los bares <b>están</b> en el centro."]}],"ex":[{"id":"gram:47.1","type":"pick","lab":"47.1","title":"47.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"[Hay|Está] un paquete para ti. [Hay|Está] en tu habitación.","ans":["Hay","Está"],"example":true},{"tpl":"¿Cuántos alumnos [hay|están] en tu clase?","ans":["hay"]},{"tpl":"—¿[Hay|Está] pan? —Sí, [hay|está] en la despensa.","ans":["Hay","está"]},{"tpl":"—¿[Hay|Está] algo para comer? —Sí, [hay|está] queso en la nevera.","ans":["Hay","hay"]},{"tpl":"¿Qué [hay|está] en esa caja?","ans":["hay"]},{"tpl":"¿[Hay|Está] una estación de metro por aquí?","ans":["Hay"]},{"tpl":"La cafetería del hospital [hay|está] en el sótano.","ans":["está"]},{"tpl":"En este edificio [hay|están] dos oficinas. [Hay|Están] en el primer piso.","ans":["hay","Están"]},{"tpl":"[Hay|Está] un ratón en mi habitación. [Hay|Está] debajo de la cama.","ans":["Hay","Está"]},{"tpl":"[Hay|Están] muchos museos en Barcelona.","ans":["Hay"]}]},{"id":"gram:47.2","type":"cloze","lab":"47.2","title":"47.2","instr":"Seleccione las formas adecuadas y escriba frases.","img":"img/gram/u47_ej47-2_tabla.png","alt":"Tabla: ¿Dónde + hay / está / están + una farmacia, una parada de autobús, la parada de autobús más próxima, el Hospital Central, las ruinas de Tikal, un banco, el Banco de Galicia, los cines Luna?","items":[{"tpl":"___","blanks":1,"ans":["¿Dónde hay una farmacia?"],"wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["¿Dónde hay una parada de autobús?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde está la parada de autobús más próxima?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde está el Hospital Central?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde están las ruinas de Tikal?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde hay un banco?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde está el Banco de Galicia?"],"wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["¿Dónde están los cines Luna?"],"wide":true,"full":true}]},{"id":"gram:47.3","type":"cloze","lab":"47.3","title":"47.3","instr":"Complete las frases con hay, está o están.","items":[{"tpl":"___ diez alumnos en mi clase.","blanks":1,"ans":["Hay"],"mid":true,"example":true},{"tpl":"¿Dónde ___ la casa de tu abuelo?","blanks":1,"ans":["está"],"mid":true},{"tpl":"___ un cine nuevo en mi barrio. ___ en la calle de Bravo Murillo.","blanks":2,"ans":["Hay Está"],"mid":true},{"tpl":"Perdone, ¿___ la calle 67 por aquí?","blanks":1,"ans":["está"],"mid":true},{"tpl":"Mis compañeros ___ en la cafetería.","blanks":1,"ans":["están"],"mid":true},{"tpl":"¿Dónde ___ la parada del 61?","blanks":1,"ans":["está"],"mid":true},{"tpl":"___ un departamento nuevo en la empresa. ___ en el piso cuarto.","blanks":2,"ans":["Hay Está"],"mid":true},{"tpl":"¿___ leche? —Sí, ___ un litro. ___ en la nevera.","blanks":3,"ans":["Hay hay Está"],"mid":true},{"tpl":"¿Dónde ___ una parada de taxis?","blanks":1,"ans":["hay"],"mid":true},{"tpl":"En mi pueblo ___ dos piscinas. ___ en las afueras.","blanks":2,"ans":["hay Están"],"mid":true},{"tpl":"¿Dónde ___ la posada La Montaña?","blanks":1,"ans":["está"],"mid":true},{"tpl":"¿___ una papelería por aquí?","blanks":1,"ans":["Hay"],"mid":true},{"tpl":"___ unas cartas para usted. ___ en el salón.","blanks":2,"ans":["Hay Están"],"mid":true},{"tpl":"En mi calle ___ un hotel. ___ cerca de mi casa.","blanks":2,"ans":["hay Está"],"mid":true},{"tpl":"En Bogotá ___ un museo del oro.","blanks":1,"ans":["hay"],"mid":true},{"tpl":"¿Dónde ___ mis llaves?","blanks":1,"ans":["están"],"mid":true},{"tpl":"En Lima ___ muchos edificios antiguos. ___ todos en el centro.","blanks":2,"ans":["Hay Están"],"mid":true}]}]},{"id":48,"name":"Presente de indicativo: verbos regulares","motto":"trabajo, como, vivo…","theory":[{"k":"img","src":"img/gram/u48_teoria-comics.png","alt":"«¿Y dónde vives ahora? – Vivo en la calle Luna.» · «Perdone. ¿Trabaja usted aquí?» · «No, gracias. No como carne.»"},{"k":"p","t":"<i>Vives, vivo, trabaja</i> y <i>como</i> son formas del presente de indicativo."},{"k":"h","t":"Formación del presente de indicativo: verbos regulares"},{"k":"table","head":["","-ar (trabajar)","-er (comer)","-ir (vivir)"],"rows":[["(yo)","trabaj-<b>o</b>","com-<b>o</b>","viv-<b>o</b>"],["(tú)","trabaj-<b>as</b>","com-<b>es</b>","viv-<b>es</b>"],["(usted)","trabaj-<b>a</b>","com-<b>e</b>","viv-<b>e</b>"],["(él, ella)","trabaj-<b>a</b>","com-<b>e</b>","viv-<b>e</b>"],["(nosotros, -as)","trabaj-<b>amos</b>","com-<b>emos</b>","viv-<b>imos</b>"],["(vosotros, -as)","trabaj-<b>áis</b>","com-<b>éis</b>","viv-<b>ís</b>"],["(ustedes)","trabaj-<b>an</b>","com-<b>en</b>","viv-<b>en</b>"],["(ellos, -as)","trabaj-<b>an</b>","com-<b>en</b>","viv-<b>en</b>"]]},{"k":"note","h":"ATENCIÓN","rows":["Verbo <i>ver</i>: <b>ve-o</b>, v-es, v-e, v-e, v-emos, v-eis, v-en, v-en"]},{"k":"p","t":"El presente de indicativo se usa para:"},{"k":"p","t":"– pedir o dar información sobre el presente."},{"k":"eg","t":"El hermano de Alicia <b>trabaja</b> en una empresa de informática.<br>Nos <b>alojamos</b> en casa de Andrés."},{"k":"p","t":"– hablar de lo que hacemos habitualmente (todos los días, una vez a la semana, siempre, nunca, etc.). Unidad 103: Adverbios y expresiones de frecuencia."},{"k":"eg","t":"En mi casa <b>cenamos</b> muy temprano.<br>Cristina <b>lleva</b> siempre vaqueros.<br>¿<b>Trabajas</b> los domingos?<br>No <b>bebo</b> vino.<br>Normalmente <b>pasamos</b> el fin de semana en el campo."},{"k":"p","t":"– hablar de verdades generales o universales."},{"k":"eg","t":"La Tierra <b>gira</b> alrededor del Sol.<br>Los vegetarianos no <b>comen</b> carne."},{"k":"p","t":"– describir acciones que están sucediendo en el momento de hablar. Unidad 56: Presente de <i>estar</i> + gerundio."},{"k":"img","src":"img/gram/u48_teoria-gorra.png","alt":"«¿Qué ves? – Una chica. Lleva una gorra de béisbol.»"},{"k":"p","t":"Unidades 49 y 50: verbos irregulares · Unidad 51: otros usos · Unidad 52: Presente para expresar períodos de tiempo."}],"ex":[{"id":"gram:48.1","type":"cloze","lab":"48.1","title":"48.1","instr":"Lea la información y complete las frases con estudiar, trabajar o vivir en forma afirmativa o negativa.","tbl":{"head":["","residencia","trabajo"],"rows":[["Arturo","Segovia","fábrica"],["José","Lima","tienda"],["Pilar","Lima","guardería"],["María","Cali","hospital"],["Ana","Cali","estudiante de Historia"],["Pedro","Buenos Aires","estudiante de Economía"]]},"items":[{"tpl":"Arturo: ___ en Segovia y ___ en una fábrica.","blanks":2,"ans":["Vivo trabajo"],"mid":true,"example":true,"exv":["Vivo","trabajo"]},{"tpl":"Pilar: José y yo ___ en Lima. José ___ en una tienda y yo ___ en una guardería.","blanks":3,"ans":["vivimos trabaja trabajo"],"mid":true},{"tpl":"Pedro: ___ en Buenos Aires. ___ ; ___ Economía.","blanks":3,"ans":["Vivo No trabajo estudio"],"mid":true},{"tpl":"María: Ana y yo ___ en Cali. Yo ___ en un hospital. Ana ___ ; ___ Historia.","blanks":4,"ans":["vivimos trabajo no trabaja estudia"],"mid":true}]},{"id":"gram:48.2","type":"cloze","lab":"48.2","title":"48.2","instr":"Complete las frases.","items":[{"tpl":"—¿A qué hora (vosotros, cenar) ___? —___ a las nueve.","blanks":2,"ans":["cenáis Cenamos"],"mid":true,"example":true,"exv":["cenáis","Cenamos"]},{"tpl":"—¿Dónde (tú, pasar) ___ los veranos? —___ los veranos en Punta del Este.","blanks":2,"ans":["pasas Paso"],"mid":true},{"tpl":"Las ballenas (vivir) ___ en aguas frías.","blanks":1,"ans":["viven"],"mid":true},{"tpl":"—¿Dónde (trabajar) ___ usted? —___ en unos grandes almacenes.","blanks":2,"ans":["trabaja Trabajo"],"mid":true},{"tpl":"Los argentinos (hablar) ___ español.","blanks":1,"ans":["hablan"],"mid":true},{"tpl":"—¿Qué (beber) ___ ustedes en las comidas? —Normalmente ___ agua.","blanks":2,"ans":["beben bebemos"],"mid":true},{"tpl":"—¿Dónde (vosotros, vivir) ___? —___ en Mérida.","blanks":2,"ans":["vivís Vivimos"],"mid":true},{"tpl":"Lalo y yo (no viajar) ___ nunca en avión.","blanks":1,"ans":["no viajamos"],"mid":true},{"tpl":"—¿Qué idiomas (hablar) ___ ustedes? —___ español e italiano.","blanks":2,"ans":["hablan Hablamos"],"mid":true},{"tpl":"—¿Qué (estudiar) ___ tus hermanas? —Ana ___ Económicas y Pilar ___ Medicina.","blanks":3,"ans":["estudian estudia estudia"],"mid":true},{"tpl":"(Nosotros, no ver) ___ mucho la tele.","blanks":1,"ans":["No vemos"],"mid":true},{"tpl":"¿A qué hora (abrir) ___ las tiendas?","blanks":1,"ans":["abren"],"mid":true}]},{"id":"gram:48.3","type":"cloze","lab":"48.3","title":"48.3","instr":"Complete las frases con los verbos del recuadro en forma afirmativa o negativa.","img":"img/gram/u48_ej48-3_ilustraciones.png","alt":"Seis viñetas: «¿Ves algo?», «¿Qué …?», «¿Qué …?», «Mira a Lucía. … un sombrero muy bonito», «¿Qué …?», «¿Qué … en la cabeza?».","bank":["beber","comer","llevar","llevar","pasar","~ver"],"items":[{"tpl":"¿___ algo?","blanks":1,"ans":["Ves"],"mid":true,"example":true},{"tpl":"¿Qué ___?","blanks":1,"ans":["comes"],"mid":true},{"tpl":"¿Qué ___?","blanks":1,"ans":["pasa"],"mid":true},{"tpl":"Mira a Lucía. ___ un sombrero muy bonito.","blanks":1,"ans":["Lleva"],"mid":true},{"tpl":"¿Qué ___?","blanks":1,"ans":["bebéis"],"mid":true},{"tpl":"¿Qué ___ en la cabeza?","blanks":1,"ans":["llevan"],"mid":true}]}]},{"id":49,"name":"Presente de indicativo: verbos irregulares (1)","motto":"quiero, mido, sueño...","theory":[{"k":"h","t":"Formación del presente de indicativo: verbos irregulares"},{"k":"p","t":"<b>e → ie</b> (querer) y <b>e → i</b> (pedir)"},{"k":"table","head":["","querer","pedir"],"rows":[["(yo)","quier-o","pid-o"],["(tú)","quier-es","pid-es"],["(usted)","quier-e","pid-e"],["(él, ella)","quier-e","pid-e"],["(nosotros, -as)","quer-emos","pedim-os"],["(vosotros, -as)","quer-éis","ped-ís"],["(ustedes)","quier-en","pid-en"],["(ellos, -as)","quier-en","pid-en"]]},{"k":"p","t":"Otros con e → ie: <i>-ar:</i> empezar, fregar, pensar, regar, cerrar · <i>-er:</i> entender, perder · <i>-ir:</i> mentir, preferir."},{"k":"p","t":"Otros con e → i: elegir, conseguir, freír, medir, reír, repetir, seguir, sonreír."},{"k":"note","h":"ATENCIÓN","rows":["<i>venir</i>: <b>vengo</b>, vienes, viene, viene, venimos, venís, vienen, vienen","<i>decir</i>: <b>digo</b>, dices, dice, dice, decimos, decís, dicen, dicen"]},{"k":"p","t":"<b>o/u → ue</b> (dormir, jugar)"},{"k":"table","head":["","dormir","jugar"],"rows":[["(yo)","duerm-o","jueg-o"],["(tú)","duerm-es","jueg-as"],["(usted)","duerm-e","jueg-a"],["(él, ella)","duerm-e","jueg-a"],["(nosotros, -as)","dorm-imos","jug-amos"],["(vosotros, -as)","dorm-ís","jug-áis"],["(ustedes)","duerm-en","jueg-an"],["(ellos, -as)","duerm-en","jueg-an"]]},{"k":"img","src":"img/gram/u49_teoria-duermo.png","alt":"«Solo duermo 5 horas al día.»"},{"k":"p","t":"Otros con o → ue: <i>-ar:</i> comprobar, contar, costar, encontrar, recordar, sonar, volar · <i>-er:</i> morder, mover, volver, poder · <i>-ir:</i> morir."},{"k":"note","h":"ATENCIÓN","rows":["<i>oler</i>: <b>huelo</b>, <b>hueles</b>, <b>huele</b>, olemos, oléis, <b>huelen</b>"]},{"k":"h","t":"Usos del presente de indicativo"},{"k":"p","t":"– Hablar del presente: <i>No <b>juego</b> muy bien al tenis.</i>"},{"k":"p","t":"– Hablar de verdades generales: <i>Las gallinas no <b>vuelan</b>.</i>"},{"k":"p","t":"– Hablar de lo que sucede en el momento de hablar: <i>¿En qué <b>piensas</b>?</i>"},{"k":"p","t":"Unidad 48: Presente de indicativo: verbos regulares · Unidad 51: Presente de indicativo: otros usos"}],"ex":[{"id":"gram:49.1","type":"cloze","lab":"49.1","title":"49.1","instr":"Complete las frases con las formas correspondientes de los verbos entre paréntesis.","items":[{"tpl":"Antonio (querer) ___ ser médico.","blanks":1,"ans":["quiere"],"mid":true,"example":true},{"tpl":"En verano (yo, regar) ___ las plantas todos los días.","blanks":1,"ans":["riego"],"mid":true},{"tpl":"La clase (empezar) ___ a las ocho.","blanks":1,"ans":["empieza"],"mid":true},{"tpl":"Luis y Pili (jugar) ___ muy mal al golf. Siempre (perder) ___.","blanks":2,"ans":["juegan pierden"],"mid":true},{"tpl":"Los bancos (cerrar) ___ a las dos.","blanks":1,"ans":["cierran"],"mid":true},{"tpl":"(yo, pensar) ___ mucho en mis amigos.","blanks":1,"ans":["Pienso"],"mid":true},{"tpl":"Algunos alumnos (venir) ___ mucho a la biblioteca.","blanks":1,"ans":["vienen"],"mid":true},{"tpl":"Antonia (no mentir) ___ nunca. Siempre (decir) ___ la verdad.","blanks":2,"ans":["no miente dice"],"mid":true},{"tpl":"Estoy muy nerviosa. (no poder) ___ dormir.","blanks":1,"ans":["No puedo"],"mid":true},{"tpl":"¿Cuánto (medir) ___ una jirafa?","blanks":1,"ans":["mide"],"mid":true},{"tpl":"A veces (yo, decir) ___ muchas tonterías.","blanks":1,"ans":["digo"],"mid":true},{"tpl":"¿A qué velocidad (volar) ___ un avión?","blanks":1,"ans":["vuela"],"mid":true}]},{"id":"gram:49.2","type":"cloze","lab":"49.2","title":"49.2","instr":"Complete las preguntas y las respuestas.","items":[{"tpl":"—¿Cuánto (tú, medir) ___? —___ 1,75 metros.","blanks":2,"ans":["mides Mido"],"mid":true,"example":true,"exv":["mides","Mido"]},{"tpl":"—¿Cuántas horas (tú, dormir) ___ al día? —___ unas ocho horas.","blanks":2,"ans":["duermes Duermo"],"mid":true},{"tpl":"—¿(preferir) ___ usted carne o pescado? —___ el pescado.","blanks":2,"ans":["Prefiere Prefiero"],"mid":true},{"tpl":"—¿A qué hora (empezar) ___ ustedes a trabajar? —___ a las nueve.","blanks":2,"ans":["empiezan Empezamos"],"mid":true},{"tpl":"—¿Quién (fregar) ___ los platos en tu casa? —Los ___ yo.","blanks":2,"ans":["friega friego"],"mid":true},{"tpl":"—¿Qué (tú, querer) ___ ser de mayor? —___ ser arquitecto.","blanks":2,"ans":["quieres Quiero"],"mid":true},{"tpl":"—¿A qué hora (tú, volver) ___ por la noche? —Normalmente ___ sobre las diez.","blanks":2,"ans":["vuelves vuelvo"],"mid":true},{"tpl":"—¿Cómo (tú, venir) ___ a la academia? —___ en autobús.","blanks":2,"ans":["vienes Vengo"],"mid":true}]},{"id":"gram:49.3","type":"cloze","lab":"49.3","title":"49.3","instr":"Observe las ilustraciones y complete las frases con los verbos del recuadro en forma afirmativa o negativa.","img":"img/gram/u49_ej49-3_ilustraciones.png","alt":"Ocho viñetas: «¿De dónde vienes?», «¿Qué … tomar?», «¿Qué …? No … oírte», «¡Qué bien … estas flores!», «¿Cuánto … estos zapatos?», «… mis gafas», «No tengas miedo. …», «Este despertador …».","bank":["costar","decir","encontrar","morder","oler","poder","querer","sonar","~venir"],"items":[{"tpl":"¿De dónde ___?","blanks":1,"ans":["vienes"],"mid":true,"example":true},{"tpl":"¿Qué ___ tomar?","blanks":1,"ans":["quieren"],"mid":true},{"tpl":"¿Qué ___? No ___ oírte.","blanks":2,"ans":["dices No puedo"],"mid":true},{"tpl":"¡Qué bien ___ estas flores!","blanks":1,"ans":["huelen"],"mid":true},{"tpl":"¿Cuánto ___ estos zapatos?","blanks":1,"ans":["cuestan"],"mid":true},{"tpl":"___ mis gafas.","blanks":1,"ans":["No encuentro"],"mid":true},{"tpl":"No tengas miedo. ___.","blanks":1,"ans":["No muerde"],"mid":true},{"tpl":"Este despertador ___.","blanks":1,"ans":["no suena"],"mid":true}]}]},{"id":50,"name":"Presente de indicativo: verbos irregulares (2)","motto":"voy, hago, conozco...","theory":[{"k":"h","t":"Formación del presente de indicativo: verbos irregulares"},{"k":"p","t":"<b>Primera persona del singular (yo) irregular</b>"},{"k":"img","src":"img/gram/u50_teoria-hago.png","alt":"«Hago gimnasia todas las mañanas.»"},{"k":"eg","t":"<i>dar:</i> <b>doy</b>, das, da, da, damos, dais, dan, dan<br><i>traer:</i> <b>traigo</b>, traes, trae, trae, traemos, traéis, traen, traen<br><i>hacer:</i> <b>hago</b>, haces, hace, hace, hacemos, hacéis, hacen, hacen<br><i>saber:</i> <b>sé</b>, sabes, sabe, sabe, sabemos, sabéis, saben, saben<br><i>poner:</i> <b>pongo</b>, pones, pone, pone, ponemos, ponéis, ponen, ponen<br><i>conocer:</i> <b>conozco</b>, conoces, conoce, conoce, conocemos, conocéis, conocen, conocen<br><i>conducir:</i> <b>conduzco</b>, conduces, conduce, conduce, conducimos, conducís, conducen, conducen<br><i>salir:</i> <b>salgo</b>, sales, sale, sale, salimos, salís, salen, salen"},{"k":"img","src":"img/gram/u50_teoria-berta.png","alt":"«Te conozco. Tú eres Berta.»"},{"k":"p","t":"Otros: parecer, traducir."},{"k":"p","t":"<b>Todas las personas irregulares excepto nosotros, -as y vosotros, -as</b>"},{"k":"eg","t":"<i>huir:</i> <b>huyo, huyes, huye, huye</b>, huimos, huís, <b>huyen, huyen</b><br><i>oír:</i> <b>oigo, oyes, oye, oye</b>, oímos, oís, <b>oyen, oyen</b>"},{"k":"p","t":"También: construir, destruir."},{"k":"img","src":"img/gram/u50_teoria-tomas.png","alt":"Tomás no oye nada."},{"k":"p","t":"<b>Todas las personas irregulares</b>"},{"k":"table","head":["","ir"],"rows":[["(yo)","<b>voy</b>"],["(tú)","<b>vas</b>"],["(usted)","<b>va</b>"],["(él, ella)","<b>va</b>"],["(nosotros, -as)","<b>vamos</b>"],["(vosotros, -as)","<b>vais</b>"],["(ustedes)","<b>van</b>"],["(ellos, -as)","<b>van</b>"]]},{"k":"img","src":"img/gram/u50_teoria-adonde.png","alt":"«¿Adónde vas? – Voy a casa.»"},{"k":"h","t":"Usos del presente de indicativo"},{"k":"eg","t":"Los domingos <b>doy</b> una vuelta por el parque.<br>Las cigüeñas <b>hacen</b> nidos en las torres.<br>No <b>sé</b> conducir.<br>¿Qué <b>dices</b>? No <b>oigo</b>."},{"k":"p","t":"Unidad 48: Presente de indicativo: verbos regulares · Unidad 51: Presente de indicativo: otros usos"}],"ex":[{"id":"gram:50.1","type":"cloze","lab":"50.1","title":"50.1","instr":"Utilice los verbos del recuadro para completar las siguientes frases.","bank":["dar","dar","hacer","huir","ir","poner","poner","~saber","saber","traducir"],"items":[{"tpl":"Guillermo no ___ nadar.","blanks":1,"ans":["sabe"],"mid":true,"example":true},{"tpl":"Soy profesor. ___ clases de Filosofía.","blanks":1,"ans":["Doy"],"mid":true},{"tpl":"Mi familia ___ a Punta del Este todos los veranos.","blanks":1,"ans":["va"],"mid":true},{"tpl":"Julia es profesora. ___ clases de Biología.","blanks":1,"ans":["Da"],"mid":true},{"tpl":"Las cigüeñas ___ sus nidos en lugares altos.","blanks":1,"ans":["ponen"],"mid":true},{"tpl":"(yo) ___ la radio cuando me despierto.","blanks":1,"ans":["Pongo"],"mid":true},{"tpl":"Mis padres ___ un viaje todos los años.","blanks":1,"ans":["hacen"],"mid":true},{"tpl":"Marta no ___ esquiar.","blanks":1,"ans":["sabe"],"mid":true},{"tpl":"La mayoría de animales ___ cuando hay peligro.","blanks":1,"ans":["huyen"],"mid":true},{"tpl":"Soy traductor. ___ libros del francés al español.","blanks":1,"ans":["Traduzco"],"mid":true}]},{"id":"gram:50.2","type":"cloze","lab":"50.2","title":"50.2","instr":"Complete las preguntas y las respuestas con los siguientes verbos: conducir, conocer, dar, hacer, ir, saber o salir.","items":[{"tpl":"—¿___ conducir? —Sí, pero no ___ muy bien.","blanks":2,"ans":["Sabes conduzco"],"mid":true,"example":true,"exv":["Sabes","conduzco"]},{"tpl":"—¿Cómo ___ a la oficina? —Normalmente ___ en metro.","blanks":2,"ans":["vas voy"],"mid":true},{"tpl":"—¿Qué ___ los fines de semana? —___ con mis amigos.","blanks":2,"ans":["haces Salgo"],"mid":true},{"tpl":"—¿___ usted hacer empanadas? —Sí, pero no las ___ muy bien.","blanks":2,"ans":["Sabe hago"],"mid":true},{"tpl":"—¿___ usted hablar inglés? —No, solo ___ hablar español.","blanks":2,"ans":["Sabe sé"],"mid":true},{"tpl":"—¿___ usted La Habana? —No, no la ___.","blanks":2,"ans":["Conoce conozco"],"mid":true},{"tpl":"—¿Adónde ___ usted en verano? —Normalmente ___ a la playa.","blanks":2,"ans":["va voy"],"mid":true},{"tpl":"—¿Qué ___ (vosotros) los domingos? —___ una vuelta o ___ a bailar.","blanks":3,"ans":["hacéis Damos vamos"],"mid":true},{"tpl":"—¿___ (vosotros) mucho al cine? —___ dos o tres veces al mes.","blanks":2,"ans":["Vais Vamos"],"mid":true},{"tpl":"—¿___ ustedes España? —Sí, la ___ muy bien. ___ allí con frecuencia.","blanks":3,"ans":["Conocen conocemos Vamos"],"mid":true}]},{"id":"gram:50.3","type":"cloze","lab":"50.3","title":"50.3","instr":"Complete los bocadillos con los verbos del recuadro en forma afirmativa o negativa.","img":"img/gram/u50_ej50-3_ilustraciones.png","alt":"Ocho viñetas: «¿Adónde vais?», «¿Por qué …?», «¡Socorro! … nadar», «Habla más alto. … bien», «… una bruja», «Perdone, ¿adónde … este autobús?», «¡… pasteles!», «Perdona, … te …».","bank":["conocer","huir","~ir","ir","oír","parecer","saber","traer"],"items":[{"tpl":"¿Adónde ___?","blanks":1,"ans":["vais"],"mid":true,"example":true},{"tpl":"¿Por qué ___?","blanks":1,"ans":["huye"],"mid":true},{"tpl":"¡Socorro! ___ nadar.","blanks":1,"ans":["No sé"],"mid":true},{"tpl":"Habla más alto. ___ bien.","blanks":1,"ans":["No oigo"],"mid":true},{"tpl":"___ una bruja.","blanks":1,"ans":["Parezco"],"mid":true},{"tpl":"Perdone, ¿adónde ___ este autobús?","blanks":1,"ans":["va"],"mid":true},{"tpl":"¡___ pasteles!","blanks":1,"ans":["Traigo"],"mid":true},{"tpl":"Perdona, ___ te ___. ¿Cómo te llamas?","blanks":2,"ans":["no conozco"],"mid":true}]}]},{"id":51,"name":"Presente de indicativo: otros usos","motto":"Mañana voy al médico","theory":[{"k":"p","t":"Usos del presente de indicativo → Unidad 48: Presente de indicativo: verbos regulares"},{"k":"h","t":"Otros usos del presente de indicativo"},{"k":"p","t":"– Hablar del futuro próximo cuando algo está ya acordado o programado, con expresiones como <i>hoy, esta noche, mañana, la semana que viene…</i>"},{"k":"eg","t":"Luis <b>regresa</b> la semana que viene.<br>Mañana <b>voy</b> al médico.<br>Nos <b>vemos</b> el domingo.<br>El curso <b>termina</b> en diciembre.<br>¿Qué <b>haces</b> esta noche?<br>La película <b>empieza</b> a las 10.<br>El avión <b>sale</b> a las 4.35."},{"k":"img","src":"img/gram/u51_teoria-sierra.png","alt":"«¿Vamos a la sierra el domingo? – No puedo. El domingo como con mis padres.»"},{"k":"p","t":"– Dar instrucciones, con <i>primero, luego…</i>"},{"k":"eg","t":"Primero <b>pelas</b> los tomates y luego los <b>partes</b>."},{"k":"img","src":"img/gram/u51_teoria-calle.png","alt":"«Baja usted por esta calle y luego tuerce a la izquierda.»"},{"k":"p","t":"– Hacer sugerencias"},{"k":"eg","t":"—¿Por qué no le <b>pides</b> el coche a Jesús? —No me atrevo.<br>—¿<b>Llamamos</b> a Nuria? —Sí, ¡venga!"},{"k":"p","t":"– Pedir consejo u opinión"},{"k":"eg","t":"—¿<b>Invito</b> a Julio? —Si tú quieres."},{"k":"img","src":"img/gram/u51_teoria-compro.png","alt":"«¿Qué hago? ¿Lo compro? – No sé. Es un poco caro.»"},{"k":"p","t":"– Ofrecer ayuda"},{"k":"eg","t":"—¿Le <b>abro</b> la puerta? —Gracias. Muy amable."},{"k":"img","src":"img/gram/u51_teoria-llevo.png","alt":"«¿Te llevo algún libro?»"},{"k":"p","t":"– Pedir favores"},{"k":"eg","t":"¿Me <b>prestas</b> cincuenta euros?"},{"k":"img","src":"img/gram/u51_teoria-pasas.png","alt":"«¿Me pasas el agua, por favor?»"},{"k":"p","t":"Unidad 52: Presente para expresar períodos de tiempo"}],"ex":[{"id":"gram:51.1","type":"cloze","lab":"51.1","title":"51.1","instr":"Hoy es domingo. Observe la agenda de Carlos para la semana que viene y complete sus planes con los verbos del recuadro.","img":"img/gram/u51_ej51-1_agenda.png","alt":"Agenda: lunes consulta Dr. Prieto; martes reunión con Sr. Chávez; miércoles ópera; jueves cenar con el director; viernes visita fábrica en Tarragona; sábado tenis con Rodolfo; domingo salir con Laura.","bank":["cenar","~ir","ir","jugar","salir","tener","visitar"],"items":[{"tpl":"El lunes ___.","blanks":1,"ans":["voy al médico"],"wide":true,"full":true,"example":true},{"tpl":"El martes ___.","blanks":1,"ans":["tengo una reunión"],"wide":true,"full":true},{"tpl":"El miércoles ___.","blanks":1,"ans":["voy a la ópera"],"wide":true,"full":true},{"tpl":"El jueves ___.","blanks":1,"ans":["ceno con el director"],"wide":true,"full":true},{"tpl":"El viernes ___.","blanks":1,"ans":["visito una fábrica en Tarragona"],"wide":true,"full":true},{"tpl":"El sábado ___.","blanks":1,"ans":["juego al tenis con Rodolfo"],"wide":true,"full":true},{"tpl":"El domingo ___.","blanks":1,"ans":["salgo con Laura"],"wide":true,"full":true}]},{"id":"gram:51.2","type":"cloze","lab":"51.2","title":"51.2","instr":"Complete las frases con los verbos del recuadro.","bank":["acabar","casarse","dar","empezar","hacer","ir","~irse","irse","regresar","salir","tener"],"items":[{"tpl":"(yo) ___ a Lisboa mañana.","blanks":1,"ans":["Me voy"],"mid":true,"example":true},{"tpl":"Jorge y Elisa ___ el sábado.","blanks":1,"ans":["se casan"],"mid":true},{"tpl":"Susana ___ una fiesta esta noche.","blanks":1,"ans":["da"],"mid":true},{"tpl":"(nosotros) ___ al teatro el domingo.","blanks":1,"ans":["Vamos"],"mid":true},{"tpl":"Daniel ___ hoy de vacaciones. El tren ___ a las 2.","blanks":2,"ans":["se va sale"],"mid":true},{"tpl":"La Feria de Turismo ___ el lunes.","blanks":1,"ans":["empieza"],"mid":true},{"tpl":"Mis padres ___ esta noche.","blanks":1,"ans":["regresan"],"mid":true},{"tpl":"La semana que viene (yo) ___ dos exámenes.","blanks":1,"ans":["tengo"],"mid":true},{"tpl":"¿Qué (vosotros) ___ este domingo?","blanks":1,"ans":["hacéis"],"mid":true},{"tpl":"Lucía ___ la carrera el año que viene.","blanks":1,"ans":["acaba"],"mid":true}]},{"id":"gram:51.3","type":"cloze","lab":"51.3","title":"51.3","instr":"Escriba las instrucciones completas utilizando las palabras del recuadro.","bank":["añadir","cortar","~pelar","poner","poner","triturar"],"items":[{"tpl":"Para hacer gazpacho, primero ___ los tomates","blanks":1,"ans":["pelas"],"mid":true,"example":true},{"tpl":"y ___ un poco de cebolla y pimiento.","blanks":1,"ans":["cortas"],"mid":true},{"tpl":"___ todo en un recipiente","blanks":1,"ans":["Pones"],"mid":true},{"tpl":"y ___ sal, aceite, ajo y pan mojado.","blanks":1,"ans":["añades"],"mid":true},{"tpl":"Lo ___ todo","blanks":1,"ans":["trituras"],"mid":true},{"tpl":"y lo ___ a enfriar en la nevera.","blanks":1,"ans":["pones"],"mid":true}]},{"id":"gram:51.4","type":"cloze","lab":"51.4","title":"51.4","instr":"Complete los diálogos con los verbos del recuadro.","bank":["ayudar","decir","dejar","dejar","hacer","ir","llevar","poner","~salir"],"items":[{"tpl":"—¿___ a cenar esta noche? —Buena idea.","blanks":1,"ans":["Salimos"],"mid":true,"example":true},{"tpl":"—¿Me ___ el coche? —Lo siento. Lo necesito.","blanks":1,"ans":["dejas"],"mid":true},{"tpl":"—¿Qué me ___, la falda o los pantalones? —Ponte la falda. Es más elegante.","blanks":1,"ans":["pongo"],"mid":true},{"tpl":"—¿Me ___ a preparar la cena? —Por supuesto. ¿Qué ___?","blanks":2,"ans":["ayudas hago"],"mid":true},{"tpl":"—¿___ al campo el domingo? —No puedo. Tengo que estudiar.","blanks":1,"ans":["Vamos"],"mid":true},{"tpl":"—¿Le ___ las bolsas? —Gracias, hijo.","blanks":1,"ans":["llevo"],"mid":true},{"tpl":"—¿Por qué no se lo ___ a tus padres? —Me da vergüenza.","blanks":1,"ans":["dices"],"mid":true},{"tpl":"—¿Me ___ un boli? —Sí, toma.","blanks":1,"ans":["dejas"],"mid":true}]}]},{"id":52,"name":"Presente para expresar períodos de tiempo","motto":"Vivo en México desde 1998","theory":[{"k":"img","src":"img/gram/u52_teoria-elsa.png","alt":"Elsa llegó a México en 1998. Elsa sigue viviendo en México. «Vivo en México desde 1998.»"},{"k":"p","t":"Se usa el presente de indicativo para referirse a acciones o situaciones que empezaron en el pasado y continúan en el presente."},{"k":"p","t":"– presente de indicativo + <i>desde</i> + fecha"},{"k":"img","src":"img/gram/u52_teoria-conozco.png","alt":"«Conozco a Elsa desde 2002.»"},{"k":"eg","t":"Julio conoció a Elsa (2002) → Julio sigue viendo a Elsa (ahora).<br>Trabajo en un banco <b>desde el año pasado</b>.<br>No voy al teatro <b>desde Navidad</b>.<br>Vivimos en este piso <b>desde enero</b>.<br>¿<b>Desde cuándo</b> conoces a Charo?"},{"k":"p","t":"– presente de indicativo + <i>desde hace</i> + período de tiempo"},{"k":"eg","t":"Keiko empezó a estudiar español en septiembre. Ahora, en diciembre, sigue estudiando español.<br>Keiko estudia español <b>desde hace tres meses</b>.<br>Rosana y Alberto viven en Argentina <b>desde hace dos años</b>.<br>No veo a Pili <b>desde hace mucho tiempo</b>."},{"k":"p","t":"– <i>hace</i> + período de tiempo + <i>que</i> + presente de indicativo"},{"k":"eg","t":"Clara miró el correo electrónico por última vez el lunes. Hoy, miércoles, sigue sin mirar el correo electrónico.<br><b>Hace un año que</b> estudio español.<br>¿Cuánto tiempo <b>hace que</b> trabajas aquí?<br><b>Hace mucho tiempo que</b> no veo a Luis."},{"k":"img","src":"img/gram/u52_teoria-clara.png","alt":"«Hace dos días que no miro el correo electrónico.»"}],"ex":[{"id":"gram:52.1","type":"cloze","lab":"52.1","title":"52.1","instr":"Complete los diálogos con la forma adecuada del verbo.","items":[{"tpl":"¿Cuánto tiempo hace que (vivir) ___ usted en Caracas?","blanks":1,"ans":["vive"],"mid":true,"example":true},{"tpl":"—¿Hablas español? —Sí, lo (hablar) ___ desde que era pequeño.","blanks":1,"ans":["hablo"],"mid":true},{"tpl":"—¿Hace mucho que (conocer) ___ a Ronaldo? —Sí, lo ___ desde 1995.","blanks":2,"ans":["conoces conozco"],"mid":true},{"tpl":"—¿Cuánto tiempo hace que (vivir) ___ ustedes en Quito? —Diez meses.","blanks":1,"ans":["viven"],"mid":true},{"tpl":"—¿Desde cuándo (ser) ___ amigos Jorge y tú? —___ amigos desde hace unos cinco años.","blanks":2,"ans":["Sois Somos"],"mid":true},{"tpl":"—Hace dos semanas que (trabajar) ___ en este bar. Me gusta.","blanks":1,"ans":["trabajo"],"mid":true},{"tpl":"—¿Desde cuándo no (ver) ___ a Petra? —No la ___ desde el verano pasado.","blanks":2,"ans":["ves veo"],"mid":true},{"tpl":"Lucas y Alba no (tener) ___ vacaciones desde hace cuatro años.","blanks":1,"ans":["tienen"],"mid":true},{"tpl":"¿Hace mucho que (conducir) ___ usted?","blanks":1,"ans":["conduce"],"mid":true},{"tpl":"¿Cuánto tiempo hace que (conocerse) ___ Elisa y Mario?","blanks":1,"ans":["se conocen"],"mid":true}]},{"id":"gram:52.2","type":"cloze","lab":"52.2","title":"52.2","instr":"Exprese la información dada en una frase comenzando con las palabras indicadas y el presente de indicativo en forma afirmativa o negativa.","items":[{"tpl":"Lupe ___","blanks":1,"ans":["conoce a Jaime desde 2001"],"ctx":"Lupe conoce a Jaime. Lo conoció en 2001.","wide":true,"full":true,"example":true},{"tpl":"Yasir ___","blanks":1,"ans":["estudia español desde hace seis meses"],"ctx":"Yasir estudia español. Empezó a estudiarlo hace seis meses.","wide":true,"full":true},{"tpl":"Hace ___","blanks":1,"ans":["un año que no vemos el mar"],"ctx":"La última vez que vimos el mar fue hace un año.","wide":true,"full":true},{"tpl":"Patricia ___","blanks":1,"ans":["no viene desde el día de su cumpleaños"],"ctx":"Patricia dejó de venir el día de su cumpleaños.","wide":true,"full":true},{"tpl":"Mis padres ___","blanks":1,"ans":["no me escriben desde Navidad"],"ctx":"La última vez que mis padres me escribieron fue en Navidad.","wide":true,"full":true},{"tpl":"Hace ___","blanks":1,"ans":["un mes que salgo con Rosario"],"ctx":"Salgo con Rosario. Empecé a salir con ella hace un mes.","wide":true,"full":true},{"tpl":"Hace ___","blanks":1,"ans":["dos semanas que no voy al cine"],"ctx":"La última vez que fui al cine fue hace dos semanas.","wide":true,"full":true},{"tpl":"(Yo) ___","blanks":1,"ans":["vivo en Guayaquil desde 1999"],"ctx":"Vivo en Guayaquil. Llegué allí en 1999.","wide":true,"full":true},{"tpl":"Hace ___","blanks":1,"ans":["una hora que estoy buscando mis gafas"],"ctx":"Estoy buscando mis gafas. Empecé a buscarlas hace una hora.","wide":true,"full":true},{"tpl":"Hace ___","blanks":1,"ans":["cinco años que mis padres no comen carne"],"ctx":"La última vez que mis padres comieron carne fue hace cinco años.","wide":true,"full":true},{"tpl":"(Yo) ___","blanks":1,"ans":["tengo móvil desde julio"],"ctx":"Tengo móvil. Lo compré en julio.","wide":true,"full":true},{"tpl":"José ___","blanks":1,"ans":["no ve a Marisa desde el verano"],"ctx":"La última vez que José vio a Marisa fue en verano.","wide":true,"full":true}]},{"id":"gram:52.3","type":"cloze","lab":"52.3","title":"52.3","instr":"Formule preguntas para las respuestas dadas.","items":[{"tpl":"___","blanks":1,"ans":["Cuánto tiempo hace que conoces a César"],"ctx":"Respuesta: Hace cinco años que conozco a César.","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Desde cuándo no fumas"],"ctx":"Respuesta: No fumo desde hace un mes.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánto tiempo hace que vivís en Mérida"],"ctx":"Respuesta: Hace dos años que vivimos en Mérida.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Desde cuándo salís juntos"],"ctx":"Respuesta: Asún y yo salimos juntos desde que teníamos dieciséis años.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Desde cuándo trabaja tu padre en esta empresa"],"ctx":"Respuesta: Mi padre trabaja en esta empresa desde que tenía veinte años.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánto tiempo hace que estudiáis español"],"ctx":"Respuesta: Hace dos años que estudiamos español.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Desde cuándo no vais al cine"],"ctx":"Respuesta: No vamos al cine desde las pasadas Navidades.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Cuánto tiempo hace que no comes un helado"],"ctx":"Respuesta: Hace muchísimo tiempo que no como un helado.","wide":true,"full":true}]}]},{"id":53,"name":"Verbos con me, te, se... (1)","motto":"me levanto","theory":[{"k":"h","t":"Verbos regulares con se: presente de indicativo"},{"k":"table","head":["","-ar (levantarse)","-er (atreverse)","-ir (aburrirse)"],"rows":[["(yo)","me levanto","me atrevo","me aburro"],["(tú)","te levantas","te atreves","te aburres"],["(usted)","se levanta","se atreve","se aburre"],["(él, ella)","se levanta","se atreve","se aburre"],["(nosotros, -as)","nos levantamos","nos atrevemos","nos aburrimos"],["(vosotros, -as)","os levantáis","os atrevéis","os aburrís"],["(ustedes)","se levantan","se atreven","se aburren"],["(ellos, -as)","se levantan","se atreven","se aburren"]]},{"k":"img","src":"img/gram/u53_teoria-ana.png","alt":"Ana se levanta a las siete."},{"k":"eg","t":"¿Te <b>atreves</b> a venir al lago?<br>En verano no nos <b>aburrimos</b> nunca."},{"k":"h","t":"Algunos verbos irregulares con se: presente de indicativo"},{"k":"p","t":"<b>e → ie:</b> <i>divertirse:</i> me divierto, te diviertes, se divierte, se divierte, nos divertimos, os divertís, se divierten, se divierten. Otros: arrepentirse, despertarse, defenderse."},{"k":"p","t":"<b>e → i:</b> <i>vestirse:</i> me visto, te vistes, se viste, se viste, nos vestimos, os vestís, se visten, se visten."},{"k":"p","t":"<b>o → ue:</b> <i>acostarse:</i> me acuesto, te acuestas, se acuesta, se acuesta, nos acostamos, os acostáis, se acuestan, se acuestan. Otros: dormirse."},{"k":"p","t":"<i>ponerse:</i> me <b>pongo</b>, te pones, se pone, se pone, nos ponemos, os ponéis, se ponen, se ponen."},{"k":"p","t":"Algunos verbos con <i>se</i> sirven para indicar que la acción o su efecto recae:"},{"k":"p","t":"– sobre la misma persona que la realiza."},{"k":"img","src":"img/gram/u53_teoria-luis.png","alt":"Luis se lava, se afeita y luego se viste."},{"k":"p","t":"– sobre una parte del cuerpo o de la ropa de esa persona."},{"k":"eg","t":"Siempre <b>me lavo</b> la cara con agua fría.<br>Los niños <b>se manchan</b> mucho la ropa.<br>Laura <b>se pinta</b> las uñas.<br>Luis <b>se plancha</b> sus camisas."},{"k":"p","t":"Unidad 39: Pronombres de complemento con el imperativo, el infinitivo y el gerundio"}],"ex":[{"id":"gram:53.1","type":"cloze","lab":"53.1","title":"53.1","instr":"Observe las ilustraciones y complete las frases con los verbos del recuadro.","img":"img/gram/u53_ej53-1_ilustraciones.png","alt":"Cinco viñetas: Arturo a las 8:00, Merche y Ernesto a las 8:30, Jaime en la ducha, Jaime vistiéndose y Merche y Ernesto a las 23:30.","bank":["acostarse","~despertarse","ducharse","levantarse","vestirse"],"items":[{"tpl":"Arturo ___ a las ocho.","blanks":1,"ans":["se despierta"],"mid":true,"example":true},{"tpl":"Merche y Ernesto ___ a las ocho y media.","blanks":1,"ans":["se levantan"],"mid":true},{"tpl":"Jaime ___ todas las mañanas.","blanks":1,"ans":["se ducha"],"mid":true},{"tpl":"Jaime ___ después de ducharse.","blanks":1,"ans":["se viste"],"mid":true},{"tpl":"Merche y Ernesto ___ a las once y media.","blanks":1,"ans":["se acuestan"],"mid":true}]},{"id":"gram:53.2","type":"cloze","lab":"53.2","title":"53.2","instr":"Complete las frases con los verbos del recuadro en forma afirmativa o negativa.","bank":["aburrirse","afeitarse","atreverse","cansarse","defenderse","divertirse","lavarse","~lavarse","mancharse","pintarse","ponerse","subirse"],"items":[{"tpl":"Javi ___ con un jabón especial.","blanks":1,"ans":["se lava"],"mid":true,"example":true},{"tpl":"(yo) ___ traje para ir a trabajar.","blanks":1,"ans":["Me pongo"],"mid":true},{"tpl":"Los gatos ___ a los árboles.","blanks":1,"ans":["se suben"],"mid":true},{"tpl":"José ___ todavía. No tiene barba.","blanks":1,"ans":["no se afeita"],"mid":true},{"tpl":"Susana ___ los ojos algunas veces.","blanks":1,"ans":["se pinta"],"mid":true},{"tpl":"Ángel y yo ___ mucho en las fiestas.","blanks":1,"ans":["nos divertimos"],"mid":true},{"tpl":"Pepe es muy sucio. ___ mucho la ropa.","blanks":1,"ans":["Se mancha"],"mid":true},{"tpl":"Alberto es muy tímido. ___ a hablar con Sarita.","blanks":1,"ans":["No se atreve"],"mid":true},{"tpl":"A Iván no le gusta el cine; ___ mucho cuando va.","blanks":1,"ans":["se aburre"],"mid":true},{"tpl":"Mi hermana y yo ___ el pelo todos los días.","blanks":1,"ans":["nos lavamos"],"mid":true},{"tpl":"Los canguros ___ con las patas cuando los atacan.","blanks":1,"ans":["se defienden"],"mid":true},{"tpl":"Mi abuela ___ cuando sube escaleras.","blanks":1,"ans":["se cansa"],"mid":true}]},{"id":"gram:53.3","type":"cloze","lab":"53.3","title":"53.3","instr":"Complete las preguntas y las respuestas con los verbos entre paréntesis.","items":[{"tpl":"—¿A qué hora (tú, levantarse) ___? —___ a las siete.","blanks":2,"ans":["te levantas Me levanto"],"wide":true,"example":true,"exv":["te levantas","Me levanto"]},{"tpl":"—¿(tú, ponerse) ___ pijama para dormir? —No, ___ camisón.","blanks":2,"ans":["Te pones me pongo"],"wide":true},{"tpl":"—¿(vosotros, bañarse) ___ en el mar en verano? —No, pero ___ en la piscina.","blanks":2,"ans":["Os bañáis nos bañamos"],"wide":true},{"tpl":"—¿Qué (vosotros, ponerse) ___ los domingos? —___ ropa normal: vaqueros y una camisa.","blanks":2,"ans":["os ponéis Nos ponemos"],"wide":true},{"tpl":"—¿Con qué (afeitarse) ___ usted? —___ con maquinilla eléctrica.","blanks":2,"ans":["se afeita Me afeito"],"wide":true},{"tpl":"—¿(usted, vestirse) ___ antes o después de desayunar? —___ después de desayunar.","blanks":2,"ans":["Se viste usted Me visto"],"wide":true},{"tpl":"—¿A qué hora (levantarse) ___ ustedes los domingos? —___ temprano, sobre las nueve.","blanks":2,"ans":["se levantan Nos levantamos"],"wide":true},{"tpl":"—¿Y a qué hora (ustedes, acostarse) ___? —___ también temprano, sobre las diez.","blanks":2,"ans":["se acuestan ustedes Nos acostamos"],"wide":true}]}]},{"id":54,"name":"Contraste entre verbos con y sin me, te, se...","motto":"me lavo / lavo","theory":[{"k":"h","t":"Compare"},{"k":"p","t":"<b>Verbos SIN me, te, se…</b> La acción o el efecto del verbo lo recibe <b>otra persona o cosa diferente</b> de quien realiza la acción."},{"k":"img","src":"img/gram/u54_teoria-lavo.png","alt":"«Lavo el pelo a las clientas.»"},{"k":"img","src":"img/gram/u54_teoria-acuesta-ninos.png","alt":"Gonzalo acuesta a los niños a las nueve."},{"k":"p","t":"<b>Verbos CON me, te, se…</b> La acción o el efecto del verbo lo recibe <b>la misma persona</b> que realiza la acción o una parte del cuerpo o ropa de esa persona."},{"k":"img","src":"img/gram/u54_teoria-melavo.png","alt":"«Me lavo el pelo todos los días.»"},{"k":"img","src":"img/gram/u54_teoria-se-acuesta.png","alt":"Gonzalo se acuesta a las once."},{"k":"h","t":"Algunos verbos tienen significado diferente con se"},{"k":"table","head":["Sin se","Con se"],"rows":[["<i>despedir</i> = echar de un trabajo","<i>despedirse</i> = decir adiós, irse de un trabajo voluntariamente"],["<i>dormir</i> = descansar","<i>dormirse</i> = quedarse dormido, aburrirse"],["<i>dejar</i> = prestar","<i>dejarse</i> = olvidarse"],["<i>encontrar</i> = hallar, descubrir","<i>encontrarse</i> = reunirse, sentirse"],["<i>ir</i> = dirigirse, asistir","<i>irse</i> = marcharse"],["<i>llamar</i> = telefonear","<i>llamarse</i> = tener un nombre"],["<i>parecer</i> = tener apariencia","<i>parecerse</i> = ser similar"]]},{"k":"img","src":"img/gram/u54_teoria-llama.png","alt":"«Te llama Jorge.»"},{"k":"eg","t":"Ana <b>duerme</b> siete horas al día.<br><b>Voy</b> a clase todos los días.<br>¿Me <b>dejas</b> este libro?<br>Emilio <b>parece</b> listo.<br>No <b>encontramos</b> las entradas."},{"k":"img","src":"img/gram/u54_teoria-melllamo.png","alt":"«¡Hola! Me llamo Juana.»"},{"k":"eg","t":"Ana <b>se duerme</b> en la ópera.<br>¡Adiós! <b>Me voy</b> a clase.<br>¡Espera! <b>Te dejas</b> un libro.<br><b>Se parece</b> a su madre.<br>Ayer <b>nos encontramos</b> con Pepa en el supermercado.<br>No <b>me encuentro</b> bien."}],"ex":[{"id":"gram:54.1","type":"cloze","lab":"54.1","title":"54.1","instr":"Observe las ilustraciones y complete las frases con los verbos del recuadro.","img":"img/gram/u54_ej54-1_ilustraciones.png","alt":"Ocho viñetas: Raúl lavando coches, un hombre comiendo espaguetis, María despertando a los niños, un padre bañando a los niños, alguien lavándose los dientes, Lucas con los cuadernos, dos personas en el mar y una mujer con ropa.","bank":["bañar","bañarse","despertar","despertarse","~lavar","lavarse","manchar","mancharse"],"items":[{"tpl":"Raúl ___ coches.","blanks":1,"ans":["lava"],"mid":true,"example":true},{"tpl":"Siempre ___ la camisa.","blanks":1,"ans":["me mancho"],"mid":true},{"tpl":"María ___ a los niños a las ocho.","blanks":1,"ans":["despierta"],"mid":true},{"tpl":"___ a los niños todas las noches.","blanks":1,"ans":["Baño"],"mid":true},{"tpl":"___ los dientes antes de acostarme.","blanks":1,"ans":["Me lavo"],"mid":true},{"tpl":"Lucas ___ mucho los cuadernos.","blanks":1,"ans":["mancha"],"mid":true},{"tpl":"En verano ___ en el mar.","blanks":1,"ans":["nos bañamos"],"mid":true},{"tpl":"Los domingos ___ tarde.","blanks":1,"ans":["me despierto"],"mid":true}]},{"id":"gram:54.2","type":"cloze","lab":"54.2","title":"54.2","instr":"Complete las frases con los verbos del recuadro.","bank":["~aburrirse","acostar","acostarse","divertir","lavar","lavarse","mirarse","vestir","vestirse"],"items":[{"tpl":"Felipe ___ viendo la tele.","blanks":1,"ans":["se aburre"],"mid":true,"example":true},{"tpl":"(yo) ___ las manos antes de las comidas.","blanks":1,"ans":["Me lavo"],"mid":true},{"tpl":"Clara ___ a los niños después de desayunar y después ___ ella.","blanks":2,"ans":["viste se viste"],"mid":true},{"tpl":"(yo) ___ muy tarde los sábados por la noche.","blanks":1,"ans":["Me acuesto"],"mid":true},{"tpl":"Alicia ___ las blusas a mano.","blanks":1,"ans":["lava"],"mid":true},{"tpl":"Juan ___ a sus hijos a las diez de la noche.","blanks":1,"ans":["acuesta"],"mid":true},{"tpl":"Miguel ___ mucho en el espejo.","blanks":1,"ans":["se mira"],"mid":true},{"tpl":"Los payasos ___ a los niños.","blanks":1,"ans":["divierten"],"mid":true}]},{"id":"gram:54.3","type":"pick","lab":"54.3","title":"54.3","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"[Llamo|Me llamo] Andrés.","ans":["Me llamo"],"example":true},{"tpl":"Tania siempre [despide|se despide] con un beso.","ans":["se despide"]},{"tpl":"¿A quién [pareces|te pareces], a tu padre o a tu madre?","ans":["te pareces"]},{"tpl":"[Vamos|Nos vamos] al cine dos veces al mes.","ans":["Vamos"]},{"tpl":"Rita [parece|se parece] muy amable.","ans":["parece"]},{"tpl":"¡Hasta luego! [Vamos|Nos vamos] al cine.","ans":["Nos vamos"]},{"tpl":"Anoche [encontré|me encontré] con Marina en la discoteca.","ans":["me encontré"]},{"tpl":"No [encuentro|me encuentro] mis gafas.","ans":["encuentro"]},{"tpl":"¿Cuántas horas [duermes|te duermes] al día?","ans":["duermes"]},{"tpl":"Siempre [dejo|me dejo] las llaves en casa.","ans":["me dejo"]}]}]},{"id":55,"name":"Verbos con me, te, le...","motto":"Me gusta la ópera","theory":[{"k":"h","t":"Gustar, encantar: presente de indicativo"},{"k":"table","head":["","","+ singular","+ plural"],"rows":[["(a mí)","me","<b>gusta</b><br><b>encanta</b>","<b>gustan</b><br><b>encantan</b>"],["(a ti)","te","",""],["(a usted)","le","",""],["(a él, a ella)","le","",""],["(a nosotros, -as)","nos","",""],["(a vosotros, -as)","os","",""],["(a ustedes)","les","",""],["(a ellos, -as)","les","",""]]},{"k":"img","src":"img/gram/u55_teoria-pasteles.png","alt":"A mi hijo le encantan los pasteles."},{"k":"eg","t":"¿Te <b>gusta</b> este traje?<br>¿Os <b>gustan</b> las naranjas?<br>Nos <b>gustan</b> la paella y el marisco.<br>A Ricardo no le <b>gusta</b> nada estudiar."},{"k":"note","h":"ATENCIÓN","rows":["<i>me, te… gusta</i> + infinitivo(s): Me gusta bailar. → A Concha le gusta cantar y bailar.<br><s>A Luis le gustan nadar y jugar al tenis.</s> → A Luis le gusta nadar y jugar al tenis.","<i>a</i> + nombre/nombre propio: A mis padres <b>les</b> gusta mucho viajar. → A Elsa no <b>le</b> gusta cocinar."]},{"k":"p","t":"Otros verbos con la misma construcción son: <i>apetecer, doler, importar, interesar, quedar</i> (con los significados de <i>tener</i> o <i>sentar</i>), <i>sentar</i>…"},{"k":"eg","t":"Te <b>sienta</b> muy bien ese vestido.<br>¿Me <b>sientan</b> bien estos pendientes?<br>¿Te <b>apetece</b> dar un paseo?<br>A Luisa le <b>duelen</b> las muelas.<br>Esta chaqueta te <b>queda</b> corta. (Es corta para ti.)<br>Solo nos <b>quedan</b> veinte euros. (Tenemos solo veinte euros.)<br>¿Te <b>duele</b> la cabeza?<br>Me <b>duelen</b> los pies.<br>No me <b>importa</b> madrugar.<br>¿Te <b>interesan</b> las matemáticas?"},{"k":"p","t":"Se usa <i>a mí, a ti…</i> para:"},{"k":"p","t":"– dar énfasis."},{"k":"eg","t":"<b>A nosotros</b> nos encanta la ópera."},{"k":"p","t":"– establecer un contraste."},{"k":"eg","t":"—Me encanta el fútbol. —<b>A mí</b> no me gusta nada.<br><b>A Pedro</b> le gusta Luisa, pero <b>a ella</b> no le gusta Pedro."},{"k":"p","t":"– dejar claro a quién nos referimos."},{"k":"eg","t":"¿Le gusta el pescado? → ¿Le gusta <b>a usted</b> el pescado? / ¿Le gusta <b>a él</b> el pescado? / ¿Le gusta <b>a ella</b> el pescado?"}],"ex":[{"id":"gram:55.1","type":"cloze","lab":"55.1","title":"55.1","instr":"Observe y complete los diálogos con gustar o encantar en afirmativa o negativa.","tbl":{"head":["","Nati","Gerardo","don Jesús"],"rows":[["tortilla","gusta","no gusta","gusta"],["queso","no gusta","no gusta","gusta"],["paella","encanta","encanta","no gusta"],["fabada","no gusta","gusta","encanta"],["calamares","gusta","no gusta","gusta"],["gambas","encanta","encanta","no gusta"]]},"items":[{"tpl":"DON JESÚS: —¿___ la tortilla, Gerardo? GERARDO: —No, ___.","blanks":2,"ans":["Te gusta no me gusta"],"wide":true,"example":true,"exv":["Te gusta","no me gusta"]},{"tpl":"GERARDO: A Nati ___ la tortilla.","blanks":1,"ans":["le gusta"],"wide":true},{"tpl":"NATI: —¿___ el queso, don Jesús? DON JESÚS: —Sí, ___.","blanks":2,"ans":["Le gusta me gusta"],"wide":true},{"tpl":"DON JESÚS: A Nati y a Gerardo ___ el queso.","blanks":1,"ans":["no les gusta"],"wide":true},{"tpl":"GERARDO: A Nati y a mí ___ la paella.","blanks":1,"ans":["nos encanta"],"wide":true},{"tpl":"NATI: —¿___ la fabada, don Jesús? DON JESÚS: —Sí, ___.","blanks":2,"ans":["Le gusta me encanta"],"wide":true},{"tpl":"DON JESÚS: —¿___ los calamares, Nati? NATI: —Sí, ___ mucho.","blanks":2,"ans":["Te gustan me gustan"],"wide":true},{"tpl":"GERARDO: A mí ___ los calamares.","blanks":1,"ans":["no me gustan"],"wide":true},{"tpl":"DON JESÚS: —¿___ las gambas a Nati y a ti, Gerardo? GERARDO: —Sí, ___.","blanks":2,"ans":["Os gustan nos encantan"],"wide":true},{"tpl":"NATI: —¿___ a usted las gambas, don Jesús? DON JESÚS: —No, ___.","blanks":2,"ans":["Le gustan no me gustan"],"wide":true}]},{"id":"gram:55.2","type":"cloze","lab":"55.2","title":"55.2","instr":"Complete las frases con gustar o encantar en afirmativa o negativa.","items":[{"tpl":"—¿___ (gustar) bailar, Sara? —Sí, ___ (encantar). ¿Y a ti? —___ (no gustar).","blanks":3,"ans":["Te gusta me encanta A mí no me gusta"],"wide":true,"example":true,"exv":["Te gusta","me encanta","A mí no me gusta"]},{"tpl":"—¿___ (gustar) leer a Rubén y a ti? —A mí ___ (encantar), pero ___ (no gustar) mucho.","blanks":3,"ans":["Os gusta me encanta a Rubén no le gusta"],"wide":true},{"tpl":"A Nacho ___ (gustar) Cristina, pero a Cristina ___ (no gustar) Nacho.","blanks":2,"ans":["le gusta no le gusta","le gusta a Cristina no le gusta"],"wide":true},{"tpl":"—¿___ (gustar) viajar, Manuel? —Sí, mucho. ¿Y a vosotras? —___ (encantar).","blanks":2,"ans":["Te gusta A nosotras nos encanta"],"wide":true},{"tpl":"—¿Qué ___ (gustar) a ustedes hacer en vacaciones? —___ (gustar) ir a la playa y descansar.","blanks":2,"ans":["les gusta Nos gusta"],"wide":true},{"tpl":"—___ (encantar) hacer deporte. ¿Y a ti, Norma? —___ (gustar) pasear y nadar.","blanks":2,"ans":["Me encanta Me gusta"],"wide":true}]},{"id":"gram:55.3","type":"cloze","lab":"55.3","title":"55.3","instr":"Complete las frases con los siguientes verbos: apetecer, doler, importar, interesar, quedar, sentar.","items":[{"tpl":"A mi abuela ___ mucho las piernas.","blanks":1,"ans":["le duelen"],"mid":true,"example":true},{"tpl":"—¿___ salir esta noche, Luis? —No, estoy cansado.","blanks":1,"ans":["Te apetece"],"mid":true},{"tpl":"A Elena y a ti ___ muy bien el color verde.","blanks":1,"ans":["os sienta"],"mid":true},{"tpl":"—¿(a vosotros) ___ mucho dinero? —A mí solo ___ un peso.","blanks":2,"ans":["Os queda me queda"],"mid":true},{"tpl":"Tengo que ir al dentista. ___ las muelas.","blanks":1,"ans":["Me duelen"],"mid":true},{"tpl":"A José y a mí no ___ madrugar.","blanks":1,"ans":["nos importa"],"mid":true},{"tpl":"—¿___ a ustedes comer algo? —No, gracias. No tenemos hambre.","blanks":1,"ans":["Les apetece"],"mid":true},{"tpl":"A Jordi y a Gonzalo ___ bien la corbata.","blanks":1,"ans":["les sienta"],"mid":true},{"tpl":"La informática es muy útil, pero a mí no ___ nada.","blanks":1,"ans":["me interesa"],"mid":true},{"tpl":"Lo siento, Gema, pero esos pantalones ___ grandes.","blanks":1,"ans":["te quedan"],"mid":true},{"tpl":"A ti ___ muy bien los sombreros, Amalia.","blanks":1,"ans":["te sientan"],"mid":true},{"tpl":"—¿___ a usted un gazpacho, Matías? —No, gracias. ___ el estómago.","blanks":2,"ans":["Le apetece Me duele"],"mid":true}]}]},{"id":56,"name":"Presente de estar + gerundio","motto":"Estoy viendo las noticias","theory":[{"k":"img","src":"img/gram/u56_teoria-ilustraciones.png","alt":"«¿Qué estás haciendo? – Estoy viendo las noticias.» · «¡Sshh! Isabel está tocando el piano.» · «Llévate el paraguas. Está lloviendo.»"},{"k":"p","t":"Presente de indicativo de <i>estar</i> + gerundio → Unidad 98: Gerundio"},{"k":"table","head":["","estar","gerundio"],"rows":[["(yo)","estoy","estudiando"],["(tú)","estás","estudiando"],["(usted)","está","estudiando"],["(él, ella)","está","bebiendo"],["(nosotros, -as)","estamos","bebiendo"],["(vosotros, -as)","estáis","bebiendo"],["(ustedes)","están","escribiendo"],["(ellos, -as)","están","escribiendo"]]},{"k":"p","t":"Se usa <i>estoy, estás…</i> + gerundio:"},{"k":"p","t":"– para hablar de acciones que están sucediendo en ese momento."},{"k":"eg","t":"—¿Qué <b>estás haciendo</b>? —<b>Estoy escuchando</b> un disco de salsa."},{"k":"p","t":"– para hablar de una situación temporal, no habitual, con expresiones de tiempo como <i>hoy, este mes, últimamente…</i>"},{"k":"eg","t":"Luisa normalmente trabaja en España, pero este mes <b>está trabajando</b> en Argentina.<br>Este año <b>estamos estudiando</b> chino.<br>Últimamente <b>estoy durmiendo</b> mucho."},{"k":"p","t":"– para enfatizar acciones o situaciones que se producen con frecuencia, con expresiones de tiempo como <i>todo el rato, siempre, a todas horas, todo el día…</i>"},{"k":"eg","t":"Antonio <b>está</b> siempre <b>pensando</b> en Belén.<br><b>Estáis</b> todo el día <b>jugando</b> y no estudiáis."},{"k":"note","h":"ATENCIÓN","rows":["Verbos con <i>se</i>: lavarse, vestirse… → Unidad 53: Verbos con me, te, se…","<i>me, te, se, nos, os, se</i> + presente de <i>estar</i> + gerundio: <b>Me estoy duchando.</b> <b>Se están vistiendo.</b>","presente de <i>estar</i> + gerundio + <i>-me, -te, -se, -nos, -os, -se</i>: <b>Estoy duchándome.</b> <b>Están vistiéndose.</b>"]},{"k":"img","src":"img/gram/u56_teoria-alfredo.png","alt":"«¿Está Alfredo? – Sí, pero se está duchando.»"},{"k":"p","t":"Unidad 57: Contraste entre presente de indicativo y estar + gerundio"}],"ex":[{"id":"gram:56.1","type":"cloze","lab":"56.1","title":"56.1","instr":"Observe las ilustraciones y complete los textos.","img":"img/gram/u56_ej56-1_ilustraciones.png","alt":"Ocho viñetas: una chica escribiendo una carta, dos hombres jugando a las cartas, una mujer mirando por la ventana con lluvia, un hombre leyendo el periódico mientras hablan por teléfono, una mujer al teléfono y una niña viendo la tele, una niña llorando, una pareja bailando y cuatro corredores de maratón.","bank":["bailar","correr","~escribir","estudiar","hacer","jugar","leer","llorar","llover","nevar","ver"],"items":[{"tpl":"___ una carta.","blanks":1,"ans":["Estoy escribiendo"],"mid":true,"example":true},{"tpl":"___ a las cartas.","blanks":1,"ans":["Estamos jugando"],"mid":true},{"tpl":"¿___? No, ___.","blanks":2,"ans":["Está lloviendo está nevando"],"mid":true},{"tpl":"—¿Qué ___, papá? —___ el periódico.","blanks":2,"ans":["está haciendo Está leyendo"],"mid":true},{"tpl":"¿___ María? —No, ___ la tele.","blanks":2,"ans":["Está estudiando está viendo"],"mid":true},{"tpl":"¿Por qué ___?","blanks":1,"ans":["están llorando"],"mid":true},{"tpl":"¿Con quién ___ Luisa?","blanks":1,"ans":["está bailando"],"mid":true},{"tpl":"___ un maratón.","blanks":1,"ans":["Estamos corriendo"],"mid":true}]},{"id":"gram:56.2","type":"cloze","lab":"56.2","title":"56.2","instr":"Complete las frases con los verbos siguientes.","bank":["acostarse","comer","discutir","dormir","escuchar","hablar","hacer","hacer","jugar","~pasar","pensar"],"items":[{"tpl":"—¿Dónde están tus padres? —___ unos días en Potosí.","blanks":1,"ans":["Están pasando"],"mid":true,"example":true,"exv":["Están pasando"]},{"tpl":"—¿Dónde están los niños? —___ en el parque.","blanks":1,"ans":["Están jugando"],"mid":true},{"tpl":"José y su hermano se quieren mucho, pero ___ siempre ___.","blanks":2,"ans":["están discutiendo"],"mid":true},{"tpl":"—¿Con quién ___ Teresa? —Con una vecina.","blanks":1,"ans":["está hablando"],"mid":true},{"tpl":"Esta semana ___ mucho calor.","blanks":1,"ans":["está haciendo"],"mid":true},{"tpl":"¡Qué obsesión! Laura y tú ___ siempre ___ en salir.","blanks":2,"ans":["estáis pensando"],"mid":true},{"tpl":"Ten cuidado, Arturo. Últimamente ___ muy poco.","blanks":1,"ans":["estás durmiendo"],"mid":true},{"tpl":"—¿Por qué no come Cristina hoy con nosotros? —___ en casa de una amiga.","blanks":1,"ans":["Está comiendo"],"mid":true},{"tpl":"—¿Dónde está Hans? —___ un curso de español en Perú.","blanks":1,"ans":["Está haciendo"],"mid":true},{"tpl":"Esta semana estamos de fiesta y ___ muy tarde.","blanks":1,"ans":["nos estamos acostando"],"mid":true},{"tpl":"—¿Qué ___? —Música cubana.","blanks":1,"ans":["estás escuchando"],"mid":true}]},{"id":"gram:56.3","type":"cloze","lab":"56.3","title":"56.3","instr":"¿Qué está pasando en este momento? Escriba frases ciertas.","items":[{"tpl":"___","blanks":1,"ans":["Estoy estudiando español"],"ctx":"(estudiar español)","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["No me estoy duchando"],"ctx":"(ducharse)","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Estoy escuchando música","No estoy escuchando música"],"ctx":"(escuchar música)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Está lloviendo","No está lloviendo"],"ctx":"(llover)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Estoy bebiendo un zumo","No estoy bebiendo un zumo"],"ctx":"(beber un zumo)","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Estoy escribiendo","No estoy escribiendo"],"ctx":"(escribir)","wide":true,"full":true}]}]},{"id":57,"name":"Contraste entre presente de indicativo y estar + gerundio","motto":"hago / estoy haciendo","theory":[{"k":"h","t":"Compare"},{"k":"p","t":"<b>PRESENTE DE INDICATIVO</b> – Se usa para hablar de acciones habituales."},{"k":"img","src":"img/gram/u57_teoria-gimnasia.png","alt":"«Hago gimnasia todas las mañanas.»"},{"k":"eg","t":"<b>Hago</b> gimnasia todas las mañanas.<br>En mi casa <b>comemos</b> a las dos.<br>Olga <b>toca</b> la guitarra en un grupo."},{"k":"p","t":"– Se usa para hablar de verdades generales o universales."},{"k":"eg","t":"En Galicia <b>llueve</b> mucho.<br>En Acapulco <b>hace</b> calor en verano.<br><b>Trabajo</b> en Santiago."},{"k":"p","t":"<b>ESTAR + GERUNDIO</b> – Se usa para hablar de acciones breves que se están desarrollando en el momento de hablar."},{"k":"img","src":"img/gram/u57_teoria-rompecabezas.png","alt":"«Estoy haciendo un rompecabezas.»"},{"k":"eg","t":"<b>Estoy haciendo</b> un rompecabezas.<br>¿Qué <b>estáis comiendo</b>?<br><b>Está tocando</b> una canción mexicana.<br>No salgas ahora. <b>Está lloviendo</b> mucho."},{"k":"p","t":"– Se usa para hablar de acciones temporales, no habituales, con expresiones como <i>esta semana, este mes, últimamente…</i>"},{"k":"eg","t":"Este verano <b>está haciendo</b> frío.<br>Esta semana <b>estoy trabajando</b> en Iquique."},{"k":"note","h":"ATENCIÓN","rows":["No se suele usar <i>estar</i> + gerundio:","– con los verbos <i>ir</i> y <i>venir</i>: <b>Vamos</b> a Viña todos los años. · Las cigüeñas <b>vienen</b> a España en primavera. · —¿Adónde <b>vais</b>? —<b>Vamos</b> a la playa. · —Es muy tarde. ¿De dónde <b>vienes</b>? —<b>Vengo</b> de una fiesta.","– con los verbos <i>conocer, comprender, entender, querer, necesitar, amar, preferir, odiar, parecer, tener, llevar</i>: Alicia <b>no lleva</b> nunca vaqueros. · Rodrigo <b>tiene</b> dos hermanos. · ¿Qué <b>lleva</b> Jesús en la cabeza? · ¿<b>Tienes</b> dinero? <b>Necesito</b> 50 euros.","– con los verbos <i>ver</i> y <i>oír</i> (cuando no significan <i>mirar</i> o <i>escuchar</i>): Félix <b>no oye</b> nada por el oído izquierdo. · —¿<b>Oyes</b> algo? —Nada. Hablan muy bajo.","PERO: <b>Estoy oyendo</b> la radio. (escuchando)"]},{"k":"p","t":"Algunas veces se puede usar el presente de indicativo para hablar de acciones que se están realizando en el momento de hablar."},{"k":"eg","t":"—¿Qué <b>haces</b>? —Nada. <b>Leo</b> un rato.<br>—¿Qué <b>estás haciendo</b>? —<b>Estoy leyendo</b> el periódico."}],"ex":[{"id":"gram:57.1","type":"cloze","lab":"57.1","title":"57.1","instr":"Complete las frases con algunos de los siguientes verbos: dar, estudiar, jugar, tocar, ver.","img":"img/gram/u57_ej57-1_ilustraciones.png","alt":"Tres viñetas: Jorge y Santi (músicos) con una batería, una guitarra y un tablero de ajedrez; Daniela (profesora) viendo la tele; Cristina (estudiante) jugando al tenis.","items":[{"tpl":"Jorge y Santi son músicos. Tocan en una orquesta. Jorge ___ la batería y Santi ___ la guitarra. Ahora no ___. ___ al ajedrez.","blanks":4,"ans":["toca toca están tocando Están jugando"],"mid":true},{"tpl":"Daniela es profesora. ___ clases de Matemáticas. Ahora no ___ clase. ___ la tele en casa.","blanks":3,"ans":["Da está dando Está viendo"],"mid":true},{"tpl":"Cristina es estudiante. ___ Medicina. Ahora no ___. ___ al tenis con una amiga.","blanks":3,"ans":["Estudia está estudiando Está jugando"],"mid":true}]},{"id":"gram:57.2","type":"cloze","lab":"57.2","title":"57.2","instr":"Complete las frases con el verbo en presente de indicativo o estar + gerundio.","items":[{"tpl":"En el desierto de Atacama (no llover) ___ nunca.","blanks":1,"ans":["no llueve"],"wide":true,"example":true},{"tpl":"Este invierno (no hacer) ___ mucho frío.","blanks":1,"ans":["no está haciendo"],"wide":true},{"tpl":"¿Me dejas un paraguas? (Llover) ___ mucho.","blanks":1,"ans":["Está lloviendo"],"wide":true},{"tpl":"—¿Está Rosa? —Sí, pero (dormir) ___.","blanks":1,"ans":["está durmiendo"],"wide":true},{"tpl":"Los vegetarianos (no comer) ___ carne.","blanks":1,"ans":["no comen"],"wide":true},{"tpl":"—¿(tú, tocar) ___ algún instrumento? —Sí, (tocar) ___ el violín.","blanks":2,"ans":["Tocas toco"],"wide":true},{"tpl":"—¿Qué (cantar) ___ Carlos? —Un tango.","blanks":1,"ans":["está cantando"],"wide":true},{"tpl":"Algunos bebés (llorar) ___ mucho.","blanks":1,"ans":["lloran"],"wide":true}]},{"id":"gram:57.3","type":"pick","lab":"57.3","title":"57.3","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"¿Adónde [vais|estáis yendo]?","ans":["vais"],"example":true},{"tpl":"¿[Oyes|Estás oyendo] algo?","ans":["Oyes"]},{"tpl":"¿Qué [quieres|estás queriendo]?","ans":["quieres"]},{"tpl":"No [entiendo|estoy entendiendo]. ¿Puedes repetir?","ans":["entiendo"]},{"tpl":"—¿Dónde están tus padres? —[Viajan|Están viajando] por América.","ans":["Están viajando"]},{"tpl":"Esta semana no [estudio|estoy estudiando] mucho.","ans":["estoy estudiando"]},{"tpl":"Está muy oscuro. No [veo|estoy viendo] nada.","ans":["veo"]}]},{"id":"gram:57.4","type":"cloze","lab":"57.4","title":"57.4","instr":"Complete las frases con el verbo en presente de indicativo o estar + gerundio.","items":[{"tpl":"—¿Adónde (ir) ___? —(Ir) ___ a casa.","blanks":2,"ans":["vas Voy"],"wide":true,"example":true,"exv":["vas","Voy"]},{"tpl":"¿(tú, conocer) ___ a esa chica?","blanks":1,"ans":["Conoces"],"wide":true},{"tpl":"¿Qué (tú, tener) ___ en la mano?","blanks":1,"ans":["tienes"],"wide":true},{"tpl":"—¿Qué (tú, ver) ___? —Un concurso.","blanks":1,"ans":["estás viendo"],"wide":true},{"tpl":"No (oír) ___ nada. Tengo que ir al médico.","blanks":1,"ans":["oigo"],"wide":true},{"tpl":"—Mira. Lola (llevar) ___ un vestido de lunares. —Sí, (parecer) ___ una bailaora.","blanks":2,"ans":["lleva parece"],"wide":true},{"tpl":"—¿Qué (querer) ___ ustedes? —(Necesitar) ___ cucharas.","blanks":2,"ans":["quieren Necesitamos"],"wide":true},{"tpl":"—¿De dónde (tú, venir) ___? (Tener) ___ mala cara. —Sí, (venir) ___ del dentista.","blanks":3,"ans":["vienes Tenéis venimos"],"wide":true}]}]},{"id":58,"name":"Pretérito indefinido: verbos regulares","motto":"trabajé, comí, viví...","theory":[{"k":"img","src":"img/gram/u58_teoria-saliste.png","alt":"«¿Saliste anoche? – No, me quedé en casa. Vi un poco la tele.»"},{"k":"img","src":"img/gram/u58_teoria-cervantes.png","alt":"Cervantes nació en Alcalá de Henares en 1547."},{"k":"p","t":"<i>Saliste, me quedé, vi</i> y <i>nació</i> son formas del pretérito indefinido."},{"k":"h","t":"Formación del pretérito indefinido: verbos regulares"},{"k":"table","head":["","-ar (trabajar)","-er (comer)","-ir (vivir)"],"rows":[["(yo)","trabaj-é","com-í","viv-í"],["(tú)","trabaj-aste","com-iste","viv-iste"],["(usted)","trabaj-ó","com-ió","viv-ió"],["(él, ella)","trabaj-ó","com-ió","viv-ió"],["(nosotros, -as)","trabaj-amos","com-imos","viv-imos"],["(vosotros, -as)","trabaj-asteis","com-isteis","viv-isteis"],["(ustedes)","trabaj-aron","com-ieron","viv-ieron"],["(ellos, -as)","trabaj-aron","com-ieron","viv-ieron"]]},{"k":"note","h":"ATENCIÓN","rows":["<i>d-ar</i> → d-i, d-iste, d-io, d-io, d-imos, d-isteis, d-ieron, d-ieron","verbos en <i>-car</i>: sacar → (yo) <b>saqué</b>, (tú) sacaste, (él, ella) sacó…","verbos en <i>-zar</i>: empezar → (yo) <b>empecé</b>, (tú) empezaste, (él, ella) empezó…","verbos en <i>-gar</i>: llegar → (yo) <b>llegué</b>, (tú) llegaste, (él, ella) llegó…"]},{"k":"p","t":"Se usa el pretérito indefinido para hablar de acciones o situaciones pasadas. Nos dice qué sucedió en un momento concreto del pasado ya terminado, <i>anoche, ayer, el jueves (pasado), la semana pasada, hace dos meses, en 1995…</i>"},{"k":"eg","t":"Anoche no <b>salimos</b>. <b>Nos quedamos</b> en casa a descansar.<br>Mis padres <b>vivieron</b> en Quito desde 1990 hasta 2001.<br>La Primera Guerra Mundial <b>empezó</b> en 1914 y <b>acabó</b> en 1918.<br>De joven, <b>viví</b> cuatro años en México."},{"k":"p","t":"– Se puede usar en una secuencia de acciones, todas acabadas."},{"k":"eg","t":"Cuando <b>acabó</b> la película, <b>encendieron</b> las luces.<br>El profesor <b>entró</b> en el aula, <b>abrió</b> el libro y <b>empezó</b> a explicar."},{"k":"p","t":"– Se usa mucho en narraciones y biografías."},{"k":"eg","t":"Miguel Ángel Asturias <b>nació</b> en Ciudad de Guatemala en 1899. <b>Estudió</b> Derecho en su país y pronto <b>se interesó</b> por las antiguas religiones y culturas de América Central. <b>Publicó</b> su primer libro, Leyendas de Guatemala, en Madrid, en 1930. <b>Recibió</b> el Premio Nobel de Literatura en 1967."}],"ex":[{"id":"gram:58.1","type":"cloze","lab":"58.1","title":"58.1","instr":"Complete las frases con el pretérito indefinido de los verbos entre paréntesis.","items":[{"tpl":"Pablo y Mar (casarse) ___ hace tres meses.","blanks":1,"ans":["se casaron"],"wide":true,"example":true},{"tpl":"El domingo por la mañana (yo, no salir) ___. (Levantarse) ___ tarde, (lavarse) ___ el pelo, (desayunar) ___ y (escribir) ___ algunas cartas.","blanks":5,"ans":["no salí Me levanté me lavé desayuné escribí"],"wide":true},{"tpl":"El año pasado (nosotros, ver) ___ a Mercedes Sosa en directo.","blanks":1,"ans":["vimos"],"wide":true},{"tpl":"Yolanda y Arturo (vivir) ___ en Argentina hasta 1998.","blanks":1,"ans":["vivieron"],"wide":true},{"tpl":"—¿Qué os (pasar) ___ ayer? —(No sonar) ___ el despertador y (llegar) ___ tarde.","blanks":3,"ans":["pasó No sonó llegamos"],"wide":true},{"tpl":"—¿Cuándo (conocerse) ___ Gala y tú? —(Conocerse) ___ en 1999, durante un viaje a Santo Domingo.","blanks":2,"ans":["os conocisteis Nos conocimos"],"wide":true},{"tpl":"—¿A qué hora (acabar) ___ la fiesta anoche? —No lo sé. Yo (acostarse) ___ a las doce.","blanks":2,"ans":["acabó me acosté"],"wide":true},{"tpl":"¿Con quién (tú, salir) ___ el domingo?","blanks":1,"ans":["saliste"],"wide":true}]},{"id":"gram:58.2","type":"cloze","lab":"58.2","title":"58.2","instr":"Complete las siguientes preguntas.","items":[{"tpl":"Ayer conocí a Donato. ¿A quién ___ ayer?","blanks":1,"ans":["conociste"],"wide":true,"example":true},{"tpl":"El domingo dimos un paseo por el Malecón. ¿Por dónde ___ un paseo el domingo?","blanks":1,"ans":["disteis"],"wide":true},{"tpl":"De joven, viví seis meses en Chile. ¿Dónde ___ de joven?","blanks":1,"ans":["viviste"],"wide":true},{"tpl":"El año pasado trabajé en una academia. ¿Dónde ___ el año pasado?","blanks":1,"ans":["trabajaste"],"wide":true},{"tpl":"Anoche hablé con Alicia. ¿Con quién ___ anoche?","blanks":1,"ans":["hablaste"],"wide":true},{"tpl":"La semana pasada comimos en un mesón. ¿Dónde ___ la semana pasada?","blanks":1,"ans":["comisteis"],"wide":true},{"tpl":"El sábado pasamos el día con Araceli. ¿Con quién ___ el día el sábado?","blanks":1,"ans":["pasasteis"],"wide":true},{"tpl":"Di una fiesta hace una semana. ¿Cuándo ___ una fiesta?","blanks":1,"ans":["diste"],"wide":true}]},{"id":"gram:58.3","type":"cloze","lab":"58.3","title":"58.3","instr":"Complete esta historia con el pretérito indefinido de los verbos entre paréntesis.","items":[{"tpl":"Una noche me (despertar) ___ un ruido.","blanks":1,"ans":["despertó"],"mid":true,"perBlank":true,"example":true},{"tpl":"(Levantarse) ___, (encender) ___ la luz y (acercarse) ___ a la ventana.","blanks":3,"ans":["Me levanté encendí me acerqué"],"mid":true,"perBlank":true},{"tpl":"En la calle (ver) ___ una figura vestida de blanco.","blanks":1,"ans":["vi"],"mid":true,"perBlank":true},{"tpl":"Cuando la figura me (ver) ___, me (llamar) ___ con la mano.","blanks":2,"ans":["vio llamó"],"mid":true,"perBlank":true},{"tpl":"(Dar) ___ un grito y la figura (alejarse) ___.","blanks":2,"ans":["Di se alejó"],"mid":true,"perBlank":true},{"tpl":"(Regresar) ___ a la cama, (apagar) ___ la luz y (acostarse) ___.","blanks":3,"ans":["Regresé apagué me acosté"],"mid":true,"perBlank":true},{"tpl":"Nunca más (volver) ___ a verla.","blanks":1,"ans":["volví"],"mid":true,"perBlank":true}]},{"id":"gram:58.4","type":"cloze","lab":"58.4","title":"58.4","instr":"Utilice los verbos del recuadro para completar la biografía de Isabel Allende.","bank":["casarse","escribir","nacer","~nacer","refugiarse","regresar","trasladarse","vivir"],"items":[{"tpl":"Isabel Allende es chilena, pero ___ en Lima, Perú, el 2 de agosto de 1942.","blanks":1,"ans":["nació"],"mid":true,"example":true},{"tpl":"En 1945 su madre ___ a Chile con Isabel y sus hermanos.","blanks":1,"ans":["regresó"],"mid":true},{"tpl":"En 1962 ___ por primera vez","blanks":1,"ans":["se casó"],"mid":true},{"tpl":"y al año siguiente ___ su hija Paula.","blanks":1,"ans":["nació"],"mid":true},{"tpl":"En 1975, dos años después del golpe militar en Chile, ___ en Caracas, Venezuela.","blanks":1,"ans":["se refugió"],"mid":true},{"tpl":"Aquí ___ trece años","blanks":1,"ans":["vivió"],"mid":true},{"tpl":"y ___ su gran éxito, La casa de los espíritus.","blanks":1,"ans":["escribió"],"mid":true},{"tpl":"En 1987 ___ a los Estados Unidos, donde reside actualmente.","blanks":1,"ans":["se trasladó"],"mid":true}]}]},{"id":59,"name":"Pretérito indefinido: verbos irregulares","motto":"durmió, leyó, hizo...","theory":[{"k":"h","t":"Formación del pretérito indefinido: verbos irregulares"},{"k":"p","t":"Segunda persona de cortesía (<i>usted, ustedes</i>) y tercera persona (<i>él, ella, ellos, ellas</i>) irregulares."},{"k":"p","t":"– Verbos en <i>e</i> + consonante(s) + <i>ir</i>"},{"k":"eg","t":"<i>ped-ir:</i> ped-í, ped-iste, <b>pid-ió</b>, <b>pid-ió</b>, ped-imos, ped-isteis, <b>pid-ieron</b>, <b>pid-ieron</b>"},{"k":"p","t":"Otros: mentir, preferir, seguir, sentir, divertirse."},{"k":"eg","t":"La semana pasada le <b>pedí</b> dinero a Nuria.<br>Pepi y Lolo <b>se divirtieron</b> mucho en mi fiesta."},{"k":"p","t":"– Verbos en <i>o</i> + consonante(s) + <i>ir</i>"},{"k":"eg","t":"<i>dorm-ir:</i> dorm-í, dorm-iste, <b>durm-ió</b>, <b>durm-ió</b>, dorm-imos, dorm-isteis, <b>durm-ieron</b>, <b>durm-ieron</b>"},{"k":"p","t":"Otros: morir."},{"k":"eg","t":"Los niños <b>durmieron</b> diez horas anoche.<br>La madre de Clara <b>murió</b> hace dos meses."},{"k":"p","t":"– Verbos en vocal + <i>er/ir</i>"},{"k":"eg","t":"<i>le-er:</i> le-í, le-íste, le-<b>yó</b>, le-<b>yó</b>, le-ímos, le-ísteis, le-<b>yeron</b>, le-<b>yeron</b>"},{"k":"p","t":"Otros: caer, construir, creer, destruir, huir, incluir, oír."},{"k":"eg","t":"El verano pasado una tormenta <b>destruyó</b> la iglesia del pueblo.<br>Los gatos <b>huyeron</b> cuando vieron al perro."},{"k":"p","t":"<b>Todas las personas irregulares (terminaciones irregulares)</b>"},{"k":"img","src":"img/gram/u59_teoria-hiciste.png","alt":"«¿Qué hiciste el domingo? – Estuve en casa con unos amigos.»"},{"k":"table","head":["Infinitivo","Raíz"],"rows":[["decir","dij-"],["estar","estuv-"],["haber","hub-"],["hacer","hic- / hiz-"],["poder","pud-"],["poner","pus-"],["querer","quis-"],["saber","sup-"],["tener","tuv-"],["traer","traj-"],["venir","vin-"]]},{"k":"p","t":"Terminaciones: <b>-e, -iste, -o, -o, -imos, -isteis, -ieron*, -ieron*</b>"},{"k":"p","t":"*PERO: <i>decir</i> → dijeron; <i>traer</i> → trajeron"},{"k":"eg","t":"El año pasado <b>hice</b> varios viajes a América del Sur.<br>El domingo <b>hubo</b> una fiesta en casa de Emilia. Pato no <b>quiso</b> venir.<br>Los abuelos de Beatriz <b>tuvieron</b> diez hijos."},{"k":"p","t":"– verbos en <i>-ducir</i> → <i>-uj-</i>"},{"k":"eg","t":"<i>conducir:</i> conduje, condujiste, condujo, condujo, condujimos, condujisteis, condujeron, condujeron"},{"k":"p","t":"Otros: producir, traducir."},{"k":"eg","t":"Hace unos años <b>traduje</b> un libro sobre Goya."},{"k":"p","t":"– <i>ir / ser</i>: fui, fuiste, fue, fue, fuimos, fuisteis, fueron, fueron"},{"k":"img","src":"img/gram/u59_teoria-fuisteis.png","alt":"«¿Adónde fuisteis el verano pasado? – A Cuba. Fueron unas vacaciones fantásticas.»"},{"k":"eg","t":"Alicia <b>fue</b> (ser) directora de un banco durante cuatro años.<br>Antonio <b>fue</b> (ir) a Puerto Rico en 2001.<br>La civilización maya <b>fue</b> (ser) muy pacífica."},{"k":"p","t":"Unidad 58: Pretérito indefinido: verbos regulares"}],"ex":[{"id":"gram:59.1","type":"cloze","lab":"59.1","title":"59.1","instr":"Complete las frases con el pretérito indefinido de los verbos entre paréntesis.","items":[{"tpl":"Alba (venir) ___ a España en 2001.","blanks":1,"ans":["vino"],"wide":true,"example":true},{"tpl":"Unos amigos míos (tener) ___ un accidente el fin de semana pasado.","blanks":1,"ans":["tuvieron"],"wide":true},{"tpl":"—¿Por qué (no venir) ___ Lucía y Paloma a la fiesta? —Porque (no querer) ___.","blanks":2,"ans":["no vinieron no quisieron"],"wide":true},{"tpl":"¿Cuántos hijos (tener) ___ la abuela de Tere?","blanks":1,"ans":["tuvo"],"wide":true},{"tpl":"Esta casa la (construir) ___ el padre de Óscar hace cincuenta años.","blanks":1,"ans":["construyó"],"wide":true},{"tpl":"—¿Qué (ustedes, hacer) ___ el domingo? —Nada especial. (Estar) ___ en casa viendo la tele. Enrique (no querer) ___ salir.","blanks":3,"ans":["hicieron Estuvimos no quiso"],"wide":true},{"tpl":"Anoche (nosotros, tener) ___ que dormir en casa de Alfredo. No (poder) ___ entrar en la nuestra.","blanks":2,"ans":["tuvimos pudimos"],"wide":true},{"tpl":"¿Cuándo (morir) ___ los abuelos de Miriam?","blanks":1,"ans":["murieron"],"wide":true},{"tpl":"Laura (caerse) ___ la semana pasada y (romperse) ___ un brazo.","blanks":2,"ans":["se cayó se rompió"],"wide":true},{"tpl":"—¿Cuándo (saber) ___ usted que estaba enferma? —Cuando me lo (decir) ___ el médico.","blanks":2,"ans":["supo dijo"],"wide":true},{"tpl":"—¿Qué (pasar) ___ anoche? —(Haber) ___ un incendio en el bloque de Ángel.","blanks":2,"ans":["pasó Hubo"],"wide":true},{"tpl":"¿Cuándo (usted, conducir) ___ un coche por primera vez?","blanks":1,"ans":["condujo"],"wide":true}]},{"id":"gram:59.2","type":"cloze","lab":"59.2","title":"59.2","instr":"Utilice los siguientes verbos para completar estas frases sobre la historia de América Latina.","bank":["construir","~independizarse","llegar","morir","producirse","ser","ser","ser","traer"],"items":[{"tpl":"Cuba ___ en 1898.","blanks":1,"ans":["se independizó"],"mid":true,"example":true},{"tpl":"Bolívar ___ en 1830.","blanks":1,"ans":["murió"],"mid":true},{"tpl":"Los primeros esclavos africanos ___ a América en el siglo XVI.","blanks":1,"ans":["llegaron"],"mid":true},{"tpl":"Los incas ___ Machu Picchu en el siglo XIII.","blanks":1,"ans":["construyeron"],"mid":true},{"tpl":"Los españoles ___ el tomate y la patata de América.","blanks":1,"ans":["trajeron"],"mid":true},{"tpl":"Hernán Cortés ___ gobernador de Nueva España o México.","blanks":1,"ans":["fue"],"mid":true},{"tpl":"La decadencia de la cultura maya ___ a mediados del siglo XV.","blanks":1,"ans":["se produjo"],"mid":true},{"tpl":"Túpac Amaru I ___ el último emperador inca.","blanks":1,"ans":["fue"],"mid":true},{"tpl":"Los mayas ___ grandes constructores.","blanks":1,"ans":["fueron"],"mid":true}]},{"id":"gram:59.3","type":"cloze","lab":"59.3","title":"59.3","instr":"Complete las conversaciones con los verbos correspondientes: alquilar, gustar, hacer, ir, ir, recorrer, ser.","bank":["alquilar","gustar","~hacer","ir","ir","recorrer","ser"],"items":[{"tpl":"—¿Qué hiciste el verano pasado? —___ a Chile. —¿Con quién ___? —Con un grupo de amigos. ___ un coche y ___ el sur hasta Tierra del Fuego. —¿Os ___? —Sí, ___ un viaje interesantísimo.","blanks":6,"ans":["Fui fuiste Alquilamos recorrimos gustó fue"],"mid":true},{"tpl":"Verbos: bailar, divertirse, ir.  —¿Qué tal el fin de semana? —___ a un club de salsa con Armando. ___ como locos toda la noche. Armando ___ muchísimo.","blanks":3,"ans":["Fui Bailamos se divirtió"],"mid":true}]}]},{"id":60,"name":"Pretérito perfecto de indicativo (1)","motto":"he trabajado","theory":[{"k":"img","src":"img/gram/u60_teoria-dia.png","alt":"«Hoy he tenido un día agotador. Me he levantado temprano y he dado cuatro clases por la mañana. Por la tarde he hecho la compra…»"},{"k":"p","t":"<i>He tenido, me he levantado, he dado</i> y <i>he hecho</i> son formas del pretérito perfecto de indicativo."},{"k":"h","t":"Formación: presente de indicativo de haber + participio del verbo correspondiente"},{"k":"table","head":["","haber","participio"],"rows":[["(yo)","he","trabajado"],["(tú)","has","trabajado"],["(usted)","ha","trabajado"],["(él, ella)","ha","comido"],["(nosotros, -as)","hemos","comido"],["(vosotros, -as)","habéis","comido"],["(ustedes)","han","vivido"],["(ellos, -as)","han","vivido"]]},{"k":"note","h":"ATENCIÓN","rows":["La forma del participio no cambia nunca. —Hoy <b>he comido</b> paella. —Pues nosotras <b>hemos comido</b> pescado.","<i>Haber</i> y el participio van siempre juntos. <s>He me levantado tarde.</s> → Me <b>he levantado</b> tarde."]},{"k":"p","t":"Unidad 99: Participio"},{"k":"p","t":"Se usa el pretérito perfecto de indicativo para hablar de acciones o situaciones ocurridas en un período de tiempo que llega hasta el presente. Informa de lo que ha ocurrido <i>hoy, este año / mes, esta mañana / tarde / semana, últimamente</i>."},{"k":"eg","t":"(1) <b>Hoy me he levantado</b> tarde.<br>(2) Lara <b>ha salido</b> todas las noches <b>esta semana</b>.<br>(3) <b>Este mes hemos ido</b> al cine tres veces.<br>(4) <b>Este año no ha hecho</b> mucho frío."},{"k":"p","t":"– Se puede usar para hablar de acciones o situaciones pasadas inmediatas, con expresiones como <i>hace poco, hace un momento, hace un rato</i>."},{"k":"eg","t":"<b>He estado</b> con Carlos hace un momento.<br>Juego muy mal al golf. <b>He aprendido</b> hace poco."},{"k":"p","t":"– Se suele emplear para dar noticias recientes."},{"k":"eg","t":"—¿Qué <b>ha pasado</b>? —<b>Ha dimitido</b> el presidente."},{"k":"p","t":"En muchas partes de América Latina y España se utiliza el pretérito indefinido (<i>Comí</i>) en lugar del pretérito perfecto (<i>He comido</i>)."},{"k":"p","t":"Unidad 61: Pretérito perfecto de indicativo (2)"}],"ex":[{"id":"gram:60.1","type":"cloze","lab":"60.1","title":"60.1","instr":"¿Qué ha hecho Betty hoy? Utilice los verbos del recuadro.","img":"img/gram/u60_ej60-1_ilustraciones.png","alt":"Ocho viñetas: Betty bostezando en la cama, corriendo, duchándose, enviando correos, en el cine con una amiga, jugando a los bolos, cenando con amigos y leyendo en la cama a las doce.","bank":["acostarse","cenar","ducharse","enviar","hacer","ir","jugar","~levantarse"],"items":[{"tpl":"___ a las diez.","blanks":1,"ans":["Se ha levantado"],"wide":true,"example":true},{"tpl":"___ footing.","blanks":1,"ans":["Ha hecho"],"wide":true},{"tpl":"___.","blanks":1,"ans":["Se ha duchado"],"wide":true},{"tpl":"___ unos correos electrónicos.","blanks":1,"ans":["Ha enviado"],"wide":true},{"tpl":"___ al cine con una amiga.","blanks":1,"ans":["Ha ido"],"wide":true},{"tpl":"___ a los bolos.","blanks":1,"ans":["Ha jugado"],"wide":true},{"tpl":"___ con unos amigos.","blanks":1,"ans":["Ha cenado"],"wide":true},{"tpl":"___ a las doce.","blanks":1,"ans":["Se ha acostado"],"wide":true}]},{"id":"gram:60.2","type":"cloze","lab":"60.2","title":"60.2","instr":"Complete las frases con el pretérito perfecto de los verbos entre paréntesis.","items":[{"tpl":"Este verano (nosotros, estar) ___ en Perú.","blanks":1,"ans":["hemos estado"],"wide":true,"example":true},{"tpl":"—¿(tú, ver) ___ a Cristina? —Sí, la (yo, ver) ___ hace un momento.","blanks":2,"ans":["Has visto he visto"],"wide":true},{"tpl":"Hoy (nosotros, trabajar) ___ cerca de diez horas.","blanks":1,"ans":["hemos trabajado"],"wide":true},{"tpl":"Este año (llover) ___ mucho.","blanks":1,"ans":["ha llovido"],"wide":true},{"tpl":"—¿Sabes usar este programa? —Regular. (yo, empezar) ___ a usarlo hace poco.","blanks":1,"ans":["He empezado"],"wide":true},{"tpl":"Mis padres (estar) ___ en la costa este invierno.","blanks":1,"ans":["han estado"],"wide":true},{"tpl":"¿Qué (vosotros, hacer) ___ este verano?","blanks":1,"ans":["habéis hecho"],"wide":true},{"tpl":"¿(tú, leer) ___ algo interesante últimamente?","blanks":1,"ans":["Has leído"],"wide":true},{"tpl":"Hoy (nosotras, comer) ___ ceviche de marisco.","blanks":1,"ans":["hemos comido"],"wide":true},{"tpl":"—¿Qué (hacer) ___ Martín este verano? —(Quedarse) ___ en Madrid. No tenía dinero.","blanks":2,"ans":["ha hecho Se ha quedado"],"wide":true}]},{"id":"gram:60.3","type":"cloze","lab":"60.3","title":"60.3","instr":"Escriba las noticias correspondientes a los titulares dados. Utilice los verbos del recuadro.","bank":["acabar","bajar","chocar","dimitir","~escaparse","ganar","morir","subir"],"items":[{"tpl":"___","blanks":1,"ans":["Se han escapado cincuenta presos"],"ctx":"Fuga de 50 presos.","wide":true,"full":true,"example":true},{"tpl":"___","blanks":1,"ans":["Ha muerto el Presidente"],"ctx":"Fallece el Presidente.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Ha dimitido la Ministra de Hacienda"],"ctx":"Dimite la ministra de Hacienda.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Ha acabado la huelga del transporte"],"ctx":"Fin de la huelga del transporte.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Han chocado dos trenes"],"ctx":"Choque de dos trenes.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Ha subido la gasolina"],"ctx":"Sube la gasolina.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["Han bajado los impuestos"],"ctx":"Bajan los impuestos.","wide":true,"full":true},{"tpl":"___","blanks":1,"ans":["El Colo-Colo ha ganado la Liga"],"ctx":"Colo-Colo, campeón de Liga.","wide":true,"full":true}]}]},{"id":61,"name":"Pretérito perfecto de indicativo (2)","motto":"he viajado mucho","theory":[{"k":"img","src":"img/gram/u61_teoria-vida.png","alt":"Ana: «toda la vida» hasta ahora: América, Asia, fábrica, actriz."},{"k":"img","src":"img/gram/u61_teoria-actriz.png","alt":"«He tenido una vida intensa. He viajado por todo el mundo. He trabajado en una fábrica. He sido actriz...»"},{"k":"p","t":"Se usa el pretérito perfecto para hablar de experiencias de nuestra vida, de lo que hemos hecho (o no) hasta ahora, sin decir cuándo. Se suele usar con <i>alguna vez, nunca, hasta ahora, en mi vida</i>."},{"k":"eg","t":"<b>He tenido</b> una vida intensa.<br>—¿<b>Has estado</b> alguna vez en Cuba? —Sí, <b>he estado</b> dos veces.<br>No <b>he comido</b> nunca ceviche.<br>Hasta ahora <b>hemos viajado</b> mucho."},{"k":"p","t":"También se usa para hablar de una acción pasada que tiene consecuencias en el presente."},{"k":"img","src":"img/gram/u61_teoria-pierna.png","alt":"«No puedo jugar. Me he roto una pierna.»"},{"k":"eg","t":"No puedo entrar en casa porque <b>he perdido</b> las llaves.<br>Estoy cansada. <b>He trabajado</b> mucho hoy."},{"k":"p","t":"Se usa con <i>ya</i> (pregunta o respuesta afirmativa), <i>todavía no</i> (respuesta negativa), para hablar de acciones que se espera que ocurran."},{"k":"img","src":"img/gram/u61_teoria-pelicula.png","alt":"«¿Ha empezado ya la película? – Todavía no.»"},{"k":"eg","t":"—¿<b>Has recogido ya</b> los billetes? —Sí, <b>los he recogido ya</b>.<br>—¿<b>Has reservado ya</b> el hotel? —No, todavía <b>no lo he reservado</b>."},{"k":"note","h":"ATENCIÓN","rows":["<i>Nunca</i> puede ir antes o después del verbo: <b>Nunca he ido</b> a Perú. · <b>No he ido nunca</b> a Perú.","Los pronombres van antes de <i>haber</i>: <b>Lo he reservado</b> ya. · <b>Me he roto</b> una pierna."]},{"k":"p","t":"Unidad 62: Contraste entre pretérito perfecto y pretérito indefinido"}],"ex":[{"id":"gram:61.1","type":"cloze","lab":"61.1","title":"61.1","instr":"Observe las ilustraciones. ¿Qué ha hecho Ana Roldán en su vida?","img":"img/gram/u61_ej61-1_ilustraciones.png","alt":"Seis viñetas de la vida de Ana Roldán: un pasaporte con sello de Uruguay, un libro titulado Aire, personajes famosos, una carta a Santiago de Chile, una enfermera en un hospital y una madre con cinco hijos.","bank":["conocer","escribir","~estar","tener","trabajar","vivir","Chile","hospital","libro","personajes famosos","cinco hijos","~Uruguay"],"items":[{"tpl":"___.","blanks":1,"ans":["Ha estado en Uruguay"],"wide":true,"ctx":"Ilustración 1","example":true},{"tpl":"___.","blanks":1,"ans":["Ha escrito un libro"],"wide":true,"ctx":"Ilustración 2"},{"tpl":"___.","blanks":1,"ans":["Ha conocido a personajes famosos"],"wide":true,"ctx":"Ilustración 3"},{"tpl":"___.","blanks":1,"ans":["Ha vivido en Chile"],"wide":true,"ctx":"Ilustración 4"},{"tpl":"___.","blanks":1,"ans":["Ha trabajado en un hospital"],"wide":true,"ctx":"Ilustración 5"},{"tpl":"___.","blanks":1,"ans":["Ha tenido cinco hijos"],"wide":true,"ctx":"Ilustración 6"}]},{"id":"gram:61.2","type":"cloze","lab":"61.2","title":"61.2","instr":"Escriba frases con estas palabras.","items":[{"tpl":"___","blanks":1,"ans":["Reinaldo no ha estado nunca en África"],"wide":true,"full":true,"ctx":"Reinaldo / estar / nunca / en África","example":true},{"tpl":"___","blanks":1,"ans":["¿Han comido ustedes alguna vez tortilla?"],"wide":true,"full":true,"ctx":"¿ustedes / comer / alguna vez / tortilla?"},{"tpl":"___","blanks":1,"ans":["¿Os habéis enamorado alguna vez?"],"wide":true,"full":true,"ctx":"¿vosotros / enamorarse / alguna vez?"},{"tpl":"___","blanks":1,"ans":["No he ido nunca a la ópera"],"wide":true,"full":true,"ctx":"yo / nunca / ir / a la ópera"},{"tpl":"___","blanks":1,"ans":["No hemos bebido nunca tequila"],"wide":true,"full":true,"ctx":"nosotros / beber / nunca / tequila"}]},{"id":"gram:61.3","type":"cloze","lab":"61.3","title":"61.3","instr":"Forme frases uniendo los elementos de las dos columnas.","tbl":{"head":["Consecuencias","Causas"],"rows":[["1. No puedo entrar en casa","a. trabajar mucho todo el día"],["2. Juana no ve bien","b. perder las llaves"],["3. No puedo pagar","c. olvidarse la cartera"],["4. Están agotadas","d. romperse las gafas"]]},"items":[{"tpl":"___","blanks":1,"ans":["No puedo entrar en casa porque he perdido las llaves"],"wide":true,"full":true,"ctx":"Frase 1","example":true},{"tpl":"___","blanks":1,"ans":["Juana no ve bien porque se ha roto las gafas"],"wide":true,"full":true,"ctx":"Frase 2"},{"tpl":"___","blanks":1,"ans":["No puedo pagar porque me he olvidado la cartera"],"wide":true,"full":true,"ctx":"Frase 3"},{"tpl":"___","blanks":1,"ans":["Están agotadas porque han trabajado mucho todo el día"],"wide":true,"full":true,"ctx":"Frase 4"}]},{"id":"gram:61.4","type":"cloze","lab":"61.4","title":"61.4","instr":"Laura y Gabriel se van de vacaciones la semana que viene. Escriba las preguntas de Gabriel sobre los preparativos y las respuestas de Laura.","items":[{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Has recogido ya los billetes los he recogido ya"],"wide":true,"ctx":"(recoger los billetes)","example":true,"exv":["Has recogido ya los billetes","los he recogido ya"]},{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Has reservado ya el hotel lo he reservado ya"],"wide":true,"ctx":"(reservar el hotel)"},{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Has pedido ya el visado lo he pedido ya"],"wide":true,"ctx":"(pedir el visado)"},{"tpl":"—¿___? —No, ___.","blanks":2,"ans":["Has cambiado ya el dinero no lo he cambiado todavía"],"wide":true,"ctx":"(cambiar dinero)"},{"tpl":"—¿___? —No, ___.","blanks":2,"ans":["Has recogido ya los cheques de viaje no los he recogido todavía"],"wide":true,"ctx":"(recoger los cheques de viaje)"}]}]},{"id":62,"name":"Contraste entre pretérito perfecto y pretérito indefinido","motto":"he estado / estuve","theory":[{"k":"h","t":"Compare"},{"k":"table","head":["PRETÉRITO PERFECTO","PRETÉRITO INDEFINIDO"],"rows":[["Acciones pasadas recientes, con <i>hace un rato, hace poco…</i><br>He visto a Pedro <b>hace un rato</b>.","Acciones pasadas más lejanas, con <i>hace una semana, hace dos años…</i><br>Vi a Pedro <b>hace una semana</b>."],["Período de tiempo que llega hasta el presente: <i>hoy, esta mañana, este mes, este año…</i><br><b>Hoy</b> no he ido a trabajar.<br><b>Este mes</b> ha llovido mucho.","Período de tiempo terminado: <i>ayer, el mes pasado, el año pasado, en 1998…</i><br><b>Ayer</b> no fui a trabajar.<br><b>El mes pasado</b> llovió mucho."],["Experiencias, sin decir cuándo: <i>alguna vez, nunca</i>.<br>¿Has estado <b>alguna vez</b> en Cuba?<br><b>Nunca</b> he comido ceviche.","Si decimos el momento exacto: <i>en 1999, el verano pasado…</i><br>Estuve en Cuba <b>en 1999</b>."],["—¿Has visto <b>ya</b> la película?<br>—No, <b>todavía no</b> la he visto.","—¿Cuándo la viste?<br>—La vi <b>el martes</b>."]]},{"k":"note","h":"ATENCIÓN","rows":["El año pasado <s>he estado</s> en Chile. → El año pasado <b>estuve</b> en Chile.","En muchas partes de América Latina y España se utiliza el pretérito indefinido (<i>Comí</i>) en lugar del pretérito perfecto (<i>He comido</i>)."]},{"k":"p","t":"Unidad 63: Pretérito imperfecto"}],"ex":[{"id":"gram:62.1","type":"pick","lab":"62.1","title":"62.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"[Hemos estado|estuvimos] con Rosa hace poco.","ans":["Hemos estado"],"example":true},{"tpl":"Hoy no [he ido|fui] a trabajar.","ans":["he ido"]},{"tpl":"¿Cuándo [ha nacido|nació] tu hijo mayor?","ans":["nació"]},{"tpl":"[Hemos estado|Estuvimos] en México el verano de 1998.","ans":["Estuvimos"]},{"tpl":"¿[Han comido|Comieron] alguna vez ceviche?","ans":["Han comido"]},{"tpl":"Este invierno no [ha nevado|nevó] mucho.","ans":["ha nevado"]},{"tpl":"¿[Has visto|Viste] ya el vídeo que te presté?","ans":["Has visto"]},{"tpl":"Peter no [ha estudiado|estudió] nunca español.","ans":["ha estudiado"]},{"tpl":"Amalia y sus padres [han venido|vinieron] a España hace tres años.","ans":["vinieron"]},{"tpl":"Todavía no [he visto|vi] la última exposición de Barceló.","ans":["he visto"]},{"tpl":"¿[Has trabajado|Trabajaste] alguna vez en una película?","ans":["Has trabajado"]},{"tpl":"Cuando nos casamos, [hemos hecho|hicimos] un viaje por América Central.","ans":["hicimos"]}]},{"id":"gram:62.2","type":"cloze","lab":"62.2","title":"62.2","instr":"Complete las frases con la forma adecuada: pretérito perfecto o pretérito indefinido.","items":[{"tpl":"¿(ustedes, montar) ___ alguna vez en globo?","blanks":1,"ans":["Han montado"],"wide":true,"example":true},{"tpl":"Mi hermana (tener) ___ un niño hace poco.","blanks":1,"ans":["ha tenido"],"wide":true},{"tpl":"Rosana nos (invitar) ___ a su chalé el fin de semana pasado.","blanks":1,"ans":["invitó"],"wide":true},{"tpl":"Este año (haber) ___ menos accidentes en las carreteras.","blanks":1,"ans":["ha habido"],"wide":true},{"tpl":"El siglo pasado (haber) ___ dos guerras mundiales.","blanks":1,"ans":["hubo"],"wide":true},{"tpl":"—¿(tú, ver) ___ a Ana? —Sí, la (ver) ___ el domingo.","blanks":2,"ans":["Has visto vi"],"wide":true},{"tpl":"—¿(vosotras, estar) ___ alguna vez en América del Sur? —Sí, hace cuatro años (estar) ___ en Uruguay.","blanks":2,"ans":["Habéis estado estuvimos"],"wide":true},{"tpl":"—¿(tú, sacar) ___ las entradas para el partido? —Por supuesto. Las (yo, comprar) ___ hace dos semanas.","blanks":2,"ans":["Has sacado compré"],"wide":true},{"tpl":"—¿Qué (ustedes, hacer) ___ este verano? —En julio (estar) ___ en Cancún. Lo (pasar) ___ estupendamente.","blanks":3,"ans":["han hecho estuvimos pasamos"],"wide":true}]},{"id":"gram:62.3","type":"cloze","lab":"62.3","title":"62.3","instr":"Arnaldo y Maite están pasando una semana de vacaciones en España. Complete el diálogo escribiendo las preguntas y respuestas como en el ejemplo.","items":[{"tpl":"—¿___? —Sí, ___. —No, ___.","blanks":3,"ans":["Habéis estado ya en Barcelona estuvimos el miércoles todavía no hemos estado en Barcelona"],"wide":true,"ctx":"(estar, Barcelona) / (miércoles) / No","example":true,"exv":["Habéis estado ya en Barcelona","estuvimos el miércoles","todavía no hemos estado en Barcelona"]},{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Habéis probado ya el cocido lo probamos el lunes"],"wide":true,"ctx":"(probar, el cocido) / (lunes)"},{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Habéis visitado ya el Museo del Prado lo visitamos el martes por la mañana"],"wide":true,"ctx":"(visitar, Museo del Prado) / (martes por la mañana)"},{"tpl":"—¿___? —No, ___.","blanks":2,"ans":["Habéis comprado ya los regalos todavía no los hemos comprado"],"wide":true,"ctx":"(comprar, los regalos) / No"},{"tpl":"—¿___? —Sí, ___.","blanks":2,"ans":["Habéis ido ya a Sevilla fuimos ayer"],"wide":true,"ctx":"(ir, a Sevilla) / (ayer)"}]}]},{"id":63,"name":"Pretérito imperfecto","motto":"trabajaba, comía, vivía","theory":[{"k":"img","src":"img/gram/u63_teoria-laboratorio.png","alt":"«Cuando era joven, trabajaba en un laboratorio.»"},{"k":"img","src":"img/gram/u63_teoria-incas.png","alt":"«Los incas cultivaban maíz y papas.»"},{"k":"p","t":"<i>Era, trabajaba</i> y <i>cultivaban</i> son formas del pretérito imperfecto."},{"k":"h","t":"Formación del pretérito imperfecto"},{"k":"table","head":["","-ar (trabajar)","-er (comer)","-ir (vivir)"],"rows":[["(yo)","trabaj-aba","com-ía","viv-ía"],["(tú)","trabaj-abas","com-ías","viv-ías"],["(usted)","trabaj-aba","com-ía","viv-ía"],["(él, ella)","trabaj-aba","com-ía","viv-ía"],["(nosotros, -as)","trabaj-ábamos","com-íamos","viv-íamos"],["(vosotros, -as)","trabaj-abais","com-íais","viv-íais"],["(ustedes)","trabaj-aban","com-ían","viv-ían"],["(ellos, -as)","trabaj-aban","com-ían","viv-ían"]]},{"k":"h","t":"Verbos irregulares"},{"k":"table","head":["","ver","ser","ir"],"rows":[["(yo)","veía","era","iba"],["(tú)","veías","eras","ibas"],["(usted)","veía","era","iba"],["(él, ella)","veía","era","iba"],["(nosotros, -as)","veíamos","éramos","íbamos"],["(vosotros, -as)","veíais","erais","ibais"],["(ustedes)","veían","eran","iban"],["(ellos, -as)","veían","eran","iban"]]},{"k":"p","t":"Se usa el pretérito imperfecto para hablar de hábitos y costumbres en el pasado."},{"k":"eg","t":"Cuando era joven, <b>trabajaba</b> en un laboratorio.<br>De pequeño, <b>iba</b> todos los veranos a casa de mis abuelos.<br>Mis padres <b>vivían</b> en un pueblo y <b>cultivaban</b> trigo."},{"k":"p","t":"Se usa también para describir personas, lugares y situaciones del pasado."},{"k":"eg","t":"Los incas <b>cultivaban</b> maíz y papas.<br>Mi abuelo <b>era</b> alto y <b>llevaba</b> siempre una boina.<br>La casa <b>tenía</b> dos pisos y <b>estaba</b> cerca del río."},{"k":"p","t":"Unidad 64: Contraste entre pretérito indefinido y pretérito imperfecto"}],"ex":[{"id":"gram:63.1","type":"cloze","lab":"63.1","title":"63.1","instr":"Complete las frases con el pretérito imperfecto de los verbos entre paréntesis.","items":[{"tpl":"Cuando (yo, ser) ___ pequeño, siempre (rezar) ___ antes de acostarme.","blanks":2,"ans":["era rezaba"],"wide":true,"example":true,"exv":["era","rezaba"]},{"tpl":"Cuando Martín y Pablo (ser) ___ jóvenes, (llevar) ___ camisas de flores y (escuchar) ___ música pop.","blanks":3,"ans":["eran llevaban escuchaban"],"wide":true},{"tpl":"Cuando nos casamos, (vivir) ___ en un piso alquilado y Nuria (trabajar) ___ en una empresa de informática.","blanks":2,"ans":["vivíamos trabajaba"],"wide":true},{"tpl":"Loli (ser) ___ muy independiente de pequeña. (Ducharse) ___ sola, (hacerse) ___ la cama, (prepararse) ___ el desayuno e (ir) ___ sola al colegio.","blanks":5,"ans":["era Se duchaba se hacía se preparaba iba"],"wide":true},{"tpl":"—¿A qué (tú, dedicarse) ___ antes de conocernos? —(Estudiar) ___ Derecho.","blanks":2,"ans":["te dedicabas Estudiaba"],"wide":true},{"tpl":"Cuando (nosotros, vivir) ___ en Ciudad de México, (ir) ___ a Acapulco todos los veranos.","blanks":2,"ans":["vivíamos íbamos"],"wide":true},{"tpl":"—¿Qué ___ (querer) ser de pequeña, María? —(Querer) ___ ser astronauta.","blanks":2,"ans":["querías Quería"],"wide":true}]},{"id":"gram:63.2","type":"cloze","lab":"63.2","title":"63.2","instr":"Complete las frases sobre las antiguas civilizaciones de América.","bank":["adorar","beber","~construir","criar","ser","tener","vivir"],"items":[{"tpl":"Los aztecas ___ pirámides escalonadas.","blanks":1,"ans":["construían"],"mid":true,"example":true},{"tpl":"Los mayas ___ un calendario de dieciocho meses.","blanks":1,"ans":["tenían"],"mid":true},{"tpl":"Los aztecas ___ en el centro y sur de México.","blanks":1,"ans":["vivían"],"mid":true},{"tpl":"Los incas ___ al sol.","blanks":1,"ans":["adoraban"],"mid":true},{"tpl":"Los aztecas ___ chocolate.","blanks":1,"ans":["bebían"],"mid":true},{"tpl":"Los incas ___ llamas.","blanks":1,"ans":["criaban"],"mid":true},{"tpl":"Los caribes ___ cazadores y recolectores.","blanks":1,"ans":["eran"],"mid":true}]},{"id":"gram:63.3","type":"cloze","lab":"63.3","title":"63.3","instr":"Complete el texto utilizando los verbos del recuadro.","bank":["acostarse","ayudar","bailar","bañarse","cultivar","divertirse","estar","gustar","haber","jugar","llevar","ocuparse","querer","reunirse","ser","tener","trabajar"],"items":[{"tpl":"Cuando era pequeño pasaba los veranos en el pueblo de mis abuelos. ___ un pueblo muy pequeño y muy pobre.","blanks":1,"ans":["Era"],"mid":true,"perBlank":true,"example":true},{"tpl":"Las casas ___ de adobe y ___ unas ventanas muy pequeñas.","blanks":2,"ans":["eran tenían"],"mid":true,"perBlank":true},{"tpl":"La casa de mis abuelos ___ en las afueras del pueblo, cerca del río. ___ dos pisos y en la parte de atrás ___ un pequeño huerto con algunos frutales.","blanks":3,"ans":["estaba Tenía había"],"mid":true,"perBlank":true},{"tpl":"Mi abuelo no ___ casi pelo; ___ siempre una boina negra.","blanks":2,"ans":["tenía llevaba"],"mid":true,"perBlank":true},{"tpl":"Mi abuela ___ el pelo y los ojos grises. Los dos me ___ mucho.","blanks":2,"ans":["tenía querían"],"mid":true,"perBlank":true},{"tpl":"Mi abuelo ___ en el campo; ___ trigo y uvas para hacer vino.","blanks":2,"ans":["trabajaba cultivaba"],"mid":true,"perBlank":true},{"tpl":"Mi abuela le ___ y ___ de la casa.","blanks":2,"ans":["ayudaba se ocupaba"],"mid":true,"perBlank":true},{"tpl":"Los veranos en el pueblo ___ muy divertidos. ___ muchos amigos y ___ todas las tardes.","blanks":3,"ans":["eran Tenía nos reuníamos"],"mid":true,"perBlank":true},{"tpl":"Unas veces ___ al fútbol, otras ___ en el río. Cuando más ___ era en las fiestas.","blanks":3,"ans":["jugábamos nos bañábamos nos divertíamos"],"mid":true,"perBlank":true},{"tpl":"Durante tres o cuatro días ___ baile todas las noches. Los chicos no ___ mucho, pero nos ___ la música y ___ tardísimo.","blanks":4,"ans":["había bailábamos gustaba nos acostábamos"],"mid":true,"perBlank":true},{"tpl":"___ unos veranos maravillosos.","blanks":1,"ans":["Eran"],"mid":true,"perBlank":true}]}]},{"id":64,"name":"Contraste entre pretérito indefinido y pretérito imperfecto","motto":"comí / comía","theory":[{"k":"h","t":"Compare"},{"k":"table","head":["PRETÉRITO INDEFINIDO","PRETÉRITO IMPERFECTO"],"rows":[["Acciones concretas, en un momento determinado.<br>La semana pasada <b>comí</b> con Luis.<br>El domingo <b>fuimos</b> al campo.<br>Aquella tarde <b>dimos</b> un paseo por el centro.","Acciones habituales en el pasado.<br>De pequeña, <b>comía</b> mucho chocolate.<br>Cuando era pequeño, <b>íbamos</b> siempre al campo los domingos.<br><b>Dábamos</b> un paseo todas las tardes."],["Acción acabada.<br>El verano pasado <b>estuvimos</b> en Managua.","Acción en desarrollo.<br><b>Estábamos</b> en Managua cuando comenzó la huelga."],["Hechos, lo que ocurrió.<br>Ayer <b>fuimos</b> a la playa.<br>Los ladrones <b>entraron</b> en la casa.<br>¿<b>Vio</b> usted al culpable?<br>Cervantes <b>fue</b> un gran escritor. <b>Nació</b> en Alcalá de Henares en 1547.","Circunstancias: cómo era, qué pasaba alrededor.<br><b>Hacía</b> mucho calor y <b>había</b> mucha gente.<br>Los ladrones entraron mientras <b>dormíamos</b> la siesta.<br>—Sí. <b>Era</b> alto, <b>tenía</b> los ojos verdes y <b>llevaba</b> una gorra negra.<br>Su padre <b>era</b> cirujano."]]},{"k":"p","t":"Unidad 65: Estaba + gerundio y contraste con el pretérito indefinido"}],"ex":[{"id":"gram:64.1","type":"pick","lab":"64.1","title":"64.1","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"Ayer no [fui|iba] a trabajar. [Estuve|Estaba] enfermo.","ans":["fui","Estaba"],"example":true},{"tpl":"¿[Fuiste|Ibas] mucho a la playa cuando [viviste|vivías] en Las Palmas?","ans":["Ibas","vivías"]},{"tpl":"El domingo pasado [estuvimos|estábamos] en la sierra. No [pudimos|podíamos] esquiar porque no [hubo|había] nieve.","ans":["estuvimos","pudimos","había"]},{"tpl":"Cuando [fui|era] joven, [fui|iba] mucho al cine.","ans":["era","iba"]},{"tpl":"Carolina [estuvo|estaba] en medio del campo cuando [empezó|empezaba] a llover.","ans":["estaba","empezó"]},{"tpl":"¿Qué [hicisteis|hacías] el sábado pasado?","ans":["hicisteis"]},{"tpl":"¿Dónde [estuviste|estabas] cuando [empezó|empezaba] el partido?","ans":["estabas","empezó"]},{"tpl":"Anoche [vi|veía] a Marisa. [Llevó|Llevaba] un vestido precioso.","ans":["vi","Llevaba"]},{"tpl":"¿Qué [hiciste|hacías] en la calle cuando te [vio|veía] Lucas?","ans":["hacías","vio"]}]},{"id":"gram:64.2","type":"cloze","lab":"64.2","title":"64.2","instr":"Complete los diálogos con los verbos entre paréntesis.","items":[{"tpl":"La (conocer) ___ cuando (vivir) ___ en Bogotá.","blanks":2,"ans":["conocí vivía"],"wide":true,"ctx":"¿Cuándo (conocer) <b>conociste</b> a Maruja?"},{"tpl":"—¿Dónde (ustedes, estar) ___ cuando (yo, llamar) ___ anoche? —(Estar) ___ dormidos y (no, oír) ___ el teléfono.","blanks":4,"ans":["estaban ustedes llamé Estábamos no oímos"],"wide":true},{"tpl":"—¿Qué (tú, hacer) ___ cuando (vivir) ___ en Ecuador? ¿Por qué (venirse) ___ a España? —(Ser) ___ maestra. (No, tener) ___ trabajo allí.","blanks":5,"ans":["hacías vivías te viniste Era No tenía"],"wide":true}]},{"id":"gram:64.3","type":"cloze","lab":"64.3","title":"64.3","instr":"Complete la historia con los verbos entre paréntesis en pretérito indefinido o pretérito imperfecto.","items":[{"tpl":"Una noche, cuando (tener) ___ once o doce años,","blanks":1,"ans":["tenía"],"mid":true,"perBlank":true,"example":true},{"tpl":"mis padres (salir) ___ y me (dejar) ___ solo. (Estar) ___ feliz porque (sentirse) ___ adulto.","blanks":4,"ans":["salieron dejaron Estaba me sentía"],"mid":true,"perBlank":true},{"tpl":"Me (preparar) ___ algo para cenar, (ver) ___ la tele y sobre las doce (irse) ___ a mi habitación.","blanks":3,"ans":["preparé vi me fui"],"mid":true,"perBlank":true},{"tpl":"De repente, (oír) ___ un ruido en el piso de abajo. (Cerrar) ___ con llave la puerta de mi habitación y (escuchar) ___.","blanks":3,"ans":["oí Cerré escuché"],"mid":true,"perBlank":true},{"tpl":"Al cabo de un rato (abrir) ___ la puerta y (bajar) ___ las escaleras con mucho miedo.","blanks":2,"ans":["abrí bajé"],"mid":true,"perBlank":true},{"tpl":"(Haber) ___ algo que (moverse) ___ cerca de una ventana.","blanks":2,"ans":["Había se movía"],"mid":true,"perBlank":true},{"tpl":"De repente, una sombra negra (saltar) ___ sobre mí. (Ser) ___ un gato.","blanks":2,"ans":["saltó Era"],"mid":true,"perBlank":true},{"tpl":"(Desmayarse) ___ y cuando (regresar) ___ mis padres, me (encontrar) ___ tirado en el suelo.","blanks":3,"ans":["Me desmayé regresaron encontraron"],"mid":true,"perBlank":true}]}]},{"id":65,"name":"Estaba + gerundio y contraste con el pretérito indefinido","motto":"estaba trabajando / trabajé","theory":[{"k":"h","t":"Pretérito imperfecto de estar + gerundio del verbo"},{"k":"table","head":["","estar","gerundio"],"rows":[["(yo)","estaba","trabajando"],["(tú)","estabas","trabajando"],["(usted)","estaba","comiendo"],["(él, ella)","estaba","comiendo"],["(nosotros, -as)","estábamos","viviendo"],["(vosotros, -as)","estabais","viviendo"],["(ustedes)","estaban","viviendo"],["(ellos, -as)","estaban","viviendo"]]},{"k":"img","src":"img/gram/u65_teoria-bruno.png","alt":"Cuando entró el jefe, Bruno estaba leyendo el periódico."},{"k":"eg","t":"Cuando entró el jefe, Bruno <b>estaba leyendo</b> el periódico."},{"k":"p","t":"Se usa <i>estaba</i> + gerundio para hablar de una acción en desarrollo en un momento concreto del pasado. Informa de lo que se hacía, por ejemplo, ayer a determinada hora o cuando sucedió algo."},{"k":"eg","t":"—Anoche te llamé a las ocho. ¿Dónde estabas?<br>—Estaba en el jardín. <b>Estaba regando</b> los rosales."},{"k":"p","t":"– Generalmente sirve para hablar de la situación o circunstancias que rodeaban un hecho pasado."},{"k":"eg","t":"Cuando llegó el presidente, yo <b>estaba aparcando</b> y Mar y Luis <b>estaban cruzando</b> la calle."},{"k":"h","t":"Compare"},{"k":"table","head":["ESTABA + GERUNDIO","PRETÉRITO INDEFINIDO"],"rows":[["Una acción en desarrollo.<br><b>Estábamos comiendo</b>…","Una acción breve que interrumpe la acción en desarrollo.<br>…cuando <b>llegaron</b> los amigos de Ana."]]},{"k":"p","t":"El pretérito indefinido se usa también para hablar de una secuencia de acciones que tuvieron lugar una después de otra."},{"k":"eg","t":"<b>Comimos</b> cuando <b>llegaron</b> los amigos de Ana. (primero llegaron, después comimos)"},{"k":"note","h":"ATENCIÓN","rows":["No se suele usar <i>estaba</i> + gerundio con determinados verbos: <i>comprender, entender, saber, querer, necesitar, amar, preferir, odiar, parecer, tener, llevar, ir, venir</i>. En su lugar se usa el pretérito imperfecto de indicativo.","<s>Estaba teniendo</s> algo de fiebre cuando me llamaste. → <b>Tenía</b> algo de fiebre cuando me llamaste."]},{"k":"p","t":"Unidad 98: Gerundio · Unidad 58: Pretérito indefinido: verbos regulares · Unidad 59: Pretérito indefinido: verbos irregulares"}],"ex":[{"id":"gram:65.1","type":"cloze","lab":"65.1","title":"65.1","instr":"Ayer a las 6 de la tarde hubo un accidente en un cruce de calles. La policía preguntó a varios testigos. Observe las ilustraciones y escriba sus respuestas. Utilice las expresiones del recuadro.","img":"img/gram/u65_ej65-1_ilustraciones.png","alt":"Un policía anota el testimonio de un testigo; seis viñetas a las 12.10: Ricardo compra el periódico, Mar y su novio esperan el autobús, Samuel lee el periódico mientras su novia habla por teléfono, el Sr. Márquez y su mujer miran un escaparate, Tomás cruza la calle, Maite echa una carta mientras sus padres aparcan.","bank":["aparcar","~comprar el periódico","cruzar la calle","echar una carta","esperar el autobús","hablar por teléfono","leer el periódico","mirar un escaparate"],"items":[{"tpl":"Ricardo: No vi nada. En ese momento ___.","blanks":1,"ans":["estaba comprando el periódico"],"wide":true,"example":true},{"tpl":"Mar: Mi novio y yo lo vimos todo. ___.","blanks":1,"ans":["Estábamos esperando el autobús"],"wide":true},{"tpl":"Samuel: Mi novia y yo no vimos nada. Ella ___ y yo ___.","blanks":2,"ans":["estaba hablando por teléfono estaba leyendo el periódico"],"wide":true},{"tpl":"Sr. Márquez: Mi mujer y yo no vimos nada. ___.","blanks":1,"ans":["Estábamos mirando un escaparate"],"wide":true},{"tpl":"Tomás: Lo vi todo. En ese momento ___.","blanks":1,"ans":["estaba cruzando la calle"],"wide":true},{"tpl":"Maite: No vimos nada. Mis padres ___ y yo ___.","blanks":2,"ans":["estaban aparcando estaba echando una carta"],"wide":true}]},{"id":"gram:65.2","type":"cloze","lab":"65.2","title":"65.2","instr":"Complete las frases con estaba + gerundio o el pretérito indefinido.","items":[{"tpl":"Cuando me vio Sofía, (hablar) ___ con unas amigas.","blanks":1,"ans":["estaba hablando"],"wide":true},{"tpl":"¿Qué (tú, hacer) ___ cuando (apagarse) ___ la luz?","blanks":2,"ans":["estabas haciendo se apagó"],"wide":true},{"tpl":"La clase (empezar) ___ cuando (nosotros, llegar) ___.","blanks":2,"ans":["empezó llegamos"],"wide":true},{"tpl":"¿(Nevar) ___ cuando (usted, salir) ___?","blanks":2,"ans":["Estaba nevando salió"],"wide":true},{"tpl":"Pedrito (caerse) ___ y (romperse) ___ una pierna cuando (jugar) ___ al fútbol.","blanks":3,"ans":["se cayó se rompió estaba jugando"],"wide":true},{"tpl":"(Yo, ducharse) ___ cuando (sonar) ___ el teléfono.","blanks":2,"ans":["Estaba duchándome sonó"],"wide":true},{"tpl":"Cuando (llegar) ___ el jefe, (irse) ___ Fina y Celia.","blanks":2,"ans":["llegó se fueron"],"wide":true}]},{"id":"gram:65.3","type":"pick","lab":"65.3","title":"65.3","instr":"Rodee la forma correcta en cada caso.","items":[{"tpl":"—¿Qué te [pasaba|estaba pasando] anoche? —[Tenía|Estaba teniendo] mucho sueño.","ans":["pasaba","Tenía"],"example":true},{"tpl":"¿Adónde [ibas|estabas yendo] ayer cuando te vio Tere?","ans":["ibas"]},{"tpl":"—¿Dónde estaban tus hermanas la semana pasada? —[Viajaban|Estaban viajando] por Argentina.","ans":["Estaban viajando"]},{"tpl":"Cuando nos encontramos con Nacho, [llevaba|estaba llevando] un poncho chileno muy bonito. [Parecía|Estaba pareciendo] un mapuche.","ans":["llevaba","Parecía"]},{"tpl":"¿De dónde [venían|estaban viniendo] cuando tuvieron el accidente?","ans":["venían"]},{"tpl":"Fui a ver a Anita porque [necesitaba|estaba necesitando] su ayuda.","ans":["necesitaba"]}]}]},{"id":66,"name":"Pretérito pluscuamperfecto","motto":"había trabajado","theory":[{"k":"img","src":"img/gram/u66_teoria-banco.png","alt":"Cuando llegué al banco, ya había cerrado."},{"k":"img","src":"img/gram/u66_teoria-lolo.png","alt":"Ayer me encontré con Lolo y no lo reconocí. Se había afeitado la cabeza."},{"k":"p","t":"<i>Había cerrado</i> y <i>se había afeitado</i> son formas del pretérito pluscuamperfecto."},{"k":"h","t":"Formación: pretérito imperfecto de haber + participio pasado"},{"k":"table","head":["","haber","participio"],"rows":[["(yo)","había","trabajado"],["(tú)","habías","trabajado"],["(usted)","había","trabajado"],["(él, ella)","había","comido"],["(nosotros, -as)","habíamos","comido"],["(vosotros, -as)","habíais","vivido"],["(ustedes)","habían","vivido"],["(ellos, -as)","habían","vivido"]]},{"k":"p","t":"Unidad 99: Participio"},{"k":"p","t":"Se usa el pretérito pluscuamperfecto para referirse a una acción pasada concluida antes de otra acción o situación también pasadas."},{"k":"eg","t":"Cuando llegué al banco (2), ya <b>había cerrado</b> (1). (El banco cerró a las 14.00; llegué a las 14.15.)<br>Cuando llegamos a la estación (2), se <b>había ido</b> el tren (1)."},{"k":"p","t":"– A veces sirve para explicar los resultados o consecuencias de una acción o situación pasadas."},{"k":"eg","t":"—¿Por qué suspendiste? —No <b>había estudiado</b> nada."},{"k":"p","t":"– Se usa con <i>ya</i> para decir o preguntar si una acción se ha realizado antes de un momento pasado."},{"k":"eg","t":"Cuando conocí a Teresa, <b>ya había tenido</b> el niño.<br>Cuando Helga vino a España, ¿<b>había estudiado ya</b> algo de español?"},{"k":"p","t":"– Se usa con <i>todavía no / no… todavía</i> para indicar que una acción no se ha realizado antes de un momento pasado."},{"k":"eg","t":"Cuando Mariano y Concha se conocieron, Concha <b>todavía no había acabado</b> la carrera.<br>Cuando llamé a casa de Antonio, <b>no se había levantado todavía</b>."}],"ex":[{"id":"gram:66.1","type":"cloze","lab":"66.1","title":"66.1","instr":"Una las dos frases.","items":[{"tpl":"___","blanks":1,"ans":["Cuando llegué a la oficina, la reunión había acabado"],"wide":true,"full":true,"ctx":"La reunión acabó. Llegué a la oficina.","example":true},{"tpl":"___","blanks":1,"ans":["Cuando llegamos al aeropuerto, el avión se había ido"],"wide":true,"full":true,"ctx":"El avión se fue. Llegamos al aeropuerto."},{"tpl":"___","blanks":1,"ans":["Cuando Aurora quiso comprar comida, las tiendas habían cerrado"],"wide":true,"full":true,"ctx":"Cerraron las tiendas. Aurora quiso comprar comida."},{"tpl":"___","blanks":1,"ans":["Cuando Sonia me llamó, ya había cenado"],"wide":true,"full":true,"ctx":"Cené. Sonia me llamó."},{"tpl":"___","blanks":1,"ans":["Cuando nos pararon en la carretera, había habido un accidente"],"wide":true,"full":true,"ctx":"Hubo un accidente. Nos pararon en la carretera."}]},{"id":"gram:66.2","type":"cloze","lab":"66.2","title":"66.2","instr":"Forme frases uniendo las acciones o situaciones de la izquierda con sus consecuencias.","tbl":{"head":["Acciones o situaciones","Consecuencias"],"rows":[["1. Me dejé la tarjeta de crédito.","a. No pudieron entrar en casa."],["2. Mis padres se dejaron las luces encendidas.","b. Aprobó todo."],["3. Félix y Raquel se dejaron las llaves dentro.","c. Tuvieron que volver a casa."],["4. No comiste nada.","d. No pude comprar nada."],["5. Paloma se tiñó el pelo.","e. No pudimos comer en casa."],["6. Mila estudió mucho.","f. Te desmayaste."],["7. Víctor tuvo un pequeño accidente.","g. No pude hablar con él."],["8. El profesor se fue.","h. No la reconocimos."],["9. Ramón no compró comida.","i. Llegó tarde."]]},"items":[{"tpl":"___","blanks":1,"ans":["No pude comprar nada porque me había dejado la tarjeta de crédito"],"wide":true,"full":true,"ctx":"Me dejé la tarjeta de crédito.","example":true},{"tpl":"___","blanks":1,"ans":["Mis padres tuvieron que volver a casa porque se habían dejado las luces encendidas"],"wide":true,"full":true,"ctx":"Mis padres se dejaron las luces encendidas."},{"tpl":"___","blanks":1,"ans":["Félix y Raquel no pudieron entrar en casa porque se habían dejado las llaves dentro"],"wide":true,"full":true,"ctx":"Félix y Raquel se dejaron las llaves dentro."},{"tpl":"___","blanks":1,"ans":["Te desmayaste porque no habías comido nada"],"wide":true,"full":true,"ctx":"No comiste nada."},{"tpl":"___","blanks":1,"ans":["No reconocimos a Paloma porque se había teñido el pelo"],"wide":true,"full":true,"ctx":"Paloma se tiñó el pelo."},{"tpl":"___","blanks":1,"ans":["Mila aprobó todo porque había estudiado mucho"],"wide":true,"full":true,"ctx":"Mila estudió mucho."},{"tpl":"___","blanks":1,"ans":["Víctor llegó tarde porque había tenido un pequeño accidente"],"wide":true,"full":true,"ctx":"Víctor tuvo un pequeño accidente."},{"tpl":"___","blanks":1,"ans":["No pude hablar con el profesor porque se había ido"],"wide":true,"full":true,"ctx":"El profesor se fue."},{"tpl":"___","blanks":1,"ans":["No pudimos comer en casa porque Ramón no había comprado comida"],"wide":true,"full":true,"ctx":"Ramón no compró comida."}]},{"id":"gram:66.3","type":"cloze","lab":"66.3","title":"66.3","instr":"¿Cuál era la situación cuando Javier llegó a casa de sus amigos? Utilice ya y todavía no.","img":"img/gram/u66_ej66-3_ilustraciones.png","alt":"Cinco viñetas: Fernando durmiendo en la cama, Lidia con la habitación desordenada, Miguel con la cama hecha, Rosa en pijama bostezando y Ángel y Pilar desayunando.","bank":["~levantarse","desayunar","hacer la cama","recoger la habitación","vestirse"],"items":[{"tpl":"Fernando ___.","blanks":1,"ans":["no se había levantado todavía","todavía no se había levantado"],"wide":true,"example":true},{"tpl":"Lidia ___.","blanks":1,"ans":["no había recogido la habitación todavía","todavía no había recogido la habitación"],"wide":true},{"tpl":"Miguel ___.","blanks":1,"ans":["ya había hecho la cama"],"wide":true},{"tpl":"Rosa ___.","blanks":1,"ans":["no se había vestido todavía","todavía no se había vestido"],"wide":true},{"tpl":"Ángel y Pilar ___.","blanks":1,"ans":["ya habían desayunado"],"wide":true}]}]},{"id":67,"name":"Futuro simple: verbos regulares","motto":"trabajaré, comeré, viviré","theory":[{"k":"img","src":"img/gram/u67_teoria-lluvia.png","alt":"Mañana lloverá en el norte."},{"k":"img","src":"img/gram/u67_teoria-caracas.png","alt":"«Llegaremos a Caracas a las cuatro y cuarto hora local.»"},{"k":"p","t":"<i>Lloverá</i> y <i>llegaremos</i> son formas del futuro simple."},{"k":"h","t":"Formación del futuro simple: verbos regulares"},{"k":"table","head":["","-ar (trabajar)","-er (comer)","-ir (vivir)"],"rows":[["(yo)","trabajar-é","comer-é","vivir-é"],["(tú)","trabajar-ás","comer-ás","vivir-ás"],["(usted)","trabajar-á","comer-á","vivir-á"],["(él, ella)","trabajar-á","comer-á","vivir-á"],["(nosotros, -as)","trabajar-emos","comer-emos","vivir-emos"],["(vosotros, -as)","trabajar-éis","comer-éis","vivir-éis"],["(ustedes)","trabajar-án","comer-án","vivir-án"],["(ellos, -as)","trabajar-án","comer-án","vivir-án"]]},{"k":"p","t":"Se usa el futuro simple para hablar de acciones o situaciones futuras. Informa de lo que sucederá <i>mañana, dentro de (tres meses, dos días…), el año que viene</i>, etc."},{"k":"eg","t":"El nuevo edificio <b>estará</b> acabado dentro de seis meses.<br>Mañana te <b>sentirás</b> mejor."},{"k":"p","t":"– Se suele usar con las siguientes expresiones: <i>luego, más tarde, pronto, el próximo (lunes) / la próxima (semana), (el año / la semana) que viene, en el año 3000, dentro de + período de tiempo, cuando + situación futura…</i>"},{"k":"eg","t":"—¿Has llamado a José? —No. Lo <b>llamaré</b> más tarde.<br>No te preocupes. Pronto <b>encontrarás</b> trabajo.<br>—¿Habéis escrito a la abuela? —No. Le <b>escribiremos</b> la semana que viene.<br>Iván <b>llegará</b> dentro de unos días.<br>Te <b>avisaré</b> cuando aterricemos."},{"k":"p","t":"Se usa el futuro simple para hacer predicciones."},{"k":"eg","t":"El fin de semana <b>nevará</b> a partir de mil metros.<br>Conocerá a una persona maravillosa y <b>se casarán</b>.<br><b>Llegaremos</b> a Marte en el año 2050."},{"k":"p","t":"Unidad 91: Condicionales (1) · Unidad 92: Condicionales (2) · Unidad 118: Oraciones temporales"}],"ex":[{"id":"gram:67.1","type":"cloze","lab":"67.1","title":"67.1","instr":"Complete las frases con el futuro simple de los verbos entre paréntesis.","items":[{"tpl":"Hoy no puedo ir. (Ir) ___ mañana.","blanks":1,"ans":["Iré"],"wide":true,"example":true},{"tpl":"—Nos vamos hoy a Panamá. —¿Y cuándo (volver) ___?","blanks":1,"ans":["volveréis"],"wide":true},{"tpl":"Hoy no te puedo llamar. Te (llamar) ___ el lunes.","blanks":1,"ans":["llamaré"],"wide":true},{"tpl":"—¿Habéis acabado la traducción? —No, la (acabar) ___ la semana que viene.","blanks":1,"ans":["acabaremos"],"wide":true},{"tpl":"—¿Han arreglado ya el ordenador? —No, lo (arreglar) ___ en cuanto puedan.","blanks":1,"ans":["arreglarán"],"wide":true},{"tpl":"—¿Has ido al dentista? —Todavía no. (Ir) ___ cuando tenga tiempo.","blanks":1,"ans":["Iré"],"wide":true},{"tpl":"—¿Puedes prestarme tu bicicleta? —Sí, claro, pero ¿cuándo me la (devolver) ___?","blanks":1,"ans":["devolverás"],"wide":true},{"tpl":"Estas plantas están secas. Riégalas o (morirse) ___.","blanks":1,"ans":["se morirán"],"wide":true},{"tpl":"—¿Crees que (yo, aprobar) ___? —(Aprobar) ___ si estudias mucho.","blanks":2,"ans":["aprobaré Aprobarás"],"wide":true},{"tpl":"Ahora no tenemos hambre. (Comer) ___ más tarde.","blanks":1,"ans":["Comeremos"],"wide":true},{"tpl":"—Quiero una bici. —Te (yo, regalar) ___ una para Reyes.","blanks":1,"ans":["regalaré"],"wide":true},{"tpl":"—Me gustaría ir a Cuba. —(Ir) ___ en cuanto podamos.","blanks":1,"ans":["Iremos"],"wide":true}]},{"id":"gram:67.2","type":"cloze","lab":"67.2","title":"67.2","instr":"Complete la predicción del tiempo para el próximo fin de semana.","items":[{"tpl":"El fin de semana (ser) ___ bastante frío.","blanks":1,"ans":["será"],"mid":true,"example":true},{"tpl":"El sábado (bajar) ___ las temperaturas en todo el país y (nevar) ___ en zonas altas del norte.","blanks":2,"ans":["bajarán nevará"],"mid":true,"perBlank":true},{"tpl":"El domingo (subir) ___ un poco las temperaturas aunque (seguir) ___ haciendo frío.","blanks":2,"ans":["subirán seguirá"],"mid":true,"perBlank":true},{"tpl":"(Llover) ___ en el oeste y suroeste.","blanks":1,"ans":["Lloverá"],"mid":true},{"tpl":"En el centro (soplar) ___ fuertes vientos del norte.","blanks":1,"ans":["soplarán"],"mid":true}]},{"id":"gram:67.3","type":"cloze","lab":"67.3","title":"67.3","instr":"Complete las predicciones del horóscopo.","bank":["ayudar","conocer","desaparecer","gastar","mejorar","pasar","~recibir","recibir","sentirse","ser","ser","verse","viajar"],"items":[{"tpl":"Aries: Recibirá muchas invitaciones. ___ una semana muy divertida, aunque ___ un poco cansado y ___ más dinero de lo normal.","blanks":3,"ans":["Será se sentirá gastará"],"mid":true},{"tpl":"Tauro: ___ envuelto en problemas, aunque sus amigos le ___. Su salud ___ excelente.","blanks":3,"ans":["Se verá ayudarán será"],"mid":true},{"tpl":"Cáncer: ___ a algún país lejano y ___ a alguien importante. ___ su situación económica.","blanks":3,"ans":["Viajará conocerá Mejorará"],"mid":true},{"tpl":"Escorpio: ___ todos sus problemas. ___ unos días muy felices con familia y amigos y ___ una sorpresa agradable.","blanks":3,"ans":["Desaparecerán Pasará recibirá"],"mid":true}]}]},{"id":68,"name":"Futuro simple: verbos irregulares","motto":"habré, podré...","theory":[{"k":"h","t":"Formación del futuro simple: verbos irregulares"},{"k":"p","t":"Estos verbos pierden la vocal del infinitivo. Las terminaciones son las mismas que las de los verbos regulares: <b>-é, -ás, -á, -á, -emos, -éis, -án, -án</b>."},{"k":"table","head":["Infinitivo","Raíz"],"rows":[["haber","habr-"],["poder","podr-"],["saber","sabr-"]]},{"k":"table","head":["Infinitivo","Raíz"],"rows":[["poner","pondr-"],["salir","saldr-"],["tener","tendr-"],["valer","valdr-"],["venir","vendr-"]]},{"k":"table","head":["Infinitivo","Raíz"],"rows":[["decir","dir-"],["hacer","har-"],["querer","querr-"]]},{"k":"img","src":"img/gram/u68_teoria-luna.png","alt":"«Pues yo creo que en el año 2050 habrá ciudades en la Luna.»"},{"k":"h","t":"Usos básicos del futuro simple"},{"k":"p","t":"– Acciones o situaciones futuras."},{"k":"eg","t":"—¿Ha venido Amelia? —No. <b>Vendrá</b> más tarde."},{"k":"p","t":"– Predicciones."},{"k":"eg","t":"En el futuro <b>podremos</b> vivir en la Luna.<br>Mañana <b>hará</b> buen tiempo en todo el país."},{"k":"p","t":"También se usa el futuro simple para expresar probabilidad o suposición en el futuro."},{"k":"eg","t":"—¿Vas a hacer tú la cena? —¿Yo? No. La <b>hará</b> Martina. (Supongo que la hará Martina.)"},{"k":"p","t":"– Se suele usar con algunas expresiones que indican diferentes grados de probabilidad: <i>creo que, estoy seguro/a de que, (me) imagino que, supongo que, probablemente, posiblemente, seguramente</i>."},{"k":"eg","t":"¿Crees que <b>vendrán</b> todos a la fiesta?<br>Estoy segura de que os <b>querréis</b> mucho y <b>seréis</b> muy felices.<br>Supongo que <b>habrá</b> comida para todos.<br>Probablemente <b>haremos</b> un viaje a América este verano."},{"k":"p","t":"– También sirve para expresar probabilidad o suposición en el presente."},{"k":"img","src":"img/gram/u68_teoria-casa.png","alt":"«¡Qué casa! ¿Cuánto valdrá?»"},{"k":"eg","t":"—¿Qué hora es?<br>—No sé; no tengo reloj. <b>Serán</b> sobre las tres. (Supongo que son las tres.)<br>—Alberto parece bastante joven. —¿Cuántos años <b>tendrá</b>? (¿Cuántos años crees que tiene?)"},{"k":"p","t":"Unidad 91: Condicionales (1) · Unidad 67: Futuro simple: verbos regulares"}],"ex":[{"id":"gram:68.1","type":"cloze","lab":"68.1","title":"68.1","instr":"Complete las frases con el futuro simple de los verbos del recuadro.","bank":["decir","haber","hacer","~hacer","poner","saber","salir","venir"],"items":[{"tpl":"—¿Has hecho la cama? —No, la ___ luego.","blanks":1,"ans":["haré"],"mid":true,"example":true},{"tpl":"—¿Ha venido Sonia? —No, probablemente ___ más tarde.","blanks":1,"ans":["vendrá"],"mid":true},{"tpl":"Mañana ___ tormentas en el centro del país y ___ bastante frío en el norte.","blanks":2,"ans":["habrá hará"],"mid":true},{"tpl":"—¿Le has dicho a Pepe que no podemos ir a su fiesta? —No, me da apuro. Se lo ___ mañana.","blanks":1,"ans":["diré"],"mid":true},{"tpl":"—¿Sabéis ya el resultado del examen? —No, pero lo ___ muy pronto.","blanks":1,"ans":["sabremos"],"mid":true},{"tpl":"—¿Ha salido ya Rocío? —No, ___ dentro de un rato.","blanks":1,"ans":["saldrá"],"mid":true},{"tpl":"—¿Has puesto el lavavajillas? —No, lo ___ esta noche después de cenar.","blanks":1,"ans":["pondré"],"mid":true}]},{"id":"gram:68.2","type":"cloze","lab":"68.2","title":"68.2","instr":"Complete estas predicciones. ¿Cómo será la vida dentro de cincuenta años? Escriba frases con las palabras dadas.","items":[{"tpl":"En el futuro ___.","blanks":1,"ans":["la vida será muy diferente"],"wide":true,"ctx":"La vida/ser/muy diferente.","example":true},{"tpl":"___","blanks":1,"ans":["La gente vivirá más"],"wide":true,"full":true,"ctx":"La gente/vivir/más."},{"tpl":"___","blanks":1,"ans":["La gente trabajará menos"],"wide":true,"full":true,"ctx":"La gente/trabajar/menos."},{"tpl":"___","blanks":1,"ans":["Los robots harán todos los trabajos físicos"],"wide":true,"full":true,"ctx":"Los robots/hacer/todos los trabajos físicos."},{"tpl":"___","blanks":1,"ans":["Habrá ciudades satélite en el espacio"],"wide":true,"full":true,"ctx":"Haber/ciudades satélite en el espacio."},{"tpl":"___","blanks":1,"ans":["Muchas enfermedades desaparecerán"],"wide":true,"full":true,"ctx":"Muchas enfermedades/desaparecer."},{"tpl":"___","blanks":1,"ans":["No habrá guerras"],"wide":true,"full":true,"ctx":"No/haber/guerras."},{"tpl":"___","blanks":1,"ans":["Las casas estarán informatizadas"],"wide":true,"full":true,"ctx":"Las casas/estar/informatizadas."}]},{"id":"gram:68.3","type":"cloze","lab":"68.3","title":"68.3","instr":"Complete las frases con los verbos entre paréntesis.","items":[{"tpl":"¿Quién crees que (ganar) ___ la copa?","blanks":1,"ans":["ganará"],"wide":true,"example":true},{"tpl":"Me imagino que cuando tenga cincuenta años (yo, estar) ___ calvo y (yo, tener) ___ muchas arrugas.","blanks":2,"ans":["estaré tendré"],"wide":true},{"tpl":"—¿Qué vas a hacer este verano? —Seguramente (ir) ___ a Viña.","blanks":1,"ans":["iremos"],"wide":true},{"tpl":"—¿Has invitado a Carlos y a Toñi? —Sí, pero supongo que no (venir) ___.","blanks":1,"ans":["vendrán"],"wide":true},{"tpl":"No he visto a Lucía esta semana. ¿Crees que (acordarse) ___ de la cita?","blanks":1,"ans":["se acordará"],"wide":true},{"tpl":"—¿Qué vas a estudiar, Rafa? —No lo sé. Probablemente (estudiar) ___ Medicina.","blanks":1,"ans":["estudiaré"],"wide":true},{"tpl":"—Supongo que (venir) ___ todos el sábado. —No lo sé. Ana no está bien.","blanks":1,"ans":["vendréis"],"wide":true}]},{"id":"gram:68.4","type":"cloze","lab":"68.4","title":"68.4","instr":"Complete las respuestas.","items":[{"tpl":"—¿Sabes dónde está Julia? —___ en casa. No sale nunca.","blanks":1,"ans":["Estará"],"mid":true,"example":true},{"tpl":"—¿Tienes tú las entradas? —¿Yo? No, las ___ Blanca. Las ha comprado ella.","blanks":1,"ans":["tendrá"],"mid":true},{"tpl":"—¿Cuántas personas crees que hay en el teatro? —___ unas cuarenta.","blanks":1,"ans":["Habrá"],"mid":true},{"tpl":"—¿Quién es la chica que está con Jorge? —No la conozco. ___ una amiga.","blanks":1,"ans":["Será"],"mid":true},{"tpl":"—¿Sabes a qué hora empieza el concierto? —No. Lo ___ Amalia. Ella tiene el programa.","blanks":1,"ans":["sabrá"],"mid":true},{"tpl":"—¿Sabes cuánto valen esos ordenadores? —No ___ mucho. Están de oferta.","blanks":1,"ans":["valdrán"],"mid":true}]}]}];
